window.BIBEL = {"built":"2026-11-13","eras":[{"id":"anfaenge","short":"Anfänge","title":"Von der Schöpfung bis zur Sintflut","range":"bis 2370 v. u. Z.","start":-4026,"end":-2370,"color":"green","summary":"Jehova erschafft Himmel und Erde und 4026 v. u. Z. den ersten Menschen. Nach der Rebellion in Eden nimmt die Bosheit überhand, bis Gott die damalige Welt in der Sintflut vernichtet. Nur Noah und seine Familie überleben."},{"id":"patriarchen","short":"Patriarchen","title":"Die Zeit der Patriarchen","range":"2370–1728 v. u. Z.","start":-2370,"end":-1728,"color":"orange","summary":"Nach der Flut verteilt sich die Menschheit über die Erde. Jehova schließt einen Bund mit Abraham, der 1943 v. u. Z. in Kraft tritt. Isaak und Jakob leben als Fremdlinge in Kanaan, bis Jakobs Familie nach Ägypten zieht."},{"id":"aegypten","short":"Ägypten & Wildnis","title":"Israel in Ägypten und in der Wildnis","range":"1728–1473 v. u. Z.","start":-1728,"end":-1473,"color":"brown","summary":"Israel wohnt 215 Jahre in Ägypten und wird dort versklavt. 1513 v. u. Z. führt Jehova sein Volk durch Moses heraus und schließt am Sinai den Gesetzesbund. Danach wandert Israel 40 Jahre durch die Wildnis."},{"id":"richter","short":"Richter","title":"Landnahme und Richterzeit","range":"1473–1117 v. u. Z.","start":-1473,"end":-1117,"color":"yellow","summary":"Unter Josua zieht Israel ins Land der Verheißung. Danach führen Richter das Volk, das immer wieder von Jehova abweicht und aus der Hand seiner Feinde befreit wird – bis es einen menschlichen König verlangt."},{"id":"koenigreich","short":"Königreich","title":"Das vereinigte Königreich","range":"1117–997 v. u. Z.","start":-1117,"end":-997,"color":"indigo","summary":"Saul, David und Salomo regieren über alle zwölf Stämme. Jehova schließt mit David einen Bund für ein dauerhaftes Königreich, und Salomo baut in Jerusalem den Tempel."},{"id":"geteilt","short":"Juda & Israel","title":"Das geteilte Königreich","range":"997–607 v. u. Z.","start":-997,"end":-607,"color":"purple","summary":"Nach Salomos Tod zerfällt das Reich in das Zehnstämmereich Israel und das Zweistämmereich Juda. Propheten warnen vor Untreue. Samaria fällt 740 v. u. Z. an Assyrien, Jerusalem 607 v. u. Z. an Babylon."},{"id":"exil","short":"Exil","title":"Exil in Babylon","range":"607–537 v. u. Z.","start":-607,"end":-537,"color":"red","summary":"Das Land Juda liegt 70 Jahre verwüstet, die Juden leben im Exil. Daniel und Hesekiel wirken in Babylon, bis Cyrus 539 v. u. Z. die Stadt erobert und die Rückkehr erlaubt."},{"id":"rueckkehr","short":"Rückkehr","title":"Rückkehr und Wiederaufbau","range":"537 – nach 443 v. u. Z.","start":-537,"end":-443,"color":"mint","summary":"Im Herbst 537 v. u. Z. wird die Anbetung Jehovas in Jerusalem wiederhergestellt. Der Tempel wird neu gebaut, später auch die Stadtmauer. Mit dem Buch Maleachi enden die Hebräischen Schriften."},{"id":"jesus","short":"Leben Jesu","title":"Das Leben Jesu","range":"3 v. u. Z. – 33 u. Z.","start":-3,"end":33,"color":"blue","gapBefore":"Rund 440 Jahre später","summary":"Jesus wird geboren, lässt sich 29 u. Z. taufen und predigt dreieinhalb Jahre über das Königreich Gottes. Am 14. Nisan 33 u. Z. stirbt er und wird am dritten Tag auferweckt."},{"id":"versammlung","short":"Urchristen","title":"Die Christenversammlung","range":"33 – um 100 u. Z.","start":33,"end":100,"color":"pink","summary":"Zu Pfingsten 33 u. Z. entsteht die Christenversammlung. Die gute Botschaft breitet sich unter Juden, Samaritern und Menschen aus den Nationen aus. Mit den Schriften des Apostels Johannes wird die Bibel um 98 u. Z. vollendet."}],"persons":[{"id":"aaron","name":"Aaron","alt":[],"sex":"m","tags":["priester","prophet"],"role":"Erster Hoher Priester Israels","eras":["aegypten"],"dates":[{"label":"Lebenszeit","value":"1597–1474 v. u. Z."},{"label":"Alter","value":"123 Jahre"}],"year":-1597,"meaning":"","summary":"Aaron, der ältere Bruder von Moses, wurde Israels erster Hoher Priester. Weil Moses meinte, nicht gut reden zu können, bestimmte Jehova Aaron zu seinem Sprecher; der 83-Jährige trat für ihn vor Pharao. Später ließ er sich vom Volk drängen, das goldene Kalb zu machen. Er starb 1474 v. u. Z. mit 123 Jahren.","facts":[{"t":"Er diente Moses als „Mund“ vor den Ältesten und vor Pharao.","r":{"t":"2. Mose 4:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/4/#v2004014-v2004016"}},{"t":"Er wirkte das erste Zeichen vor Pharao und gab das Signal für die erste Plage.","r":{"t":"2. Mose 7:9-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/7/#v2007009-v2007020"}},{"t":"Auf Drängen des Volkes machte er das goldene Kalb.","r":{"t":"2. Mose 32:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/32/#v2032001-v2032006"}},{"t":"Er wurde mit seinen Söhnen in den Priesterdienst eingesetzt.","r":{"t":"3. Mose 8:1-36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/3-mose/8/#v3008001-v3008036"}},{"t":"Er starb mit 123 Jahren auf dem Berg Hor.","r":{"t":"4. Mose 33:39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/33/#v4033039"}}],"lesson":"","family":{"father":"Amram","mother":"jochebed","spouses":["Elischeba"],"children":["Nadab","Abihu","Eleasar","Ithamar"],"siblings":["moses","mirjam"]},"related":["pinehas"],"events":["brennender-dornbusch","zehn-plagen","erstes-passah","goldenes-kalb","auszug-aus-aegypten","durchzug-rotes-meer","gesetzesbund","stiftshuette","korahs-aufstand"],"books":[],"refs":[{"t":"2. Mose 4:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/4/#v2004014-v2004016"},{"t":"2. Mose 28:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/28/#v2028001"},{"t":"4. Mose 17:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/17/#v4017008"},{"t":"4. Mose 20:23-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/20/#v4020023-v4020029"}],"sources":[{"title":"Aaron – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000005"}]},{"id":"abel","name":"Abel","alt":[],"sex":"m","tags":[],"role":"Sohn Adams, erster Glaubenszeuge","eras":["anfaenge"],"dates":[],"year":-4018,"meaning":"„Hauch“, „Nichtigkeit“ (vielleicht)","summary":"Abel war der zweite Sohn Adams und Evas. Als Schafhirt brachte er Jehova von den Erstlingen seiner Herde ein Opfer dar, das Gott annahm. Aus Eifersucht erschlug ihn sein Bruder Kain. Der Apostel Paulus nennt Abel als ersten Glaubenszeugen.","facts":[{"t":"Er wurde Schafhirt, sein Bruder Kain Ackerbauer.","r":{"t":"1. Mose 4:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004002"}},{"t":"Er opferte von den Erstlingen seiner Herde; Gott sah wohlwollend auf sein Opfer.","r":{"t":"1. Mose 4:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004004"}},{"t":"Sein Opfer war wegen seines Glaubens „wertvoller“ als das Kains.","r":{"t":"Hebräer 11:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011004"}},{"t":"Er wurde von seinem Bruder Kain getötet.","r":{"t":"1. Mose 4:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004008"}}],"lesson":"","family":{"father":"adam","mother":"eva","spouses":[],"children":[],"siblings":["kain","seth"]},"related":[],"events":["kain-und-abel"],"books":[],"refs":[{"t":"1. Mose 4:2-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004002-v1004008"},{"t":"Hebräer 11:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011004"}],"sources":[{"title":"Abel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000018"}]},{"id":"abigail","name":"Abigail","alt":[],"sex":"f","tags":[],"role":"Frau Nabals, später Davids","eras":["koenigreich"],"dates":[],"year":-1085,"meaning":"„(Mein) Vater freut sich“","summary":"Abigail war die verständige und schöne Frau Nabals, eines reichen, harten Mannes aus Maon. Als Nabal Davids Boten beleidigte und David sich rächen wollte, ging sie ihm mit Lebensmitteln entgegen und bewahrte ihn mit klugen Worten vor Blutschuld. Nachdem Jehova Nabal geschlagen hatte und er gestorben war, heiratete David sie.","facts":[{"t":"Sie war „gut hinsichtlich Verständigkeit und schön“.","r":{"t":"1. Samuel 25:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/25/#v9025003"}},{"t":"Sie brachte David und seinen Männern Lebensmittel.","r":{"t":"1. Samuel 25:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/25/#v9025018"}},{"t":"David dankte ihr, dass sie ihn vor Blutschuld bewahrt hatte.","r":{"t":"1. Samuel 25:32, 33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/25/#v9025032"}},{"t":"Nach Nabals Tod wurde sie Davids Frau.","r":{"t":"1. Samuel 25:39-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/25/#v9025039-v9025042"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Nabal","david"],"children":[],"siblings":[]},"related":[],"events":["david-flieht-vor-saul"],"books":[],"refs":[{"t":"1. Samuel 25:2-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/25/#v9025002-v9025042"}],"sources":[{"title":"Abigail – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000037"},{"title":"David – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001130"}]},{"id":"abija","name":"Abija","alt":["Abijam"],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"980–978 v. u. Z. (3 Jahre)"}],"year":-980,"meaning":"„(Mein) Vater ist Jehova“","summary":"Abija, auch Abijam genannt, war ein Sohn Rehabeams und Maachas und der zweite König des Zweistämmereichs Juda. Er war väterlicher- und mütterlicherseits ein Nachkomme Davids und steht in der königlichen Abstammungslinie Jesu.","facts":[{"t":"Er regierte nur drei Jahre.","r":{"t":"1. Könige 15:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015001"}},{"t":"Er kämpfte gegen Jerobeam von Israel.","r":{"t":"2. Chronika 13:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/13/#v14013001-v14013020"}},{"t":"Er steht im Geschlechtsregister Jesu.","r":{"t":"Matthäus 1:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001007"}}],"lesson":"","family":{"father":"rehabeam","mother":"Maacha","spouses":[],"children":["asa"],"siblings":[]},"related":[],"events":[],"books":[],"refs":[{"t":"1. Könige 15:1-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015001-v11015008"},{"t":"2. Chronika 13:1-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/13/#v14013001-v14013022"}],"sources":[{"title":"Abija – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000041"}]},{"id":"abraham","name":"Abraham","alt":["Abram"],"sex":"m","tags":["patriarch","vorfahr-jesu"],"role":"Patriarch, „Freund Jehovas“","eras":["patriarchen"],"dates":[{"label":"Lebenszeit","value":"2018–1843 v. u. Z."},{"label":"Alter","value":"175 Jahre"}],"year":-2018,"meaning":"„Vater einer Menge“ (Abram: „Vater ist hoch“)","summary":"Abraham, ursprünglich Abram, stammte aus Ur in Chaldäa und glaubte wie Sem und Noah an Jehova. Auf Gottes Gebot verließ er seine Heimat und lebte als Fremdling in Zelten im Land Kanaan. Jehova schloss mit ihm einen Bund und kündigte an, dass der verheißene „Nachkomme“ von ihm abstammen werde. Wegen seines Glaubens und Gehorsams wurde er „Freund Jehovas“ genannt.","facts":[{"t":"Geboren 2018 v. u. Z., 352 Jahre nach der Sintflut.","r":{"t":"1. Mose 11:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011026"}},{"t":"Verließ auf Gottes Gebot Ur und zog über Haran nach Kanaan.","r":{"t":"Apostelgeschichte 7:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/7/#v44007002-v44007004"}},{"t":"Überquerte 1943 v. u. Z. mit 75 Jahren den Euphrat.","r":{"t":"1. Mose 12:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/12/#v1012004"}},{"t":"Mit 99 Jahren erhielt er den Namen Abraham.","r":{"t":"1. Mose 17:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/17/#v1017005"}},{"t":"War bereit, seinen Sohn Isaak zu opfern; Gott sorgte für einen Widder.","r":{"t":"1. Mose 22:1-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/22/#v1022001-v1022018"}},{"t":"Starb 1843 v. u. Z. mit 175 Jahren; begraben in der Höhle von Machpela.","r":{"t":"1. Mose 25:7-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025007-v1025010"}}],"lesson":"Abraham bewies seinen Glauben durch Taten – deshalb wurde er „Freund Jehovas“ genannt.","family":{"father":"terach","mother":"","spouses":["sara","hagar","Ketura"],"children":["isaak","ismael"],"siblings":["Nahor","Haran"]},"related":["lot","melchisedek","sem"],"events":["geburt-abrams","abrahamischer-bund","melchisedek-segnet-abram","sodom-und-gomorra","geburt-isaaks","hagar-und-ismael","opferung-isaaks","isaak-heiratet-rebekka","tod-abrahams"],"books":[],"refs":[{"t":"1. Mose 12:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/12/#v1012001-v1012003"},{"t":"1. Mose 22:1-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/22/#v1022001-v1022018"},{"t":"Römer 4:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/4/#v45004011"},{"t":"Jakobus 2:21-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jakobus/2/#v59002021-v59002023"}],"sources":[{"title":"Abraham – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000060"}]},{"id":"absalom","name":"Absalom","alt":["Abischalom"],"sex":"m","tags":[],"role":"Sohn Davids, Aufrührer","eras":["koenigreich"],"dates":[],"year":-1075,"meaning":"„Vater (d. h. Gott) ist Frieden“","summary":"Absalom war ein in Hebron geborener Sohn Davids und Maachas, berühmt für seine Schönheit und sein üppiges Haar. Er ließ seinen Halbbruder Amnon töten, der seine Schwester Tamar entehrt hatte, und floh. Später gewann er durch Schmeichelei die Herzen der Israeliten, ließ sich in Hebron zum König ausrufen und vertrieb David aus Jerusalem. In der Schlacht verfing er sich mit dem Kopf in einem Baum und wurde von Joab getötet.","facts":[{"t":"Er wurde im ganzen Land wegen seiner Schönheit gepriesen.","r":{"t":"2. Samuel 14:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/14/#v10014025"}},{"t":"Er ließ Amnon töten.","r":{"t":"2. Samuel 13:28, 29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/13/#v10013028"}},{"t":"Er „stahl das Herz der Männer Israels“.","r":{"t":"2. Samuel 15:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/15/#v10015006"}},{"t":"Er verfing sich in einem großen Baum und wurde getötet.","r":{"t":"2. Samuel 18:9-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/18/#v10018009-v10018015"}}],"lesson":"","family":{"father":"david","mother":"Maacha","spouses":[],"children":["Tamar"],"siblings":["salomo","Amnon","Adonia","Tamar"]},"related":["joab"],"events":["absaloms-aufstand"],"books":[],"refs":[{"t":"2. Samuel 15:1-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/15/#v10015001-v10015014"},{"t":"2. Samuel 18:1-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/18/#v10018001-v10018033"}],"sources":[{"title":"Absalom – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000063"}]},{"id":"achan","name":"Achan","alt":["Achar"],"sex":"m","tags":[],"role":"Israelit, nahm verbotene Beute","eras":["richter"],"dates":[{"label":"Zeit","value":"1473 v. u. Z."}],"year":-1472,"meaning":"verbunden mit Achar: „Der in Verruf brachte“","summary":"Achan aus dem Stamm Juda nahm bei der Einnahme Jerichos heimlich ein kostbares Gewand, Gold und Silber an sich, obwohl Jehova geboten hatte, dass alles Wertvolle der Stadt ihm gehörte. Damit beraubte er Gott. Deshalb versagte Jehova Israel seine Hilfe, und die Israeliten erlitten bei Ai eine Niederlage. Achan wurde entlarvt und mit seiner Hausgemeinschaft gesteinigt.","facts":[{"t":"Jericho war „der Vernichtung geweiht“; Silber und Gold gehörten Jehova.","r":{"t":"Josua 6:17-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/6/#v6006017-v6006019"}},{"t":"Er vergrub die Beute unter seinem Zelt.","r":{"t":"Josua 7:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/7/#v6007021"}},{"t":"Israel wurde bei Ai geschlagen.","r":{"t":"Josua 7:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/7/#v6007004"}},{"t":"Er wurde entlarvt und gesteinigt.","r":{"t":"Josua 7:24-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/7/#v6007024-v6007026"}}],"lesson":"","family":{"father":"Karmi","mother":"","spouses":[],"children":[],"siblings":[]},"related":["josua"],"events":["fall-jerichos"],"books":[],"refs":[{"t":"Josua 7:1-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/7/#v6007001-v6007026"},{"t":"1. Chronika 2:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/2/#v13002007"}],"sources":[{"title":"Achan – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000074"}]},{"id":"adam","name":"Adam","alt":[],"sex":"m","tags":["vorfahr-jesu"],"role":"Der erste Mensch","eras":["anfaenge"],"dates":[{"label":"Lebenszeit","value":"4026–3096 v. u. Z."},{"label":"Alter","value":"930 Jahre"}],"year":-4026,"meaning":"„Erdenmensch“, „Menschheit“","summary":"Adam war der erste Mensch. Jehova bildete ihn 4026 v. u. Z. aus dem Staub des Erdbodens und erschuf ihn „im Bilde Gottes“ – mit Eigenschaften wie Liebe, Weisheit, Gerechtigkeit und Macht. Er lebte mit Eva im Paradies Eden, schloss sich aber ihrem Ungehorsam gegenüber Gott an und brachte dadurch Sünde und Tod über alle seine Nachkommen.","facts":[{"t":"Wurde als vollkommener Mensch erschaffen und wurde „eine lebende Seele“.","r":{"t":"1. Mose 2:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/2/#v1002007"}},{"t":"Sollte die Erde verwalten und sich die Tiere untertan halten.","r":{"t":"1. Mose 1:26-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001026-v1001028"}},{"t":"Jehova bildete aus einer seiner Rippen Eva, seine Frau.","r":{"t":"1. Mose 2:21-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/2/#v1002021-v1002023"}},{"t":"Hörte auf seine Frau und aß von dem verbotenen Baum.","r":{"t":"1. Mose 3:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003006"}},{"t":"Starb 3096 v. u. Z. mit 930 Jahren.","r":{"t":"1. Mose 5:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005005"}}],"lesson":"","family":{"father":"","mother":"","spouses":["eva"],"children":["kain","abel","seth"],"siblings":[]},"related":[],"events":["erschaffung-des-menschen","suendenfall","tod-adams"],"books":[],"refs":[{"t":"1. Mose 1:26-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001026-v1001028"},{"t":"1. Mose 2:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/2/#v1002007"},{"t":"1. Mose 3:17-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003017-v1003019"},{"t":"Römer 5:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/5/#v45005012"}],"sources":[{"title":"Adam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000089"}]},{"id":"ahab","name":"Ahab","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"ab 940 v. u. Z. (22 Jahre)"}],"year":-940,"meaning":"„Vaters Bruder“","summary":"Ahab, der Sohn Omris, regierte 22 Jahre in Samaria. Durch seine Heirat mit Isebel, der Tochter des Sidonierkönigs, förderte er den Baalskult in noch nie da gewesenem Ausmaß. Elia kündigte ihm eine Dürre an, die dreieinhalb Jahre dauerte. Um den Weingarten Naboths zu bekommen, ließ Isebel Naboth umbringen. Ahab fiel im Kampf bei Ramoth-Gilead.","facts":[{"t":"Er baute Baal einen Tempel in Samaria.","r":{"t":"1. Könige 16:30-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016030-v11016033"}},{"t":"Elia kündigte ihm eine Dürre an.","r":{"t":"1. Könige 17:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/17/#v11017001"}},{"t":"Er nahm Naboths Weingarten in Besitz.","r":{"t":"1. Könige 21:1-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/21/#v11021001-v11021016"}},{"t":"Er demütigte sich, als Elia ihm das Urteil verkündete.","r":{"t":"1. Könige 21:27-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/21/#v11021027-v11021029"}},{"t":"Er starb in der Schlacht bei Ramoth-Gilead.","r":{"t":"1. Könige 22:34-37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/22/#v11022034-v11022037"}}],"lesson":"","family":{"father":"omri","mother":"","spouses":["isebel"],"children":["ahasja-israel","joram-israel","athalja"],"siblings":[]},"related":["elia","josaphat"],"events":["elia-und-die-duerre","elia-auf-dem-karmel"],"books":[],"refs":[{"t":"1. Könige 16:29-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016029-v11016033"},{"t":"1. Könige 21:1-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/21/#v11021001-v11021029"},{"t":"1. Könige 22:29-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/22/#v11022029-v11022040"}],"sources":[{"title":"Ahab – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000138"}]},{"id":"ahas","name":"Ahas","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"ab 762 v. u. Z. (16 Jahre)"}],"year":-762,"meaning":"Kurzform von Jehoahas: „Jehova hat ergriffen“","summary":"Ahas, der Sohn Jothams, kam mit 20 Jahren auf den Thron und regierte 16 Jahre. Er war ein götzendienerischer König, der Hilfe nicht bei Jehova, sondern beim Assyrerkönig Tiglath-Pileser III. suchte und ihm tributpflichtig wurde. Micha, Hosea und Jesaja wirkten während seiner Regierung.","facts":[{"t":"Er ließ sogar seinen Sohn durchs Feuer gehen.","r":{"t":"2. Könige 16:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/16/#v12016003"}},{"t":"Er suchte die Hilfe Assyriens.","r":{"t":"2. Könige 16:7, 8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/16/#v12016007"}},{"t":"Jesaja ermutigte ihn vergeblich, auf Jehova zu vertrauen.","r":{"t":"Jesaja 7:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/7/#v23007001-v23007012"}}],"lesson":"","family":{"father":"jotham","mother":"","spouses":[],"children":["hiskia"],"siblings":[]},"related":["jesaja"],"events":[],"books":[],"refs":[{"t":"2. Könige 16:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/16/#v12016001-v12016020"},{"t":"2. Chronika 28:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/28/#v14028001-v14028027"}],"sources":[{"title":"Ahas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000144"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"ahasja-juda","name":"Ahasja","alt":["Jehoahas"],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 906 v. u. Z. (1 Jahr)"}],"year":-906,"meaning":"„Jehova hat ergriffen“","summary":"Ahasja, der Sohn Jorams und Athaljas, war mit 22 Jahren König von Juda und regierte nur ein Jahr. Er ließ sich von seiner herrschsüchtigen Mutter zum Bösen beeinflussen. Als er König Joram von Israel besuchte, wurde er bei Jehus Strafgericht über das Haus Ahab getötet.","facts":[{"t":"Seine Mutter Athalja beriet ihn zum Bösen.","r":{"t":"2. Chronika 22:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/22/#v14022002-v14022004"}},{"t":"Er zog mit Joram von Israel gegen Syrien.","r":{"t":"2. Könige 8:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/8/#v12008028"}},{"t":"Er wurde auf Jehus Befehl getötet.","r":{"t":"2. Könige 9:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009027"}}],"lesson":"","family":{"father":"joram-juda","mother":"athalja","spouses":["Zibja"],"children":["joas-juda"],"siblings":[]},"related":["jehu"],"events":["jehu-vollstreckt-gericht"],"books":[],"refs":[{"t":"2. Könige 8:25-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/8/#v12008025-v12008029"},{"t":"2. Könige 9:27-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009027-v12009029"},{"t":"2. Chronika 22:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/22/#v14022001-v14022009"}],"sources":[{"title":"Ahasja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000145"}]},{"id":"ahasja-israel","name":"Ahasja","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 919 v. u. Z. (2 Jahre)"}],"year":-919,"meaning":"„Jehova hat ergriffen“","summary":"Ahasja, der Sohn Ahabs und Isebels, war zwei Jahre König von Israel und betete wie seine Eltern Baal an. Nach einem Sturz ließ er Baal-Sebub, den Gott Ekrons, befragen. Elia verkündete ihm, dass er sterben werde, weil er nicht Jehova befragt hatte.","facts":[{"t":"Er diente Baal.","r":{"t":"1. Könige 22:51-53","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/22/#v11022051-v11022053"}},{"t":"Moab lehnte sich nach Ahabs Tod auf.","r":{"t":"2. Könige 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/1/#v12001001"}},{"t":"Er befragte Baal-Sebub statt Jehova.","r":{"t":"2. Könige 1:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/1/#v12001002-v12001004"}}],"lesson":"","family":{"father":"ahab","mother":"isebel","spouses":[],"children":[],"siblings":["joram-israel","athalja"]},"related":["elia"],"events":[],"books":[],"refs":[{"t":"1. Könige 22:51-53","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/22/#v11022051-v11022053"},{"t":"2. Könige 1:1-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/1/#v12001001-v12001018"}],"sources":[{"title":"Ahasja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000145"}]},{"id":"ahasverus","name":"Ahasverus","alt":["Xerxes I."],"sex":"m","tags":["herrscher"],"role":"König von Persien (Buch Esther)","eras":["rueckkehr"],"dates":[{"label":"Regierung","value":"Thronbesteigung 496 v. u. Z.; 1. Regierungsjahr 495"}],"year":-496,"meaning":"","summary":"Der Ahasverus des Buches Esther wird mit Xerxes I. gleichgesetzt, dem Sohn Darius’ des Großen. Er herrschte von Indien bis Äthiopien über 127 Gerichtsbezirke und residierte in Susa. In seinem 3. Jahr verstieß er Königin Waschti, im 7. Jahr machte er Esther zur Königin, und im 12. Jahr erlaubte er Haman, die Ausrottung der Juden zu befehlen – ein Plan, den Esther und Mordechai vereitelten.","facts":[{"t":"Er regierte über 127 Gerichtsbezirke.","r":{"t":"Esther 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/1/#v17001001"}},{"t":"Er verstieß Waschti, weil sie nicht erschien.","r":{"t":"Esther 1:10-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/1/#v17001010-v17001019"}},{"t":"Er erwählte Esther zur Königin.","r":{"t":"Esther 2:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002017"}},{"t":"Er ließ die Juden sich verteidigen.","r":{"t":"Esther 8:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/8/#v17008011"}}],"lesson":"","family":{"father":"Darius der Große","mother":"","spouses":["esther","Waschti"],"children":["artaxerxes"],"siblings":[]},"related":["haman","mordechai"],"events":["esther-wird-koenigin","esther-rettet-ihr-volk"],"books":[],"refs":[{"t":"Esther 1:1-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/1/#v17001001-v17001022"},{"t":"Esther 2:16-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002016-v17002018"},{"t":"Esther 8:1-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/8/#v17008001-v17008017"}],"sources":[{"title":"Ahasverus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000142"}]},{"id":"amazja","name":"Amazja","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"ab 858 v. u. Z. (29 Jahre)"}],"year":-858,"meaning":"„Stark ist Jehova“","summary":"Amazja wurde 858 v. u. Z. nach der Ermordung seines Vaters Joas mit 25 Jahren König. Er ließ die Mörder seines Vaters hinrichten, verschonte aber nach dem Gesetz Moses ihre Söhne. Anfangs setzte er sich für die wahre Anbetung ein; nach einem Sieg über Edom betete er jedoch die Götter der Edomiter an und wurde von Joas von Israel geschlagen.","facts":[{"t":"Er bestrafte die Söhne der Mörder nicht.","r":{"t":"2. Könige 14:5, 6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/14/#v12014005"}},{"t":"Er verehrte die Götter Edoms.","r":{"t":"2. Chronika 25:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/25/#v14025014"}},{"t":"Joas von Israel besiegte ihn und plünderte Jerusalem.","r":{"t":"2. Könige 14:11-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/14/#v12014011-v12014014"}}],"lesson":"","family":{"father":"joas-juda","mother":"Jehoaddin","spouses":["Jecholja"],"children":["usija"],"siblings":[]},"related":["joas-israel"],"events":[],"books":[],"refs":[{"t":"2. Könige 14:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/14/#v12014001-v12014020"},{"t":"2. Chronika 25:1-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/25/#v14025001-v14025028"}],"sources":[{"title":"Amazja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000224"}]},{"id":"amon","name":"Amon","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"661–660 v. u. Z. (2 Jahre)"}],"year":-661,"meaning":"","summary":"Amon, der Sohn Manasses, wurde mit 22 Jahren König und trieb Götzendienst wie sein Vater in dessen früheren Jahren. Nach zwei Jahren wurde er von seinen eigenen Dienern ermordet; das Volk setzte seinen Sohn Josia auf den Thron.","facts":[{"t":"Er diente den Götzen wie sein Vater.","r":{"t":"2. Könige 21:20-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/21/#v12021020-v12021022"}},{"t":"Er demütigte sich nicht wie Manasse.","r":{"t":"2. Chronika 33:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/33/#v14033023"}},{"t":"Seine Diener ermordeten ihn.","r":{"t":"2. Könige 21:23, 24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/21/#v12021023"}}],"lesson":"","family":{"father":"manasse","mother":"","spouses":["Jedida"],"children":["josia"],"siblings":[]},"related":[],"events":[],"books":[],"refs":[{"t":"2. Könige 21:19-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/21/#v12021019-v12021026"},{"t":"2. Chronika 33:21-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/33/#v14033021-v14033025"}],"sources":[{"title":"Amon – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000244"}]},{"id":"amos","name":"Amos","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet aus Tekoa","eras":["geteilt"],"dates":[{"label":"Zeit","value":"9. Jahrhundert v. u. Z. (Buch um 804 v. u. Z.)"}],"year":-804,"meaning":"„Getragen“, „Die Last tragend“","summary":"Amos aus Tekoa in Juda war kein Prophetensohn, sondern ein Hirte und Ritzer von Maulbeerfeigen, als Jehova ihn rief. Er prophezeite vor allem gegen das Nordreich Israel, das trotz Wohlstands die Armen unterdrückte und am Kälberdienst festhielt. Er schrieb das gleichnamige Bibelbuch.","facts":[{"t":"Er war Hirte, kein Prophet von Beruf.","r":{"t":"Amos 7:14, 15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/amos/7/#v30007014"}},{"t":"Er stammte aus Tekoa.","r":{"t":"Amos 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/amos/1/#v30001001"}},{"t":"Jehova offenbart seine vertraulichen Angelegenheiten seinen Propheten.","r":{"t":"Amos 3:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/amos/3/#v30003007"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jerobeam-ii","hosea"],"events":[],"books":["Amos"],"refs":[{"t":"Amos 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/amos/1/#v30001001"},{"t":"Amos 3:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/amos/3/#v30003007"},{"t":"Amos 7:10-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/amos/7/#v30007010-v30007017"}],"sources":[{"title":"Amos – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000246"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"ananias-damaskus","name":"Ananias","alt":["Ananias von Damaskus"],"sex":"m","tags":["juenger"],"role":"Jünger in Damaskus","eras":["versammlung"],"dates":[],"year":34,"meaning":"„Jehova hat Gunst erwiesen“","summary":"Ananias war ein christlicher Jünger in Damaskus. Nach der Bekehrung des Saulus nannte Jesus ihm in einer Vision dessen Namen und Adresse. Ananias zögerte zuerst, weil er wusste, wie heftig Saulus die Christen verfolgt hatte. Doch er ging hin, Saulus erhielt sein Augenlicht zurück, und Ananias teilte ihm seinen Auftrag mit. Paulus beschrieb ihn später als ehrfurchtsvollen Mann mit gutem Ruf.","facts":[{"t":"Jesus sandte ihn in einer Vision zu Saulus.","r":{"t":"Apostelgeschichte 9:10-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009010-v44009012"}},{"t":"Er hatte zuerst Bedenken.","r":{"t":"Apostelgeschichte 9:13, 14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009013"}},{"t":"Durch ihn erhielt Saulus sein Augenlicht zurück.","r":{"t":"Apostelgeschichte 9:17, 18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009017"}},{"t":"Er stand bei allen Juden in Damaskus in gutem Ruf.","r":{"t":"Apostelgeschichte 22:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/22/#v44022012"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus"],"events":["bekehrung-des-saulus"],"books":[],"refs":[{"t":"Apostelgeschichte 9:10-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009010-v44009019"},{"t":"Apostelgeschichte 22:12-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/22/#v44022012-v44022016"}],"sources":[{"title":"Ananias – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000267"}]},{"id":"ananias-und-sapphira","name":"Ananias und Sapphira","alt":["Ananias","Sapphira"],"sex":"m","tags":[],"role":"Ehepaar, das den heiligen Geist belog","eras":["versammlung"],"dates":[],"year":33,"meaning":"Ananias: „Jehova hat Gunst erwiesen“","summary":"Nach Pfingsten 33 u. Z. unterstützten sich die Christen in Jerusalem gegenseitig aus einem gemeinsamen Fonds. Ananias verkaufte ein Feld und gab mit Wissen seiner Frau Sapphira nur einen Teil des Erlöses ab, tat aber so, als sei es der ganze Betrag – vermutlich, um Ansehen zu gewinnen. Petrus deckte die Täuschung auf. Ananias fiel tot nieder, und etwa drei Stunden später starb auch Sapphira, die die Lüge aufrechterhielt.","facts":[{"t":"Sie behielten heimlich einen Teil des Erlöses.","r":{"t":"Apostelgeschichte 5:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/5/#v44005001"}},{"t":"Petrus: Du hast nicht Menschen belogen, sondern Gott.","r":{"t":"Apostelgeschichte 5:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/5/#v44005003"}},{"t":"Ananias fiel nieder und starb.","r":{"t":"Apostelgeschichte 5:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/5/#v44005005"}},{"t":"Etwa drei Stunden später starb auch Sapphira.","r":{"t":"Apostelgeschichte 5:7-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/5/#v44005007-v44005010"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["petrus"],"events":[],"books":[],"refs":[{"t":"Apostelgeschichte 5:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/5/#v44005001-v44005011"}],"sources":[{"title":"Ananias – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000267"}]},{"id":"andreas","name":"Andreas","alt":[],"sex":"m","tags":["apostel"],"role":"Apostel, Bruder des Petrus","eras":["jesus"],"dates":[],"year":29,"meaning":"„Mannhaft“ (wahrscheinlich)","summary":"Andreas, der Bruder von Simon Petrus, stammte aus Bethsaida und lebte später mit Simon in Kapernaum, wo beide als Fischer arbeiteten. Er war zuerst ein Jünger Johannes’ des Täufers. Im Herbst 29 u. Z. hörte er, wie Johannes Jesus als „das Lamm Gottes“ vorstellte, folgte Jesus und brachte seinen Bruder zu ihm. Später wurde er einer der zwölf Apostel.","facts":[{"t":"Er war ein Jünger Johannes’ des Täufers.","r":{"t":"Johannes 1:35, 40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001035"}},{"t":"Er sagte zu Simon: „Wir haben den Messias gefunden.“","r":{"t":"Johannes 1:41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001041"}},{"t":"Jesus berief ihn, ein „Menschenfischer“ zu werden.","r":{"t":"Markus 1:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/1/#v41001016"}},{"t":"Er wies auf den Jungen mit fünf Broten und zwei Fischen hin.","r":{"t":"Johannes 6:8, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/6/#v43006008"}}],"lesson":"","family":{"father":"Jona (Johannes)","mother":"","spouses":[],"children":[],"siblings":["petrus"]},"related":["johannes-der-taeufer"],"events":["erste-juenger","wahl-der-apostel","speisung-der-5000"],"books":[],"refs":[{"t":"Johannes 1:35-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001035-v43001042"},{"t":"Matthäus 4:18-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/4/#v40004018-v40004020"}],"sources":[{"title":"Andreas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000273"}]},{"id":"hanna-prophetin","name":"Anna","alt":["Hanna"],"sex":"f","tags":["prophet"],"role":"Prophetin im Tempel","eras":["jesus"],"dates":[{"label":"Alter","value":"84 Jahre (als Witwe)"}],"year":-2,"meaning":"","summary":"Anna war eine betagte Prophetin, die Tochter Phanuels aus dem Stamm Ascher. Als Witwe war sie ständig im Tempel und diente Gott Tag und Nacht mit Fasten und Gebeten. Als Joseph und Maria das Kind Jesus in den Tempel brachten, dankte sie Gott und sprach über das Kind zu allen, die auf die Befreiung Jerusalems warteten.","facts":[{"t":"Sie war die Tochter Phanuels aus dem Stamm Ascher.","r":{"t":"Lukas 2:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002036"}},{"t":"Sie fehlte nie im Tempel.","r":{"t":"Lukas 2:37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002037"}},{"t":"Sie sprach über das Kind zu allen, die auf Befreiung warteten.","r":{"t":"Lukas 2:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002038"}}],"lesson":"","family":{"father":"Phanuel","mother":"","spouses":[],"children":[],"siblings":[]},"related":["simeon-in-jerusalem"],"events":["darstellung-im-tempel"],"books":[],"refs":[{"t":"Lukas 2:36-38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002036-v42002038"}],"sources":[{"title":"Phanuel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003457"}]},{"id":"hannas","name":"Annas","alt":["Hannas"],"sex":"m","tags":["priester"],"role":"Einflussreicher früherer Hoher Priester","eras":["jesus"],"dates":[{"label":"Zeit","value":"Hoher Priester 6/7 bis um 15 u. Z."}],"year":6,"meaning":"„Gunst erweisend“ (aus dem Hebräischen)","summary":"Annas wurde 6 oder 7 u. Z. vom römischen Statthalter Quirinius als Hoher Priester eingesetzt und behielt das Amt bis um 15 u. Z. Auch danach übte er als maßgeblicher Sprecher der jüdischen Führung großen Einfluss aus: Fünf seiner Söhne und sein Schwiegersohn Kaiphas wurden Hohe Priester. Nach der Festnahme Jesu wurde Jesus zuerst zu Annas gebracht.","facts":[{"t":"Er war Hoher Priester, als der 12-jährige Jesus im Tempel war.","r":{"t":"Lukas 2:42-49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002042-v42002049"}},{"t":"Jesus wurde zuerst zu ihm geführt.","r":{"t":"Johannes 18:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/18/#v43018013"}},{"t":"Er war beim Verhör der Apostel dabei.","r":{"t":"Apostelgeschichte 4:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/4/#v44004006"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["kaiphas"],"events":["gethsemane"],"books":[],"refs":[{"t":"Johannes 18:12-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/18/#v43018012-v43018024"},{"t":"Lukas 3:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003002"}],"sources":[{"title":"Annas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000284"}]},{"id":"apollos","name":"Apollos","alt":[],"sex":"m","tags":["juenger"],"role":"Redegewandter Lehrer aus Alexandria","eras":["versammlung"],"dates":[{"label":"Zeit","value":"um 52 u. Z. in Ephesus"}],"year":52,"meaning":"Kurzform von Apollonius","summary":"Apollos war ein Jude aus Alexandria in Ägypten, sehr redegewandt und in den Hebräischen Schriften gut bewandert. Er kannte zunächst nur die Taufe des Johannes. Als er um 52 u. Z. in Ephesus mutig in der Synagoge sprach, erklärten Aquila und Priscilla ihm den Weg Gottes genauer. In Korinth half er den Brüdern sehr und widerlegte die Juden anhand der Schriften – er „begoss“, was Paulus „gepflanzt“ hatte.","facts":[{"t":"Er war beredt und in den Schriften bewandert.","r":{"t":"Apostelgeschichte 18:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018024"}},{"t":"Aquila und Priscilla nahmen ihn beiseite.","r":{"t":"Apostelgeschichte 18:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018026"}},{"t":"Er widerlegte die Juden öffentlich mit den Schriften.","r":{"t":"Apostelgeschichte 18:27, 28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018027"}},{"t":"Paulus pflanzte, Apollos begoss – Gott aber ließ es wachsen.","r":{"t":"1. Korinther 3:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-korinther/3/#v46003006"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["aquila","priszilla","paulus"],"events":["dritte-missionsreise"],"books":[],"refs":[{"t":"Apostelgeschichte 18:24-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018024-v44018028"},{"t":"1. Korinther 3:4-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-korinther/3/#v46003004-v46003009"}],"sources":[{"title":"Apollos – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000307"}]},{"id":"aquila","name":"Aquila","alt":[],"sex":"m","tags":["juenger"],"role":"Zeltmacher, Mann der Priscilla","eras":["versammlung"],"dates":[],"year":50,"meaning":"„Adler“ (aus dem Lateinischen)","summary":"Aquila, ein Jude aus Pontus, wird immer zusammen mit seiner Frau Priscilla erwähnt. Durch das Dekret des Kaisers Claudius aus Rom vertrieben, ließen sie sich in Korinth nieder. Dort nahmen sie Paulus im Herbst 50 u. Z. bei sich auf und arbeiteten mit ihm als Zeltmacher. Später halfen sie in Ephesus Apollos, Gottes Weg genauer zu verstehen, und stellten ihr Haus für Zusammenkünfte zur Verfügung.","facts":[{"t":"Paulus wohnte und arbeitete bei ihnen.","r":{"t":"Apostelgeschichte 18:2, 3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018002"}},{"t":"Sie reisten mit Paulus nach Ephesus.","r":{"t":"Apostelgeschichte 18:18, 19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018018"}},{"t":"Sie erklärten Apollos den Weg Gottes genauer.","r":{"t":"Apostelgeschichte 18:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018026"}},{"t":"Sie setzten für Paulus ihr Leben aufs Spiel.","r":{"t":"Römer 16:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/16/#v45016003"}}],"lesson":"","family":{"father":"","mother":"","spouses":["priszilla"],"children":[],"siblings":[]},"related":["paulus","apollos"],"events":["zweite-missionsreise","dritte-missionsreise"],"books":[],"refs":[{"t":"Apostelgeschichte 18:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018001-v44018003"},{"t":"Apostelgeschichte 18:18-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018018-v44018026"},{"t":"1. Korinther 16:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-korinther/16/#v46016019"}],"sources":[{"title":"Aquila – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000320"}]},{"id":"artaxerxes","name":"Artaxerxes","alt":["Artaxerxes Longimanus"],"sex":"m","tags":["herrscher"],"role":"König von Persien (Esra, Nehemia)","eras":["rueckkehr"],"dates":[{"label":"Regierung","value":"Thronbesteigung 475 v. u. Z."}],"year":-475,"meaning":"","summary":"Artaxerxes Longimanus, der Sohn Xerxes’ I., bestieg nach jw.org 475 v. u. Z. den Thron (nicht 465, wie viele Nachschlagewerke angeben). In seinem 7. Jahr erlaubte er dem Priester Esra, nach Jerusalem zu ziehen, und in seinem 20. Jahr (455 v. u. Z.) gab er Nehemia die Erlaubnis, Jerusalem wieder aufzubauen. Mit diesem Wort begannen die in Daniel 9 vorhergesagten 69 Jahrwochen bis zum Messias.","facts":[{"t":"Er gab Esra einen Brief mit weitreichenden Vollmachten.","r":{"t":"Esra 7:11-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/7/#v15007011-v15007026"}},{"t":"Er erlaubte Nehemia, Jerusalem wieder aufzubauen.","r":{"t":"Nehemia 2:1-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/2/#v16002001-v16002008"}},{"t":"Das 20. Jahr des Artaxerxes war 455 v. u. Z.","r":{"t":"Daniel 9:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/9/#v27009025"}}],"lesson":"","family":{"father":"ahasverus","mother":"","spouses":[],"children":[],"siblings":[]},"related":["esra","nehemia"],"events":["esra-kommt-nach-jerusalem","nehemia-baut-die-mauer"],"books":[],"refs":[{"t":"Esra 7:1-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/7/#v15007001-v15007028"},{"t":"Nehemia 2:1-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/2/#v16002001-v16002008"}],"sources":[{"title":"Artaxerxes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000389"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"asa","name":"Asa","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"977–937 v. u. Z. (41 Jahre)"}],"year":-978,"meaning":"","summary":"Asa, Sohn Abijams und Enkel Rehabeams, regierte 41 Jahre über Juda. Nach Jahren des Abfalls bekundete er „wie David, sein Vorvater“, großen Eifer für die reine Anbetung und entfernte Götzen und Tempelprostituierte aus dem Land. Mit Jehovas Hilfe besiegte er das gewaltige Heer Serachs, des Äthiopiers.","facts":[{"t":"Er tat, was recht war in Jehovas Augen.","r":{"t":"1. Könige 15:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015011-v11015013"}},{"t":"Er besiegte Serach, den Äthiopier.","r":{"t":"2. Chronika 14:9-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/14/#v14014009-v14014012"}},{"t":"Später verließ er sich auf den König von Syrien statt auf Jehova.","r":{"t":"2. Chronika 16:7-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/16/#v14016007-v14016009"}}],"lesson":"","family":{"father":"abija","mother":"","spouses":[],"children":["josaphat"],"siblings":[]},"related":[],"events":[],"books":[],"refs":[{"t":"1. Könige 15:9-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015009-v11015024"},{"t":"2. Chronika 14:1–16:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/14/#v14014001-v14016014"}],"sources":[{"title":"Asa – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000397"}]},{"id":"asarja","name":"Asarja","alt":["Abednego"],"sex":"m","tags":[],"role":"Gefährte Daniels (Abednego)","eras":["exil"],"dates":[{"label":"Zeit","value":"617 v. u. Z. nach Babylon gebracht"}],"year":-619,"meaning":"„Geholfen hat Jehova“","summary":"Asarja war einer der hebräischen jungen Männer, die 617 v. u. Z. gefangen genommen wurden. Sein Name wurde in Abednego geändert, was wahrscheinlich „Diener des Nebo“ bedeutet. Nach einer dreijährigen Ausbildung war er mit seinen Gefährten den Weisen Babylons weit überlegen. Die schwerste Prüfung seiner Loyalität bestand er im übermäßig geheizten Feuerofen.","facts":[{"t":"Sein Name wurde auf Abednego abgeändert.","r":{"t":"Daniel 1:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001007"}},{"t":"Er erhielt das Amt eines Verwalters.","r":{"t":"Daniel 2:49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002049"}},{"t":"Er wurde in den Feuerofen geworfen und gerettet.","r":{"t":"Daniel 3:19-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003019-v27003027"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["daniel","hananja","mischael"],"events":["daniel-in-babylon","feuerofen"],"books":[],"refs":[{"t":"Daniel 1:6-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001006-v27001020"},{"t":"Daniel 3:12-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003012-v27003030"}],"sources":[{"title":"Asarja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000486"}]},{"id":"athalja","name":"Athalja","alt":[],"sex":"f","tags":["koenig"],"role":"Königin von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 905–898 v. u. Z. (6 Jahre)"}],"year":-905,"meaning":"","summary":"Athalja war die Tochter Ahabs und Isebels und wurde aus politischen Gründen mit Joram von Juda verheiratet. Nach dem Tod ihres Sohnes Ahasja ließ sie die königliche Nachkommenschaft umbringen und riss den Thron an sich. Doch der kleine Joas wurde gerettet; nach sechs Jahren stürzte der Hohe Priester Jehojada Athalja, und sie wurde getötet.","facts":[{"t":"Sie war eine Enkelin Omris.","r":{"t":"2. Könige 8:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/8/#v12008026"}},{"t":"Sie vernichtete die königliche Nachkommenschaft.","r":{"t":"2. Könige 11:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011001"}},{"t":"Joas wurde sechs Jahre im Haus Jehovas versteckt.","r":{"t":"2. Könige 11:2, 3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011002"}},{"t":"Sie wurde auf Jehojadas Befehl getötet.","r":{"t":"2. Könige 11:13-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011013-v12011016"}}],"lesson":"","family":{"father":"ahab","mother":"isebel","spouses":["joram-juda"],"children":["ahasja-juda"],"siblings":["joram-israel","ahasja-israel"]},"related":["jojada","joas-juda"],"events":["athalja-und-joas"],"books":[],"refs":[{"t":"2. Könige 11:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011001-v12011020"},{"t":"2. Chronika 22:10–23:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/22/#v14022010-v14023021"}],"sources":[{"title":"Athalja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000457"}]},{"id":"barak","name":"Barak","alt":[],"sex":"m","tags":["richter"],"role":"Heerführer gegen Sisera","eras":["richter"],"dates":[],"year":-1300,"meaning":"„Blitz“","summary":"Barak, der Sohn Abinoams aus Kedesch in Naphtali, wurde von Jehova eingesetzt, als Israel 20 Jahre unter dem Kanaaniterkönig Jabin litt. Er bestand darauf, dass die Prophetin Debora ihn begleitete. Mit 10 000 Mann besiegte er vom Berg Tabor aus das gut bewaffnete Heer Siseras. Hebräer 11 nennt ihn unter den Vorbildern des Glaubens.","facts":[{"t":"Israel war 20 Jahre von Jabin bedrückt.","r":{"t":"Richter 4:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004001-v7004003"}},{"t":"Er wollte nur gehen, wenn Debora mitkam.","r":{"t":"Richter 4:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004008"}},{"t":"Jehova gab Israel einen unvergesslichen Sieg.","r":{"t":"Psalm 83:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/psalmen/83/#v19083009"}},{"t":"Er wird unter den Glaubensvorbildern genannt.","r":{"t":"Hebräer 11:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011032"}}],"lesson":"","family":{"father":"Abinoam","mother":"","spouses":[],"children":[],"siblings":[]},"related":["debora","jael"],"events":["debora-und-barak"],"books":[],"refs":[{"t":"Richter 4:1-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004001-v7004024"},{"t":"Richter 5:1-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/5/#v7005001-v7005031"},{"t":"Hebräer 11:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011032"}],"sources":[{"title":"Barak – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000559"}]},{"id":"barnabas","name":"Barnabas","alt":["Joseph"],"sex":"m","tags":["juenger"],"role":"Missionar, Gefährte des Paulus","eras":["versammlung"],"dates":[],"year":33,"meaning":"„Sohn des Trostes“","summary":"Barnabas hieß eigentlich Joseph und war ein Levit aus Zypern; die Apostel gaben ihm den Beinamen Barnabas. Kurz nach Pfingsten verkaufte er ein Feld und gab den Erlös den Aposteln. Er war warmherzig und ermunterte andere. Er stellte Paulus den Aposteln vor, wirkte mit ihm in Antiochia und unternahm mit ihm die erste Missionsreise. Später nahm er seinen Cousin Markus mit nach Zypern.","facts":[{"t":"Er verkaufte ein Feld und gab das Geld den Aposteln.","r":{"t":"Apostelgeschichte 4:36, 37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/4/#v44004036"}},{"t":"Er setzte sich für den neubekehrten Saulus ein.","r":{"t":"Apostelgeschichte 9:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009027"}},{"t":"Er war „ein guter Mann und voll heiligem Geist und Glauben“.","r":{"t":"Apostelgeschichte 11:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/11/#v44011024"}},{"t":"Er trennte sich von Paulus wegen Markus.","r":{"t":"Apostelgeschichte 15:37-39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015037-v44015039"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus","markus"],"events":["erste-missionsreise","beschneidungsfrage"],"books":[],"refs":[{"t":"Apostelgeschichte 4:36, 37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/4/#v44004036"},{"t":"Apostelgeschichte 11:22-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/11/#v44011022-v44011026"},{"t":"Apostelgeschichte 13:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/13/#v44013001-v44013004"}],"sources":[{"title":"Barnabas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000566"}]},{"id":"bartholomaeus","name":"Bartholomäus","alt":["Nathanael"],"sex":"m","tags":["apostel"],"role":"Apostel (Nathanael)","eras":["jesus"],"dates":[],"year":29,"meaning":"„Sohn des Tolmai“","summary":"Bartholomäus war einer der zwölf Apostel und wird allgemein mit Nathanael gleichgesetzt: Matthäus und Lukas nennen ihn zusammen mit Philippus, so wie Johannes Nathanael zusammen mit Philippus nennt. Philippus brachte ihn zu Jesus, und Nathanael erkannte Jesus als Sohn Gottes und König Israels.","facts":[{"t":"Jesus nannte ihn einen Israeliten ohne Trug.","r":{"t":"Johannes 1:47","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001047"}},{"t":"„Du bist der Sohn Gottes, du bist König von Israel.“","r":{"t":"Johannes 1:49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001049"}},{"t":"Er steht in den Apostellisten neben Philippus.","r":{"t":"Matthäus 10:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/10/#v40010003"}}],"lesson":"","family":{"father":"Tolmai","mother":"","spouses":[],"children":[],"siblings":[]},"related":["philippus-apostel"],"events":["erste-juenger","wahl-der-apostel"],"books":[],"refs":[{"t":"Johannes 1:45-51","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001045-v43001051"},{"t":"Lukas 6:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006014"}],"sources":[{"title":"Bartholomäus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000569"}]},{"id":"baruch","name":"Baruch","alt":[],"sex":"m","tags":[],"role":"Sekretär Jeremias","eras":["geteilt"],"dates":[{"label":"Zeit","value":"625–607 v. u. Z."}],"year":-625,"meaning":"„Gesegnet“","summary":"Baruch, der Sohn Nerijas, war der Sekretär des Propheten Jeremia. Ab dem 4. Jahr König Jojakims (625 v. u. Z.) schrieb er die Botschaft vom Untergang Jerusalems nieder, die Jeremia ihm diktierte, und las sie im folgenden Jahr am Eingang des Tempels öffentlich vor. Als der König die Rolle verbrannte, schrieb er sie erneut.","facts":[{"t":"Er schrieb Jeremias Worte in eine Buchrolle.","r":{"t":"Jeremia 36:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/36/#v24036004"}},{"t":"Er las die Rolle vor dem Volk im Tempel vor.","r":{"t":"Jeremia 36:8-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/36/#v24036008-v24036010"}},{"t":"Jehova ermahnte ihn, nicht nach großen Dingen zu trachten.","r":{"t":"Jeremia 45:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/45/#v24045001-v24045005"}}],"lesson":"","family":{"father":"Nerija","mother":"","spouses":[],"children":[],"siblings":["Seraja"]},"related":["jeremia","jojakim"],"events":[],"books":[],"refs":[{"t":"Jeremia 36:1-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/36/#v24036001-v24036032"},{"t":"Jeremia 45:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/45/#v24045001-v24045005"}],"sources":[{"title":"Baruch – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000571"}]},{"id":"bascha","name":"Bascha","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 975 v. u. Z. (24 Jahre)"}],"year":-975,"meaning":"","summary":"Bascha aus dem Stamm Issachar riss den Thron an sich, indem er Nadab tötete, und schlug – wie prophezeit – das ganze Haus Jerobeams nieder. Doch er setzte den Kälberkult fort, weshalb auch seinem Haus der Untergang angekündigt wurde. Er führte Krieg gegen Asa von Juda.","facts":[{"t":"Er tötete Nadab und das Haus Jerobeams.","r":{"t":"1. Könige 15:27-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015027-v11015029"}},{"t":"Der Prophet Jehu kündigte seinem Haus Unglück an.","r":{"t":"1. Könige 16:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016001-v11016004"}},{"t":"Er führte Krieg gegen Asa von Juda.","r":{"t":"1. Könige 15:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015016"}}],"lesson":"","family":{"father":"Ahija","mother":"","spouses":[],"children":["ela"],"siblings":[]},"related":["asa"],"events":[],"books":[],"refs":[{"t":"1. Könige 15:27–16:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015027-v11016007"}],"sources":[{"title":"Bascha – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000528"}]},{"id":"batseba","name":"Bathseba","alt":["Batseba"],"sex":"f","tags":["vorfahr-jesu"],"role":"Frau Davids, Mutter Salomos","eras":["koenigreich"],"dates":[],"year":-1060,"meaning":"„Tochter des Überflusses“","summary":"Bathseba war zuerst die Frau des Hethiters Uria, eines der starken Männer Davids. David sah sie vom Dach seines Palastes aus, beging mit ihr Ehebruch und ließ ihren Mann im Krieg umkommen. Danach wurde sie Davids Frau. Ihr erstes Kind starb; später gebar sie Salomo, der Davids Nachfolger wurde.","facts":[{"t":"David sah sie vom Dach aus, wie sie sich badete.","r":{"t":"2. Samuel 11:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011002-v10011004"}},{"t":"Nach Urias Tod wurde sie Davids Frau.","r":{"t":"2. Samuel 11:26, 27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011026"}},{"t":"Sie gebar Salomo, den Jehova liebte.","r":{"t":"2. Samuel 12:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/12/#v10012024"}},{"t":"Mit Nathan sorgte sie dafür, dass Salomo König wurde.","r":{"t":"1. Könige 1:11-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/1/#v11001011-v11001031"}}],"lesson":"","family":{"father":"Eliam","mother":"","spouses":["uria","david"],"children":["salomo","Schimea","Schobab","Nathan"],"siblings":[]},"related":["nathan"],"events":["david-und-batseba","salomo-wird-koenig"],"books":[],"refs":[{"t":"2. Samuel 11:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011001-v10011027"},{"t":"2. Samuel 12:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/12/#v10012024"},{"t":"1. Könige 1:11-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/1/#v11001011-v11001031"},{"t":"Matthäus 1:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001006"}],"sources":[{"title":"Bathseba – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000581"}]},{"id":"belsazar","name":"Belsazar","alt":[],"sex":"m","tags":["herrscher"],"role":"Mitregent in Babylon","eras":["exil"],"dates":[{"label":"Gestorben","value":"539 v. u. Z."}],"year":-545,"meaning":"„Schütze sein Leben“ (akkadisch)","summary":"Belsazar, der erstgeborene Sohn Nabonids, war in den letzten Jahren des Babylonischen Reiches Mitregent und wird in der Bibel „König von Babylon“ genannt. Archäologische Funde haben das bestätigt. In der Nacht des Falls Babylons 539 v. u. Z. hielt er ein großes Fest und trank aus den Gefäßen des Tempels Jehovas; noch in derselben Nacht wurde er getötet.","facts":[{"t":"Er veranstaltete ein Festmahl für 1000 seiner Großen.","r":{"t":"Daniel 5:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005001"}},{"t":"Er ließ aus den Gefäßen des Tempels trinken.","r":{"t":"Daniel 5:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005002-v27005004"}},{"t":"Eine Hand schrieb an die Wand.","r":{"t":"Daniel 5:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005005"}},{"t":"In derselben Nacht wurde er getötet.","r":{"t":"Daniel 5:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005030"}}],"lesson":"","family":{"father":"Nabonid","mother":"","spouses":[],"children":[],"siblings":[]},"related":["daniel"],"events":["fall-babylons"],"books":[],"refs":[{"t":"Daniel 5:1-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005001-v27005031"}],"sources":[{"title":"Belsazar – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000628"}]},{"id":"benjamin","name":"Benjamin","alt":["Ben-Oni"],"sex":"m","tags":[],"role":"Jüngster Sohn Jakobs","eras":["patriarchen"],"dates":[],"year":-1755,"meaning":"„Sohn der rechten Hand“","summary":"Benjamin war der zwölfte Sohn Jakobs und Josephs einziger Vollbruder – anscheinend der einzige Sohn Jakobs, der in Kanaan geboren wurde. Seine Mutter Rahel starb bei seiner Geburt und nannte ihn Ben-Oni („Sohn meiner Trauer“); Jakob gab ihm den Namen Benjamin. Nach Josephs Verschwinden war er der Liebling seines Vaters.","facts":[{"t":"Rahel starb bei seiner Geburt auf dem Weg nach Ephrath (Bethlehem).","r":{"t":"1. Mose 35:16-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/35/#v1035016-v1035019"}},{"t":"Jakob ließ ihn nur sehr ungern mit nach Ägypten ziehen.","r":{"t":"1. Mose 42:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/42/#v1042004"}},{"t":"Joseph ließ seinen Becher in Benjamins Sack verstecken, um die Brüder zu prüfen.","r":{"t":"1. Mose 44:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/44/#v1044001-v1044012"}}],"lesson":"","family":{"father":"jakob","mother":"rahel","spouses":[],"children":[],"siblings":["joseph","ruben","simeon","levi","juda","dina"]},"related":[],"events":["joseph-gibt-sich-zu-erkennen"],"books":[],"refs":[{"t":"1. Mose 35:16-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/35/#v1035016-v1035019"},{"t":"1. Mose 43:29-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/43/#v1043029-v1043034"},{"t":"1. Mose 44:1-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/44/#v1044001-v1044034"}],"sources":[{"title":"Benjamin – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000640"}]},{"id":"bileam","name":"Bileam","alt":[],"sex":"m","tags":[],"role":"Wahrsager aus Pethor","eras":["aegypten"],"dates":[{"label":"Zeit","value":"15. Jahrhundert v. u. Z."}],"year":-1474,"meaning":"„Verschlinger“ (vielleicht)","summary":"Bileam, der Sohn Beors, wohnte in Pethor am oberen Euphrat und kannte Jehova. Der Moabiterkönig Balak bot ihm Lohn, damit er Israel verfluche. Unterwegs stellte sich ihm Jehovas Engel in den Weg, und seine Eselin begann zu sprechen. Statt zu fluchen, musste Bileam Israel segnen – doch später riet er, Israel zur Sünde zu verleiten.","facts":[{"t":"Er lehnte die erste Abordnung Balaks ab.","r":{"t":"4. Mose 22:5-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/22/#v4022005-v4022014"}},{"t":"Seine Eselin sprach durch ein Wunder zu ihm.","r":{"t":"4. Mose 22:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/22/#v4022028"}},{"t":"Er segnete Israel, statt es zu verfluchen.","r":{"t":"4. Mose 23:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/23/#v4023011"}},{"t":"Er riet, Israel zur Untreue gegenüber Jehova zu verleiten.","r":{"t":"4. Mose 31:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/31/#v4031016"}}],"lesson":"","family":{"father":"Beor","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["bileam-und-balak"],"books":[],"refs":[{"t":"4. Mose 22:1–24:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/22/#v4022001-v4024025"},{"t":"2. Petrus 2:15, 16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-petrus/2/#v61002015"},{"t":"Offenbarung 2:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/2/#v66002014"}],"sources":[{"title":"Bileam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000543"}]},{"id":"boas","name":"Boas","alt":[],"sex":"m","tags":["vorfahr-jesu"],"role":"Grundbesitzer in Bethlehem, Mann Ruths","eras":["richter"],"dates":[{"label":"Zeit","value":"etwa 14. Jahrhundert v. u. Z."}],"year":-1350,"meaning":"„In Stärke“ (vielleicht)","summary":"Boas war ein vermögender Grundbesitzer in Bethlehem, der Sohn Salmons und Rahabs. Als Ruth auf seinem Feld Ähren las, behandelte er sie freundlich und großzügig. Als naher Verwandter Elimelechs heiratete er sie als Rückkäufer und wurde der Vater Obeds – ein Glied in der Abstammungslinie des Messias.","facts":[{"t":"Er war ein „vermögender Mann“ aus der Familie Elimelechs.","r":{"t":"Ruth 2:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/2/#v8002001"}},{"t":"Er sorgte dafür, dass Ruth genug auflesen konnte.","r":{"t":"Ruth 2:15, 16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/2/#v8002015"}},{"t":"Am Stadttor regelte er den Rückkauf rechtmäßig.","r":{"t":"Ruth 4:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/4/#v8004001-v8004010"}},{"t":"Er steht im Geschlechtsregister Jesu.","r":{"t":"Matthäus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001005"}}],"lesson":"","family":{"father":"Salmon","mother":"rahab","spouses":["ruth"],"children":["Obed"],"siblings":[]},"related":["noomi"],"events":["ruth-und-noomi"],"books":[],"refs":[{"t":"Ruth 2:1-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/2/#v8002001-v8002023"},{"t":"Ruth 4:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/4/#v8004001-v8004013"},{"t":"Matthäus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001005"}],"sources":[{"title":"Boas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000779"}]},{"id":"cyrus","name":"Cyrus","alt":["Kyros","Cyrus der Große"],"sex":"m","tags":["herrscher"],"role":"König von Persien, Eroberer Babylons","eras":["exil","rueckkehr"],"dates":[{"label":"Zeit","value":"eroberte Babylon 539 v. u. Z."}],"year":-539,"meaning":"","summary":"Cyrus der Große begründete das Persische Reich und eroberte 539 v. u. Z. Babylon. Jesaja hatte ihn rund 200 Jahre vorher mit Namen als den angekündigt, der Jerusalem wieder aufbauen lassen würde. In seinem ersten Jahr erließ er die Verordnung, die den Juden die Rückkehr und den Wiederaufbau des Tempels erlaubte.","facts":[{"t":"Jesaja nannte ihn mit Namen.","r":{"t":"Jesaja 44:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/44/#v23044028"}},{"t":"Er zog am 3. Marchäschwan 539 v. u. Z. in Babylon ein."},{"t":"Er gestattete den Juden die Rückkehr und den Tempelbau.","r":{"t":"Esra 1:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/1/#v15001001-v15001004"}},{"t":"Er gab die Tempelgeräte zurück.","r":{"t":"Esra 1:7, 8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/1/#v15001007"}}],"lesson":"","family":{"father":"Kambyses","mother":"","spouses":[],"children":[],"siblings":[]},"related":["daniel","darius-der-meder","serubbabel"],"events":["fall-babylons","erlass-des-cyrus"],"books":[],"refs":[{"t":"Jesaja 44:28–45:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/44/#v23044028-v23045003"},{"t":"Esra 1:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/1/#v15001001-v15001011"},{"t":"2. Chronika 36:22, 23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/36/#v14036022"}],"sources":[{"title":"Cyrus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001102"}]},{"id":"daniel","name":"Daniel","alt":["Beltschazzar"],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet in Babylon","eras":["exil"],"dates":[{"label":"Zeit","value":"617 nach Babylon gebracht; bis mindestens 536 v. u. Z. tätig"}],"year":-620,"meaning":"„Mein Richter ist Gott“","summary":"Daniel, ein bedeutender Prophet aus dem Stamm Juda, wurde 617 v. u. Z. als junger Mann nach Babylon gebracht und erhielt den Namen Beltschazzar. Er weigerte sich, sich mit den Speisen des Königs zu verunreinigen, und Jehova gab ihm Einsicht in Visionen und Träume. Er blieb bis zum Fall Babylons am Hof, diente danach unter den Persern und wurde aus der Löwengrube gerettet. Er schrieb das gleichnamige Bibelbuch.","facts":[{"t":"Er bat darum, nur Gemüse und Wasser zu bekommen.","r":{"t":"Daniel 1:8-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001008-v27001016"}},{"t":"Er war zehnmal besser als alle Weisen Babylons.","r":{"t":"Daniel 1:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001020"}},{"t":"Er deutete Nebukadnezars Traum vom Standbild.","r":{"t":"Daniel 2:24-45","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002024-v27002045"}},{"t":"Er deutete die Schrift an der Wand.","r":{"t":"Daniel 5:25-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005025-v27005028"}},{"t":"Jehovas Engel rettete ihn aus der Löwengrube.","r":{"t":"Daniel 6:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006022"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["hananja","mischael","asarja","nebukadnezar","belsazar","darius-der-meder","cyrus"],"events":["daniel-in-babylon","traum-vom-standbild","nebukadnezars-wahnsinn","fall-babylons","loewengrube","erlass-des-cyrus"],"books":["Daniel"],"refs":[{"t":"Daniel 1:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001001-v27001021"},{"t":"Daniel 6:1-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006001-v27006028"},{"t":"Daniel 9:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/9/#v27009001-v27009027"}],"sources":[{"title":"Daniel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001117"}]},{"id":"darius-der-meder","name":"Darius der Meder","alt":["Darius"],"sex":"m","tags":["herrscher"],"role":"König der Chaldäer nach dem Fall Babylons","eras":["exil"],"dates":[{"label":"Zeit","value":"ab 539 v. u. Z."}],"year":-539,"meaning":"","summary":"Darius der Meder wurde nach der Eroberung Babylons durch das Heer des Persers Cyrus König der Chaldäer – damals etwa 62 Jahre alt. Er ordnete die Verwaltung mit 120 Satrapen und drei hohen Beamten, zu denen auch Daniel gehörte. Neider brachten ihn dazu, ein Gesetz zu erlassen, durch das Daniel in die Löwengrube kam; nach Daniels Rettung ließ er die Verschwörer bestrafen.","facts":[{"t":"Er empfing das Königreich mit etwa 62 Jahren.","r":{"t":"Daniel 5:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005031"}},{"t":"Er setzte 120 Satrapen und drei hohe Beamte ein.","r":{"t":"Daniel 6:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006001"}},{"t":"Er hoffte, dass Daniels Gott ihn retten würde.","r":{"t":"Daniel 6:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006016"}},{"t":"Er gebot Ehrfurcht vor dem Gott Daniels.","r":{"t":"Daniel 6:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006026"}}],"lesson":"","family":{"father":"Ahasverus","mother":"","spouses":[],"children":[],"siblings":[]},"related":["daniel","cyrus"],"events":["fall-babylons","loewengrube"],"books":[],"refs":[{"t":"Daniel 5:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005031"},{"t":"Daniel 6:1-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006001-v27006028"},{"t":"Daniel 9:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/9/#v27009001"}],"sources":[{"title":"Darius – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001124"}]},{"id":"david","name":"David","alt":[],"sex":"m","tags":["koenig","prophet","schreiber","vorfahr-jesu"],"role":"König Israels, Psalmendichter","eras":["koenigreich"],"dates":[{"label":"Geboren","value":"1107 v. u. Z."},{"label":"Regierung","value":"1077–1037 v. u. Z. (40 Jahre)"}],"year":-1107,"meaning":"„Geliebter“ (wahrscheinlich)","summary":"David, der jüngste der acht Söhne Isais aus Bethlehem, war Hirte, Musiker, Dichter, Krieger, Prophet und König. Als junger Mann besiegte er Goliath; später musste er jahrelang vor Saul fliehen. 1077 v. u. Z. wurde er König in Hebron, 1070 v. u. Z. über ganz Israel, und er machte Jerusalem zur Hauptstadt. Jehova schloss mit ihm einen Bund für ein ewiges Königreich. Trotz schwerer Sünden bereute er aufrichtig und vertraute stets auf Jehova.","facts":[{"t":"Samuel salbte ihn als Jüngsten der Söhne Isais.","r":{"t":"1. Samuel 16:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/16/#v9016011-v9016013"}},{"t":"Er besiegte den Riesen Goliath im Namen Jehovas.","r":{"t":"1. Samuel 17:45-51","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017045-v9017051"}},{"t":"Mit 30 Jahren wurde er in Hebron König über Juda.","r":{"t":"2. Samuel 5:3-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/5/#v10005003-v10005005"}},{"t":"Er eroberte Jerusalem und machte es zur Hauptstadt.","r":{"t":"2. Samuel 5:6-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/5/#v10005006-v10005009"}},{"t":"Nach seiner Sünde mit Bathseba bereute er zutiefst.","r":{"t":"Psalm 51:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/psalmen/51/#v19051001-v19051004"}},{"t":"Sein Name steht in den Überschriften von 73 Psalmen."}],"lesson":"","family":{"father":"Isai","mother":"","spouses":["michal","abigail","batseba","Ahinoam"],"children":["absalom","salomo","Amnon","Adonia","Tamar"],"siblings":[]},"related":["samuel","jonathan","nathan","joab","saul"],"events":["david-wird-gesalbt","david-und-goliath","david-flieht-vor-saul","sauls-tod","david-koenig-in-hebron","david-erobert-jerusalem","bundeslade-nach-jerusalem","bund-mit-david","david-und-batseba","absaloms-aufstand","salomo-wird-koenig"],"books":["Psalm (viele)"],"refs":[{"t":"1. Samuel 16:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/16/#v9016001-v9016013"},{"t":"2. Samuel 7:8-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/7/#v10007008-v10007016"},{"t":"Psalm 51:1-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/psalmen/51/#v19051001-v19051019"},{"t":"Apostelgeschichte 13:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/13/#v44013022"}],"sources":[{"title":"David – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001130"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"debora","name":"Debora","alt":[],"sex":"f","tags":["prophet","richter"],"role":"Prophetin in Israel","eras":["richter"],"dates":[],"year":-1300,"meaning":"„Biene“","summary":"Debora war eine Prophetin in Israel, die Frau Lappidoths. Sie wohnte unter einer Palme zwischen Rama und Bethel, und die Israeliten kamen zu ihr, um sich richten zu lassen. Jehova gebrauchte sie, um Barak zu beauftragen, gegen das Heer des Kanaaniterkönigs Jabin unter Sisera zu kämpfen. Sie ging mit Barak in die Schlacht und sagte voraus, dass eine Frau die Ehre des Sieges erhalten würde.","facts":[{"t":"Die Israeliten kamen zu ihr, um sich richten zu lassen.","r":{"t":"Richter 4:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004004"}},{"t":"Sie rief Barak auf, mit 10 000 Mann gegen Sisera zu ziehen.","r":{"t":"Richter 4:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004006"}},{"t":"Sie sagte voraus, dass eine Frau Sisera besiegen würde.","r":{"t":"Richter 4:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004009"}},{"t":"Mit Barak sang sie ein Siegeslied, das Jehova alle Ehre gab.","r":{"t":"Richter 5:1-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/5/#v7005001-v7005031"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Lappidoth"],"children":[],"siblings":[]},"related":["barak","jael"],"events":["zeit-der-richter","debora-und-barak"],"books":[],"refs":[{"t":"Richter 4:4-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004004-v7004010"},{"t":"Richter 5:1-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/5/#v7005001-v7005031"}],"sources":[{"title":"Debora – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001138"}]},{"id":"delila","name":"Delila","alt":[],"sex":"f","tags":[],"role":"Verriet Simson an die Philister","eras":["richter"],"dates":[],"year":-1130,"meaning":"„Herabhängend“ (vielleicht)","summary":"Delila wohnte im Wildbachtal Sorek; Simson verliebte sich gegen Ende seiner 20-jährigen Richterzeit in sie. Die Achsenherren der Philister versprachen ihr je 1100 Silberstücke, wenn sie das Geheimnis seiner Kraft herausfände. Nach mehreren Versuchen drängte sie ihn so lange, bis er es ihr verriet – und lieferte ihn seinen Feinden aus.","facts":[{"t":"Jeder Achsenherr der Philister bot ihr 1100 Silberstücke.","r":{"t":"Richter 16:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016005"}},{"t":"Dreimal gab Simson ihr eine irreführende Antwort.","r":{"t":"Richter 16:6-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016006-v7016014"}},{"t":"Sie drängte ihn täglich, bis er sein Geheimnis verriet.","r":{"t":"Richter 16:15-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016015-v7016017"}},{"t":"Sie ließ ihm das Haar abschneiden und rief die Philister.","r":{"t":"Richter 16:19-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016019-v7016021"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["simson"],"events":["simson-und-die-philister"],"books":[],"refs":[{"t":"Richter 16:4-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016004-v7016021"}],"sources":[{"title":"Delila – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001149"}]},{"id":"dina","name":"Dina","alt":[],"sex":"f","tags":[],"role":"Tochter Jakobs","eras":["patriarchen"],"dates":[],"year":-1765,"meaning":"„Gerichtet“ (d. h. gerechtfertigt)","summary":"Dina war die Tochter Jakobs und Leas und wurde in Haran geboren. Als die Familie bei Sichem zeltete, besuchte sie unklugerweise immer wieder die jungen Kanaaniterinnen. Dabei tat ihr Sichem, der Sohn eines Hiwiterfürsten, Gewalt an. Ihre Brüder Simeon und Levi rächten sie, indem sie die Männer der Stadt töteten.","facts":[{"t":"Sie wurde in Haran geboren.","r":{"t":"1. Mose 30:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/30/#v1030021"}},{"t":"Sie besuchte gewohnheitsmäßig die jungen Frauen des Landes.","r":{"t":"1. Mose 34:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/34/#v1034001"}},{"t":"Sichem tat ihr Gewalt an.","r":{"t":"1. Mose 34:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/34/#v1034002"}},{"t":"Simeon und Levi rächten sie.","r":{"t":"1. Mose 34:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/34/#v1034025"}}],"lesson":"","family":{"father":"jakob","mother":"lea","spouses":[],"children":[],"siblings":["ruben","simeon","levi","juda","joseph","benjamin"]},"related":[],"events":[],"books":[],"refs":[{"t":"1. Mose 34:1-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/34/#v1034001-v1034031"}],"sources":[{"title":"Dina – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001182"}]},{"id":"tabitha","name":"Dorkas","alt":["Tabitha"],"sex":"f","tags":["juenger"],"role":"Christin in Joppe, von Petrus auferweckt","eras":["versammlung"],"dates":[{"label":"Zeit","value":"gestorben und auferweckt 36 u. Z."}],"year":36,"meaning":"„Gazelle“ (Dorkas und Tabitha)","summary":"Dorkas, auf Aramäisch Tabitha, gehörte zur Versammlung in Joppe. Sie tat viel Gutes und nähte unter anderem Kleidung für bedürftige Witwen. Sie ist die einzige Frau, die in der Bibel ausdrücklich „Jüngerin“ genannt wird. Als sie 36 u. Z. starb, holten die Jünger Petrus aus Lydda. Er betete und sagte: „Tabitha, steh auf!“ – die erste berichtete Auferweckung durch einen Apostel. Daraufhin wurden in Joppe viele gläubig.","facts":[{"t":"Sie war reich an guten Taten und Gaben der Barmherzigkeit.","r":{"t":"Apostelgeschichte 9:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009036"}},{"t":"Die Witwen zeigten die Kleider, die sie gemacht hatte.","r":{"t":"Apostelgeschichte 9:39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009039"}},{"t":"Petrus sagte: „Tabitha, steh auf!“","r":{"t":"Apostelgeschichte 9:40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009040"}},{"t":"Viele in Joppe wurden gläubig.","r":{"t":"Apostelgeschichte 9:42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009042"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["petrus"],"events":[],"books":[],"refs":[{"t":"Apostelgeschichte 9:36-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009036-v44009042"}],"sources":[{"title":"Dorkas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001214"}]},{"id":"ebed-melech","name":"Ebed-Melech","alt":[],"sex":"m","tags":[],"role":"Äthiopier, rettete Jeremia","eras":["geteilt"],"dates":[],"year":-608,"meaning":"„Diener des Königs“","summary":"Ebed-Melech war ein äthiopischer Eunuch im Haus König Zedekias. Als die Fürsten Jeremia in eine Zisterne warfen, um ihn verhungern zu lassen, setzte er sich trotz der Gefahr beim König für den Propheten ein und zog ihn mit Seilen heraus. Jehova versprach ihm, ihn bei der Zerstörung Jerusalems zu retten, weil er auf ihn vertraut hatte.","facts":[{"t":"Er sprach beim König für Jeremia vor.","r":{"t":"Jeremia 38:7-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/38/#v24038007-v24038009"}},{"t":"Er zog Jeremia mit Seilen und alten Lumpen aus der Zisterne.","r":{"t":"Jeremia 38:10-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/38/#v24038010-v24038013"}},{"t":"Jehova versprach ihm Rettung, weil er auf ihn vertraute.","r":{"t":"Jeremia 39:15-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/39/#v24039015-v24039018"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jeremia","zedekia"],"events":["zerstoerung-jerusalems-607"],"books":[],"refs":[{"t":"Jeremia 38:7-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/38/#v24038007-v24038013"},{"t":"Jeremia 39:15-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/39/#v24039015-v24039018"}],"sources":[{"title":"Ebed-Melech – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001247"}]},{"id":"ehud","name":"Ehud","alt":[],"sex":"m","tags":["richter"],"role":"Richter, Befreier von Moab","eras":["richter"],"dates":[],"year":-1400,"meaning":"","summary":"Ehud, ein linkshändiger Benjaminiter, wurde von Gott erwählt, Israel aus 18 Jahren Knechtschaft unter König Eglon von Moab zu befreien. Unter dem Vorwand, Tribut zu überbringen, gelangte er zu Eglon und tötete ihn mit einem kurzen zweischneidigen Schwert. Danach führte er Israel zum Sieg über Moab.","facts":[{"t":"Israel war 18 Jahre Eglon von Moab unterworfen.","r":{"t":"Richter 3:12-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/3/#v7003012-v7003014"}},{"t":"Jehova erweckte ihn als „Retter“.","r":{"t":"Richter 3:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/3/#v7003015"}},{"t":"Er tötete Eglon mit einem zweischneidigen Schwert.","r":{"t":"Richter 3:16-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/3/#v7003016-v7003022"}},{"t":"Danach hatte das Land 80 Jahre Ruhe.","r":{"t":"Richter 3:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/3/#v7003030"}}],"lesson":"","family":{"father":"Gera","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["zeit-der-richter"],"books":[],"refs":[{"t":"Richter 3:12-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/3/#v7003012-v7003030"}],"sources":[{"title":"Ehud – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001268"}]},{"id":"ela","name":"Ela","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 952 v. u. Z. (2 Jahre)"}],"year":-952,"meaning":"","summary":"Ela, der Sohn Baschas, regierte in Tirza einen Teil von zwei Jahren. Als er betrunken war, wurde er von Simri, einem Obersten seiner Wagen, ermordet. Simri rottete daraufhin das Haus Baschas aus, wie Jehova es angekündigt hatte.","facts":[{"t":"Er regierte in Tirza.","r":{"t":"1. Könige 16:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016008"}},{"t":"Simri tötete ihn, als er betrunken war.","r":{"t":"1. Könige 16:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016009"}},{"t":"Das Haus Baschas wurde ausgerottet.","r":{"t":"1. Könige 16:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016011-v11016013"}}],"lesson":"","family":{"father":"bascha","mother":"","spouses":[],"children":[],"siblings":[]},"related":["simri"],"events":[],"books":[],"refs":[{"t":"1. Könige 16:8-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016008-v11016014"}],"sources":[{"title":"Ela – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001273"}]},{"id":"eli","name":"Eli","alt":[],"sex":"m","tags":["priester","richter"],"role":"Hoher Priester in Silo","eras":["richter"],"dates":[{"label":"Wirken","value":"richtete Israel 40 Jahre"},{"label":"Alter","value":"98 Jahre"}],"year":-1220,"meaning":"„Hinaufgestiegen“","summary":"Eli, ein Nachkomme Aarons, war Hoher Priester und richtete Israel 40 Jahre. In seinen Tagen war das Wort Jehovas selten. Seine Söhne Hophni und Pinehas dienten als Priester, waren aber „nichtsnutzige Männer“, und Eli war zu nachsichtig mit ihnen. Als er mit 98 Jahren hörte, dass die Bundeslade erbeutet und seine Söhne gefallen waren, stürzte er und starb.","facts":[{"t":"Er hielt die betende Hanna zunächst für betrunken.","r":{"t":"1. Samuel 1:12-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001012-v9001014"}},{"t":"Seine Söhne missbrauchten ihr Priesteramt.","r":{"t":"1. Samuel 2:12-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/2/#v9002012-v9002017"}},{"t":"Er ehrte seine Söhne mehr als Jehova.","r":{"t":"1. Samuel 2:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/2/#v9002029"}},{"t":"Er starb, als er vom Verlust der Lade hörte.","r":{"t":"1. Samuel 4:15-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/4/#v9004015-v9004018"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":["Hophni","Pinehas"],"siblings":[]},"related":["samuel","hanna"],"events":["hannas-gebet","bundeslade-erbeutet"],"books":[],"refs":[{"t":"1. Samuel 2:12-36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/2/#v9002012-v9002036"},{"t":"1. Samuel 3:11-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/3/#v9003011-v9003014"},{"t":"1. Samuel 4:12-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/4/#v9004012-v9004018"}],"sources":[{"title":"Eli – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001290"}]},{"id":"elia","name":"Elia","alt":[],"sex":"m","tags":["prophet"],"role":"Prophet in Israel","eras":["geteilt"],"dates":[{"label":"Wirken","value":"ab der Zeit Ahabs (um 940 v. u. Z.) bis nach 913 v. u. Z."}],"year":-940,"meaning":"„Mein Gott ist Jehova“","summary":"Elia aus Tischbe war einer der bedeutendsten Propheten Israels. Er wirkte in einer Zeit, in der Ahab und Isebel den Baalskult förderten. Er kündigte eine Dürre an, bewies auf dem Berg Karmel, dass Jehova der wahre Gott ist, und erweckte einen Toten. Laut jw.org wurde er im Windsturm nicht in den Himmel zu Gott aufgenommen, sondern mit einem neuen Auftrag an einen anderen Ort versetzt – Jahre später schrieb er noch einen Brief an König Joram von Juda.","facts":[{"t":"Er kündigte Ahab eine Dürre an.","r":{"t":"1. Könige 17:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/17/#v11017001"}},{"t":"Raben versorgten ihn mit Nahrung.","r":{"t":"1. Könige 17:2-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/17/#v11017002-v11017006"}},{"t":"Er erweckte den Sohn der Witwe von Zarephath.","r":{"t":"1. Könige 17:17-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/17/#v11017017-v11017024"}},{"t":"Auf dem Karmel sandte Jehova Feuer auf sein Opfer.","r":{"t":"1. Könige 18:36-39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/18/#v11018036-v11018039"}},{"t":"Später schrieb er König Joram von Juda einen Brief.","r":{"t":"2. Chronika 21:12-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/21/#v14021012-v14021015"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["elisa","ahab","isebel"],"events":["elia-und-die-duerre","elia-auf-dem-karmel","elia-am-horeb","elia-wird-weggenommen"],"books":[],"refs":[{"t":"1. Könige 17:1-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/17/#v11017001-v11017024"},{"t":"1. Könige 18:17-46","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/18/#v11018017-v11018046"},{"t":"2. Könige 2:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/2/#v12002001-v12002012"},{"t":"Jakobus 5:17, 18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jakobus/5/#v59005017"}],"sources":[{"title":"Elia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001307"}]},{"id":"elisa","name":"Elisa","alt":[],"sex":"m","tags":["prophet"],"role":"Prophet, Nachfolger Elias","eras":["geteilt"],"dates":[{"label":"Wirken","value":"10. und 9. Jahrhundert v. u. Z."}],"year":-925,"meaning":"„Gott ist Rettung“","summary":"Elisa, der Sohn Schaphats, wurde berufen, als Elia sein Amtsgewand auf ihn warf, während er pflügte. Etwa sechs Jahre diente er Elia, dann erhielt er „zwei Anteile“ von dessen Geist und wurde sein Nachfolger. Er wirkte unter den Königen Ahab, Ahasja, Joram, Jehu, Jehoahas und Joas und vollbrachte viele Wunder – unter anderem die Heilung Naamans.","facts":[{"t":"Er verließ seine Arbeit, um Elia zu folgen.","r":{"t":"1. Könige 19:19-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/19/#v11019019-v11019021"}},{"t":"Er erbat zwei Anteile vom Geist Elias.","r":{"t":"2. Könige 2:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/2/#v12002009"}},{"t":"Er erweckte den Sohn der Schunemitin.","r":{"t":"2. Könige 4:32-37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/4/#v12004032-v12004037"}},{"t":"Er heilte den Syrer Naaman vom Aussatz.","r":{"t":"2. Könige 5:1-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005001-v12005014"}},{"t":"Er ließ Jehu zum König salben.","r":{"t":"2. Könige 9:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009001-v12009003"}}],"lesson":"","family":{"father":"Schaphat","mother":"","spouses":[],"children":[],"siblings":[]},"related":["elia","naaman","jehu","joas-israel"],"events":["elia-am-horeb","elia-wird-weggenommen","naaman-wird-geheilt","jehu-vollstreckt-gericht"],"books":[],"refs":[{"t":"1. Könige 19:19-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/19/#v11019019-v11019021"},{"t":"2. Könige 2:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/2/#v12002001-v12002015"},{"t":"2. Könige 4:1–6:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/4/#v12004001-v12006023"},{"t":"2. Könige 13:14-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/13/#v12013014-v12013021"}],"sources":[{"title":"Elisa – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001316"}]},{"id":"elisabeth","name":"Elisabeth","alt":[],"sex":"f","tags":[],"role":"Mutter von Johannes dem Täufer","eras":["jesus"],"dates":[],"year":-60,"meaning":"„Mein Gott ist Überfluss“","summary":"Elisabeth, die gottesfürchtige Frau des Priesters Sacharja, stammte selbst aus der Priesterfamilie Aarons. Beide waren schon alt, als der Engel Gabriel ankündigte, dass sie einen Sohn bekommen würde. Im sechsten Monat ihrer Schwangerschaft besuchte sie ihre Verwandte Maria; da hüpfte das Kind in ihrem Leib, und Elisabeth segnete Maria, erfüllt mit heiligem Geist.","facts":[{"t":"Sie und Sacharja waren gerecht vor Gott.","r":{"t":"Lukas 1:5, 6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001005"}},{"t":"Sie hielt sich fünf Monate abgesondert.","r":{"t":"Lukas 1:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001024"}},{"t":"Mit heiligem Geist erfüllt, segnete sie Maria.","r":{"t":"Lukas 1:41-45","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001041-v42001045"}},{"t":"Sie bestand darauf, dass das Kind Johannes heißen sollte.","r":{"t":"Lukas 1:60","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001060"}}],"lesson":"","family":{"father":"","mother":"","spouses":["zacharias"],"children":["johannes-der-taeufer"],"siblings":[]},"related":["maria"],"events":["ankuendigung-johannes","ankuendigung-jesu","geburt-johannes"],"books":[],"refs":[{"t":"Lukas 1:5-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001005-v42001025"},{"t":"Lukas 1:39-66","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001039-v42001066"}],"sources":[{"title":"Elisabeth – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001323"}]},{"id":"epaphroditus","name":"Epaphroditus","alt":[],"sex":"m","tags":["juenger"],"role":"Bruder aus Philippi","eras":["versammlung"],"dates":[],"year":60,"meaning":"","summary":"Epaphroditus war ein vertrauenswürdiges Mitglied der Versammlung in Philippi. Die Philipper schickten ihn mit einer Gabe zu Paulus, der in Rom gefangen war (um 59–61 u. Z.). Dort wurde er todkrank, doch Gott erbarmte sich seiner. Weil er sich nach den Philippern sehnte und bedrückt war, dass sie von seiner Krankheit gehört hatten, schickte Paulus ihn mit dem Philipperbrief zurück.","facts":[{"t":"Paulus nannte ihn Bruder, Mitarbeiter und Mitstreiter.","r":{"t":"Philipper 2:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philipper/2/#v50002025"}},{"t":"Er war krank bis nahe an den Tod.","r":{"t":"Philipper 2:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philipper/2/#v50002027"}},{"t":"Solche Männer sollten geschätzt werden.","r":{"t":"Philipper 2:29, 30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philipper/2/#v50002029"}},{"t":"Er brachte Paulus die Gaben der Philipper.","r":{"t":"Philipper 4:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philipper/4/#v50004018"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus"],"events":["paulus-in-rom"],"books":[],"refs":[{"t":"Philipper 2:25-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philipper/2/#v50002025-v50002030"},{"t":"Philipper 4:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philipper/4/#v50004018"}],"sources":[{"title":"Epaphroditus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001380"}]},{"id":"esau","name":"Esau","alt":["Edom"],"sex":"m","tags":[],"role":"Zwillingsbruder Jakobs, Vorvater der Edomiter","eras":["patriarchen"],"dates":[{"label":"Geboren","value":"1858 v. u. Z."}],"year":-1858,"meaning":"„Behaart“, „Haarig“","summary":"Esau war der Erstgeborene Isaaks und Rebekkas und der Zwillingsbruder Jakobs. Er wurde ein geschickter Jäger, hatte aber keine Wertschätzung für geistige Dinge: Für ein Linsengericht verkaufte er Jakob sein Erstgeburtsrecht. Von ihm stammen die Edomiter ab; den Namen Edom („Rot“) erhielt er wegen des roten Gerichts.","facts":[{"t":"Die Zwillinge stießen sich schon im Mutterleib; der Ältere sollte dem Jüngeren dienen.","r":{"t":"1. Mose 25:22, 23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025022"}},{"t":"Er verkaufte sein Erstgeburtsrecht für ein Linsengericht und etwas Brot.","r":{"t":"1. Mose 25:29-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025029-v1025034"}},{"t":"Mit 40 Jahren heiratete er zwei Hethiterinnen – zum Kummer seiner Eltern.","r":{"t":"1. Mose 26:34, 35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/26/#v1026034"}},{"t":"Isaak gab den Segen des Erstgeborenen Jakob.","r":{"t":"1. Mose 27:30-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/27/#v1027030-v1027040"}},{"t":"Die Bibel warnt davor, heilige Dinge so gering zu schätzen wie Esau.","r":{"t":"Hebräer 12:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/12/#v58012016"}}],"lesson":"","family":{"father":"isaak","mother":"rebekka","spouses":["Judith","Basemath"],"children":[],"siblings":["jakob"]},"related":[],"events":["esau-verkauft-erstgeburtsrecht","jakob-erhaelt-den-segen","jakob-ringt-mit-engel"],"books":[],"refs":[{"t":"1. Mose 25:24-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025024-v1025034"},{"t":"1. Mose 27:1-41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/27/#v1027001-v1027041"},{"t":"Hebräer 12:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/12/#v58012016"}],"sources":[{"title":"Esau – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001417"}]},{"id":"esra","name":"Esra","alt":[],"sex":"m","tags":["priester","schreiber"],"role":"Priester und kundiger Abschreiber","eras":["rueckkehr"],"dates":[{"label":"Zeit","value":"kam 468 v. u. Z. nach Jerusalem"}],"year":-468,"meaning":"„Hilfe“","summary":"Esra war ein aaronitischer Priester, ein Gelehrter, kundiger Abschreiber und Lehrer des Gesetzes. Er hatte „sein Herz bereitgemacht, das Gesetz Jehovas zu befragen und danach zu tun und zu lehren“. 468 v. u. Z. führte er mit Erlaubnis des Artaxerxes eine Gruppe nach Jerusalem. Er schrieb das gleichnamige Buch und sehr wahrscheinlich auch die beiden Bücher Chronika.","facts":[{"t":"Er stammte von Eleasar und Pinehas ab.","r":{"t":"Esra 7:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/7/#v15007001-v15007005"}},{"t":"Er hatte sein Herz bereitgemacht, das Gesetz zu lehren.","r":{"t":"Esra 7:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/7/#v15007010"}},{"t":"Er verzichtete auf eine Eskorte und vertraute auf Jehova.","r":{"t":"Esra 8:21-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/8/#v15008021-v15008023"}},{"t":"Er las dem Volk aus dem Gesetz vor.","r":{"t":"Nehemia 8:1-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/8/#v16008001-v16008008"}}],"lesson":"","family":{"father":"Seraja","mother":"","spouses":[],"children":[],"siblings":[]},"related":["artaxerxes","nehemia"],"events":["esra-kommt-nach-jerusalem"],"books":["Esra","1. Chronika","2. Chronika"],"refs":[{"t":"Esra 7:1-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/7/#v15007001-v15007028"},{"t":"Esra 8:21-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/8/#v15008021-v15008032"},{"t":"Nehemia 8:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/8/#v16008001-v16008012"}],"sources":[{"title":"Esra – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001475"}]},{"id":"esther","name":"Esther","alt":["Hadassa"],"sex":"f","tags":[],"role":"Königin von Persien","eras":["rueckkehr"],"dates":[{"label":"Zeit","value":"5. Jahrhundert v. u. Z., unter Ahasverus (Xerxes I.)"}],"year":-489,"meaning":"Hadassa: „Myrte“","summary":"Esther, mit hebräischem Namen Hadassa, war ein jüdisches Waisenmädchen aus dem Stamm Benjamin, das von seinem Cousin Mordechai aufgezogen wurde. Im 7. Jahr des Perserkönigs Ahasverus wurde sie Königin anstelle Waschtis. Als Haman die Ausrottung aller Juden plante, setzte sie ihr Leben aufs Spiel, ging ungerufen zum König und deckte den Plan auf. So rettete sie ihr Volk.","facts":[{"t":"Mordechai nahm sie als Tochter an.","r":{"t":"Esther 2:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002007"}},{"t":"Sie wurde im 7. Jahr des Ahasverus Königin.","r":{"t":"Esther 2:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002016"}},{"t":"„Wenn ich umkommen muss, so komme ich um.“","r":{"t":"Esther 4:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/4/#v17004016"}},{"t":"Sie deckte Hamans Plan vor dem König auf.","r":{"t":"Esther 7:3-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/7/#v17007003-v17007006"}}],"lesson":"","family":{"father":"Abihajil","mother":"","spouses":["ahasverus"],"children":[],"siblings":[]},"related":["mordechai","haman"],"events":["esther-wird-koenigin","esther-rettet-ihr-volk"],"books":[],"refs":[{"t":"Esther 2:5-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002005-v17002018"},{"t":"Esther 4:13-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/4/#v17004013-v17004017"},{"t":"Esther 7:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/7/#v17007001-v17007010"}],"sources":[{"title":"Esther – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001430"},{"title":"Ahasverus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000142"}]},{"id":"eunike","name":"Eunike","alt":[],"sex":"f","tags":["juenger"],"role":"Mutter des Timotheus","eras":["versammlung"],"dates":[],"year":47,"meaning":"von einem Wurzelwort, das „siegen“ bedeutet","summary":"Eunike war eine gläubige Jüdin, die Tochter der Lois, verheiratet mit einem ungläubigen Griechen. Sehr wahrscheinlich wurden sie und ihre Mutter in Lystra durch das Predigen des Paulus auf seiner ersten Missionsreise Christen. Obwohl ihr Mann kein Anbeter Jehovas war, unterwies sie ihren Sohn Timotheus von frühester Kindheit an vorbildlich in den heiligen Schriften.","facts":[{"t":"Sie war eine gläubige Jüdin, ihr Mann Grieche.","r":{"t":"Apostelgeschichte 16:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016001"}},{"t":"Paulus lobt ihren ungeheuchelten Glauben.","r":{"t":"2. Timotheus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/1/#v55001005"}},{"t":"Sie lehrte Timotheus die heiligen Schriften.","r":{"t":"2. Timotheus 3:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/3/#v55003015"}}],"lesson":"","family":{"father":"","mother":"lois","spouses":["Grieche (Name nicht genannt)"],"children":["timotheus"],"siblings":[]},"related":["paulus"],"events":[],"books":[],"refs":[{"t":"Apostelgeschichte 16:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016001"},{"t":"2. Timotheus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/1/#v55001005"}],"sources":[{"title":"Eunike – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001443"}]},{"id":"eva","name":"Eva","alt":[],"sex":"f","tags":[],"role":"Die erste Frau","eras":["anfaenge"],"dates":[],"year":-4026,"meaning":"„Lebendige“, „Lebende“","summary":"Eva war die erste Frau und die letzte irdische Schöpfung, von der die Bibel berichtet. Jehova bildete sie aus einer Rippe Adams als dessen Gegenstück. Von einer Schlange getäuscht, aß sie von dem Baum der Erkenntnis von Gut und Böse und veranlasste auch Adam, Gott ungehorsam zu sein.","facts":[{"t":"Jehova bildete sie aus einer Rippe Adams; Adam nahm sie freudig zur Frau.","r":{"t":"1. Mose 2:21-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/2/#v1002021-v1002023"}},{"t":"Gott segnete das Paar und gab ihm den Auftrag, die Erde zu füllen.","r":{"t":"1. Mose 1:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001028"}},{"t":"Eine Schlange – Sprachrohr eines unsichtbaren Geistgeschöpfes – betrog sie.","r":{"t":"1. Mose 3:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003001-v1003006"}},{"t":"Paulus schreibt, dass Eva gründlich getäuscht wurde.","r":{"t":"1. Timotheus 2:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-timotheus/2/#v54002014"}},{"t":"Sie wurde die Mutter von Kain, Abel und Seth.","r":{"t":"1. Mose 4:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004001"}}],"lesson":"","family":{"father":"","mother":"","spouses":["adam"],"children":["kain","abel","seth"],"siblings":[]},"related":[],"events":["erschaffung-des-menschen","suendenfall"],"books":[],"refs":[{"t":"1. Mose 2:18-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/2/#v1002018-v1002023"},{"t":"1. Mose 3:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003001-v1003006"},{"t":"1. Timotheus 2:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-timotheus/2/#v54002014"}],"sources":[{"title":"Eva – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001450"}]},{"id":"felix","name":"Felix","alt":[],"sex":"m","tags":["herrscher"],"role":"Römischer Prokurator von Judäa","eras":["versammlung"],"dates":[{"label":"Zeit","value":"hielt Paulus um 56–58 u. Z. gefangen"}],"year":56,"meaning":"„glücklich“ (aus dem Lateinischen)","summary":"Felix war Prokurator der römischen Provinz Judäa. Nach dem letzten Jerusalembesuch des Paulus um 56 u. Z. hielt er ihn zwei Jahre lang in Cäsarea gefangen. Als Paulus vor ihm und seiner Frau Drusilla über Gerechtigkeit, Selbstbeherrschung und das kommende Gericht sprach, geriet Felix in Furcht. Er hoffte vergeblich auf Bestechungsgeld. Vermutlich 58 u. Z. löste Festus ihn ab.","facts":[{"t":"Paulus verteidigte sich vor ihm in Cäsarea.","r":{"t":"Apostelgeschichte 24:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/24/#v44024010"}},{"t":"Er geriet in Furcht, als Paulus vom Gericht sprach.","r":{"t":"Apostelgeschichte 24:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/24/#v44024024"}},{"t":"Er hoffte, Paulus würde ihm Geld geben.","r":{"t":"Apostelgeschichte 24:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/24/#v44024026"}},{"t":"Er ließ Paulus gebunden zurück, um den Juden zu gefallen.","r":{"t":"Apostelgeschichte 24:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/24/#v44024027"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Drusilla"],"children":[],"siblings":[]},"related":["paulus","festus","herodes-agrippa-ii"],"events":["paulus-verhaftet"],"books":[],"refs":[{"t":"Apostelgeschichte 23:23–24:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/23/#v44023023-v44024027"}],"sources":[{"title":"Felix – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001502"}]},{"id":"festus","name":"Festus","alt":["Porcius Festus"],"sex":"m","tags":["herrscher"],"role":"Römischer Statthalter von Judäa","eras":["versammlung"],"dates":[{"label":"Zeit","value":"Statthalter ab wahrscheinlich 58 u. Z."}],"year":58,"meaning":"„festlich“, „freudig“ (aus dem Lateinischen)","summary":"Porcius Festus folgte Felix als Statthalter von Judäa, wahrscheinlich 58 u. Z. Die Oberpriester wollten Paulus nach Jerusalem bringen lassen, doch Festus verhandelte in Cäsarea. Als er Paulus fragte, ob er in Jerusalem gerichtet werden wolle, berief sich Paulus auf Cäsar. Festus war von seiner Unschuld überzeugt und legte den Fall König Agrippa II. vor.","facts":[{"t":"Er folgte Felix im Amt.","r":{"t":"Apostelgeschichte 24:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/24/#v44024027"}},{"t":"Paulus rief: „Ich berufe mich auf Cäsar!“","r":{"t":"Apostelgeschichte 25:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/25/#v44025011"}},{"t":"Er fand nichts, was den Tod verdient hätte.","r":{"t":"Apostelgeschichte 25:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/25/#v44025025"}},{"t":"Er hielt Paulus für „von Sinnen“.","r":{"t":"Apostelgeschichte 26:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/26/#v44026024"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus","felix","herodes-agrippa-ii"],"events":["paulus-verhaftet"],"books":[],"refs":[{"t":"Apostelgeschichte 25:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/25/#v44025001-v44025027"}],"sources":[{"title":"Festus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001512"}]},{"id":"gabriel","name":"Gabriel","alt":[],"sex":"","tags":["engel"],"role":"Engel Gottes","eras":["jesus","exil"],"dates":[],"year":-3,"meaning":"„Kräftiger Mann Gottes“","summary":"Gabriel ist neben Michael der einzige heilige Engel, der in der Bibel namentlich erwähnt wird. Er erschien Daniel zweimal, um ihm Visionen und die Prophezeiung über die „siebzig Wochen“ zu erklären. Später überbrachte er dem Priester Sacharja die Nachricht von der Geburt Johannes’ des Täufers und kündigte Maria an, dass sie den Sohn Gottes gebären werde.","facts":[{"t":"Er erklärte Daniel die Vision vom Widder und Ziegenbock.","r":{"t":"Daniel 8:15-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/8/#v27008015-v27008026"}},{"t":"Er übermittelte die Prophezeiung von den 70 Wochen.","r":{"t":"Daniel 9:21-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/9/#v27009021-v27009027"}},{"t":"Er kündigte Sacharja die Geburt des Johannes an.","r":{"t":"Lukas 1:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001019"}},{"t":"Er wurde zu Maria nach Nazareth gesandt.","r":{"t":"Lukas 1:26-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001026-v42001033"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["daniel","maria","zacharias"],"events":["ankuendigung-johannes","ankuendigung-jesu"],"books":[],"refs":[{"t":"Daniel 9:21-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/9/#v27009021-v27009027"},{"t":"Lukas 1:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001019"},{"t":"Lukas 1:26-38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001026-v42001038"}],"sources":[{"title":"Gabriel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001582"}]},{"id":"gamaliel","name":"Gamaliel","alt":[],"sex":"m","tags":[],"role":"Pharisäer und Gesetzeslehrer","eras":["versammlung"],"dates":[],"year":33,"meaning":"vielleicht „Lohn (Belohnung) von Gott“","summary":"Gamaliel war ein angesehener Pharisäer, Gesetzeslehrer und Mitglied des Sanhedrins; Paulus war zu seinen Füßen im Gesetz unterwiesen worden. Als die Apostel vor den Sanhedrin gestellt wurden, riet er, sie in Ruhe zu lassen: Sei ihr Werk von Menschen, werde es scheitern; sei es aber von Gott, könne man es nicht stürzen.","facts":[{"t":"Er war beim ganzen Volk geachtet.","r":{"t":"Apostelgeschichte 5:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/5/#v44005034"}},{"t":"„Wenn es aber von Gott ist, werdet ihr sie nicht stürzen können.“","r":{"t":"Apostelgeschichte 5:38, 39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/5/#v44005038"}},{"t":"Paulus wurde zu seinen Füßen unterrichtet.","r":{"t":"Apostelgeschichte 22:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/22/#v44022003"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus","petrus"],"events":[],"books":[],"refs":[{"t":"Apostelgeschichte 5:33-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/5/#v44005033-v44005040"},{"t":"Apostelgeschichte 22:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/22/#v44022003"}],"sources":[{"title":"Gamaliel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001604"}]},{"id":"gideon","name":"Gideon","alt":["Jerubbaal"],"sex":"m","tags":["richter"],"role":"Richter, Befreier von den Midianitern","eras":["richter"],"dates":[],"year":-1250,"meaning":"„Umhauer“","summary":"Gideon aus dem Stamm Manasse war einer der hervorragendsten Richter Israels. Als die Midianiter Israel sieben Jahre lang plünderten, berief ihn ein Engel Jehovas zum Befreier. Gideon riss den Baalsaltar seines Vaters nieder und besiegte mit nur 300 Mann – ausgerüstet mit Hörnern, Krügen und Fackeln – das riesige Heer Midians.","facts":[{"t":"Ein Engel sagte zu ihm: „Jehova ist mit dir, du tapferer Starker.“","r":{"t":"Richter 6:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/6/#v7006012"}},{"t":"Er riss den Altar Baals nieder, den sein Vater errichtet hatte.","r":{"t":"Richter 6:25-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/6/#v7006025-v7006027"}},{"t":"Jehova verringerte sein Heer auf 300 Mann.","r":{"t":"Richter 7:2-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/7/#v7007002-v7007007"}},{"t":"Mit Hörnern, Krügen und Fackeln wurde Midian geschlagen.","r":{"t":"Richter 7:16-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/7/#v7007016-v7007022"}}],"lesson":"","family":{"father":"Joas","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["zeit-der-richter","gideons-300"],"books":[],"refs":[{"t":"Richter 6:11-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/6/#v7006011-v7006040"},{"t":"Richter 7:1-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/7/#v7007001-v7007025"},{"t":"Hebräer 11:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011032"}],"sources":[{"title":"Gideon – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001685"}]},{"id":"goliath","name":"Goliath","alt":[],"sex":"m","tags":[],"role":"Riese der Philister","eras":["koenigreich"],"dates":[],"year":-1091,"meaning":"","summary":"Goliath aus Gath war ein Riese und Vorkämpfer der Philister – sechs Ellen und eine Spanne groß (etwa 2,9 m). Sein kupfernes Panzerhemd wog rund 57 kg. Im Tal zwischen den Heeren verhöhnte er Israel und forderte einen Zweikampf. Der junge David trat ihm im Namen Jehovas entgegen und tötete ihn mit einer Schleuder.","facts":[{"t":"Er war etwa 2,9 m groß.","r":{"t":"1. Samuel 17:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017004"}},{"t":"Er verhöhnte die Schlachtreihen Israels.","r":{"t":"1. Samuel 17:8-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017008-v9017010"}},{"t":"David traf ihn mit einem Stein an der Stirn.","r":{"t":"1. Samuel 17:49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017049"}},{"t":"Er gehörte zu den Rephaim.","r":{"t":"1. Chronika 20:5, 8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/20/#v13020005"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["david"],"events":["david-und-goliath"],"books":[],"refs":[{"t":"1. Samuel 17:1-54","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017001-v9017054"}],"sources":[{"title":"Goliath – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001739"}]},{"id":"habakuk","name":"Habakuk","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet aus Juda","eras":["geteilt"],"dates":[{"label":"Zeit","value":"Buch vielleicht um 628 v. u. Z."}],"year":-628,"meaning":"„Innige Umarmung“","summary":"Habakuk war ein hebräischer Prophet aus Juda und schrieb das nach ihm benannte Bibelbuch, vielleicht um 628 v. u. Z. Er fragte Jehova, warum er Unrecht zulasse, und erfuhr, dass Gott die Chaldäer als Strafwerkzeug gebrauchen würde. Bekannt sind seine Worte, dass der Gerechte durch seine Treue leben wird.","facts":[{"t":"Er fragte, wie lange Jehova Gewalttat zulassen werde.","r":{"t":"Habakuk 1:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/habakuk/1/#v35001002-v35001004"}},{"t":"Jehova kündigte das Kommen der Chaldäer an.","r":{"t":"Habakuk 1:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/habakuk/1/#v35001006"}},{"t":"„Der Gerechte wird durch seine Treue am Leben bleiben.“","r":{"t":"Habakuk 2:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/habakuk/2/#v35002004"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":[],"books":["Habakuk"],"refs":[{"t":"Habakuk 1:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/habakuk/1/#v35001001-v35001011"},{"t":"Habakuk 2:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/habakuk/2/#v35002001-v35002004"},{"t":"Habakuk 3:17-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/habakuk/3/#v35003017-v35003019"}],"sources":[{"title":"Habakuk – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001789"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"hagar","name":"Hagar","alt":[],"sex":"f","tags":[],"role":"Magd Saras, Mutter Ismaels","eras":["patriarchen"],"dates":[],"year":-1950,"meaning":"","summary":"Hagar war die ägyptische Magd Saras. Weil Sara unfruchtbar blieb, gab sie Hagar Abraham zur Frau, und Hagar gebar ihm Ismael. Als sie schwanger war, verachtete sie ihre Herrin und lief weg, kehrte aber auf Anweisung eines Engels zurück. Später wurden sie und Ismael weggeschickt.","facts":[{"t":"Wurde wahrscheinlich in Ägypten Saras Magd.","r":{"t":"1. Mose 12:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/12/#v1012016"}},{"t":"Sara gab sie Abraham, um durch sie Kinder zu bekommen.","r":{"t":"1. Mose 16:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/16/#v1016001-v1016003"}},{"t":"Der Engel Jehovas fand sie an einer Quelle und schickte sie zurück.","r":{"t":"1. Mose 16:7-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/16/#v1016007-v1016009"}},{"t":"Mit Ismael weggeschickt, erfuhr sie in der Wildnis Gottes Hilfe.","r":{"t":"1. Mose 21:14-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021014-v1021019"}}],"lesson":"","family":{"father":"","mother":"","spouses":["abraham"],"children":["ismael"],"siblings":[]},"related":["sara"],"events":["hagar-und-ismael"],"books":[],"refs":[{"t":"1. Mose 16:1-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/16/#v1016001-v1016016"},{"t":"1. Mose 21:9-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021009-v1021021"}],"sources":[{"title":"Hagar – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001811"}]},{"id":"haggai","name":"Haggai","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet nach dem Exil","eras":["rueckkehr"],"dates":[{"label":"Wirken","value":"520 v. u. Z."}],"year":-520,"meaning":"„(An einem) Fest (geboren)“","summary":"Haggai war ein hebräischer Prophet, der während der Statthalterschaft Serubbabels in Juda wirkte. Im zweiten Jahr des Perserkönigs Darius Hystaspis (520 v. u. Z.) übermittelte er innerhalb von etwa vier Monaten vier Botschaften Jehovas, die das Volk anspornten, den liegengebliebenen Tempelbau wieder aufzunehmen. Er schrieb das gleichnamige Bibelbuch.","facts":[{"t":"Er tadelte das Volk, weil es in getäfelten Häusern wohnte, während der Tempel verwüstet lag.","r":{"t":"Haggai 1:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/1/#v37001003"}},{"t":"Er sagte: „Achtet auf eure Wege.“","r":{"t":"Haggai 1:5-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/1/#v37001005-v37001007"}},{"t":"Jehova kündigte an, alle Nationen zu erschüttern.","r":{"t":"Haggai 2:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/2/#v37002006"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["sacharja","serubbabel","jeschua"],"events":["tempel-vollendet"],"books":["Haggai"],"refs":[{"t":"Haggai 1:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/1/#v37001001-v37001015"},{"t":"Haggai 2:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/2/#v37002001-v37002009"},{"t":"Esra 5:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/5/#v15005001"}],"sources":[{"title":"Haggai – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001812"}]},{"id":"ham","name":"Ham","alt":[],"sex":"m","tags":[],"role":"Sohn Noahs","eras":["anfaenge","patriarchen"],"dates":[],"year":-2466,"meaning":"","summary":"Ham war einer der drei Söhne Noahs und überlebte mit seiner Frau die Sintflut. Er wurde der Vater von Kusch, Mizrajim, Put und Kanaan; von ihnen stammen unter anderem die Äthiopier, die Ägypter und die Kanaaniter ab. Weil Ham seinem Vater nicht den gebührenden Respekt erwies, sprach Noah einen Fluch aus – allerdings über Hams Sohn Kanaan.","facts":[{"t":"Überlebte die Flut mit seiner Frau, seinen Eltern und seinen Brüdern.","r":{"t":"1. Mose 7:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/7/#v1007013"}},{"t":"Vater von Kusch, Mizrajim, Put und Kanaan.","r":{"t":"1. Mose 10:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/10/#v1010006"}},{"t":"Erzählte seinen Brüdern respektlos von der Blöße seines Vaters.","r":{"t":"1. Mose 9:20-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009020-v1009022"}},{"t":"Noah verfluchte nicht Ham, sondern dessen Sohn Kanaan.","r":{"t":"1. Mose 9:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009024"}}],"lesson":"","family":{"father":"noah","mother":"","spouses":[],"children":["Kusch","Mizrajim","Put","Kanaan"],"siblings":["sem","japhet"]},"related":[],"events":["bau-der-arche","sintflut"],"books":[],"refs":[{"t":"1. Mose 9:18-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009018-v1009027"},{"t":"1. Mose 10:6-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/10/#v1010006-v1010020"}],"sources":[{"title":"Ham – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001832"}]},{"id":"haman","name":"Haman","alt":[],"sex":"m","tags":["herrscher"],"role":"Erster Minister, Feind der Juden","eras":["rueckkehr"],"dates":[],"year":-484,"meaning":"","summary":"Haman, der Sohn Hammedathas, der Agagiter – möglicherweise ein Amalekiter königlicher Abstammung –, war der erste Minister des Perserkönigs Ahasverus. Weil Mordechai sich nicht vor ihm niederbeugte, plante er, alle Juden im Reich auszurotten, und erwirkte dafür einen Erlass. Doch Esther deckte seinen Plan auf, und Haman wurde an dem Pfahl gehängt, den er für Mordechai errichtet hatte.","facts":[{"t":"Der König erhob ihn über alle Fürsten.","r":{"t":"Esther 3:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/3/#v17003001"}},{"t":"Er warf das Los (Pur), um einen Tag für die Vernichtung festzulegen.","r":{"t":"Esther 3:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/3/#v17003007"}},{"t":"Er ließ einen Pfahl für Mordechai errichten.","r":{"t":"Esther 5:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/5/#v17005014"}},{"t":"Er wurde selbst daran gehängt.","r":{"t":"Esther 7:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/7/#v17007010"}}],"lesson":"","family":{"father":"Hammedatha","mother":"","spouses":["Seresch"],"children":[],"siblings":[]},"related":["esther","mordechai","ahasverus"],"events":["esther-rettet-ihr-volk"],"books":[],"refs":[{"t":"Esther 3:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/3/#v17003001-v17003015"},{"t":"Esther 7:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/7/#v17007001-v17007010"}],"sources":[{"title":"Haman – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001833"}]},{"id":"hananja","name":"Hananja","alt":["Schadrach"],"sex":"m","tags":[],"role":"Gefährte Daniels (Schadrach)","eras":["exil"],"dates":[{"label":"Zeit","value":"617 v. u. Z. nach Babylon gebracht"}],"year":-619,"meaning":"„Jehova hat Gunst erwiesen“","summary":"Hananja war einer der drei jüdischen Gefährten Daniels, die 617 v. u. Z. nach Babylon gebracht wurden; dort erhielt er den Namen Schadrach. Mit Mischael und Asarja weigerte er sich, vor Nebukadnezars goldenem Standbild niederzufallen, und wurde in den Feuerofen geworfen – doch Gott rettete sie.","facts":[{"t":"Er erhielt den babylonischen Namen Schadrach.","r":{"t":"Daniel 1:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001006"}},{"t":"Er wurde zum Verwalter in Babylon befördert.","r":{"t":"Daniel 2:49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002049"}},{"t":"Er betete das goldene Bild nicht an.","r":{"t":"Daniel 3:16-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003016-v27003018"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["daniel","mischael","asarja"],"events":["daniel-in-babylon","feuerofen"],"books":[],"refs":[{"t":"Daniel 1:6-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001006-v27001020"},{"t":"Daniel 3:12-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003012-v27003030"}],"sources":[{"title":"Hananja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001853"},{"title":"Schadrach – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003927"}]},{"id":"hanna","name":"Hanna","alt":[],"sex":"f","tags":[],"role":"Mutter Samuels","eras":["richter"],"dates":[],"year":-1190,"meaning":"„Gunst“, „Gnade“","summary":"Hanna war mit dem Leviten Elkana verheiratet und blieb lange kinderlos, während seine andere Frau Peninna sie deswegen verhöhnte. Beim jährlichen Besuch der Stiftshütte in Silo schüttete sie Jehova ihr Herz aus und gelobte, einen Sohn seinem Dienst zu weihen. Sie bekam Samuel und brachte ihn nach seiner Entwöhnung zu Eli nach Silo.","facts":[{"t":"Elkana liebte sie, obwohl sie kinderlos war.","r":{"t":"1. Samuel 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001005"}},{"t":"Sie gelobte, ihren Sohn Jehova zu geben.","r":{"t":"1. Samuel 1:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001011"}},{"t":"Sie brachte Samuel nach seiner Entwöhnung nach Silo.","r":{"t":"1. Samuel 1:24-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001024-v9001028"}},{"t":"Sie dankte Jehova mit einem Gebet voller Lobpreis.","r":{"t":"1. Samuel 2:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/2/#v9002001-v9002010"}},{"t":"Später bekam sie noch drei Söhne und zwei Töchter.","r":{"t":"1. Samuel 2:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/2/#v9002021"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Elkana"],"children":["samuel"],"siblings":[]},"related":["eli"],"events":["hannas-gebet"],"books":[],"refs":[{"t":"1. Samuel 1:1-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001001-v9001028"},{"t":"1. Samuel 2:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/2/#v9002001-v9002010"}],"sources":[{"title":"Hanna – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001861"}]},{"id":"henoch","name":"Henoch","alt":[],"sex":"m","tags":["prophet","vorfahr-jesu"],"role":"Prophet vor der Sintflut","eras":["anfaenge"],"dates":[{"label":"Alter","value":"365 Jahre"}],"year":-3404,"meaning":"„Erzogener“, „Eingeweihter“","summary":"Henoch, der Sohn Jereds, war der Siebte in der Linie von Adam her. Er „wandelte beständig mit dem wahren Gott“ und kündigte als Prophet Jehovas das Gericht über die Gottlosen an. Gott ließ nicht zu, dass seine Feinde ihn umbrachten, sondern „nahm ihn hinweg“ – Henoch wurde nur 365 Jahre alt.","facts":[{"t":"Sohn Jereds; mit 65 Jahren wurde er Vater Methusalahs.","r":{"t":"1. Mose 5:18, 21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005018"}},{"t":"Er wandelte beständig mit dem wahren Gott.","r":{"t":"1. Mose 5:22-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005022-v1005024"}},{"t":"Er sagte voraus, dass Gott mit seinen heiligen Myriaden Gericht halten werde.","r":{"t":"Judas 14-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001014-v65001015"}},{"t":"Paulus zählt ihn zu der „großen Wolke von Zeugen“.","r":{"t":"Hebräer 11:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011005"}}],"lesson":"","family":{"father":"Jered","mother":"","spouses":[],"children":["methusalah"],"siblings":[]},"related":[],"events":["henoch-wandelt-mit-gott"],"books":[],"refs":[{"t":"1. Mose 5:21-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005021-v1005024"},{"t":"Hebräer 11:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011005"},{"t":"Judas 14-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001014-v65001015"}],"sources":[{"title":"Henoch – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001371"}]},{"id":"herodes-agrippa-i","name":"Herodes Agrippa I.","alt":["König Herodes","Agrippa I."],"sex":"m","tags":["herrscher"],"role":"König über Judäa","eras":["versammlung"],"dates":[{"label":"Gestorben","value":"44 u. Z."}],"year":41,"meaning":"","summary":"Herodes Agrippa I. war ein Enkel Herodes’ des Großen und der letzte Herodianer, der König über ganz Palästina wurde. Um den Juden zu gefallen, ließ er den Apostel Jakobus mit dem Schwert hinrichten und Petrus festnehmen, den ein Engel befreite. In Cäsarea ließ er sich bei einer Rede als Gott feiern; da schlug ihn der Engel Jehovas, und er starb 44 u. Z.","facts":[{"t":"Er ließ Jakobus, den Bruder des Johannes, töten.","r":{"t":"Apostelgeschichte 12:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012001"}},{"t":"Er ließ Petrus ins Gefängnis werfen.","r":{"t":"Apostelgeschichte 12:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012003"}},{"t":"Das Volk rief: „Eines Gottes Stimme und nicht eines Menschen!“","r":{"t":"Apostelgeschichte 12:21, 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012021"}},{"t":"Der Engel Jehovas schlug ihn, weil er Gott nicht die Ehre gab.","r":{"t":"Apostelgeschichte 12:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012023"}}],"lesson":"","family":{"father":"Aristobulos","mother":"","spouses":[],"children":["herodes-agrippa-ii","Bernice","Drusilla","Mariamne III."],"siblings":[]},"related":["herodes-der-grosse","jakobus-zebedaeus","petrus"],"events":["petrus-befreit"],"books":[],"refs":[{"t":"Apostelgeschichte 12:1-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012001-v44012023"}],"sources":[{"title":"Herodes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002000"}]},{"id":"herodes-agrippa-ii","name":"Herodes Agrippa II.","alt":["König Agrippa","Agrippa"],"sex":"m","tags":["herrscher"],"role":"König, vor dem Paulus sich verteidigte","eras":["versammlung"],"dates":[],"year":58,"meaning":"","summary":"Herodes Agrippa II., Sohn von Agrippa I., war ein Urenkel Herodes’ des Großen; mit ihm endete die Linie der herodianischen Fürsten. Er wurde in Rom erzogen und herrschte über mehrere Gebiete. Wahrscheinlich 58 u. Z. besuchte er mit seiner Schwester Bernice den Statthalter Festus in Cäsarea. Dort hörte er die Verteidigungsrede des Paulus und erkannte, dass dieser nichts getan hatte, was Tod oder Fesseln verdiente.","facts":[{"t":"Er kam mit Bernice zu Festus nach Cäsarea.","r":{"t":"Apostelgeschichte 25:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/25/#v44025013"}},{"t":"Paulus verteidigte sich vor ihm.","r":{"t":"Apostelgeschichte 26:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/26/#v44026001-v44026003"}},{"t":"„In kurzer Zeit würdest du mich überreden, ein Christ zu werden.“","r":{"t":"Apostelgeschichte 26:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/26/#v44026028"}},{"t":"Er hielt Paulus für unschuldig.","r":{"t":"Apostelgeschichte 26:31, 32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/26/#v44026031"}}],"lesson":"","family":{"father":"herodes-agrippa-i","mother":"Kypros","spouses":[],"children":[],"siblings":["Bernice","Drusilla","Mariamne III."]},"related":["paulus","festus","felix"],"events":["paulus-verhaftet"],"books":[],"refs":[{"t":"Apostelgeschichte 25:13–26:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/25/#v44025013-v44026032"}],"sources":[{"title":"Herodes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002000"}]},{"id":"herodes-antipas","name":"Herodes Antipas","alt":["Antipas","Herodes"],"sex":"m","tags":["herrscher"],"role":"Bezirksherrscher von Galiläa und Peräa","eras":["jesus"],"dates":[],"year":-4,"meaning":"","summary":"Herodes Antipas, ein Sohn Herodes’ des Großen, erhielt die Tetrarchie Galiläa und Peräa. Er heiratete Herodias, die Frau seines Halbbruders. Weil Johannes der Täufer ihn deswegen zurechtwies, ließ er ihn einsperren und auf Herodias’ Betreiben enthaupten. Jesus nannte ihn „diesen Fuchs“. Bei Jesu Prozess schickte Pilatus Jesus zu ihm; Herodes verspottete ihn und sandte ihn zurück.","facts":[{"t":"Er ließ Johannes den Täufer enthaupten.","r":{"t":"Markus 6:17-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/6/#v41006017-v41006028"}},{"t":"Jesus nannte ihn „diesen Fuchs“.","r":{"t":"Lukas 13:31, 32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/13/#v42013031"}},{"t":"Er verspottete Jesus und schickte ihn zu Pilatus zurück.","r":{"t":"Lukas 23:7-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/23/#v42023007-v42023011"}}],"lesson":"","family":{"father":"herodes-der-grosse","mother":"Malthake","spouses":["Herodias"],"children":[],"siblings":["Archelaus"]},"related":["johannes-der-taeufer","pilatus"],"events":["tod-johannes-des-taeufers","tod-jesu"],"books":[],"refs":[{"t":"Markus 6:14-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/6/#v41006014-v41006029"},{"t":"Lukas 23:6-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/23/#v42023006-v42023012"}],"sources":[{"title":"Herodes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002000"}]},{"id":"herodes-der-grosse","name":"Herodes der Große","alt":["Herodes"],"sex":"m","tags":["herrscher"],"role":"König von Judäa","eras":["jesus"],"dates":[],"year":-40,"meaning":"","summary":"Herodes der Große stammte aus der Dynastie der Idumäer (Edomiter). Er war ein geschickter Diplomat und befähigter Heerführer, aber skrupellos, misstrauisch, grausam und mordlustig. Als Astrologen nach dem neugeborenen „König der Juden“ fragten, ließ er in Bethlehem und Umgebung alle Jungen bis zu zwei Jahren umbringen. Kurz danach starb er; seine Söhne Archelaus, Antipas und Philippus erhielten Teile seines Reiches.","facts":[{"t":"Er erschrak, als er vom geborenen König der Juden hörte.","r":{"t":"Matthäus 2:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002001-v40002003"}},{"t":"Er ließ die kleinen Jungen in Bethlehem töten.","r":{"t":"Matthäus 2:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002016"}},{"t":"Nach seinem Tod kehrte Jesu Familie aus Ägypten zurück.","r":{"t":"Matthäus 2:19-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002019-v40002023"}}],"lesson":"","family":{"father":"Antipater","mother":"Kypros","spouses":[],"children":["herodes-antipas","Archelaus","Philippus"],"siblings":[]},"related":[],"events":["astrologen-und-flucht"],"books":[],"refs":[{"t":"Matthäus 2:1-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002001-v40002022"},{"t":"Lukas 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001005"}],"sources":[{"title":"Herodes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002000"}]},{"id":"hesekiel","name":"Hesekiel","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet unter den Weggeführten","eras":["exil"],"dates":[{"label":"Wirken","value":"ab 613 v. u. Z."}],"year":-613,"meaning":"„Gott stärkt“","summary":"Hesekiel, der Sohn des Priesters Busi, wurde 617 v. u. Z. mit König Jojachin nach Babylon weggeführt. Im fünften Jahr dieses Exils (613 v. u. Z.), offenbar mit 30 Jahren, erhielt er am Strom Kebar seine erste Vision. Er prophezeite unter den Juden in Babylonien, zur gleichen Zeit, als Jeremia in Jerusalem und Daniel am Hof wirkten. Er schrieb das gleichnamige Bibelbuch.","facts":[{"t":"Er stammte aus einer Priesterfamilie.","r":{"t":"Hesekiel 1:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/1/#v26001003"}},{"t":"Er sah eine Vision von Jehovas himmlischem Wagen.","r":{"t":"Hesekiel 1:4-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/1/#v26001004-v26001028"}},{"t":"Jehova machte ihn zum Wächter für das Haus Israel.","r":{"t":"Hesekiel 3:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/3/#v26003017"}},{"t":"Er sah eine Vision von einem künftigen Tempel.","r":{"t":"Hesekiel 40:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/40/#v26040001-v26040004"}}],"lesson":"","family":{"father":"Busi","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jeremia","daniel","jojachin"],"events":["wegfuehrung-jojachins","hesekiel-wird-prophet"],"books":["Hesekiel"],"refs":[{"t":"Hesekiel 1:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/1/#v26001001-v26001003"},{"t":"Hesekiel 3:16-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/3/#v26003016-v26003021"},{"t":"Hesekiel 37:1-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/37/#v26037001-v26037014"}],"sources":[{"title":"Hesekiel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001469"}]},{"id":"hiob","name":"Hiob","alt":[],"sex":"m","tags":[],"role":"Mann aus Uz, bewahrte seine Lauterkeit","eras":["aegypten"],"dates":[{"label":"Zeit","value":"Prüfung wahrscheinlich um 1613 v. u. Z."}],"year":-1613,"meaning":"„Gegenstand der Feindseligkeit“, „Angefeindeter“","summary":"Hiob lebte im Land Uz und betete Jehova an, obwohl er kein Israelit war. Gott sagte von ihm, es gebe auf der Erde keinen wie ihn – untadelig und rechtschaffen. Als Satan seine Lauterkeit infrage stellte, verlor Hiob seinen Besitz, seine Kinder und seine Gesundheit. Doch er hielt an seiner Treue fest, und Jehova stellte ihn wieder her.","facts":[{"t":"Er lebte wahrscheinlich zwischen dem Tod Josephs und dem Auftreten von Moses."},{"t":"Er war sehr reich und hatte sieben Söhne und drei Töchter.","r":{"t":"Hiob 1:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/1/#v18001001-v18001003"}},{"t":"Er trat für Witwen, Waisen und Hilflose ein.","r":{"t":"Hiob 29:12-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/29/#v18029012-v18029017"}},{"t":"Satan stellte seine Lauterkeit infrage.","r":{"t":"Hiob 1:6-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/1/#v18001006-v18001012"}},{"t":"Nach der Prüfung erhielt er das Doppelte und lebte noch 140 Jahre.","r":{"t":"Hiob 42:10-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/42/#v18042010-v18042017"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["hiobs-pruefung"],"books":[],"refs":[{"t":"Hiob 1:1-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/1/#v18001001-v18001022"},{"t":"Hiob 2:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/2/#v18002001-v18002010"},{"t":"Hiob 42:10-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/42/#v18042010-v18042017"},{"t":"Jakobus 5:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jakobus/5/#v59005011"}],"sources":[{"title":"Hiob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002475"}]},{"id":"hiskia","name":"Hiskia","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"745–717 v. u. Z."}],"year":-746,"meaning":"„Jehova stärkt“","summary":"Hiskia, der Sohn Ahas’, hielt weiterhin fest zu Jehova; unter allen Königen Judas war keiner wie er. Schon zu Beginn seiner Regierung förderte er eifrig die wahre Anbetung. Als der Assyrerkönig Sanherib 732 v. u. Z. Jerusalem bedrohte, vertraute er auf Jehova, der die Stadt rettete. Nach einer schweren Krankheit verlängerte Gott sein Leben um 15 Jahre.","facts":[{"t":"Er tat, was recht war in Jehovas Augen.","r":{"t":"2. Könige 18:3-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/18/#v12018003-v12018007"}},{"t":"Er schützte Jerusalems Wasserversorgung vor den Assyrern.","r":{"t":"2. Chronika 32:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/32/#v14032002-v14032004"}},{"t":"Jehovas Engel schlug das Heer Sanheribs.","r":{"t":"2. Könige 19:35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/19/#v12019035"}},{"t":"Nach seiner Heilung schrieb er ein Danklied.","r":{"t":"Jesaja 38:9-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/38/#v23038009-v23038020"}},{"t":"Seine Männer schrieben Sprüche Salomos ab.","r":{"t":"Sprüche 25:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Spr%C3%BCche/25/#v20025001"}}],"lesson":"","family":{"father":"ahas","mother":"","spouses":["Hephzibah"],"children":["manasse"],"siblings":[]},"related":["jesaja","sanherib","micha"],"events":["sanherib-bedroht-jerusalem"],"books":[],"refs":[{"t":"2. Könige 18:1–20:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/18/#v12018001-v12020021"},{"t":"2. Chronika 29:1–32:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/29/#v14029001-v14032033"},{"t":"Jesaja 36:1–39:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/36/#v23036001-v23039008"}],"sources":[{"title":"Hiskia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002011"}]},{"id":"hosea-koenig","name":"Hoschea","alt":["Hosea"],"sex":"m","tags":["koenig"],"role":"Letzter König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 758 v. u. Z., fest ab etwa 748 (9 Jahre)"}],"year":-758,"meaning":"","summary":"Hoschea, der Sohn Elas, war der letzte König des Nordreichs Israel. Er riss den Thron durch eine Verschwörung gegen Pekach an sich. Er tat, was böse war, wenn auch nicht so schlimm wie seine Vorgänger. Als er sich gegen Assyrien auflehnte, belagerten die Assyrer Samaria und nahmen es 740 v. u. Z. ein.","facts":[{"t":"Er ermordete Pekach.","r":{"t":"2. Könige 15:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015030"}},{"t":"Er wurde dem König von Assyrien tributpflichtig.","r":{"t":"2. Könige 17:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/17/#v12017003"}},{"t":"Er suchte Hilfe bei Ägypten und wurde gefangen gesetzt.","r":{"t":"2. Könige 17:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/17/#v12017004"}},{"t":"In seinem 9. Jahr fiel Samaria.","r":{"t":"2. Könige 17:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/17/#v12017006"}}],"lesson":"","family":{"father":"Ela","mother":"","spouses":[],"children":[],"siblings":[]},"related":["pekach"],"events":["fall-samarias"],"books":[],"refs":[{"t":"2. Könige 17:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/17/#v12017001-v12017006"},{"t":"2. Könige 18:9-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/18/#v12018009-v12018012"}],"sources":[{"title":"Hoschea – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002090"},{"title":"A6-B Propheten und Könige von Juda und Israel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070215"}]},{"id":"hosea","name":"Hosea","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet, Sohn Beeris","eras":["geteilt"],"dates":[{"label":"Wirken","value":"Ende 9. und Anfang 8. Jahrhundert v. u. Z."}],"year":-810,"meaning":"Kurzform von Hoschaja","summary":"Hosea, der Sohn Beeris, war ein Prophet Jehovas während der Herrschaft der Könige Usija, Jotham, Ahas und Hiskia von Juda und Jerobeams II. von Israel. Er schrieb das Bibelbuch Hosea, in dem die Untreue Israels mit der Untreue einer Ehefrau verglichen wird. Amos, Jesaja und Micha waren seine Zeitgenossen.","facts":[{"t":"Er war der Sohn Beeris.","r":{"t":"Hosea 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hosea/1/#v28001001"}},{"t":"Seine Ehe mit Gomer veranschaulichte Israels Untreue.","r":{"t":"Hosea 1:2, 3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hosea/1/#v28001002"}},{"t":"Er rief Israel auf, zu Jehova umzukehren.","r":{"t":"Hosea 14:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hosea/14/#v28014001"}}],"lesson":"","family":{"father":"Beeri","mother":"","spouses":["Gomer"],"children":[],"siblings":[]},"related":["amos","jesaja","micha"],"events":[],"books":["Hosea"],"refs":[{"t":"Hosea 1:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hosea/1/#v28001001-v28001011"},{"t":"Hosea 3:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hosea/3/#v28003001-v28003005"},{"t":"Hosea 14:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hosea/14/#v28014001-v28014009"}],"sources":[{"title":"Hosea – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002086"}]},{"id":"hulda","name":"Hulda","alt":[],"sex":"f","tags":["prophet"],"role":"Prophetin zur Zeit Josias","eras":["geteilt"],"dates":[],"year":-642,"meaning":"Femininum von Heled: „Lebensdauer“","summary":"Hulda, die Frau Schallums, diente in Jerusalem als Prophetin während der Herrschaft König Josias. Als das Buch des Gesetzes im Tempel gefunden worden war, ließ Josia Jehova durch sie befragen. Sie kündigte an, dass das Unglück über die abtrünnige Nation kommen werde, Josia es aber wegen seiner Demut nicht mehr erleben müsse.","facts":[{"t":"Josias Abordnung ging zu ihr, um Jehova zu befragen.","r":{"t":"2. Könige 22:12-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/22/#v12022012-v12022014"}},{"t":"Sie kündigte Unglück über Jerusalem an.","r":{"t":"2. Könige 22:15-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/22/#v12022015-v12022017"}},{"t":"Josia sollte das Unglück wegen seiner Demut nicht sehen.","r":{"t":"2. Könige 22:18-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/22/#v12022018-v12022020"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Schallum"],"children":[],"siblings":[]},"related":["josia"],"events":["josias-reform"],"books":[],"refs":[{"t":"2. Könige 22:14-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/22/#v12022014-v12022020"},{"t":"2. Chronika 34:22-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/34/#v14034022-v14034028"}],"sources":[{"title":"Hulda – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002101"}]},{"id":"isaak","name":"Isaak","alt":[],"sex":"m","tags":["patriarch","vorfahr-jesu"],"role":"Patriarch, Sohn Abrahams","eras":["patriarchen"],"dates":[{"label":"Lebenszeit","value":"1918–1738 v. u. Z."},{"label":"Alter","value":"180 Jahre"}],"year":-1918,"meaning":"„Lachen“, „Gelächter“","summary":"Isaak war der einzige Sohn Abrahams und Saras und ein wichtiges Glied in der zu Christus führenden Abstammungslinie. Er wurde geboren, als seine Eltern schon sehr alt waren – ein Beweis, dass für Jehova nichts zu außergewöhnlich ist. Mit etwa 25 Jahren wurde er „so gut wie geopfert“, mit 40 heiratete er Rebekka, mit 60 wurde er Vater der Zwillinge Esau und Jakob.","facts":[{"t":"Wurde am 8. Tag beschnitten und mit etwa 5 Jahren entwöhnt.","r":{"t":"1. Mose 21:4-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021004-v1021008"}},{"t":"Abraham war bereit, ihn auf einem Berg im Land Moria zu opfern.","r":{"t":"1. Mose 22:1-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/22/#v1022001-v1022014"}},{"t":"Heiratete mit 40 Jahren Rebekka.","r":{"t":"1. Mose 25:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025020"}},{"t":"Wurde mit 60 Jahren Vater von Esau und Jakob.","r":{"t":"1. Mose 25:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025026"}},{"t":"Starb 1738 v. u. Z. in Hebron mit 180 Jahren.","r":{"t":"1. Mose 35:28, 29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/35/#v1035028"}}],"lesson":"","family":{"father":"abraham","mother":"sara","spouses":["rebekka"],"children":["esau","jakob"],"siblings":["ismael"]},"related":[],"events":["geburt-isaaks","hagar-und-ismael","opferung-isaaks","isaak-heiratet-rebekka","tod-abrahams","esau-verkauft-erstgeburtsrecht","jakob-erhaelt-den-segen"],"books":[],"refs":[{"t":"1. Mose 21:1-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021001-v1021007"},{"t":"1. Mose 22:1-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/22/#v1022001-v1022018"},{"t":"1. Mose 25:19-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025019-v1025026"},{"t":"Galater 4:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/4/#v48004028"}],"sources":[{"title":"Isaak – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002203"}]},{"id":"isebel","name":"Isebel","alt":[],"sex":"f","tags":[],"role":"Frau König Ahabs","eras":["geteilt"],"dates":[{"label":"Zeit","value":"2. Hälfte des 10. Jahrhunderts v. u. Z."}],"year":-940,"meaning":"„Wo ist der Erhabene?“ (vielleicht, phönizisch)","summary":"Isebel, die Tochter des Sidonierkönigs Ethbaal, war die Frau König Ahabs. Sie war eine herrschsüchtige, fanatische Verfechterin des Baalskults und wollte die Anbetung Jehovas verdrängen. Sie ließ Jehovas Propheten töten und trachtete Elia nach dem Leben. Um Naboths Weingarten für Ahab zu bekommen, ließ sie Naboth durch falsche Zeugen umbringen. Bei Jehus Gericht wurde sie aus dem Fenster gestürzt.","facts":[{"t":"Sie ließ Jehovas Propheten töten.","r":{"t":"1. Könige 18:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/18/#v11018004"}},{"t":"Sie schwor, Elia umzubringen.","r":{"t":"1. Könige 19:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/19/#v11019001"}},{"t":"Sie ließ Naboth durch falsche Zeugen töten.","r":{"t":"1. Könige 21:5-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/21/#v11021005-v11021016"}},{"t":"Sie wurde auf Jehus Befehl aus dem Fenster gestürzt.","r":{"t":"2. Könige 9:30-37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009030-v12009037"}}],"lesson":"","family":{"father":"Ethbaal","mother":"","spouses":["ahab"],"children":["ahasja-israel","joram-israel","athalja"],"siblings":[]},"related":["elia","jehu"],"events":["elia-am-horeb","jehu-vollstreckt-gericht"],"books":[],"refs":[{"t":"1. Könige 16:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016031"},{"t":"1. Könige 21:1-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/21/#v11021001-v11021025"},{"t":"2. Könige 9:30-37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009030-v12009037"}],"sources":[{"title":"Isebel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002463"}]},{"id":"ismael","name":"Ismael","alt":[],"sex":"m","tags":[],"role":"Erster Sohn Abrahams","eras":["patriarchen"],"dates":[{"label":"Geboren","value":"1932 v. u. Z."}],"year":-1932,"meaning":"„Gott hört (erhört)“","summary":"Ismael war der Sohn Abrahams und der ägyptischen Magd Hagar, geboren 1932 v. u. Z., als Abraham 86 Jahre alt war. Gott versprach, ihn zu segnen und zu einer großen Nation zu machen; Erbe des Bundes sollte aber Isaak sein. Weil Ismael den jüngeren Isaak verspottete, wurden er und seine Mutter 1913 v. u. Z. weggeschickt.","facts":[{"t":"Geboren, als Abraham 86 Jahre alt war.","r":{"t":"1. Mose 16:15, 16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/16/#v1016015"}},{"t":"Gott verhieß, dass er zwölf Vorsteher hervorbringen und eine große Nation werden würde.","r":{"t":"1. Mose 17:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/17/#v1017020"}},{"t":"Wurde mit 13 Jahren zusammen mit Abraham beschnitten.","r":{"t":"1. Mose 17:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/17/#v1017025"}},{"t":"Verspottete Isaak an dem Tag, als dieser entwöhnt wurde.","r":{"t":"1. Mose 21:8, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021008"}},{"t":"Begrub zusammen mit Isaak seinen Vater.","r":{"t":"1. Mose 25:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025009"}}],"lesson":"","family":{"father":"abraham","mother":"hagar","spouses":[],"children":[],"siblings":["isaak"]},"related":[],"events":["hagar-und-ismael","tod-abrahams"],"books":[],"refs":[{"t":"1. Mose 16:11-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/16/#v1016011-v1016016"},{"t":"1. Mose 17:18-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/17/#v1017018-v1017020"},{"t":"1. Mose 21:8-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021008-v1021021"},{"t":"Galater 4:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/4/#v48004029"}],"sources":[{"title":"Ismael – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002215"}]},{"id":"jael","name":"Jael","alt":[],"sex":"f","tags":[],"role":"Frau des Keniters Heber","eras":["richter"],"dates":[],"year":-1300,"meaning":"„Steinbock“","summary":"Jael war die Frau des Keniters Heber und keine Israelitin. Als der kanaanitische Heerführer Sisera nach seiner Niederlage zu ihrem Zelt floh, nahm sie ihn auf, gab ihm Milch zu trinken und deckte ihn zu. Als er fest schlief, tötete sie ihn. So erfüllte sich Deboras Prophezeiung, dass eine Frau die Ehre des Sieges erhalten würde.","facts":[{"t":"Ihr Mann Heber lebte im Frieden mit den Kanaanitern.","r":{"t":"Richter 4:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004017"}},{"t":"Sie gab Sisera geronnene Milch zu trinken.","r":{"t":"Richter 5:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/5/#v7005025"}},{"t":"Sie tötete Sisera, als er schlief.","r":{"t":"Richter 4:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004021"}},{"t":"Im Lied Deboras wird sie gesegnet.","r":{"t":"Richter 5:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/5/#v7005024"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Heber"],"children":[],"siblings":[]},"related":["debora","barak"],"events":["debora-und-barak"],"books":[],"refs":[{"t":"Richter 4:17-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004017-v7004022"},{"t":"Richter 5:24-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/5/#v7005024-v7005027"}],"sources":[{"title":"Jael – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002286"}]},{"id":"jakob","name":"Jakob","alt":["Israel"],"sex":"m","tags":["patriarch","vorfahr-jesu"],"role":"Patriarch, Stammvater Israels","eras":["patriarchen","aegypten"],"dates":[{"label":"Lebenszeit","value":"1858–1711 v. u. Z."},{"label":"Alter","value":"147 Jahre"}],"year":-1858,"meaning":"„Einer, der die Ferse ergreift“, „Verdränger“","summary":"Jakob, der jüngere Zwillingssohn Isaaks und Rebekkas, war ein Mann, der in Zelten wohnte und Gottes Verheißungen hoch schätzte. Er erwarb von Esau das Erstgeburtsrecht und erhielt den Segen seines Vaters. In Haran heiratete er Lea und Rahel; seine zwölf Söhne wurden die Stammväter Israels. Nach einem Ringkampf mit einem Engel erhielt er den Namen Israel.","facts":[{"t":"Bei der Geburt hielt er die Ferse Esaus fest – daher sein Name.","r":{"t":"1. Mose 25:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025026"}},{"t":"Er floh 1781 v. u. Z. vor Esau nach Haran.","r":{"t":"1. Mose 28:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/28/#v1028001-v1028005"}},{"t":"Er diente Laban 14 Jahre für Lea und Rahel.","r":{"t":"1. Mose 29:18-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029018-v1029030"}},{"t":"Am Jabbok rang er mit einem Engel und wurde Israel genannt.","r":{"t":"1. Mose 32:24-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/32/#v1032024-v1032028"}},{"t":"1728 v. u. Z. zog er mit 130 Jahren nach Ägypten.","r":{"t":"1. Mose 47:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/47/#v1047009"}},{"t":"Nach 17 Jahren in Ägypten starb er mit 147 Jahren.","r":{"t":"1. Mose 47:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/47/#v1047028"}}],"lesson":"","family":{"father":"isaak","mother":"rebekka","spouses":["lea","rahel","Bilha","Silpa"],"children":["ruben","simeon","levi","juda","dina","joseph","benjamin"],"siblings":["esau"]},"related":["laban"],"events":["esau-verkauft-erstgeburtsrecht","jakob-erhaelt-den-segen","jakobs-traum","jakob-heiratet","jakob-ringt-mit-engel","joseph-wird-verkauft","jakob-zieht-nach-aegypten","tod-jakobs"],"books":[],"refs":[{"t":"1. Mose 25:19-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025019-v1025034"},{"t":"1. Mose 28:10-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/28/#v1028010-v1028022"},{"t":"1. Mose 32:24-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/32/#v1032024-v1032030"},{"t":"1. Mose 49:1-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/49/#v1049001-v1049033"}],"sources":[{"title":"Jakob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002279"},{"title":"Rahel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003621"}]},{"id":"jakobus-zebedaeus","name":"Jakobus","alt":["Jakobus, Sohn des Zebedäus"],"sex":"m","tags":["apostel"],"role":"Apostel, Sohn des Zebedäus","eras":["jesus","versammlung"],"dates":[{"label":"Gestorben","value":"sehr wahrscheinlich 44 u. Z."}],"year":29,"meaning":"Form von Jakob: „Einer, der die Ferse ergreift“","summary":"Jakobus, der Sohn des Zebedäus und Bruder des Apostels Johannes, arbeitete im Fischereibetrieb seines Vaters, als Jesus ihn berief. Seine Mutter war vermutlich Salome. Mit Petrus und Johannes gehörte er zu den drei Aposteln, die Jesus bei besonderen Anlässen mitnahm. Sehr wahrscheinlich 44 u. Z. ließ Herodes Agrippa I. ihn mit dem Schwert hinrichten – er war der erste der zwölf Apostel, der als Märtyrer starb.","facts":[{"t":"Er verließ das Boot seines Vaters, um Jesus zu folgen.","r":{"t":"Matthäus 4:21, 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/4/#v40004021"}},{"t":"Jesus nannte ihn und Johannes „Söhne des Donners“.","r":{"t":"Markus 3:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/3/#v41003017"}},{"t":"Er erlebte die Umgestaltung Jesu mit.","r":{"t":"Matthäus 17:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/17/#v40017001"}},{"t":"Herodes ließ ihn mit dem Schwert töten.","r":{"t":"Apostelgeschichte 12:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012001"}}],"lesson":"","family":{"father":"Zebedäus","mother":"Salome","spouses":[],"children":[],"siblings":["johannes-apostel"]},"related":["petrus"],"events":["wahl-der-apostel","umgestaltung","petrus-befreit"],"books":[],"refs":[{"t":"Matthäus 4:21, 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/4/#v40004021"},{"t":"Markus 3:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/3/#v41003017"},{"t":"Apostelgeschichte 12:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012001"}],"sources":[{"title":"Jakobus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002313"}]},{"id":"jakobus-alphaeus","name":"Jakobus","alt":["Jakobus, Sohn des Alphäus","Jakobus der Geringere"],"sex":"m","tags":["apostel"],"role":"Apostel, Sohn des Alphäus","eras":["jesus"],"dates":[],"year":31,"meaning":"Form von Jakob","summary":"Jakobus, der Sohn des Alphäus, war ein weiterer Apostel Jesu dieses Namens. Möglicherweise war Alphäus mit Klopas identisch; dann wäre seine Mutter jene Maria, die „die Mutter Jakobus’ des Geringeren“ genannt wird. Vielleicht hieß er „der Geringere“, weil er kleiner oder jünger war als Jakobus, der Sohn des Zebedäus.","facts":[{"t":"Er steht in allen Apostellisten.","r":{"t":"Matthäus 10:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/10/#v40010003"}},{"t":"Er war nach Jesu Himmelfahrt mit den anderen Aposteln zusammen.","r":{"t":"Apostelgeschichte 1:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001013"}},{"t":"Eine Maria wird „Mutter Jakobus’ des Geringeren“ genannt.","r":{"t":"Markus 15:40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/15/#v41015040"}}],"lesson":"","family":{"father":"Alphäus","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["wahl-der-apostel"],"books":[],"refs":[{"t":"Matthäus 10:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/10/#v40010003"},{"t":"Apostelgeschichte 1:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001013"}],"sources":[{"title":"Jakobus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002313"}]},{"id":"jakobus-halbbruder-jesu","name":"Jakobus","alt":["Jakobus, Bruder Jesu","Jakobus, Halbbruder Jesu"],"sex":"m","tags":["schreiber","juenger"],"role":"Halbbruder Jesu, Schreiber des Jakobusbriefs","eras":["jesus","versammlung"],"dates":[{"label":"Zeit","value":"Jakobusbrief vor 62 u. Z. in Jerusalem geschrieben"}],"year":33,"meaning":"Form von Jakob: „Einer, der die Ferse ergreift“","summary":"Jakobus war ein Sohn von Joseph und Maria und damit ein Halbbruder Jesu – wahrscheinlich der älteste der vier Brüder. Während Jesu Dienst glaubten seine Brüder noch nicht an ihn. Nach seiner Auferstehung erschien Jesus Jakobus persönlich. Jakobus wurde ein führender Aufseher der Versammlung in Jerusalem und schlug 49 u. Z. die Entscheidung in der Beschneidungsfrage vor. Er schrieb den Jakobusbrief.","facts":[{"t":"Seine Brüder glaubten zunächst nicht an Jesus.","r":{"t":"Johannes 7:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/7/#v43007005"}},{"t":"Der auferweckte Jesus erschien ihm.","r":{"t":"1. Korinther 15:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-korinther/15/#v46015007"}},{"t":"Er schlug eine Entscheidung zur Beschneidung vor.","r":{"t":"Apostelgeschichte 15:13-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015013-v44015021"}},{"t":"Er nannte sich „Sklave Gottes und des Herrn Jesus Christus“.","r":{"t":"Jakobus 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jakobus/1/#v59001001"}}],"lesson":"","family":{"father":"joseph-marias-mann","mother":"maria","spouses":[],"children":[],"siblings":["jesus","judas-halbbruder-jesu","Joseph","Simon"]},"related":["petrus","paulus"],"events":["pfingsten-33","beschneidungsfrage"],"books":["Jakobus"],"refs":[{"t":"Matthäus 13:55","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/13/#v40013055"},{"t":"Apostelgeschichte 12:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012017"},{"t":"Galater 1:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/1/#v48001019"},{"t":"Galater 2:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/2/#v48002009"}],"sources":[{"title":"Jakobus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002313"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"japhet","name":"Japhet","alt":[],"sex":"m","tags":[],"role":"Sohn Noahs","eras":["anfaenge","patriarchen"],"dates":[{"label":"Geboren","value":"2470 v. u. Z. (wahrscheinlich)"}],"year":-2470,"meaning":"„Möge er weiten Raum gewähren“","summary":"Japhet war ein Sohn Noahs und anscheinend der älteste der drei Brüder. Er und seine Frau gehörten zu den acht Menschen, die in der Arche die Sintflut überlebten. Nach der Flut bekamen sie sieben Söhne, von denen aus sich die Bewohner der Inseln und Küstenländer ausbreiteten.","facts":[{"t":"Überlebte die Sintflut mit seiner Frau in der Arche.","r":{"t":"1. Petrus 3:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-petrus/3/#v60003020"}},{"t":"Bedeckte mit Sem respektvoll die Blöße seines Vaters.","r":{"t":"1. Mose 9:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009023"}},{"t":"Seine Söhne: Gomer, Magog, Madai, Jawan, Tubal, Meschech und Tiras.","r":{"t":"1. Mose 10:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/10/#v1010002"}}],"lesson":"","family":{"father":"noah","mother":"","spouses":[],"children":["Gomer","Magog","Madai","Jawan","Tubal","Meschech","Tiras"],"siblings":["sem","ham"]},"related":[],"events":["bau-der-arche","sintflut"],"books":[],"refs":[{"t":"1. Mose 9:18-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009018-v1009027"},{"t":"1. Mose 10:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/10/#v1010001-v1010005"}],"sources":[{"title":"Japhet – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002323"}]},{"id":"joahas-juda","name":"Jehoahas","alt":["Joahas","Schallum"],"sex":"m","tags":["koenig"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"628 v. u. Z. (3 Monate)"}],"year":-628,"meaning":"„Jehova hat ergriffen“","summary":"Jehoahas, ein Sohn Josias und Hamutals, wurde nach dem Tod seines Vaters vom Volk zum König gewählt, obwohl er nicht der älteste Sohn war. Er regierte nur drei Monate; dann setzte ihn Pharao Necho ab und führte ihn nach Ägypten, wo er starb.","facts":[{"t":"Er wurde mit 23 Jahren König.","r":{"t":"2. Könige 23:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/23/#v12023031"}},{"t":"Pharao Necho nahm ihn gefangen.","r":{"t":"2. Könige 23:33, 34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/23/#v12023033"}},{"t":"Jeremia kündigte an, dass er nicht zurückkehren werde.","r":{"t":"Jeremia 22:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/22/#v24022011"}}],"lesson":"","family":{"father":"josia","mother":"Hamutal","spouses":[],"children":[],"siblings":["jojakim","zedekia"]},"related":[],"events":[],"books":[],"refs":[{"t":"2. Könige 23:30-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/23/#v12023030-v12023034"},{"t":"2. Chronika 36:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/36/#v14036001-v14036004"}],"sources":[{"title":"Jehoahas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002372"},{"title":"A6-B Propheten und Könige von Juda und Israel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070215"}]},{"id":"jehoahas-israel","name":"Jehoahas","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"876 – um 860 v. u. Z. (17 Jahre)"}],"year":-876,"meaning":"„Jehova hat ergriffen“","summary":"Jehoahas, der Sohn Jehus, regierte 17 Jahre über Israel. Weil er tat, was böse war, ließ Jehova zu, dass Hasael von Syrien Israel bedrückte, bis von seinem Heer nur noch ein kleiner Rest übrig war. Als Jehoahas Jehova besänftigte, erhielt Israel einen Retter.","facts":[{"t":"Hasael bedrückte Israel alle seine Tage.","r":{"t":"2. Könige 13:3, 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/13/#v12013003"}},{"t":"Er besänftigte Jehova, und Jehova hörte ihn.","r":{"t":"2. Könige 13:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/13/#v12013004"}},{"t":"Ihm blieben nur 50 Reiter, 10 Wagen und 10 000 Mann.","r":{"t":"2. Könige 13:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/13/#v12013007"}}],"lesson":"","family":{"father":"jehu","mother":"","spouses":[],"children":["joas-israel"],"siblings":[]},"related":[],"events":[],"books":[],"refs":[{"t":"2. Könige 13:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/13/#v12013001-v12013009"}],"sources":[{"title":"Jehoahas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002372"}]},{"id":"jojada","name":"Jehojada","alt":["Jojada"],"sex":"m","tags":["priester"],"role":"Hoher Priester zur Zeit von Joas","eras":["geteilt"],"dates":[],"year":-905,"meaning":"„Möge Jehova wissen“","summary":"Jehojada war Hoher Priester zur Zeit Jorams, Ahasjas, Athaljas und des Joas. Er war mit Jehoscheba verheiratet, die den kleinen Joas vor Athalja rettete. Nach sechs Jahren stürzte er Athalja, setzte Joas als König ein und erhob die wahre Anbetung wieder zu ihrer richtigen Stellung.","facts":[{"t":"Seine Frau Jehoscheba versteckte Joas.","r":{"t":"2. Chronika 22:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/22/#v14022011"}},{"t":"Im siebten Jahr ließ er Joas zum König krönen.","r":{"t":"2. Könige 11:4-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011004-v12011012"}},{"t":"Er schloss einen Bund, dass das Volk Jehova gehören sollte.","r":{"t":"2. Könige 11:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011017"}},{"t":"Man begrub ihn bei den Königen.","r":{"t":"2. Chronika 24:15, 16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/24/#v14024015"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Jehoscheba"],"children":["Sacharja"],"siblings":[]},"related":["joas-juda","athalja"],"events":["athalja-und-joas"],"books":[],"refs":[{"t":"2. Könige 11:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011001-v12011021"},{"t":"2. Chronika 23:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/23/#v14023001-v14023021"},{"t":"2. Chronika 24:15, 16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/24/#v14024015"}],"sources":[{"title":"Jehojada – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002376"}]},{"id":"jehova","name":"Jehova","alt":["JHWH","Gott, der Allmächtige"],"sex":"","tags":["gott"],"role":"Gott, der Schöpfer","eras":[],"dates":[],"year":null,"meaning":"„Er lässt werden“","summary":"Jehova ist der Eigenname Gottes. Titel wie „Gott“, „Schöpfer“, „Vater“ oder „der Allmächtige“ beschreiben ihn – doch erst sein Name bringt zum Ausdruck, wer und was er ist. In den Hebräischen Schriften der Neuen-Welt-Übersetzung steht der Name 6979-mal, denn Jehova wollte, dass sein Name auf der ganzen Erde bekannt wird.","facts":[{"t":"Nur sein Eigenname drückt seine Persönlichkeit mit all seinen Eigenschaften voll aus.","r":{"t":"Psalm 83:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/psalmen/83/#v19083018"}},{"t":"In den ältesten hebräischen Handschriften steht der Name als vier Konsonanten (JHWH), das sogenannte Tetragrammaton."},{"t":"„Jehova“ ist im deutschen Sprachraum die überlieferte Aussprache des Gottesnamens."},{"t":"Jehova kündigte an, seinen Namen auf der ganzen Erde verkünden zu lassen.","r":{"t":"2. Mose 9:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/9/#v2009016"}},{"t":"Er ist der Schöpfer der Himmel und der Erde.","r":{"t":"1. Mose 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001001"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["schoepfung","erschaffung-des-menschen","suendenfall","kain-und-abel","regenbogenbund","hiobs-pruefung","brennender-dornbusch","zehn-plagen","gesetzesbund","bund-mit-david","salomo-bittet-um-weisheit"],"books":[],"refs":[{"t":"Psalm 83:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/psalmen/83/#v19083018"},{"t":"Jesaja 42:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/42/#v23042008"},{"t":"2. Mose 9:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/9/#v2009016"}],"sources":[{"title":"Jehova – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002391"}]},{"id":"jehu","name":"Jehu","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 904–877 v. u. Z. (28 Jahre)"}],"year":-905,"meaning":"„Jehova ist er“ (vielleicht)","summary":"Jehu, ein Militärbefehlshaber, wurde auf Jehovas Anweisung von einem Prophetensohn im Auftrag Elisas zum König gesalbt. Entschlossen vollstreckte er das Urteil an Ahabs Haus: Er tötete Joram von Israel, Ahasja von Juda und Isebel und vernichtete den Baalskult in Israel. Doch die goldenen Kälber Jerobeams ließ er bestehen.","facts":[{"t":"Er wurde in Ramoth-Gilead gesalbt.","r":{"t":"2. Könige 9:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009001-v12009010"}},{"t":"Er tötete König Joram.","r":{"t":"2. Könige 9:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009024"}},{"t":"Isebel wurde aus dem Fenster gestürzt.","r":{"t":"2. Könige 9:30-37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009030-v12009037"}},{"t":"Er tilgte Baal aus Israel, nicht aber die goldenen Kälber.","r":{"t":"2. Könige 10:28, 29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/10/#v12010028"}}],"lesson":"","family":{"father":"Josaphat","mother":"","spouses":[],"children":["jehoahas-israel"],"siblings":[]},"related":["elisa","isebel","joram-israel"],"events":["elia-am-horeb","jehu-vollstreckt-gericht"],"books":[],"refs":[{"t":"2. Könige 9:1–10:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009001-v12010036"}],"sources":[{"title":"Jehu – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002401"}]},{"id":"jephtha","name":"Jephtha","alt":[],"sex":"m","tags":["richter"],"role":"Richter in Gilead","eras":["richter"],"dates":[{"label":"Wirken","value":"6 Jahre, ab etwa 1173 v. u. Z."}],"year":-1173,"meaning":"„(Gott) hat geöffnet“","summary":"Jephtha aus dem Stamm Manasse richtete das Land Gilead sechs Jahre lang, wahrscheinlich zur Zeit Elis. Von seinen Halbbrüdern vertrieben, wurde er später von den Ältesten Gileads zurückgeholt, um gegen die Ammoniter zu kämpfen. Vor der Schlacht legte er ein Gelübde ab: Wer ihm nach dem Sieg zuerst aus seinem Haus entgegenkäme, sollte Jehova gehören. Das war seine einzige Tochter.","facts":[{"t":"Er richtete Israel sechs Jahre.","r":{"t":"Richter 12:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/12/#v7012007"}},{"t":"Er verwies auf die 300 Jahre, die Israel das Land östlich des Jordan besaß.","r":{"t":"Richter 11:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011026"}},{"t":"Jehovas Geist kam auf ihn, und er besiegte die Ammoniter.","r":{"t":"Richter 11:29-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011029-v7011033"}},{"t":"Er erfüllte sein Gelübde, obwohl es ihn seine einzige Tochter kostete.","r":{"t":"Richter 11:34-39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011034-v7011039"}}],"lesson":"","family":{"father":"Gilead","mother":"","spouses":[],"children":["jephthas-tochter"],"siblings":[]},"related":[],"events":["zeit-der-richter","jephthas-geluebde"],"books":[],"refs":[{"t":"Richter 11:1-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011001-v7011040"},{"t":"Hebräer 11:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011032"}],"sources":[{"title":"Jephtha – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002413"}]},{"id":"jephthas-tochter","name":"Jephthas Tochter","alt":[],"sex":"f","tags":[],"role":"Diente ihr Leben lang am Heiligtum","eras":["richter"],"dates":[],"year":-1172,"meaning":"","summary":"Jephthas einzige Tochter kam ihrem Vater nach seinem Sieg über die Ammoniter als Erste entgegen. Wegen seines Gelübdes sollte sie „Jehova gehören“. Laut jw.org bedeutete das kein Menschenopfer – das wäre für Jehova abscheulich gewesen –, sondern dass sie unverheiratet für immer im Dienst am Heiligtum stand, ähnlich wie Samuel von seiner Mutter Gott zur Verfügung gestellt wurde.","facts":[{"t":"Sie kam ihrem Vater mit Tamburinen und Tanz entgegen.","r":{"t":"Richter 11:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011034"}},{"t":"Sie unterstützte ihren Vater darin, sein Gelübde zu halten.","r":{"t":"Richter 11:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011036"}},{"t":"Sie blieb unverheiratet.","r":{"t":"Richter 11:37-39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011037-v7011039"}},{"t":"Jedes Jahr besuchten die Töchter Israels sie, um sie zu loben.","r":{"t":"Richter 11:40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011040"}}],"lesson":"","family":{"father":"jephtha","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["jephthas-geluebde"],"books":[],"refs":[{"t":"Richter 11:34-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011034-v7011040"}],"sources":[{"title":"Jephtha – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002413"}]},{"id":"jeremia","name":"Jeremia","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet in Juda","eras":["geteilt","exil"],"dates":[{"label":"Wirken","value":"ab 647 v. u. Z."}],"year":-647,"meaning":"„Jehova erhöht“ (vielleicht)","summary":"Jeremia, der Sohn Hilkijas, eines Priesters aus Anathoth, wurde 647 v. u. Z. als junger Mann zum Propheten berufen. Obwohl er sich selbst für zu jung hielt, verkündete er über 40 Jahre lang mutig Jehovas Gericht über Juda und Jerusalem. Er wurde verspottet, geschlagen und eingesperrt, erlebte aber die Erfüllung seiner Prophezeiung: die Zerstörung Jerusalems 607 v. u. Z. Er schrieb die Bücher Jeremia, Klagelieder sowie 1. und 2. Könige.","facts":[{"t":"Jehova sagte: „Zum Propheten für die Nationen machte ich dich.“","r":{"t":"Jeremia 1:4-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/1/#v24001004-v24001010"}},{"t":"Er diktierte Baruch seine Prophezeiungen.","r":{"t":"Jeremia 36:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/36/#v24036004"}},{"t":"Er wurde in eine schlammige Zisterne geworfen.","r":{"t":"Jeremia 38:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/38/#v24038006"}},{"t":"Er sagte 70 Jahre der Verwüstung voraus.","r":{"t":"Jeremia 25:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/25/#v24025011"}},{"t":"Nach der Zerstörung Jerusalems schrieb er die Klagelieder."}],"lesson":"","family":{"father":"Hilkija","mother":"","spouses":[],"children":[],"siblings":[]},"related":["baruch","ebed-melech","josia","zedekia"],"events":["jeremia-wird-berufen","zerstoerung-jerusalems-607"],"books":["Jeremia","Klagelieder","1. Könige","2. Könige"],"refs":[{"t":"Jeremia 1:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/1/#v24001001-v24001010"},{"t":"Jeremia 20:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/20/#v24020009"},{"t":"Jeremia 25:8-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/25/#v24025008-v24025012"},{"t":"Jeremia 38:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/38/#v24038001-v24038013"}],"sources":[{"title":"Jeremia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002421"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"jerobeam","name":"Jerobeam","alt":["Jerobeam I."],"sex":"m","tags":["koenig"],"role":"Erster König des Zehnstämmereichs Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"ab 997 v. u. Z. (22 Jahre)"}],"year":-997,"meaning":"","summary":"Jerobeam, der Sohn Nebats, ein Ephraimiter, war unter Salomo Aufseher über die Fronarbeiter. Der Prophet Ahija kündigte ihm an, dass er über zehn Stämme regieren werde. Nach der Reichsteilung 997 v. u. Z. wurde er König Israels. Damit das Volk nicht mehr zum Tempel nach Jerusalem ging, stellte er goldene Kälber in Bethel und Dan auf – eine Sünde, die das Nordreich bis zu seinem Ende prägte.","facts":[{"t":"Salomo machte ihn zum Aufseher über die Fronarbeiter.","r":{"t":"1. Könige 11:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/11/#v11011028"}},{"t":"Ahija riss sein Gewand in zwölf Stücke und gab ihm zehn.","r":{"t":"1. Könige 11:29-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/11/#v11011029-v11011031"}},{"t":"Er stellte goldene Kälber in Bethel und Dan auf.","r":{"t":"1. Könige 12:28, 29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/12/#v11012028"}},{"t":"Er setzte Priester ein, die keine Leviten waren.","r":{"t":"1. Könige 12:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/12/#v11012031"}}],"lesson":"","family":{"father":"Nebat","mother":"Zerua","spouses":[],"children":["nadab"],"siblings":[]},"related":["rehabeam"],"events":["reichsteilung"],"books":[],"refs":[{"t":"1. Könige 11:26-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/11/#v11011026-v11011040"},{"t":"1. Könige 12:20-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/12/#v11012020-v11012033"},{"t":"1. Könige 14:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/14/#v11014001-v11014020"}],"sources":[{"title":"Jerobeam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002431"},{"title":"A6-A Propheten und Könige von Juda und Israel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070206"}]},{"id":"jerobeam-ii","name":"Jerobeam II.","alt":["Jerobeam"],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 844 v. u. Z. (41 Jahre)"}],"year":-844,"meaning":"","summary":"Jerobeam II., der Sohn des Joas und Urenkel Jehus, regierte 41 Jahre als 14. Herrscher des Nordreichs. Wie Jona vorhergesagt hatte, stellte er die Grenzen Israels wieder her. Doch auch er ließ die von Jerobeam I. eingeführte Kälberverehrung bestehen. In seiner Zeit wirkten Jona, Hosea und Amos.","facts":[{"t":"Er tat, was böse war in Jehovas Augen.","r":{"t":"2. Könige 14:23, 24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/14/#v12014023"}},{"t":"Er stellte die Grenzen Israels wieder her, wie Jona angekündigt hatte.","r":{"t":"2. Könige 14:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/14/#v12014025"}},{"t":"Amos prophezeite gegen sein Haus.","r":{"t":"Amos 7:9-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/amos/7/#v30007009-v30007011"}}],"lesson":"","family":{"father":"joas-israel","mother":"","spouses":[],"children":["secharja"],"siblings":[]},"related":["jona","amos","hosea"],"events":[],"books":[],"refs":[{"t":"2. Könige 14:23-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/14/#v12014023-v12014029"}],"sources":[{"title":"Jerobeam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002431"}]},{"id":"jesaja","name":"Jesaja","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet in Juda","eras":["geteilt"],"dates":[{"label":"Wirken","value":"um 778 bis nach 732 v. u. Z."}],"year":-778,"meaning":"„Rettung von Jehova“","summary":"Jesaja, der Sohn des Amoz, diente Juda und Jerusalem als Prophet in den Tagen der Könige Usija, Jotham, Ahas und Hiskia – ungefähr ab 778 v. u. Z. bis nach 732 v. u. Z. Er erlebte den Untergang des Nordreichs Israel 740 v. u. Z. In einer schlimmen Zeit kündigte er Gericht an, aber auch Trost und Rettung für einen treuen Überrest.","facts":[{"t":"In einer Vision sah er Jehova auf seinem Thron und sagte: „Hier bin ich! Sende mich.“","r":{"t":"Jesaja 6:1-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/6/#v23006001-v23006008"}},{"t":"Seine Frau wird als „Prophetin“ bezeichnet.","r":{"t":"Jesaja 8:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/8/#v23008003"}},{"t":"Er ermutigte Hiskia, als Sanherib Jerusalem bedrohte.","r":{"t":"Jesaja 37:5-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/37/#v23037005-v23037007"}},{"t":"Er war ein Zeitgenosse von Micha, Hosea und Oded."}],"lesson":"","family":{"father":"Amoz","mother":"","spouses":[],"children":[],"siblings":[]},"related":["hiskia","ahas","usija","micha"],"events":["jesaja-wird-berufen","sanherib-bedroht-jerusalem"],"books":["Jesaja"],"refs":[{"t":"Jesaja 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/1/#v23001001"},{"t":"Jesaja 6:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/6/#v23006001-v23006013"},{"t":"Jesaja 37:21-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/37/#v23037021-v23037035"}],"sources":[{"title":"Jesaja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002204"}]},{"id":"jeschua","name":"Jeschua","alt":["Josua"],"sex":"m","tags":["priester"],"role":"Hoher Priester nach dem Exil","eras":["rueckkehr"],"dates":[{"label":"Zeit","value":"Rückkehr 537 v. u. Z."}],"year":-537,"meaning":"Kurzform von Josua: „Jehova ist Rettung“ (vielleicht)","summary":"Jeschua, in den Büchern Haggai und Sacharja Josua genannt, war der Sohn Jozadaks und ein Nachkomme Eleasars. Sein Vater war von Nebukadnezar nach Babylon weggeführt worden. 537 v. u. Z. kehrte Jeschua mit Serubbabel zurück und diente als Hoher Priester für den wiederhergestellten Überrest. So bewahrte Jehova die Linie der Hohen Priester.","facts":[{"t":"Er kehrte mit Serubbabel zurück.","r":{"t":"Esra 2:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/2/#v15002002"}},{"t":"Er baute mit anderen den Altar wieder auf.","r":{"t":"Esra 3:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/3/#v15003002"}},{"t":"In einer Vision Sacharjas wurde er von Satan angeklagt.","r":{"t":"Sacharja 3:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/3/#v38003001-v38003005"}}],"lesson":"","family":{"father":"Jozadak","mother":"","spouses":[],"children":[],"siblings":[]},"related":["serubbabel","sacharja","haggai"],"events":["rueckkehr-nach-jerusalem","tempelfundament","tempel-vollendet"],"books":[],"refs":[{"t":"Esra 3:2, 8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/3/#v15003002"},{"t":"Haggai 1:1, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/1/#v37001001"},{"t":"Sacharja 3:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/3/#v38003001-v38003010"}],"sources":[{"title":"Jeschua – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002446"}]},{"id":"jesus","name":"Jesus Christus","alt":["Jesus","Christus","Messias","Michael","das Wort","Jesus von Nazareth"],"sex":"m","tags":["prophet","koenig","priester"],"role":"Sohn Gottes, Messias und König","eras":["jesus","versammlung"],"dates":[{"label":"Lebenszeit","value":"auf der Erde 2 v. u. Z. – 33 u. Z."}],"year":-2,"meaning":"Jesus: „Jehova ist Rettung“; Christus: „Gesalbter“","summary":"Jesus Christus ist der Sohn Gottes. Bevor er Mensch wurde, lebte er im Himmel als „das Wort“, der Erstgeborene aller Schöpfung. 2 v. u. Z. wurde er in Bethlehem geboren, 29 u. Z. getauft und mit heiligem Geist gesalbt. Dreieinhalb Jahre predigte er über das Königreich Gottes. Am 14. Nisan 33 u. Z. starb er am Marterpfahl, am dritten Tag wurde er auferweckt. Durch sein Opfer werden Sündenvergebung und ewiges Leben möglich.","facts":[{"t":"Im Himmel war er „das Wort“, der Erstgeborene aller Schöpfung.","r":{"t":"Kolosser 1:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/kolosser/1/#v51001015"}},{"t":"Er wurde 2 v. u. Z., um den 1. Oktober, in Bethlehem geboren.","r":{"t":"Lukas 2:4-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002004-v42002007"}},{"t":"Bei seiner Taufe 29 u. Z. nannte Jehova ihn seinen Sohn.","r":{"t":"Matthäus 3:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/3/#v40003016"}},{"t":"Er predigte: „Das Königreich des Himmels ist nah.“","r":{"t":"Matthäus 4:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/4/#v40004017"}},{"t":"Am 14. Nisan 33 u. Z. starb er am Marterpfahl.","r":{"t":"Johannes 19:16-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019016-v43019030"}},{"t":"Laut jw.org bezieht sich der Name Michael auf Gottes Sohn – vor und nach seinem Leben auf der Erde.","r":{"t":"1. Thessalonicher 4:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-thessalonicher/4/#v52004016"}}],"lesson":"","family":{"father":"jehova","mother":"maria","spouses":[],"children":[],"siblings":["jakobus-halbbruder-jesu","judas-halbbruder-jesu","Joseph","Simon"]},"related":["joseph-marias-mann","johannes-der-taeufer","petrus","johannes-apostel","maria-magdalene"],"events":["ankuendigung-jesu","geburt-jesu","darstellung-im-tempel","astrologen-und-flucht","zwoelfjaehriger-jesus","taufe-jesu","versuchung","erste-juenger","hochzeit-in-kana","erste-tempelreinigung","samariterin","bergpredigt","wahl-der-apostel","speisung-der-5000","jesus-geht-auf-dem-wasser","umgestaltung","auferweckung-des-lazarus","einzug-in-jerusalem","abendmahl-des-herrn","gethsemane","tod-jesu","auferweckung-jesu","himmelfahrt"],"books":[],"refs":[{"t":"Johannes 1:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001001-v43001003"},{"t":"Johannes 3:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/3/#v43003016"},{"t":"Matthäus 20:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/20/#v40020028"},{"t":"Philipper 2:5-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philipper/2/#v50002005-v50002011"}],"sources":[{"title":"Jesus Christus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002451"},{"title":"Michael – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003035"},{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"},{"title":"B1 Das Hauptthema der Bibel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070221"}]},{"id":"jethro","name":"Jethro","alt":["Reguel"],"sex":"m","tags":["priester"],"role":"Priester von Midian, Schwiegervater von Moses","eras":["aegypten"],"dates":[],"year":-1560,"meaning":"von einer Wurzel mit der Bedeutung „mehr als genug“","summary":"Jethro, auch Reuel genannt, war ein Keniter und „der Priester von Midian“ – das Haupt einer großen Familie. Moses lebte 40 Jahre bei ihm und hütete seine Herden. Später besuchte Jethro Moses in der Wildnis und gab ihm den klugen Rat, tüchtige Männer als Oberste einzusetzen, die ihm beim Richten helfen sollten.","facts":[{"t":"Er hatte mindestens sieben Töchter.","r":{"t":"2. Mose 2:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002016"}},{"t":"Er gab Moses seine Tochter Zippora zur Frau.","r":{"t":"2. Mose 2:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002021"}},{"t":"Er riet Moses, die Last des Richtens auf andere zu verteilen.","r":{"t":"2. Mose 18:13-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/18/#v2018013-v2018026"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":["zippora"],"siblings":[]},"related":["moses"],"events":["moses-flieht-nach-midian"],"books":[],"refs":[{"t":"2. Mose 2:15-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002015-v2002022"},{"t":"2. Mose 18:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/18/#v2018001-v2018027"}],"sources":[{"title":"Jethro – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002454"}]},{"id":"joab","name":"Joab","alt":[],"sex":"m","tags":[],"role":"Heerführer Davids","eras":["koenigreich"],"dates":[],"year":-1077,"meaning":"„Jehova ist Vater“","summary":"Joab, ein Sohn Zerujas und Neffe Davids, war Davids Heerführer. Er war tüchtig, erfinderisch und tatkräftig, aber auch ehrgeizig, rachsüchtig und manchmal skrupellos. Er tötete Abner, um seinen Bruder Asahel zu rächen, und später gegen Davids ausdrücklichen Wunsch Absalom. Am Ende schloss er sich Adonia an und wurde unter Salomo hingerichtet.","facts":[{"t":"Seine Brüder waren Abischai und Asahel.","r":{"t":"1. Chronika 2:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/2/#v13002016"}},{"t":"Er tötete Abner aus Rache.","r":{"t":"2. Samuel 3:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/3/#v10003027"}},{"t":"Er führte Davids Befehl aus, Uria an die Front zu stellen.","r":{"t":"2. Samuel 11:14-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011014-v10011017"}},{"t":"Er tötete Absalom.","r":{"t":"2. Samuel 18:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/18/#v10018014"}},{"t":"Er wurde auf Salomos Befehl hingerichtet.","r":{"t":"1. Könige 2:28-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/2/#v11002028-v11002034"}}],"lesson":"","family":{"father":"","mother":"Zeruja","spouses":[],"children":[],"siblings":["Abischai","Asahel"]},"related":["david","absalom"],"events":["david-koenig-in-hebron","david-erobert-jerusalem","david-und-batseba","absaloms-aufstand"],"books":[],"refs":[{"t":"2. Samuel 3:22-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/3/#v10003022-v10003030"},{"t":"2. Samuel 18:9-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/18/#v10018009-v10018017"},{"t":"1. Könige 2:28-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/2/#v11002028-v11002034"}],"sources":[{"title":"Joab – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002469"}]},{"id":"joas-juda","name":"Joas","alt":["Jehoas"],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"898–859 v. u. Z. (40 Jahre)"}],"year":-898,"meaning":"","summary":"Joas, der jüngste Sohn Ahasjas, wurde als Kleinkind vor Athaljas Mordplan gerettet und sechs Jahre im Tempel versteckt. Mit sieben Jahren wurde er König und tat, solange der Hohe Priester Jehojada lebte, was recht war; er ließ den Tempel ausbessern. Nach Jehojadas Tod jedoch wandte er sich dem Götzendienst zu und ließ dessen Sohn Sacharja steinigen.","facts":[{"t":"Er wurde mit sieben Jahren König.","r":{"t":"2. Könige 11:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011021"}},{"t":"Er ließ das Haus Jehovas ausbessern.","r":{"t":"2. Könige 12:4-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/12/#v12012004-v12012015"}},{"t":"Nach Jehojadas Tod ließ er Sacharja steinigen.","r":{"t":"2. Chronika 24:17-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/24/#v14024017-v14024022"}},{"t":"Er wurde von seinen eigenen Dienern ermordet.","r":{"t":"2. Chronika 24:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/24/#v14024025"}}],"lesson":"","family":{"father":"ahasja-juda","mother":"Zibja","spouses":[],"children":["amazja"],"siblings":[]},"related":["jojada","athalja"],"events":["athalja-und-joas"],"books":[],"refs":[{"t":"2. Könige 11:1–12:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011001-v12012021"},{"t":"2. Chronika 24:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/24/#v14024001-v14024027"}],"sources":[{"title":"Joas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002474"}]},{"id":"joas-israel","name":"Joas","alt":["Jehoas"],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 859 v. u. Z. (16 Jahre)"}],"year":-859,"meaning":"","summary":"Joas, der Sohn des Jehoahas und Enkel Jehus, regierte 16 Jahre über Israel und ließ die Kälberverehrung bestehen. Er besuchte den sterbenden Propheten Elisa, der ihm drei Siege über Syrien ankündigte. Später besiegte er Amazja von Juda und plünderte Jerusalem.","facts":[{"t":"Er weinte am Sterbebett Elisas.","r":{"t":"2. Könige 13:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/13/#v12013014"}},{"t":"Er schlug Syrien dreimal.","r":{"t":"2. Könige 13:18, 19, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/13/#v12013018"}},{"t":"Er besiegte Amazja und brach in die Mauer Jerusalems ein.","r":{"t":"2. Könige 14:11-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/14/#v12014011-v12014014"}}],"lesson":"","family":{"father":"jehoahas-israel","mother":"","spouses":[],"children":["jerobeam-ii"],"siblings":[]},"related":["elisa","amazja"],"events":[],"books":[],"refs":[{"t":"2. Könige 13:10-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/13/#v12013010-v12013025"},{"t":"2. Könige 14:8-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/14/#v12014008-v12014016"}],"sources":[{"title":"Joas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002474"}]},{"id":"jochebed","name":"Jochebed","alt":[],"sex":"f","tags":[],"role":"Mutter von Moses, Aaron und Mirjam","eras":["aegypten"],"dates":[],"year":-1620,"meaning":"„Jehova ist Herrlichkeit“ (vielleicht)","summary":"Jochebed, eine Tochter Levis, war mit Amram verheiratet und die Mutter von Mirjam, Aaron und Moses. Sie glaubte fest an Jehova: Trotz Pharaos Befehl tötete sie ihren neugeborenen Sohn nicht, sondern verbarg ihn drei Monate lang und legte ihn dann in einem Papyruskästchen ins Schilf am Nil. Pharaos Tochter fand ihn – und Jochebed durfte ihn stillen.","facts":[{"t":"Sie verbarg ihren Säugling drei Monate lang.","r":{"t":"2. Mose 2:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002002"}},{"t":"Sie legte ihn in einem Papyruskästchen ins Schilf am Nil.","r":{"t":"2. Mose 2:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002003"}},{"t":"Pharaos Tochter beauftragte sie, das Kind zu stillen.","r":{"t":"2. Mose 2:7-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002007-v2002009"}},{"t":"Mit ihrem Mann lehrte sie ihre Kinder die reine Anbetung."}],"lesson":"","family":{"father":"levi","mother":"","spouses":["Amram"],"children":["mirjam","aaron","moses"],"siblings":[]},"related":[],"events":["geburt-moses"],"books":[],"refs":[{"t":"2. Mose 2:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002001-v2002010"},{"t":"2. Mose 6:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/6/#v2006020"},{"t":"Hebräer 11:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011023"}],"sources":[{"title":"Jochebed – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002478"}]},{"id":"joel","name":"Joel","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet, Sohn Pethuels","eras":["geteilt"],"dates":[{"label":"Zeit","value":"Buch vielleicht um 820 v. u. Z."}],"year":-820,"meaning":"„Jehova ist Gott“","summary":"Joel, der Sohn Pethuels, war ein Prophet Jehovas und schrieb das nach ihm benannte Bibelbuch. Über sein Leben ist wenig bekannt; sein Buch wurde vielleicht um 820 v. u. Z. geschrieben. Bekannt ist besonders seine Prophezeiung, dass Gott seinen Geist auf Menschen aller Art ausgießen werde.","facts":[{"t":"Er war der Sohn Pethuels.","r":{"t":"Joel 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/joel/1/#v29001001"}},{"t":"Er kündigte den großen Tag Jehovas an.","r":{"t":"Joel 2:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/joel/2/#v29002001"}},{"t":"Er sagte die Ausgießung von Gottes Geist voraus.","r":{"t":"Joel 2:28, 29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/joel/2/#v29002028"}}],"lesson":"","family":{"father":"Pethuel","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["pfingsten-33"],"books":["Joel"],"refs":[{"t":"Joel 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/joel/1/#v29001001"},{"t":"Joel 2:28-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/joel/2/#v29002028-v29002032"},{"t":"Apostelgeschichte 2:16-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/2/#v44002016-v44002021"}],"sources":[{"title":"Joel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002481"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"johannes-apostel","name":"Johannes","alt":["Johannes, der Apostel","Johannes, Sohn des Zebedäus"],"sex":"m","tags":["apostel","schreiber"],"role":"Apostel, Sohn des Zebedäus","eras":["jesus","versammlung"],"dates":[{"label":"Gestorben","value":"um 100 u. Z."}],"year":29,"meaning":"„Jehova hat Gunst erwiesen“","summary":"Johannes, der Sohn des Zebedäus und Bruder des Jakobus, war einer der zwölf Apostel und gehörte mit Petrus und Jakobus zu Jesu engsten Gefährten. Beim letzten Passah saß er neben Jesus, und Jesus vertraute ihm vom Marterpfahl aus seine Mutter an. Um 96 u. Z. schrieb er in der Verbannung auf Patmos die Offenbarung; danach schrieb er von Ephesus aus sein Evangelium und drei Briefe. Er starb um 100 u. Z. als letzter der Apostel.","facts":[{"t":"Jesus nannte ihn und Jakobus „Söhne des Donners“.","r":{"t":"Markus 3:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/3/#v41003017"}},{"t":"Beim letzten Passah lag er neben Jesus.","r":{"t":"Johannes 13:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/13/#v43013023"}},{"t":"Jesus vertraute ihm seine Mutter an.","r":{"t":"Johannes 19:26, 27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019026"}},{"t":"Auf Patmos erhielt er die Offenbarung.","r":{"t":"Offenbarung 1:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/1/#v66001009"}}],"lesson":"","family":{"father":"Zebedäus","mother":"Salome","spouses":[],"children":[],"siblings":["jakobus-zebedaeus"]},"related":["petrus","jesus","maria"],"events":["erste-juenger","wahl-der-apostel","umgestaltung","abendmahl-des-herrn","tod-jesu","pfingsten-33","philippus-und-der-aethiopier","offenbarung-auf-patmos","abschluss-der-bibel"],"books":["Johannes","1. Johannes","2. Johannes","3. Johannes","Offenbarung"],"refs":[{"t":"Johannes 13:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/13/#v43013023"},{"t":"Johannes 19:26, 27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019026"},{"t":"Johannes 21:20-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/21/#v43021020-v43021024"},{"t":"Offenbarung 1:1, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/1/#v66001001"}],"sources":[{"title":"Johannes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002489"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"johannes-der-taeufer","name":"Johannes der Täufer","alt":["Johannes"],"sex":"m","tags":["prophet"],"role":"Vorläufer Jesu","eras":["jesus"],"dates":[{"label":"Geboren","value":"2 v. u. Z."},{"label":"Wirken","value":"ab Frühjahr 29 u. Z."}],"year":-2,"meaning":"„Jehova hat Gunst erwiesen“","summary":"Johannes, der Sohn Sacharjas und Elisabeths, wurde durch ein Wunder Gottes geboren und war sein Leben lang Nasiräer. Ab dem Frühjahr 29 u. Z. predigte er in der Wildnis Reue und taufte. Im Herbst taufte er Jesus und wies seine Jünger auf ihn als „das Lamm Gottes“ hin. Weil er Herodes Antipas wegen dessen Ehe mit Herodias zurechtwies, wurde er eingesperrt und später enthauptet.","facts":[{"t":"Gabriel kündigte seine Geburt an.","r":{"t":"Lukas 1:13-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001013-v42001017"}},{"t":"Er bereitete Jehova ein Volk vor.","r":{"t":"Lukas 1:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001017"}},{"t":"Er nannte Jesus „das Lamm Gottes“.","r":{"t":"Johannes 1:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001029"}},{"t":"Durch ihn erfüllte sich die Prophezeiung über das Kommen „Elias“.","r":{"t":"Matthäus 17:10-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/17/#v40017010-v40017013"}},{"t":"Laut jw.org gehört er nicht zur „Braut“, die mit Christus im Himmel regiert.","r":{"t":"Matthäus 11:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/11/#v40011011"}}],"lesson":"","family":{"father":"zacharias","mother":"elisabeth","spouses":[],"children":[],"siblings":[]},"related":["jesus","herodes-antipas","andreas"],"events":["ankuendigung-johannes","geburt-johannes","johannes-tauft","taufe-jesu","erste-juenger","tod-johannes-des-taeufers"],"books":[],"refs":[{"t":"Lukas 1:13-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001013-v42001017"},{"t":"Lukas 3:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003001-v42003020"},{"t":"Johannes 1:19-36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001019-v43001036"},{"t":"Matthäus 14:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/14/#v40014001-v40014012"}],"sources":[{"title":"Johannes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002489"},{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"}]},{"id":"jojachin","name":"Jojachin","alt":["Jechonja","Konja"],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt","exil"],"dates":[{"label":"Regierung","value":"618–617 v. u. Z. (3 Monate, 10 Tage)"}],"year":-618,"meaning":"„Jehova hat befestigt“ (wahrscheinlich)","summary":"Jojachin, auch Jechonja genannt, wurde mit 18 Jahren König und setzte den schlechten Weg seines Vaters Jojakim fort. Nach nur drei Monaten und zehn Tagen ergab er sich 617 v. u. Z. Nebukadnezar und wurde mit Tausenden Judäern nach Babylon weggeführt. 580 v. u. Z. ließ ihn Ewil-Merodach aus dem Gefängnis frei.","facts":[{"t":"Er tat, was böse war in Jehovas Augen.","r":{"t":"2. Könige 24:8, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024008"}},{"t":"Er wurde mit seinen Fürsten nach Babylon weggeführt.","r":{"t":"2. Könige 24:12-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024012-v12024015"}},{"t":"Im fünften Jahr seines Exils begann Hesekiel zu prophezeien.","r":{"t":"Hesekiel 1:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/1/#v26001002"}},{"t":"580 v. u. Z. ließ ihn Ewil-Merodach frei.","r":{"t":"2. Könige 25:27-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/25/#v12025027-v12025030"}}],"lesson":"","family":{"father":"jojakim","mother":"Nehuschta","spouses":[],"children":[],"siblings":[]},"related":["nebukadnezar","hesekiel"],"events":["wegfuehrung-jojachins","hesekiel-wird-prophet"],"books":[],"refs":[{"t":"2. Könige 24:8-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024008-v12024017"},{"t":"2. Könige 25:27-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/25/#v12025027-v12025030"},{"t":"Matthäus 1:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001011"}],"sources":[{"title":"Jojachin – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002375"}]},{"id":"jojakim","name":"Jojakim","alt":["Eljakim"],"sex":"m","tags":["koenig"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"628–618 v. u. Z. (11 Jahre)"}],"year":-628,"meaning":"„Jehova richtet auf“ (vielleicht)","summary":"Jojakim, ursprünglich Eljakim genannt, ein Sohn Josias, wurde von Pharao Necho als König eingesetzt. Seine Herrschaft war von Ungerechtigkeit, Bedrückung und Blutvergießen geprägt. Später wurde er Nebukadnezar tributpflichtig und lehnte sich 618 v. u. Z. gegen ihn auf.","facts":[{"t":"Pharao Necho machte ihn zum König.","r":{"t":"2. Könige 23:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/23/#v12023034"}},{"t":"Er verbrannte die Buchrolle mit Jeremias Prophezeiungen.","r":{"t":"Jeremia 36:22-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/36/#v24036022-v24036024"}},{"t":"Er ließ den Propheten Urija töten.","r":{"t":"Jeremia 26:20-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/26/#v24026020-v24026023"}},{"t":"Nebukadnezar machte ihn zum Vasallen.","r":{"t":"2. Könige 24:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024001"}}],"lesson":"","family":{"father":"josia","mother":"Sebida","spouses":["Nehuschta"],"children":["jojachin"],"siblings":["joahas-juda","zedekia"]},"related":["jeremia","baruch","nebukadnezar"],"events":[],"books":[],"refs":[{"t":"2. Könige 23:34–24:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/23/#v12023034-v12024006"},{"t":"Jeremia 36:1-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/36/#v24036001-v24036032"}],"sources":[{"title":"Jojakim – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002377"}]},{"id":"jona","name":"Jona","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet, Bote nach Ninive","eras":["geteilt"],"dates":[{"label":"Wirken","value":"zur Zeit Jerobeams II. (Buch um 844 v. u. Z.)"}],"year":-844,"meaning":"„Taube“","summary":"Jona, der Sohn Amittais aus Gath-Hepher, war ein Prophet in Israel zur Zeit Jerobeams II. Als Jehova ihn beauftragte, Ninive das Gericht anzukündigen, floh er per Schiff in Richtung Tarschisch. In einem Sturm warf man ihn ins Meer, und ein großer Fisch verschlang ihn. Nach drei Tagen kam er frei, ging nach Ninive – und die Niniviten bereuten. Jona schrieb das gleichnamige Buch.","facts":[{"t":"Er sagte die Wiederherstellung der Grenzen Israels voraus.","r":{"t":"2. Könige 14:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/14/#v12014025"}},{"t":"Er floh vor seinem Auftrag nach Joppe.","r":{"t":"Jona 1:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jona/1/#v32001001-v32001003"}},{"t":"Er betete im Innern eines großen Fisches.","r":{"t":"Jona 2:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jona/2/#v32002001-v32002010"}},{"t":"Die Niniviten bereuten in Sacktuch.","r":{"t":"Jona 3:4-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jona/3/#v32003004-v32003010"}},{"t":"Jehova lehrte ihn mit einer Flaschenkürbispflanze Mitgefühl.","r":{"t":"Jona 4:6-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jona/4/#v32004006-v32004011"}}],"lesson":"","family":{"father":"Amittai","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jerobeam-ii"],"events":["jona-in-ninive"],"books":["Jona"],"refs":[{"t":"Jona 1:1–4:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jona/1/#v32001001-v32004011"},{"t":"Matthäus 12:39-41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/12/#v40012039-v40012041"}],"sources":[{"title":"Jona – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002503"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"jonathan","name":"Jonathan","alt":[],"sex":"m","tags":[],"role":"Sohn Sauls, Freund Davids","eras":["koenigreich"],"dates":[{"label":"Gestorben","value":"um 1078 v. u. Z."}],"year":-1138,"meaning":"„Jehova hat gegeben“","summary":"Jonathan war der älteste Sohn König Sauls und ein tapferer Heerführer. Bekannt ist er vor allem für seine uneigennützige Freundschaft mit David, den Jehova als König bestimmt hatte – obwohl Jonathan selbst Thronerbe war und etwa 30 Jahre älter als David. Er schloss einen Bund mit David und schützte ihn vor Sauls Zorn. Um 1078 v. u. Z. fiel er mit seinem Vater auf dem Gilboa.","facts":[{"t":"Er befehligte schon früh tausend Krieger.","r":{"t":"1. Samuel 13:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/13/#v9013002"}},{"t":"Er schloss mit David einen Bund und gab ihm sein Obergewand.","r":{"t":"1. Samuel 18:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/18/#v9018001-v9018004"}},{"t":"Er warnte David vor Sauls Absichten.","r":{"t":"1. Samuel 20:12-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/20/#v9020012-v9020017"}},{"t":"Er starb im Kampf gegen die Philister.","r":{"t":"1. Samuel 31:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/31/#v9031002"}}],"lesson":"","family":{"father":"saul","mother":"Ahinoam","spouses":[],"children":["mephiboscheth"],"siblings":["michal","Isch-Boscheth"]},"related":["david"],"events":["david-flieht-vor-saul","sauls-tod"],"books":[],"refs":[{"t":"1. Samuel 18:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/18/#v9018001-v9018004"},{"t":"1. Samuel 20:1-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/20/#v9020001-v9020042"},{"t":"2. Samuel 1:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/1/#v10001025"}],"sources":[{"title":"Jonathan – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002506"}]},{"id":"joram-juda","name":"Joram","alt":["Jehoram"],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"ab 913 v. u. Z. (8 Jahre)"}],"year":-913,"meaning":"„Jehova ist hoch (ist erhaben)“","summary":"Joram (Jehoram), der Erstgeborene Josaphats, wurde mit 32 Jahren König von Juda. Er heiratete Athalja, die Tochter Ahabs und Isebels, und folgte dem schlechten Weg des Hauses Ahab. Zeitweise regierten in Juda und Israel gleichnamige Könige.","facts":[{"t":"Er war mit Athalja verheiratet.","r":{"t":"2. Könige 8:16-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/8/#v12008016-v12008018"}},{"t":"Er tat, was böse war in Jehovas Augen.","r":{"t":"2. Chronika 21:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/21/#v14021006"}},{"t":"Philister und Araber drangen in Juda ein.","r":{"t":"2. Chronika 21:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/21/#v14021016"}}],"lesson":"","family":{"father":"josaphat","mother":"","spouses":["athalja"],"children":["ahasja-juda"],"siblings":[]},"related":[],"events":[],"books":[],"refs":[{"t":"2. Könige 8:16-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/8/#v12008016-v12008024"},{"t":"2. Chronika 21:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/21/#v14021001-v14021020"}],"sources":[{"title":"Joram – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002381"}]},{"id":"joram-israel","name":"Joram","alt":["Jehoram"],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 917 v. u. Z. (12 Jahre)"}],"year":-917,"meaning":"„Jehova ist hoch“","summary":"Joram (Jehoram), ein Sohn Ahabs und Isebels, folgte seinem Bruder Ahasja als König Israels und regierte 12 Jahre. In seiner Zeit wirkte Elisa als Prophet. Bei Ramoth-Gilead im Krieg gegen Syrien verwundet, wurde er in Jesreel von Jehu getötet.","facts":[{"t":"Er entfernte die Säule Baals, hielt aber an Jerobeams Sünden fest.","r":{"t":"2. Könige 3:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/3/#v12003001-v12003003"}},{"t":"Elisa wirkte während seiner Regierung.","r":{"t":"2. Könige 3:11-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/3/#v12003011-v12003020"}},{"t":"Jehu tötete ihn mit einem Pfeil.","r":{"t":"2. Könige 9:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009024"}}],"lesson":"","family":{"father":"ahab","mother":"isebel","spouses":[],"children":[],"siblings":["ahasja-israel","athalja"]},"related":["elisa","jehu","naaman"],"events":["naaman-wird-geheilt","jehu-vollstreckt-gericht"],"books":[],"refs":[{"t":"2. Könige 3:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/3/#v12003001-v12003027"},{"t":"2. Könige 9:14-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009014-v12009026"}],"sources":[{"title":"Joram – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002381"}]},{"id":"josaphat","name":"Josaphat","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"ab 936 v. u. Z. (25 Jahre)"}],"year":-937,"meaning":"„Jehova ist Richter“","summary":"Josaphat, der Sohn Asas, wurde mit 35 Jahren König und regierte 25 Jahre. Seine Herrschaft war von Stabilität, Wohlstand und Frieden geprägt. Er sandte Fürsten, Leviten und Priester aus, um das Volk aus dem Buch des Gesetzes zu lehren. Doch er verschwägerte sich mit dem gottlosen König Ahab – sein Sohn Joram heiratete Athalja.","facts":[{"t":"Im dritten Jahr ließ er das Gesetz Jehovas im Land lehren.","r":{"t":"2. Chronika 17:7-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/17/#v14017007-v14017009"}},{"t":"Er verbündete sich mit Ahab im Krieg.","r":{"t":"2. Chronika 18:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/18/#v14018001-v14018003"}},{"t":"Vor einem übermächtigen Feind vertraute er auf Jehova.","r":{"t":"2. Chronika 20:12-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/20/#v14020012-v14020017"}}],"lesson":"","family":{"father":"asa","mother":"Asuba","spouses":[],"children":["joram-juda"],"siblings":[]},"related":["ahab"],"events":[],"books":[],"refs":[{"t":"2. Chronika 17:1-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/17/#v14017001-v14017019"},{"t":"2. Chronika 20:1-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/20/#v14020001-v14020030"},{"t":"1. Könige 22:41-50","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/22/#v11022041-v11022050"}],"sources":[{"title":"Josaphat – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002383"}]},{"id":"joseph","name":"Joseph","alt":["Josef"],"sex":"m","tags":[],"role":"Sohn Jakobs, Verwalter Ägyptens","eras":["patriarchen","aegypten"],"dates":[{"label":"Gestorben","value":"1657 v. u. Z."},{"label":"Alter","value":"110 Jahre"}],"year":-1767,"meaning":"„Möge Jah hinzufügen (mehren)“","summary":"Joseph war der erste Sohn Jakobs und Rahels und der Lieblingssohn seines Vaters. Aus Eifersucht verkauften ihn seine Halbbrüder als Sklaven nach Ägypten. Dort blieb er Jehova treu – auch als Potiphars Frau ihn verführen wollte und er unschuldig ins Gefängnis kam. Gott ließ ihn Pharaos Träume deuten; Joseph wurde Verwalter Ägyptens und rettete in der Hungersnot seine Familie.","facts":[{"t":"Er wurde geboren, als Jakob etwa 91 Jahre alt war.","r":{"t":"1. Mose 30:22-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/30/#v1030022-v1030024"}},{"t":"Mit 17 Jahren hütete er Schafe; Jakob schenkte ihm ein langes gestreiftes Gewand.","r":{"t":"1. Mose 37:2, 3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037002"}},{"t":"Er erzählte Träume, die eine künftige Vorrangstellung andeuteten.","r":{"t":"1. Mose 37:5-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037005-v1037010"}},{"t":"Er widerstand den Annäherungen der Frau Potiphars.","r":{"t":"1. Mose 39:7-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/39/#v1039007-v1039012"}},{"t":"Er deutete Pharaos Träume und wurde über Ägypten gesetzt.","r":{"t":"1. Mose 41:14-41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/41/#v1041014-v1041041"}},{"t":"Er starb mit 110 Jahren und gab Anweisung wegen seiner Gebeine.","r":{"t":"1. Mose 50:22-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/50/#v1050022-v1050026"}}],"lesson":"","family":{"father":"jakob","mother":"rahel","spouses":["Asenath"],"children":["Manasse","Ephraim"],"siblings":["benjamin","ruben","simeon","levi","juda","dina"]},"related":["potiphar"],"events":["joseph-wird-verkauft","joseph-wird-verwalter","joseph-gibt-sich-zu-erkennen","jakob-zieht-nach-aegypten","tod-jakobs","tod-josephs"],"books":[],"refs":[{"t":"1. Mose 37:2-36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037002-v1037036"},{"t":"1. Mose 39:1–41:57","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/39/#v1039001-v1041057"},{"t":"1. Mose 45:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/45/#v1045001-v1045015"},{"t":"Hebräer 11:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011022"}],"sources":[{"title":"Joseph – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002515"}]},{"id":"joseph-marias-mann","name":"Joseph","alt":["Josef","Joseph, Marias Mann"],"sex":"m","tags":[],"role":"Mann Marias, Adoptivvater Jesu","eras":["jesus"],"dates":[],"year":-25,"meaning":"„Möge Jah hinzufügen (mehren)“","summary":"Joseph, ein Nachkomme Davids, war Zimmermann in Nazareth. Als seine Verlobte Maria vor der Heirat durch heiligen Geist schwanger wurde, wollte er sie zunächst heimlich entlassen; nach der Erklärung eines Engels im Traum nahm er sie zur Frau. Er war gerecht, gehorchte Gottes Anweisungen und hielt sich an das Gesetz. Er brachte seine Familie vor Herodes nach Ägypten in Sicherheit und wurde später Vater von mindestens vier Söhnen und von Töchtern.","facts":[{"t":"Er war Zimmermann in Nazareth.","r":{"t":"Matthäus 13:55","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/13/#v40013055"}},{"t":"Ein Engel erklärte ihm im Traum, was geschehen war.","r":{"t":"Matthäus 1:19-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001019-v40001024"}},{"t":"Er floh mit Maria und Jesus nach Ägypten.","r":{"t":"Matthäus 2:13-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002013-v40002015"}},{"t":"Er wird in Lukas 3:23 „Sohn des Heli“ genannt.","r":{"t":"Lukas 3:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003023"}}],"lesson":"","family":{"father":"Jakob","mother":"","spouses":["maria"],"children":["jakobus-halbbruder-jesu","judas-halbbruder-jesu"],"siblings":[]},"related":["jesus"],"events":["geburt-jesu","darstellung-im-tempel","astrologen-und-flucht","zwoelfjaehriger-jesus"],"books":[],"refs":[{"t":"Matthäus 1:18-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001018-v40001025"},{"t":"Matthäus 2:13-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002013-v40002023"},{"t":"Lukas 2:39-51","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002039-v42002051"}],"sources":[{"title":"Joseph – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002515"}]},{"id":"joseph-von-arimathaea","name":"Joseph von Arimathia","alt":["Joseph"],"sex":"m","tags":["juenger"],"role":"Ratsherr, der Jesus bestattete","eras":["jesus"],"dates":[],"year":33,"meaning":"Kurzform von Josiphja: „Möge Jah hinzufügen (mehren)“","summary":"Joseph war ein reicher Mann aus der judäischen Stadt Arimathia und ein angesehenes Mitglied des Sanhedrins. Er war gut und gerecht und wartete auf Gottes Königreich, bekannte sich aber aus Furcht nicht offen als Jünger Jesu. Dem Vorgehen des Sanhedrins gegen Jesus stimmte er nicht zu. Nach Jesu Tod bat er Pilatus mutig um den Leib und legte ihn in seine neue Felsengruft.","facts":[{"t":"Er war ein Jünger, aber heimlich aus Furcht vor den Juden.","r":{"t":"Johannes 19:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019038"}},{"t":"Er hatte dem Beschluss des Rates nicht zugestimmt.","r":{"t":"Lukas 23:50, 51","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/23/#v42023050"}},{"t":"Er ging mutig zu Pilatus und bat um Jesu Leib.","r":{"t":"Markus 15:43","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/15/#v41015043"}},{"t":"Er legte Jesus in seine neue Gruft im Felsen.","r":{"t":"Matthäus 27:57-60","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/27/#v40027057-v40027060"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jesus","nikodemus","pilatus"],"events":["tod-jesu"],"books":[],"refs":[{"t":"Matthäus 27:57-60","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/27/#v40027057-v40027060"},{"t":"Markus 15:42-46","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/15/#v41015042-v41015046"},{"t":"Lukas 23:50-53","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/23/#v42023050-v42023053"},{"t":"Johannes 19:38-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019038-v43019042"}],"sources":[{"title":"Joseph – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002515"}]},{"id":"josia","name":"Josia","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"659–629 v. u. Z. (31 Jahre)"}],"year":-659,"meaning":"„Jehova hat geheilt“ (falls mit einer arabischen Wurzel verwandt)","summary":"Josia wurde mit acht Jahren König, nachdem sein Vater Amon ermordet worden war. Im 8. Regierungsjahr begann er, Jehova zu suchen, und ab dem 12. Jahr reinigte er Juda und sogar Teile des früheren Nordreichs vom Götzendienst. Bei der Ausbesserung des Tempels wurde das Buch des Gesetzes gefunden. Er feierte ein Passah wie keines zuvor. Gegen Ende seiner Regierung fiel er bei Megiddo im Kampf gegen Pharao Necho.","facts":[{"t":"Mit 16 Jahren begann er, den Gott Davids zu suchen.","r":{"t":"2. Chronika 34:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/34/#v14034003"}},{"t":"Er vernichtete die Altäre der falschen Götter.","r":{"t":"2. Chronika 34:3-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/34/#v14034003-v14034007"}},{"t":"Das Buch des Gesetzes wurde im Tempel gefunden.","r":{"t":"2. Könige 22:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/22/#v12022008"}},{"t":"Er feierte ein außergewöhnliches Passah.","r":{"t":"2. Könige 23:21-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/23/#v12023021-v12023023"}},{"t":"Er wurde bei Megiddo tödlich verwundet.","r":{"t":"2. Chronika 35:20-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/35/#v14035020-v14035024"}}],"lesson":"","family":{"father":"amon","mother":"Jedida","spouses":["Hamutal","Sebida"],"children":["joahas-juda","jojakim","zedekia","Johanan"],"siblings":[]},"related":["jeremia","zephanja","hulda"],"events":["jeremia-wird-berufen","josias-reform"],"books":[],"refs":[{"t":"2. Könige 22:1–23:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/22/#v12022001-v12023030"},{"t":"2. Chronika 34:1–35:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/34/#v14034001-v14035027"}],"sources":[{"title":"Josia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002525"}]},{"id":"josua","name":"Josua","alt":["Hoschea"],"sex":"m","tags":["schreiber"],"role":"Nachfolger von Moses, Heerführer Israels","eras":["richter","aegypten"],"dates":[{"label":"Alter","value":"110 Jahre"}],"year":-1513,"meaning":"„Jehova ist Rettung“","summary":"Josua, der Sohn Nuns aus dem Stamm Ephraim, diente Moses und wurde später sein Nachfolger. Er war ein mutiger Anführer, der den Verheißungen Jehovas völlig vertraute. Als Kundschafter gab er mit Kaleb einen guten Bericht. Unter seiner Führung zog Israel über den Jordan, nahm das Land Kanaan ein und verteilte es unter die Stämme. Er starb mit 110 Jahren.","facts":[{"t":"1513 v. u. Z. führte er Israel bei Rephidim gegen die Amalekiter.","r":{"t":"2. Mose 17:8-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/17/#v2017008-v2017013"}},{"t":"Mit Kaleb gab er einen guten Bericht über das Land.","r":{"t":"4. Mose 14:6-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/14/#v4014006-v4014009"}},{"t":"Er wurde zum Nachfolger von Moses bestimmt.","r":{"t":"5. Mose 34:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/5-mose/34/#v5034009"}},{"t":"Er führte Israel über den Jordan und nahm Jericho ein.","r":{"t":"Josua 6:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/6/#v6006001-v6006021"}},{"t":"Er verteilte das Land durch Lose, später von Silo aus.","r":{"t":"Josua 18:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/18/#v6018001-v6018010"}},{"t":"Er starb mit 110 Jahren und wurde in Timnath-Serach begraben.","r":{"t":"Josua 24:29, 30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/24/#v6024029"}}],"lesson":"Josuas unerschütterliche Loyalität wirkte sich auf das ganze Volk aus: Israel diente Jehova alle Tage Josuas.","family":{"father":"Nun","mother":"","spouses":[],"children":[],"siblings":[]},"related":["moses","kaleb"],"events":["goldenes-kalb","zwoelf-kundschafter","tod-moses","jordan-ueberquerung","fall-jerichos","sonne-steht-still","landverteilung","tod-josuas"],"books":["Josua"],"refs":[{"t":"4. Mose 14:6-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/14/#v4014006-v4014009"},{"t":"Josua 1:6-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/1/#v6001006-v6001009"},{"t":"Josua 24:14, 15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/24/#v6024014"}],"sources":[{"title":"Josua – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002523"},{"title":"Josua (Buch) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002524"}]},{"id":"jotham","name":"Jotham","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"777–762 v. u. Z. (16 Jahre)"}],"year":-777,"meaning":"„Jehova ist vollkommen“","summary":"Jotham, der Sohn Usijas, übernahm die Pflichten seines Vaters, als dieser aussätzig wurde, und regierte dann 16 Jahre. Er tat, was recht war in Jehovas Augen, das Volk aber handelte weiterhin verderblich. Micha, Hosea und Jesaja prophezeiten in seiner Zeit.","facts":[{"t":"Er vertrat seinen aussätzigen Vater.","r":{"t":"2. Könige 15:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015005"}},{"t":"Er tat, was recht war, das Volk aber handelte verderblich.","r":{"t":"2. Chronika 27:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/27/#v14027002"}},{"t":"Er baute das obere Tor des Hauses Jehovas.","r":{"t":"2. Chronika 27:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/27/#v14027003"}}],"lesson":"","family":{"father":"usija","mother":"Jeruscha","spouses":[],"children":["ahas"],"siblings":[]},"related":[],"events":[],"books":[],"refs":[{"t":"2. Könige 15:32-38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015032-v12015038"},{"t":"2. Chronika 27:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/27/#v14027001-v14027009"}],"sources":[{"title":"Jotham – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002529"}]},{"id":"juda","name":"Juda","alt":[],"sex":"m","tags":["vorfahr-jesu"],"role":"Sohn Jakobs, Stammvater Judas","eras":["patriarchen"],"dates":[],"year":-1770,"meaning":"„Lobgepriesen“","summary":"Juda war der vierte Sohn Jakobs und Leas. Er riet seinen Brüdern, Joseph nicht zu töten, sondern ihn an Kaufleute zu verkaufen. Später bot er sich als Sklave an, um Benjamin zu retten. Jakob sagte voraus, dass das Zepter nicht von Juda weichen werde – sein Stamm besaß später das Königtum.","facts":[{"t":"Er schlug vor, Joseph an vorüberziehende Kaufleute zu verkaufen.","r":{"t":"1. Mose 37:25-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037025-v1037027"}},{"t":"Von Tamar bekam er die Zwillinge Perez und Serach.","r":{"t":"1. Mose 38:27-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/38/#v1038027-v1038030"}},{"t":"Er bot sich an, an Benjamins Stelle Sklave zu werden.","r":{"t":"1. Mose 44:18-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/44/#v1044018-v1044034"}},{"t":"Jakob sagte: Das Zepter wird nicht von Juda weichen.","r":{"t":"1. Mose 49:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/49/#v1049010"}}],"lesson":"","family":{"father":"jakob","mother":"lea","spouses":[],"children":["Er","Onan","Schela","Perez","Serach"],"siblings":["ruben","simeon","levi","dina","joseph","benjamin"]},"related":["tamar"],"events":["joseph-wird-verkauft","joseph-gibt-sich-zu-erkennen","tod-jakobs"],"books":[],"refs":[{"t":"1. Mose 37:25-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037025-v1037027"},{"t":"1. Mose 44:18-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/44/#v1044018-v1044034"},{"t":"1. Mose 49:8-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/49/#v1049008-v1049010"}],"sources":[{"title":"Juda – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002538"}]},{"id":"judas-halbbruder-jesu","name":"Judas","alt":["Judas, Bruder Jesu","Judas, Halbbruder Jesu"],"sex":"m","tags":["schreiber","juenger"],"role":"Halbbruder Jesu, Schreiber des Judasbriefs","eras":["jesus","versammlung"],"dates":[{"label":"Zeit","value":"Judasbrief um 65 u. Z. geschrieben"}],"year":65,"meaning":"eine Form des Namens Juda","summary":"Judas war ein Halbbruder Jesu und Bruder des Jakobus. Er stellt sich in seinem Brief bescheiden als „Sklave Jesu Christi, aber ein Bruder des Jakobus“ vor. Er war offenbar nicht derselbe wie der Apostel Judas, der Sohn des Jakobus, denn er spricht von den Aposteln in der dritten Person. Um 65 u. Z. schrieb er seinen Brief und ermahnte die Christen, für den Glauben kraftvoll zu kämpfen.","facts":[{"t":"Er wird unter den Brüdern Jesu genannt.","r":{"t":"Matthäus 13:55","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/13/#v40013055"}},{"t":"Er nennt sich „ein Bruder des Jakobus“.","r":{"t":"Judas 1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001001"}},{"t":"Er ermuntert, für den Glauben kraftvoll zu kämpfen.","r":{"t":"Judas 3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001003"}},{"t":"Er erinnert an die Worte der Apostel.","r":{"t":"Judas 17-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001017-v65001018"}}],"lesson":"","family":{"father":"joseph-marias-mann","mother":"maria","spouses":[],"children":[],"siblings":["jesus","jakobus-halbbruder-jesu","Joseph","Simon"]},"related":[],"events":[],"books":["Judas"],"refs":[{"t":"Matthäus 13:55","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/13/#v40013055"},{"t":"Judas 1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001001-v65001004"}],"sources":[{"title":"Judas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002541"}]},{"id":"judas-iskariot","name":"Judas Iskariot","alt":["Judas"],"sex":"m","tags":["apostel"],"role":"Apostel, der Jesus verriet","eras":["jesus"],"dates":[],"year":31,"meaning":"","summary":"Judas Iskariot, der Sohn Simons, war der Apostel, der Jesus verriet. Sein Beiname lässt vermuten, dass er aus der judäischen Stadt Kerijoth-Hezron stammte – dann wäre er der einzige Judäer unter den Aposteln gewesen. Man hatte ihm die Kasse anvertraut, doch er war ein habgieriger Dieb. Für 30 Silberstücke verriet er Jesus an die Oberpriester. Danach erhängte er sich.","facts":[{"t":"Er wurde 31 u. Z. als Apostel ausgewählt.","r":{"t":"Lukas 6:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006016"}},{"t":"Er war ein Dieb und stahl aus der Kasse.","r":{"t":"Johannes 12:4-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/12/#v43012004-v43012006"}},{"t":"Er verriet Jesus für 30 Silberstücke.","r":{"t":"Matthäus 26:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026014-v40026016"}},{"t":"Er erhängte sich.","r":{"t":"Matthäus 27:3-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/27/#v40027003-v40027005"}}],"lesson":"","family":{"father":"Simon Iskariot","mother":"","spouses":[],"children":[],"siblings":[]},"related":["matthias"],"events":["wahl-der-apostel","abendmahl-des-herrn","gethsemane"],"books":[],"refs":[{"t":"Matthäus 26:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026014-v40026016"},{"t":"Matthäus 26:47-50","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026047-v40026050"},{"t":"Johannes 12:4-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/12/#v43012004-v43012006"},{"t":"Apostelgeschichte 1:16-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001016-v44001020"}],"sources":[{"title":"Judas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002541"}]},{"id":"kain","name":"Kain","alt":[],"sex":"m","tags":[],"role":"Erster Sohn Adams und Evas","eras":["anfaenge"],"dates":[],"year":-4020,"meaning":"„Hervorgebrachtes“","summary":"Kain war der Erstgeborene Adams und Evas und das erste Kind, das auf der Erde geboren wurde. Er wurde Ackerbauer. Als Gott sein Opfer nicht wohlwollend ansah, wohl aber das seines Bruders Abel, erschlug Kain seinen Bruder. Zur Strafe wurde er vom Erdboden verbannt.","facts":[{"t":"Eva sagte bei seiner Geburt, sie habe „mit der Hilfe Jehovas“ einen Mann hervorgebracht.","r":{"t":"1. Mose 4:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004001"}},{"t":"Er opferte von seinem Ernteertrag; Gott blickte nicht wohlwollend auf sein Opfer.","r":{"t":"1. Mose 4:3-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004003-v1004005"}},{"t":"Er ermordete seinen Bruder Abel.","r":{"t":"1. Mose 4:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004008"}},{"t":"Er wurde vom Erdboden verbannt; der Boden sollte ihm kaum noch Ertrag bringen.","r":{"t":"1. Mose 4:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004011"}},{"t":"Der Apostel Johannes nennt ihn als warnendes Beispiel.","r":{"t":"1. Johannes 3:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-johannes/3/#v62003012"}}],"lesson":"","family":{"father":"adam","mother":"eva","spouses":[],"children":["Henoch"],"siblings":["abel","seth"]},"related":[],"events":["kain-und-abel"],"books":[],"refs":[{"t":"1. Mose 4:1-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004001-v1004016"},{"t":"1. Johannes 3:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-johannes/3/#v62003011"}],"sources":[{"title":"Kain – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000857"}]},{"id":"kaiphas","name":"Kaiphas","alt":["Joseph Kaiphas"],"sex":"m","tags":["priester"],"role":"Hoher Priester zur Zeit Jesu","eras":["jesus","versammlung"],"dates":[{"label":"Zeit","value":"Hoher Priester um 18 bis um 36 u. Z."}],"year":18,"meaning":"","summary":"Joseph Kaiphas, ein Sadduzäer und Schwiegersohn des Annas, war während des Dienstes Jesu Hoher Priester – länger als jeder seiner unmittelbaren Vorgänger. Er ging im Komplott gegen Jesus führend voran und meinte, es sei vorteilhaft, dass ein Mensch für das Volk sterbe. Er leitete das Verhör vor dem Sanhedrin und verfolgte später auch die Apostel.","facts":[{"t":"Er riet, dass ein Mensch für das Volk sterben solle.","r":{"t":"Johannes 11:49-53","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011049-v43011053"}},{"t":"Jesus wurde vor ihn und den Sanhedrin gebracht.","r":{"t":"Matthäus 26:57-66","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026057-v40026066"}},{"t":"Er ging gegen die Apostel vor.","r":{"t":"Apostelgeschichte 4:5-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/4/#v44004005-v44004007"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["hannas","pilatus"],"events":["gethsemane","tod-jesu","auferweckung-des-lazarus"],"books":[],"refs":[{"t":"Johannes 11:47-53","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011047-v43011053"},{"t":"Matthäus 26:57-68","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026057-v40026068"}],"sources":[{"title":"Kaiphas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000856"}]},{"id":"kaleb","name":"Kaleb","alt":[],"sex":"m","tags":[],"role":"Treuer Kundschafter aus Juda","eras":["aegypten","richter"],"dates":[],"year":-1552,"meaning":"„Hund“","summary":"Kaleb, der Sohn Jephunnes aus dem Stamm Juda, war einer der zwölf Kundschafter. Zusammen mit Josua gab er einen guten Bericht und ermutigte das Volk, das Land in Besitz zu nehmen. Weil er „Jehova, seinem Gott, völlig nachgefolgt war“, durfte er als einer der wenigen seiner Generation 1473 v. u. Z. ins Land der Verheißung ziehen. Mit 85 Jahren erbat er sich das Gebiet um Hebron.","facts":[{"t":"Mit 40 Jahren kundschaftete er das Land 40 Tage lang aus.","r":{"t":"4. Mose 13:6, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/13/#v4013006"}},{"t":"Er sagte: „Lasst uns gleich hinaufziehen.“","r":{"t":"4. Mose 13:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/13/#v4013030"}},{"t":"Er folgte Jehova völlig nach.","r":{"t":"4. Mose 32:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/32/#v4032012"}},{"t":"Mit 85 Jahren erbat er sich das Bergland um Hebron.","r":{"t":"Josua 14:10-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/14/#v6014010-v6014014"}}],"lesson":"","family":{"father":"Jephunne","mother":"","spouses":[],"children":[],"siblings":[]},"related":["josua","othniel"],"events":["zwoelf-kundschafter","landverteilung"],"books":[],"refs":[{"t":"4. Mose 13:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/13/#v4013030"},{"t":"4. Mose 14:6-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/14/#v4014006-v4014009"},{"t":"Josua 14:6-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/14/#v6014006-v6014014"}],"sources":[{"title":"Kaleb – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000863"}]},{"id":"koenigin-von-saba","name":"Königin von Scheba","alt":["Königin von Saba"],"sex":"f","tags":["herrscher"],"role":"Besuchte Salomo","eras":["koenigreich"],"dates":[],"year":-1020,"meaning":"","summary":"Die Bibel nennt den Namen dieser Königin nicht. Sie herrschte über Scheba, ein wohlhabendes Königreich wahrscheinlich im Südwesten Arabiens, das für Gold und Duftstoffe bekannt war. Sie hatte vom Ruf Salomos „in Verbindung mit dem Namen Jehovas“ gehört und kam mit einem großen Tross nach Jerusalem, um ihn mit schwierigen Fragen zu prüfen. Jesus erwähnte sie später als Beispiel.","facts":[{"t":"Sie kam mit Kamelen voll Balsamöl, Gold und Edelsteinen.","r":{"t":"1. Könige 10:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/10/#v11010001"}},{"t":"Sie prüfte Salomo mit schwierigen Fragen.","r":{"t":"1. Könige 10:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/10/#v11010001"}},{"t":"Sie pries Jehova, Salomos Gott.","r":{"t":"1. Könige 10:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/10/#v11010009"}},{"t":"Jesus sagte, sie sei von den Enden der Erde gekommen, um Salomos Weisheit zu hören.","r":{"t":"Matthäus 12:42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/12/#v40012042"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["salomo"],"events":["besuch-der-koenigin-von-saba"],"books":[],"refs":[{"t":"1. Könige 10:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/10/#v11010001-v11010013"},{"t":"Matthäus 12:42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/12/#v40012042"}],"sources":[{"title":"Scheba – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003970"}]},{"id":"korah","name":"Korah","alt":[],"sex":"m","tags":[],"role":"Levit, Anführer eines Aufstands","eras":["aegypten"],"dates":[],"year":-1500,"meaning":"„Kahl“ (vielleicht)","summary":"Korah war ein kehathitischer Levit. Während der Wüstenwanderung verbündete er sich mit den Rubenitern Dathan, Abiram und On sowie mit 250 angesehenen Vorstehern und lehnte sich gegen die Autorität von Moses und Aaron auf. Jehova vollstreckte das Urteil: Die Erde verschlang die Aufrührer, und Feuer verzehrte die 250 Männer.","facts":[{"t":"Er behauptete, die ganze Gemeinde sei heilig – warum sollten sich Moses und Aaron erheben?","r":{"t":"4. Mose 16:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/16/#v4016003"}},{"t":"Mit 250 Männern erschien er mit Feuerbecken vor Jehova.","r":{"t":"4. Mose 16:16-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/16/#v4016016-v4016018"}},{"t":"Die Erde tat ihren Mund auf und verschlang die Aufrührer.","r":{"t":"4. Mose 16:31-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/16/#v4016031-v4016033"}},{"t":"Die Söhne Korahs starben jedoch nicht.","r":{"t":"4. Mose 26:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/26/#v4026011"}}],"lesson":"","family":{"father":"Jizhar","mother":"","spouses":[],"children":[],"siblings":[]},"related":["moses","aaron"],"events":["korahs-aufstand"],"books":[],"refs":[{"t":"4. Mose 16:1-50","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/16/#v4016001-v4016050"},{"t":"Judas 11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001011"}],"sources":[{"title":"Korah – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002648"}]},{"id":"kornelius","name":"Kornelius","alt":[],"sex":"m","tags":["juenger"],"role":"Römischer Offizier, erster unbeschnittener Christ","eras":["versammlung"],"dates":[{"label":"Zeit","value":"getauft im Herbst 36 u. Z."}],"year":36,"meaning":"","summary":"Kornelius war ein Offizier über 100 Soldaten der italischen Abteilung und lebte in Cäsarea. Er war gottergeben, gab viele Gaben der Barmherzigkeit und betete unablässig. Im Herbst 36 u. Z. erschien ihm ein Engel und sagte ihm, er solle Petrus holen lassen. Während Petrus predigte, kam heiliger Geist auf Kornelius und seine Angehörigen und Freunde – sie wurden die ersten unbeschnittenen Nichtjuden in der Christenversammlung.","facts":[{"t":"Er war ein gottergebener Mann, der Gott fürchtete.","r":{"t":"Apostelgeschichte 10:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010001"}},{"t":"Ein Engel sagte: Deine Gebete sind vor Gott emporgestiegen.","r":{"t":"Apostelgeschichte 10:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010003"}},{"t":"Er versammelte Verwandte und Freunde, um Petrus zu hören.","r":{"t":"Apostelgeschichte 10:24, 33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010024"}},{"t":"Sie empfingen heiligen Geist und wurden getauft.","r":{"t":"Apostelgeschichte 10:44-48","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010044-v44010048"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["petrus"],"events":["kornelius-getauft"],"books":[],"refs":[{"t":"Apostelgeschichte 10:1-48","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010001-v44010048"}],"sources":[{"title":"Kornelius – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001041"}]},{"id":"laban","name":"Laban","alt":[],"sex":"m","tags":[],"role":"Bruder Rebekkas, Schwiegervater Jakobs","eras":["patriarchen"],"dates":[],"year":-1880,"meaning":"„Weiß“","summary":"Laban, Sohn Bethuels und Bruder Rebekkas, wohnte in Haran in Paddan-Aram und war der Vater von Lea und Rahel. Als Jakob zu ihm floh, ließ er ihn insgesamt 14 Jahre für seine beiden Töchter arbeiten. In der Hochzeitsnacht betrog er Jakob, indem er ihm Lea statt Rahel gab.","facts":[{"t":"Er wird „der Syrer“ (Aramäer) genannt, weil er in Paddan-Aram wohnte.","r":{"t":"1. Mose 25:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025020"}},{"t":"Er stimmte zu, dass Rebekka Isaak heiratete.","r":{"t":"1. Mose 24:50, 51","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024050"}},{"t":"Er gab Jakob in der Hochzeitsnacht Lea statt Rahel.","r":{"t":"1. Mose 29:21-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029021-v1029026"}},{"t":"Er verfolgte Jakob, als dieser mit seiner Familie wegzog.","r":{"t":"1. Mose 31:22-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/31/#v1031022-v1031024"}}],"lesson":"","family":{"father":"Bethuel","mother":"","spouses":[],"children":["lea","rahel"],"siblings":["rebekka"]},"related":["jakob"],"events":["isaak-heiratet-rebekka","jakob-heiratet"],"books":[],"refs":[{"t":"1. Mose 24:29-51","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024029-v1024051"},{"t":"1. Mose 29:13-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029013-v1029030"},{"t":"1. Mose 31:17-55","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/31/#v1031017-v1031055"}],"sources":[{"title":"Laban – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002655"},{"title":"Rahel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003621"}]},{"id":"lamech","name":"Lamech","alt":[],"sex":"m","tags":["vorfahr-jesu"],"role":"Vater Noahs","eras":["anfaenge"],"dates":[{"label":"Alter","value":"777 Jahre"}],"year":-3152,"meaning":"","summary":"Lamech, ein Nachkomme Seths und Sohn Methusalahs, war der Vater Noahs. Er glaubte an Gott und sagte bei der Geburt seines Sohnes, dieser werde Trost von der mühevollen Arbeit auf dem verfluchten Erdboden bringen. Er lebte 777 Jahre und starb etwa fünf Jahre vor der Sintflut.","facts":[{"t":"Gab seinem Sohn den Namen Noah und sprach von dem Trost, den er bringen werde.","r":{"t":"1. Mose 5:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005029"}},{"t":"Die Worte erfüllten sich, als zu Noahs Lebzeiten der Fluch auf dem Erdboden aufgehoben wurde.","r":{"t":"1. Mose 8:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/8/#v1008021"}},{"t":"Er war noch ein Zeitgenosse Adams."},{"t":"Er steht im Geschlechtsregister Jesu.","r":{"t":"Lukas 3:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003036"}}],"lesson":"","family":{"father":"methusalah","mother":"","spouses":[],"children":["noah"],"siblings":[]},"related":[],"events":[],"books":[],"refs":[{"t":"1. Mose 5:25-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005025-v1005031"},{"t":"Lukas 3:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003036"}],"sources":[{"title":"Lamech – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002673"}]},{"id":"lazarus","name":"Lazarus","alt":["Lazarus von Bethanien"],"sex":"m","tags":["juenger"],"role":"Freund Jesu, von ihm auferweckt","eras":["jesus"],"dates":[{"label":"Zeit","value":"auferweckt 32 u. Z. (nach dem Fest der Einweihung)"}],"year":32,"meaning":"wahrscheinlich gr. Form von Eleasar: „Gott hat geholfen“","summary":"Lazarus lebte mit seinen Schwestern Martha und Maria in Bethanien, etwa drei Kilometer von Jerusalem entfernt. Jesus liebte diese Familie und war dort oft zu Gast. Als Lazarus schwer krank wurde, kam Jesus erst, als er schon vier Tage tot war – und rief ihn aus der Gruft heraus. Wegen dieses Wunders glaubten viele an Jesus. Die Oberpriester wollten daraufhin auch Lazarus töten.","facts":[{"t":"Jesus liebte Martha, Maria und Lazarus.","r":{"t":"Johannes 11:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011005"}},{"t":"Er lag bereits vier Tage in der Gruft.","r":{"t":"Johannes 11:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011017"}},{"t":"Jesus rief: „Lazarus, komm heraus!“","r":{"t":"Johannes 11:43, 44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011043"}},{"t":"Die Oberpriester berieten, auch ihn zu töten.","r":{"t":"Johannes 12:9-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/12/#v43012009-v43012011"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":["martha","maria-bethanien"]},"related":["jesus"],"events":["auferweckung-des-lazarus"],"books":[],"refs":[{"t":"Johannes 11:1-44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011001-v43011044"},{"t":"Johannes 12:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/12/#v43012001-v43012011"}],"sources":[{"title":"Lazarus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002698"}]},{"id":"lea","name":"Lea","alt":[],"sex":"f","tags":["vorfahr-jesu"],"role":"Erste Frau Jakobs","eras":["patriarchen"],"dates":[],"year":-1790,"meaning":"„Kuh“ oder „Wildkuh“ (vielleicht)","summary":"Lea, die ältere Tochter Labans, wurde Jakobs erste Frau, weil ihr Vater Jakob betrog und sie ihm anstelle Rahels gab. Jakob liebte Rahel mehr; Jehova aber begünstigte Lea und schenkte ihr Söhne. Sie wurde die Mutter von Ruben, Simeon, Levi, Juda, Issachar und Sebulon sowie der Tochter Dina.","facts":[{"t":"Ihre Augen werden als glanzlos beschrieben; Rahel war schöner.","r":{"t":"1. Mose 29:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029017"}},{"t":"Laban gab sie Jakob in der Hochzeitsnacht statt Rahel.","r":{"t":"1. Mose 29:23-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029023-v1029025"}},{"t":"Jehova sah, dass sie weniger geliebt wurde, und schenkte ihr Söhne.","r":{"t":"1. Mose 29:31-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029031-v1029035"}}],"lesson":"","family":{"father":"laban","mother":"","spouses":["jakob"],"children":["ruben","simeon","levi","juda","Issachar","Sebulon","dina"],"siblings":["rahel"]},"related":[],"events":["jakob-heiratet"],"books":[],"refs":[{"t":"1. Mose 29:16-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029016-v1029035"},{"t":"1. Mose 30:9-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/30/#v1030009-v1030021"}],"sources":[{"title":"Lea – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002702"}]},{"id":"levi","name":"Levi","alt":[],"sex":"m","tags":[],"role":"Sohn Jakobs, Stammvater der Leviten","eras":["patriarchen"],"dates":[],"year":-1771,"meaning":"„Anhänglichkeit“, „Angeschlossen“","summary":"Levi war der dritte Sohn Jakobs und Leas. Mit Simeon ging er brutal gegen die Männer von Sichem vor, was Jakob scharf verurteilte. Levi wurde der Vater von Gerschon, Kehath und Merari, deren Nachkommen die drei Hauptabteilungen der Leviten bildeten.","facts":[{"t":"Lea hoffte bei seiner Geburt, Jakob werde sich ihr nun anschließen.","r":{"t":"1. Mose 29:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029034"}},{"t":"Er rächte mit Simeon die Schändung Dinas.","r":{"t":"1. Mose 34:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/34/#v1034025"}},{"t":"Jakob sagte voraus, dass seine Nachkommen in Israel zerstreut würden.","r":{"t":"1. Mose 49:5-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/49/#v1049005-v1049007"}},{"t":"Er war der Vater von Gerschon, Kehath und Merari.","r":{"t":"1. Mose 46:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/46/#v1046011"}}],"lesson":"","family":{"father":"jakob","mother":"lea","spouses":[],"children":["Gerschon","Kehath","Merari"],"siblings":["ruben","simeon","juda","dina","joseph","benjamin"]},"related":[],"events":["joseph-wird-verkauft"],"books":[],"refs":[{"t":"1. Mose 29:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029034"},{"t":"1. Mose 34:25-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/34/#v1034025-v1034031"},{"t":"1. Mose 46:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/46/#v1046011"}],"sources":[{"title":"Levi – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002727"}]},{"id":"lois","name":"Lois","alt":[],"sex":"f","tags":["juenger"],"role":"Großmutter des Timotheus","eras":["versammlung"],"dates":[],"year":47,"meaning":"","summary":"Lois war die Großmutter des Timotheus, offenbar die Mutter seiner Mutter Eunike. Die Familie lebte anscheinend in Lystra. Paulus lobte ihren „ungeheuchelten Glauben“. Zusammen mit Eunike unterwies sie Timotheus wohl schon von klein auf in den heiligen Schriften.","facts":[{"t":"Paulus erwähnt ihren ungeheuchelten Glauben.","r":{"t":"2. Timotheus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/1/#v55001005"}},{"t":"Timotheus kannte die Schriften von frühester Kindheit an.","r":{"t":"2. Timotheus 3:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/3/#v55003015"}},{"t":"Die Familie lebte offenbar in Lystra.","r":{"t":"Apostelgeschichte 16:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016001"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":["eunike"],"siblings":[]},"related":["timotheus"],"events":[],"books":[],"refs":[{"t":"2. Timotheus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/1/#v55001005"},{"t":"2. Timotheus 3:14, 15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/3/#v55003014"}],"sources":[{"title":"Lois – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002768"}]},{"id":"lot","name":"Lot","alt":[],"sex":"m","tags":[],"role":"Neffe Abrahams","eras":["patriarchen"],"dates":[],"year":-1990,"meaning":"","summary":"Lot war der Sohn Harans und damit Abrahams Neffe. Er zog mit Abraham nach Kanaan, trennte sich später von ihm und ließ sich in der Nähe von Sodom nieder. Obwohl er unter den Sodomitern wohnte, blieb er ein gerechter Mann; Engel retteten ihn und seine Töchter, bevor Jehova Sodom und Gomorra vernichtete.","facts":[{"t":"Nach dem Tod seines Vaters zog er mit Terach und Abram nach Haran.","r":{"t":"1. Mose 11:27-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011027-v1011031"}},{"t":"Wegen Streit zwischen den Hirten trennte er sich von Abram und wählte die Jordangegend.","r":{"t":"1. Mose 13:5-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/13/#v1013005-v1013012"}},{"t":"Petrus nennt ihn einen gerechten Mann, der unter dem Treiben in Sodom litt.","r":{"t":"2. Petrus 2:7, 8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-petrus/2/#v61002007"}},{"t":"Wurde vor der Vernichtung gerettet und floh nach Zoar.","r":{"t":"1. Mose 19:15-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/19/#v1019015-v1019023"}}],"lesson":"","family":{"father":"Haran","mother":"","spouses":["lots-frau"],"children":[],"siblings":[]},"related":["abraham"],"events":["abrahamischer-bund","melchisedek-segnet-abram","sodom-und-gomorra"],"books":[],"refs":[{"t":"1. Mose 13:5-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/13/#v1013005-v1013012"},{"t":"1. Mose 19:15-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/19/#v1019015-v1019026"},{"t":"2. Petrus 2:6-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-petrus/2/#v61002006-v61002008"}],"sources":[{"title":"Lot – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002776"}]},{"id":"lots-frau","name":"Lots Frau","alt":[],"sex":"f","tags":[],"role":"Wurde zur Salzsäule","eras":["patriarchen"],"dates":[],"year":-1980,"meaning":"","summary":"Ihren Namen nennt die Bibel nicht. Als Engel Lot und seine Familie aus Sodom führten, war sie ungehorsam und schaute sich nach der Stadt um – wahrscheinlich, weil sie an dem hing, was sie zurücklassen musste. Dabei wurde sie zu einer Salzsäule. Jesus erinnerte später an sie als warnendes Beispiel.","facts":[{"t":"Wurde mit Lot und ihren Töchtern aus Sodom hinausgeführt.","r":{"t":"1. Mose 19:15, 16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/19/#v1019015"}},{"t":"Schaute sich entgegen der Anweisung um und wurde zu einer Salzsäule.","r":{"t":"1. Mose 19:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/19/#v1019026"}},{"t":"Jesus sagte: „Denkt an Lots Frau.“","r":{"t":"Lukas 17:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/17/#v42017032"}}],"lesson":"","family":{"father":"","mother":"","spouses":["lot"],"children":[],"siblings":[]},"related":[],"events":["sodom-und-gomorra"],"books":[],"refs":[{"t":"1. Mose 19:15-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/19/#v1019015-v1019026"},{"t":"Lukas 17:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/17/#v42017032"}],"sources":[{"title":"Lot – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002776"}]},{"id":"lukas","name":"Lukas","alt":[],"sex":"m","tags":["schreiber","juenger"],"role":"Arzt und Bibelschreiber","eras":["versammlung"],"dates":[],"year":50,"meaning":"","summary":"Lukas war ein gebildeter Arzt und treuer Begleiter des Paulus. Er war kein Augenzeuge des Lebens Jesu und wurde wahrscheinlich kurz nach Pfingsten 33 u. Z. gläubig. In der Apostelgeschichte verrät das „wir“, wann er dabei war: etwa von Troas nach Philippi und auf der Reise nach Rom. Er schrieb das Lukasevangelium (um 56–58 u. Z.) und die Apostelgeschichte (um 61 u. Z.) und blieb bis zuletzt bei Paulus.","facts":[{"t":"Er recherchierte alles von Anfang an genau.","r":{"t":"Lukas 1:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001001-v42001004"}},{"t":"Paulus nannte ihn „den geliebten Arzt“.","r":{"t":"Kolosser 4:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/kolosser/4/#v51004014"}},{"t":"Er reiste mit Paulus nach Rom.","r":{"t":"Apostelgeschichte 27:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/27/#v44027001"}},{"t":"„Lukas allein ist bei mir.“","r":{"t":"2. Timotheus 4:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/4/#v55004011"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus"],"events":["zweite-missionsreise","schiffbruch","paulus-in-rom","tod-des-paulus"],"books":["Lukas","Apostelgeschichte"],"refs":[{"t":"Lukas 1:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001001-v42001004"},{"t":"Apostelgeschichte 1:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001001"},{"t":"Apostelgeschichte 16:10-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016010-v44016017"}],"sources":[{"title":"Lukas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002790"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"lydia","name":"Lydia","alt":[],"sex":"f","tags":["juenger"],"role":"Purpurhändlerin in Philippi","eras":["versammlung"],"dates":[{"label":"Zeit","value":"getauft um 50 u. Z."}],"year":50,"meaning":"","summary":"Lydia stammte aus Thyatira in Kleinasien und verkaufte in Philippi Purpur. Sie war eine Anbeterin Gottes und stand offenbar ihrem eigenen Haushalt vor. Als Paulus um 50 u. Z. in Philippi predigte, öffnete Jehova ihr Herz: Sie und ihre Hausgenossen gehörten zu den ersten Christen in Europa. Sie bestand darauf, dass Paulus und seine Begleiter bei ihr wohnten.","facts":[{"t":"Jehova öffnete ihr Herz weit.","r":{"t":"Apostelgeschichte 16:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016014"}},{"t":"Sie und ihr Haus ließen sich taufen.","r":{"t":"Apostelgeschichte 16:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016015"}},{"t":"Sie nötigte die Missionare, bei ihr zu bleiben.","r":{"t":"Apostelgeschichte 16:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016015"}},{"t":"Paulus und Silas besuchten die Brüder in ihrem Haus.","r":{"t":"Apostelgeschichte 16:40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016040"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus","silas"],"events":["zweite-missionsreise"],"books":[],"refs":[{"t":"Apostelgeschichte 16:12-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016012-v44016015"},{"t":"Apostelgeschichte 16:40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016040"}],"sources":[{"title":"Lydia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002798"}]},{"id":"maleachi","name":"Maleachi","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet, letzter Schreiber der Hebräischen Schriften","eras":["rueckkehr"],"dates":[{"label":"Zeit","value":"Buch nach 443 v. u. Z."}],"year":-443,"meaning":"","summary":"Maleachi war ein hebräischer Prophet und Bibelschreiber. Über seine Vorfahren und sein Leben berichtet die Bibel nichts; sein Buch zeigt, dass er für den Namen und die Anbetung Jehovas eiferte. Er tadelte Priester und Volk, die Jehova minderwertige Opfer brachten und ihre Frauen treulos behandelten. Sein Buch entstand nach 443 v. u. Z.","facts":[{"t":"Er tadelte die Priester für fehlerhafte Opfer.","r":{"t":"Maleachi 1:6-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/1/#v39001006-v39001008"}},{"t":"Er verurteilte Treulosigkeit gegenüber der Ehefrau.","r":{"t":"Maleachi 2:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/2/#v39002014-v39002016"}},{"t":"„Bringt den ganzen Zehnten in das Vorratshaus.“","r":{"t":"Maleachi 3:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/3/#v39003010"}},{"t":"Er kündigte die Sendung „Elias, des Propheten“, an.","r":{"t":"Maleachi 4:5, 6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/4/#v39004005"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["nehemia"],"events":["abschluss-hebraeische-schriften"],"books":["Maleachi"],"refs":[{"t":"Maleachi 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/1/#v39001001"},{"t":"Maleachi 3:1, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/3/#v39003001"},{"t":"Maleachi 4:5, 6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/4/#v39004005"}],"sources":[{"title":"Maleachi – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002860"},{"title":"Maleachi (Buch) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002861"}]},{"id":"manasse","name":"Manasse","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"716–662 v. u. Z. (55 Jahre)"}],"year":-716,"meaning":"„Vergessen Machender“","summary":"Manasse, der Sohn Hiskias, kam mit 12 Jahren auf den Thron und regierte 55 Jahre – länger als jeder andere König Judas. Er baute die Höhen wieder auf, diente Baal und dem „Heer der Himmel“, trieb Magie und ließ seine Söhne durchs Feuer gehen. Er verführte Juda, Schlimmeres zu tun als die Nationen. Als er nach Babylon gebracht wurde, demütigte er sich jedoch vor Jehova, und Gott ließ ihn zurückkehren.","facts":[{"t":"Er stellte das Bild eines heiligen Pfahls ins Haus Jehovas.","r":{"t":"2. Könige 21:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/21/#v12021007"}},{"t":"Er vergoss sehr viel unschuldiges Blut.","r":{"t":"2. Könige 21:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/21/#v12021016"}},{"t":"In Bedrängnis demütigte er sich vor Jehova.","r":{"t":"2. Chronika 33:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/33/#v14033011-v14033013"}},{"t":"Danach entfernte er die fremden Götter.","r":{"t":"2. Chronika 33:15, 16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/33/#v14033015"}}],"lesson":"","family":{"father":"hiskia","mother":"Hephzibah","spouses":[],"children":["amon"],"siblings":[]},"related":[],"events":[],"books":[],"refs":[{"t":"2. Könige 21:1-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/21/#v12021001-v12021018"},{"t":"2. Chronika 33:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/33/#v14033001-v14033020"}],"sources":[{"title":"Manasse – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002882"}]},{"id":"maria","name":"Maria","alt":["Maria, Mutter Jesu"],"sex":"f","tags":[],"role":"Mutter Jesu","eras":["jesus","versammlung"],"dates":[],"year":-20,"meaning":"von hebr. Mirjam, „Rebellisch“ (vielleicht)","summary":"Maria, die Tochter Helis aus dem Stamm Juda, war eine Nachkommin Davids und lebte in Nazareth. Zu Beginn des Jahres 2 v. u. Z. sandte Gott den Engel Gabriel zu der Jungfrau und ließ ihr ankündigen, dass sie durch heiligen Geist den Sohn Gottes gebären werde. Demütig nahm sie den Auftrag an. Sie heiratete Joseph und bekam später weitere Kinder. Sie stand bei Jesu Tod am Marterpfahl und gehörte zu den Jüngern in Jerusalem.","facts":[{"t":"Gabriel grüßte sie: „Jehova ist mit dir.“","r":{"t":"Lukas 1:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001028"}},{"t":"Sie sagte: „Siehe, Jehovas Sklavin!“","r":{"t":"Lukas 1:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001038"}},{"t":"Sie besuchte ihre Verwandte Elisabeth.","r":{"t":"Lukas 1:39-45","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001039-v42001045"}},{"t":"Sie stand beim Marterpfahl Jesu.","r":{"t":"Johannes 19:25-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019025-v43019027"}},{"t":"Nach Jesu Himmelfahrt war sie mit den Jüngern zusammen.","r":{"t":"Apostelgeschichte 1:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001014"}}],"lesson":"","family":{"father":"Heli","mother":"","spouses":["joseph-marias-mann"],"children":["jesus","jakobus-halbbruder-jesu","judas-halbbruder-jesu"],"siblings":[]},"related":["elisabeth","gabriel"],"events":["ankuendigung-jesu","geburt-jesu","darstellung-im-tempel","astrologen-und-flucht","zwoelfjaehriger-jesus","hochzeit-in-kana","tod-jesu","pfingsten-33"],"books":[],"refs":[{"t":"Lukas 1:26-56","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001026-v42001056"},{"t":"Lukas 2:1-52","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002001-v42002052"},{"t":"Johannes 19:25-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019025-v43019027"}],"sources":[{"title":"Maria – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002918"}]},{"id":"maria-magdalene","name":"Maria Magdalene","alt":[],"sex":"f","tags":["juenger"],"role":"Jüngerin Jesu","eras":["jesus"],"dates":[],"year":30,"meaning":"Magdalene: „Zu Magdala gehörend“","summary":"Maria Magdalene stammte wahrscheinlich aus Magdala am Westufer des Galiläischen Meeres. Jesus hatte sieben Dämonen aus ihr ausgetrieben; daraufhin bekundete sie Glauben an ihn als den Messias und unterstützte ihn mit ihrem Besitz. Sie war bei seinem Tod am Marterpfahl dabei, kam früh am Morgen zu seinem Grab und war eine der Ersten, denen der auferweckte Jesus erschien.","facts":[{"t":"Jesus trieb sieben Dämonen aus ihr aus.","r":{"t":"Lukas 8:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/8/#v42008002"}},{"t":"Sie diente Jesus mit ihren Mitteln.","r":{"t":"Lukas 8:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/8/#v42008003"}},{"t":"Sie stand beim Marterpfahl.","r":{"t":"Johannes 19:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019025"}},{"t":"Der auferweckte Jesus sprach sie mit Namen an.","r":{"t":"Johannes 20:11-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/20/#v43020011-v43020018"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jesus"],"events":["tod-jesu","auferweckung-jesu"],"books":[],"refs":[{"t":"Lukas 8:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/8/#v42008001-v42008003"},{"t":"Johannes 20:1-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/20/#v43020001-v43020018"}],"sources":[{"title":"Maria – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002918"}]},{"id":"maria-bethanien","name":"Maria von Bethanien","alt":["Maria"],"sex":"f","tags":["juenger"],"role":"Schwester von Martha und Lazarus","eras":["jesus"],"dates":[],"year":32,"meaning":"von hebr. Mirjam, „Rebellisch“ (vielleicht)","summary":"Maria war die Schwester von Martha und Lazarus in Bethanien am Osthang des Ölbergs. Während Martha sich um die Bewirtung kümmerte, setzte sich Maria zu Jesu Füßen und hörte ihm zu – Jesus sagte, sie habe „das gute Teil erwählt“. Kurz vor Jesu Tod salbte sie ihn mit kostbarem Öl.","facts":[{"t":"Sie lauschte zu Jesu Füßen seinem Wort.","r":{"t":"Lukas 10:39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/10/#v42010039"}},{"t":"Jesus lobte sie: Sie habe das gute Teil erwählt.","r":{"t":"Lukas 10:42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/10/#v42010042"}},{"t":"Sie fiel Jesus nach Lazarus’ Tod weinend zu Füßen.","r":{"t":"Johannes 11:32, 33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011032"}},{"t":"Sie salbte Jesu Füße mit kostbarem duftendem Öl aus echter Narde.","r":{"t":"Johannes 12:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/12/#v43012003"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":["martha","lazarus"]},"related":["jesus"],"events":["auferweckung-des-lazarus"],"books":[],"refs":[{"t":"Lukas 10:38-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/10/#v42010038-v42010042"},{"t":"Johannes 11:28-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011028-v43011033"},{"t":"Johannes 12:1-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/12/#v43012001-v43012008"}],"sources":[{"title":"Maria – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002918"}]},{"id":"markus","name":"Markus","alt":["Johannes Markus","Johannes"],"sex":"m","tags":["schreiber","juenger"],"role":"Missionar, Schreiber des Markusevangeliums","eras":["versammlung"],"dates":[],"year":44,"meaning":"römischer Beiname; sein hebräischer Name Johannes bedeutet „Jehova hat Gunst erwiesen“","summary":"Johannes Markus war der Sohn Marias aus Jerusalem, in deren Haus sich die ersten Christen versammelten, und ein Cousin des Barnabas. Auf der ersten Missionsreise verließ er Paulus und Barnabas in Pamphylien, worauf Paulus ihn später nicht mitnehmen wollte. Barnabas nahm ihn mit nach Zypern. Später war Markus bei Paulus in Rom und bei Petrus in Babylon, und Paulus nannte ihn „nützlich für den Dienst“. Er schrieb das Markusevangelium (um 60–65 u. Z. in Rom).","facts":[{"t":"Im Haus seiner Mutter beteten viele für Petrus.","r":{"t":"Apostelgeschichte 12:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012012"}},{"t":"In Pamphylien kehrte er nach Jerusalem zurück.","r":{"t":"Apostelgeschichte 13:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/13/#v44013013"}},{"t":"Er war ein Cousin des Barnabas.","r":{"t":"Kolosser 4:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/kolosser/4/#v51004010"}},{"t":"„Er ist mir für den Dienst nützlich.“","r":{"t":"2. Timotheus 4:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/4/#v55004011"}}],"lesson":"","family":{"father":"","mother":"Maria (aus Jerusalem)","spouses":[],"children":[],"siblings":[]},"related":["barnabas","paulus","petrus"],"events":["erste-missionsreise"],"books":["Markus"],"refs":[{"t":"Apostelgeschichte 12:12, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012012"},{"t":"Apostelgeschichte 15:37-39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015037-v44015039"},{"t":"1. Petrus 5:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-petrus/5/#v60005013"}],"sources":[{"title":"Markus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002902"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"martha","name":"Martha","alt":[],"sex":"f","tags":["juenger"],"role":"Schwester von Lazarus und Maria","eras":["jesus"],"dates":[],"year":32,"meaning":"","summary":"Martha aus Bethanien war die Schwester von Lazarus und Maria; Jesus war bei den dreien oft zu Gast. Als Jesus sie besuchte, war Martha sehr um das Essen bemüht. Jesus wies sie freundlich darauf hin, dass geistige Dinge wichtiger sind. Nach dem Tod ihres Bruders bekannte sie mit starkem Glauben, dass Jesus der Christus ist.","facts":[{"t":"Sie nahm Jesus gastfreundlich in ihr Haus auf.","r":{"t":"Lukas 10:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/10/#v42010038"}},{"t":"„Martha, Martha, du bist besorgt und beunruhigt um viele Dinge.“","r":{"t":"Lukas 10:41, 42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/10/#v42010041"}},{"t":"Sie glaubte an die Auferstehung am letzten Tag.","r":{"t":"Johannes 11:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011024"}},{"t":"„Ich habe geglaubt, dass du der Christus, der Sohn Gottes, bist.“","r":{"t":"Johannes 11:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011027"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":["lazarus","maria-bethanien"]},"related":["jesus"],"events":["auferweckung-des-lazarus"],"books":[],"refs":[{"t":"Lukas 10:38-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/10/#v42010038-v42010042"},{"t":"Johannes 11:17-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011017-v43011027"},{"t":"Johannes 12:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/12/#v43012002"}],"sources":[{"title":"Martha – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002917"}]},{"id":"matthaeus","name":"Matthäus","alt":["Levi"],"sex":"m","tags":["apostel","schreiber"],"role":"Apostel und Evangelienschreiber","eras":["jesus","versammlung"],"dates":[],"year":30,"meaning":"„Gabe Jehovas“ (wahrscheinlich)","summary":"Matthäus, auch Levi genannt, ein Sohn des Alphäus, war Steuereinnehmer in oder bei Kapernaum. Zu Beginn des galiläischen Dienstes Jesu (30 oder Anfang 31 u. Z.) rief Jesus ihn vom Steuerbüro weg; Matthäus ließ alles zurück und folgte ihm. Er wurde einer der zwölf Apostel und schrieb das nach ihm benannte Evangelium, wahrscheinlich als erstes der vier (um 41 u. Z.).","facts":[{"t":"Er „ließ alles zurück, stand auf und folgte ihm nach“.","r":{"t":"Lukas 5:27, 28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/5/#v42005027"}},{"t":"Er gab ein großes Festmahl für Jesus.","r":{"t":"Lukas 5:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/5/#v42005029"}},{"t":"Er war Steuereinnehmer.","r":{"t":"Matthäus 10:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/10/#v40010003"}},{"t":"Sein Evangelium entstand um 41 u. Z."}],"lesson":"","family":{"father":"Alphäus","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["wahl-der-apostel"],"books":["Matthäus"],"refs":[{"t":"Matthäus 9:9-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/9/#v40009009-v40009013"},{"t":"Markus 2:13-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/2/#v41002013-v41002017"},{"t":"Lukas 5:27-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/5/#v42005027-v42005032"}],"sources":[{"title":"Matthäus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002938"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"matthias","name":"Matthias","alt":[],"sex":"m","tags":["apostel"],"role":"Nachfolger von Judas Iskariot","eras":["versammlung"],"dates":[{"label":"Zeit","value":"33 u. Z. ausgewählt"}],"year":33,"meaning":"„Gabe Jehovas“ (wahrscheinlich)","summary":"Matthias wurde durch das Los dazu bestimmt, Judas Iskariot als Apostel zu ersetzen. Nach Jesu Himmelfahrt schlug Petrus den etwa 120 versammelten Jüngern vor, das Amt neu zu besetzen, wie David es vorhergesagt hatte. Zur Wahl standen Joseph Barsabbas und Matthias; nach einem Gebet fiel das Los auf Matthias – nur wenige Tage vor Pfingsten.","facts":[{"t":"Petrus verwies auf Psalm 109:8: „Sein Aufsichtsamt übernehme ein anderer.“","r":{"t":"Apostelgeschichte 1:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001020"}},{"t":"Das Los fiel auf Matthias.","r":{"t":"Apostelgeschichte 1:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001026"}},{"t":"Es ist der letzte in der Bibel erwähnte Gebrauch von Losen."}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["petrus","judas-iskariot"],"events":["pfingsten-33"],"books":[],"refs":[{"t":"Apostelgeschichte 1:15-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001015-v44001026"}],"sources":[{"title":"Matthias – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002940"}]},{"id":"melchisedek","name":"Melchisedek","alt":[],"sex":"m","tags":["priester","herrscher"],"role":"König von Salem und Priester Gottes","eras":["patriarchen"],"dates":[{"label":"Zeit","value":"vor 1933 v. u. Z."}],"year":-1934,"meaning":"„König der Gerechtigkeit“","summary":"Melchisedek war König von Salem und „Priester Gottes, des Höchsten“ – der erste Priester, den die Bibel erwähnt. Als Abram von seinem Sieg über Kedorlaomer zurückkam, brachte Melchisedek Brot und Wein und segnete ihn. Weil die Bibel weder seine Abstammung noch weitere Angaben über ihn nennt, war er ein passendes Vorbild für Jesus Christus, der für immer König und Priester ist.","facts":[{"t":"Salem bildete vermutlich den Kern des späteren Jerusalem.","r":{"t":"Psalm 76:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/psalmen/76/#v19076002"}},{"t":"Segnete Abram nach dessen Sieg über Kedorlaomer.","r":{"t":"1. Mose 14:18-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/14/#v1014018-v1014020"}},{"t":"Paulus nennt ihn „König der Gerechtigkeit“ und „König des Friedens“.","r":{"t":"Hebräer 7:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/7/#v58007001"}},{"t":"Ohne bekanntes Geschlechtsregister – ein Vorbild für Christus.","r":{"t":"Hebräer 7:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/7/#v58007003"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["abraham"],"events":["melchisedek-segnet-abram"],"books":[],"refs":[{"t":"1. Mose 14:18-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/14/#v1014018-v1014020"},{"t":"Hebräer 7:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/7/#v58007001-v58007003"}],"sources":[{"title":"Melchisedek – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002970"},{"title":"Sem – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003997"}]},{"id":"menahem","name":"Menahem","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"ab etwa 790 v. u. Z. (10 Jahre)"}],"year":-790,"meaning":"„Einer, der tröstet“","summary":"Menahem, der Sohn Gadis, tötete Schallum in Samaria und regierte zehn Jahre über Israel. Er behandelte die Bewohner der Stadt Tiphsach, die ihm das Tor nicht öffnen wollte, grausam. Er hielt an der Kälberanbetung fest und zahlte dem Assyrerkönig hohen Tribut.","facts":[{"t":"Er tötete Schallum.","r":{"t":"2. Könige 15:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015014"}},{"t":"Er schlug Tiphsach grausam nieder.","r":{"t":"2. Könige 15:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015016"}},{"t":"Er zahlte dem König von Assyrien 1000 Talente Silber.","r":{"t":"2. Könige 15:19, 20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015019"}}],"lesson":"","family":{"father":"Gadi","mother":"","spouses":[],"children":["pekachja"],"siblings":[]},"related":["schallum"],"events":[],"books":[],"refs":[{"t":"2. Könige 15:14-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015014-v12015022"}],"sources":[{"title":"Menahem – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002978"}]},{"id":"mephiboscheth","name":"Mephiboscheth","alt":[],"sex":"m","tags":[],"role":"Sohn Jonathans","eras":["koenigreich"],"dates":[],"year":-1083,"meaning":"","summary":"Mephiboscheth war der Sohn Jonathans und Enkel Sauls. Als die Nachricht vom Tod seines Vaters kam, floh seine Wärterin mit dem Fünfjährigen; dabei fiel er und wurde lahm. Aus Erinnerung an seinen Bund mit Jonathan erwies David ihm liebende Güte: Er gab ihm den Besitz Sauls zurück und ließ ihn ständig an seinem Tisch essen.","facts":[{"t":"Mit fünf Jahren wurde er bei einem Sturz lahm.","r":{"t":"2. Samuel 4:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/4/#v10004004"}},{"t":"Er lebte in Lo-Debar im Haus Machirs.","r":{"t":"2. Samuel 9:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/9/#v10009004"}},{"t":"David erwies ihm um Jonathans willen liebende Güte.","r":{"t":"2. Samuel 9:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/9/#v10009007"}},{"t":"Er aß ständig am Tisch des Königs.","r":{"t":"2. Samuel 9:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/9/#v10009013"}}],"lesson":"","family":{"father":"jonathan","mother":"","spouses":[],"children":["Micha"],"siblings":[]},"related":["david"],"events":[],"books":[],"refs":[{"t":"2. Samuel 4:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/4/#v10004004"},{"t":"2. Samuel 9:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/9/#v10009001-v10009013"},{"t":"2. Samuel 19:24-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/19/#v10019024-v10019030"}],"sources":[{"title":"Mephiboscheth – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002986"}]},{"id":"methusalah","name":"Methusalah","alt":[],"sex":"m","tags":["vorfahr-jesu"],"role":"Großvater Noahs, ältester Mensch der Bibel","eras":["anfaenge"],"dates":[{"label":"Gestorben","value":"2370 v. u. Z."},{"label":"Alter","value":"969 Jahre"}],"year":-3339,"meaning":"„Mann des Wurfgeschosses“ (vielleicht)","summary":"Methusalah war der Sohn des Propheten Henoch, der Vater Lamechs und der Großvater Noahs. Mit 969 Jahren erreichte er das höchste Alter, das die Bibel nennt. Er starb 2370 v. u. Z., im Jahr der Sintflut – die Bibel sagt aber nur, dass er „starb“, nicht dass er in der Flut umkam.","facts":[{"t":"Sohn Henochs, Vater Lamechs, Großvater Noahs.","r":{"t":"1. Mose 5:21-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005021-v1005029"}},{"t":"Gehörte zur achten Generation der Menschheit.","r":{"t":"Lukas 3:37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003037"}},{"t":"Wurde 969 Jahre alt.","r":{"t":"1. Mose 5:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005027"}}],"lesson":"","family":{"father":"henoch","mother":"","spouses":[],"children":["lamech"],"siblings":[]},"related":["noah"],"events":[],"books":[],"refs":[{"t":"1. Mose 5:21-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005021-v1005027"},{"t":"Lukas 3:37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003037"}],"sources":[{"title":"Methusalah – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003022"}]},{"id":"micha","name":"Micha","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet aus Moreschet","eras":["geteilt"],"dates":[{"label":"Wirken","value":"unter Jotham, Ahas und Hiskia (777–717 v. u. Z.)"}],"year":-777,"meaning":"Kurzform von Michael oder Michaja","summary":"Micha aus dem Dorf Morescheth war Prophet Jehovas während der Herrschaft Jothams, Ahas’ und Hiskias von Juda. Er war ein Zeitgenosse Hoseas und Jesajas. Anscheinend hörte er gegen Ende der Herrschaft Hiskias auf zu prophezeien, als er sein Buch vollendet hatte.","facts":[{"t":"Er stammte aus Morescheth.","r":{"t":"Micha 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/micha/1/#v33001001"}},{"t":"Er sagte voraus, dass der Herrscher Israels aus Bethlehem kommen werde.","r":{"t":"Micha 5:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/micha/5/#v33005002"}},{"t":"Er fasste zusammen, was Jehova fordert: Recht, Güte und Bescheidenheit.","r":{"t":"Micha 6:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/micha/6/#v33006008"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jesaja","hiskia"],"events":[],"books":["Micha"],"refs":[{"t":"Micha 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/micha/1/#v33001001"},{"t":"Micha 4:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/micha/4/#v33004001-v33004004"},{"t":"Micha 5:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/micha/5/#v33005002"},{"t":"Micha 6:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/micha/6/#v33006008"}],"sources":[{"title":"Micha – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003032"}]},{"id":"michal","name":"Michal","alt":[],"sex":"f","tags":[],"role":"Tochter Sauls, Frau Davids","eras":["koenigreich"],"dates":[],"year":-1100,"meaning":"„Wer ist wie Gott?“ (wahrscheinlich)","summary":"Michal, die jüngere Tochter König Sauls, war in David verliebt und wurde seine Frau, nachdem David Sauls gefährliche Bedingung erfüllt hatte. Als Saul David töten wollte, half sie ihm zu fliehen. Während Davids Abwesenheit gab Saul sie einem anderen Mann. Später verachtete sie David, als er vor der Bundeslade tanzte.","facts":[{"t":"Saul gab sie David, nachdem er 200 Philister geschlagen hatte.","r":{"t":"1. Samuel 18:20-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/18/#v9018020-v9018027"}},{"t":"Sie half David, durch ein Fenster zu fliehen.","r":{"t":"1. Samuel 19:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/19/#v9019011"}},{"t":"Saul gab sie einem anderen Mann.","r":{"t":"1. Samuel 25:44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/25/#v9025044"}},{"t":"Sie verachtete David, als er vor Jehova tanzte.","r":{"t":"2. Samuel 6:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/6/#v10006016"}}],"lesson":"","family":{"father":"saul","mother":"Ahinoam","spouses":["david"],"children":[],"siblings":["jonathan","Merab"]},"related":[],"events":["david-flieht-vor-saul","bundeslade-nach-jerusalem"],"books":[],"refs":[{"t":"1. Samuel 18:20-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/18/#v9018020-v9018029"},{"t":"1. Samuel 19:11-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/19/#v9019011-v9019017"},{"t":"2. Samuel 6:16-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/6/#v10006016-v10006023"}],"sources":[{"title":"Michal – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003036"}]},{"id":"mirjam","name":"Mirjam","alt":[],"sex":"f","tags":["prophet"],"role":"Prophetin, Schwester von Moses und Aaron","eras":["aegypten"],"dates":[],"year":-1605,"meaning":"„Rebellisch“ (vielleicht)","summary":"Mirjam war die ältere Schwester von Moses und Aaron. Als Mädchen passte sie am Nil auf ihren kleinen Bruder auf und sorgte geschickt dafür, dass seine eigene Mutter ihn stillen durfte. Nach dem Durchzug durch das Rote Meer führte „Mirjam, die Prophetin“, die Frauen beim Lobgesang an. Weil sie gegen Moses murrte, wurde sie vorübergehend mit Aussatz geschlagen.","facts":[{"t":"Sie beobachtete am Nil, was mit dem kleinen Moses geschah.","r":{"t":"2. Mose 2:4-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002004-v2002008"}},{"t":"Sie leitete die Frauen beim Tamburinspiel und Gesang.","r":{"t":"2. Mose 15:20, 21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/15/#v2015020"}},{"t":"Wegen ihres Murrens gegen Moses wurde sie aussätzig.","r":{"t":"4. Mose 12:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/12/#v4012001-v4012015"}},{"t":"Nach sieben Tagen außerhalb des Lagers durfte sie zurückkehren.","r":{"t":"4. Mose 12:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/12/#v4012015"}}],"lesson":"","family":{"father":"Amram","mother":"jochebed","spouses":[],"children":[],"siblings":["moses","aaron"]},"related":[],"events":["geburt-moses","durchzug-rotes-meer"],"books":[],"refs":[{"t":"2. Mose 2:4-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002004-v2002008"},{"t":"2. Mose 15:20, 21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/15/#v2015020"},{"t":"4. Mose 12:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/12/#v4012001-v4012015"}],"sources":[{"title":"Mirjam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003074"}]},{"id":"mischael","name":"Mischael","alt":["Meschach"],"sex":"m","tags":[],"role":"Gefährte Daniels (Meschach)","eras":["exil"],"dates":[{"label":"Zeit","value":"617 v. u. Z. nach Babylon gebracht"}],"year":-619,"meaning":"„Wer ist wie Gott?“ (vielleicht)","summary":"Mischael war einer der drei judäischen Gefährten Daniels; der oberste Hofbeamte Babylons gab ihm den Namen Meschach. Zusammen mit Hananja und Asarja hielt er an der reinen Anbetung fest und überlebte den Feuerofen.","facts":[{"t":"Er erhielt den Namen Meschach.","r":{"t":"Daniel 1:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001006"}},{"t":"Er bat mit Daniel Gott um Offenbarung des Traums.","r":{"t":"Daniel 2:17, 18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002017"}},{"t":"Er wurde mit seinen Gefährten aus dem Feuerofen gerettet.","r":{"t":"Daniel 3:26, 27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003026"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["daniel","hananja","asarja"],"events":["daniel-in-babylon","feuerofen"],"books":[],"refs":[{"t":"Daniel 1:6-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001006-v27001020"},{"t":"Daniel 3:12-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003012-v27003030"}],"sources":[{"title":"Mischael – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003078"},{"title":"Meschach – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003007"}]},{"id":"mordechai","name":"Mordechai","alt":[],"sex":"m","tags":["schreiber"],"role":"Cousin Esthers, später Erster Minister","eras":["rueckkehr"],"dates":[{"label":"Zeit","value":"Anfang des 5. Jahrhunderts v. u. Z."}],"year":-495,"meaning":"","summary":"Mordechai, ein Benjaminiter, war Esthers älterer Cousin und Vormund und diente im Palast von Susa. Er deckte eine Verschwörung gegen den König auf und weigerte sich, sich vor Haman niederzubeugen. Als Haman die Juden ausrotten wollte, bewegte er Esther, beim König einzuschreiten. Danach wurde er Erster Minister. Vieles deutet darauf hin, dass er das Buch Esther schrieb.","facts":[{"t":"Er zog Esther auf.","r":{"t":"Esther 2:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002007"}},{"t":"Er deckte eine Verschwörung gegen den König auf.","r":{"t":"Esther 2:21-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002021-v17002023"}},{"t":"Er beugte sich nicht vor Haman nieder.","r":{"t":"Esther 3:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/3/#v17003002"}},{"t":"„Wer weiß, ob du nicht für eine Zeit wie diese Königin geworden bist?“","r":{"t":"Esther 4:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/4/#v17004014"}}],"lesson":"","family":{"father":"Jair","mother":"","spouses":[],"children":[],"siblings":[]},"related":["esther","haman","ahasverus"],"events":["esther-wird-koenigin","esther-rettet-ihr-volk"],"books":["Esther"],"refs":[{"t":"Esther 2:5-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002005-v17002007"},{"t":"Esther 4:12-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/4/#v17004012-v17004014"},{"t":"Esther 10:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/10/#v17010003"}],"sources":[{"title":"Mordechai – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003111"}]},{"id":"moses","name":"Moses","alt":["Mose"],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet, Führer Israels, Mittler des Gesetzesbundes","eras":["aegypten"],"dates":[{"label":"Lebenszeit","value":"1593–1473 v. u. Z."},{"label":"Alter","value":"120 Jahre"}],"year":-1593,"meaning":"„Herausgezogen“ (d. h. aus dem Wasser errettet)","summary":"Moses, „der Mann des wahren Gottes“, war Führer der Nation Israel, Mittler des Gesetzesbundes, Prophet, Richter und Bibelschreiber. Als Säugling vor Pharaos Mordbefehl gerettet, wuchs er am Hof Pharaos auf, entschied sich aber für Gottes Volk. Nach 40 Jahren in Midian sandte ihn Jehova, Israel aus Ägypten zu führen. Er leitete das Volk 40 Jahre durch die Wildnis und starb mit 120 Jahren auf dem Berg Nebo.","facts":[{"t":"Geboren 1593 v. u. Z.; Pharaos Tochter adoptierte ihn.","r":{"t":"2. Mose 2:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002001-v2002010"}},{"t":"Er wurde in aller Weisheit der Ägypter unterwiesen.","r":{"t":"Apostelgeschichte 7:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/7/#v44007022"}},{"t":"Mit 40 Jahren stellte er sich auf die Seite seines Volkes und musste nach Midian fliehen.","r":{"t":"Hebräer 11:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011024"}},{"t":"Mit 80 Jahren beauftragte ihn Jehova am Horeb aus einem brennenden Dornbusch.","r":{"t":"2. Mose 3:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/3/#v2003001-v2003015"}},{"t":"Er führte Israel 1513 v. u. Z. aus Ägypten und vermittelte den Gesetzesbund.","r":{"t":"2. Mose 24:3-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/24/#v2024003-v2024008"}},{"t":"Er starb mit 120 Jahren, nachdem er das Land vom Nebo aus gesehen hatte.","r":{"t":"5. Mose 34:1-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/5-mose/34/#v5034001-v5034007"}}],"lesson":"","family":{"father":"Amram","mother":"jochebed","spouses":["zippora"],"children":["Gerschom","Elieser"],"siblings":["aaron","mirjam"]},"related":["josua","jethro"],"events":["geburt-moses","moses-flieht-nach-midian","brennender-dornbusch","zehn-plagen","erstes-passah","auszug-aus-aegypten","durchzug-rotes-meer","manna","gesetzesbund","goldenes-kalb","stiftshuette","zwoelf-kundschafter","korahs-aufstand","kupferschlange","tod-moses"],"books":["1. Mose","2. Mose","3. Mose","4. Mose","5. Mose","Hiob"],"refs":[{"t":"2. Mose 3:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/3/#v2003001-v2003015"},{"t":"4. Mose 12:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/12/#v4012003"},{"t":"5. Mose 34:5-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/5-mose/34/#v5034005-v5034012"},{"t":"Hebräer 11:23-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011023-v58011029"}],"sources":[{"title":"Moses – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003118"},{"title":"Exodus (2. Mose) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001459"},{"title":"Hiob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002475"}]},{"id":"naaman","name":"Naaman","alt":[],"sex":"m","tags":["herrscher"],"role":"Syrischer Heerführer","eras":["geteilt"],"dates":[{"label":"Zeit","value":"10. Jahrhundert v. u. Z., zur Zeit Jorams von Israel"}],"year":-910,"meaning":"von einer Wurzel mit der Bedeutung „lieblich sein“","summary":"Naaman war ein angesehener syrischer Heeroberster, durch den Jehova Syrien Rettung verschafft hatte – doch er war aussätzig. Ein verschlepptes israelitisches Mädchen erzählte von dem Propheten in Samaria. Elisa ließ ihm sagen, er solle sich siebenmal im Jordan waschen. Nach anfänglichem Zorn gehorchte Naaman, wurde gesund und erkannte, dass es keinen Gott gibt außer in Israel.","facts":[{"t":"Ein israelitisches Mädchen wies ihn auf Elisa hin.","r":{"t":"2. Könige 5:2, 3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005002"}},{"t":"Er sollte sich siebenmal im Jordan waschen.","r":{"t":"2. Könige 5:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005010"}},{"t":"Seine Haut wurde wie die eines kleinen Jungen.","r":{"t":"2. Könige 5:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005014"}},{"t":"Er wollte nur noch Jehova Opfer darbringen.","r":{"t":"2. Könige 5:15-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005015-v12005017"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["elisa"],"events":["naaman-wird-geheilt"],"books":[],"refs":[{"t":"2. Könige 5:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005001-v12005027"},{"t":"Lukas 4:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/4/#v42004027"}],"sources":[{"title":"Naaman – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003149"}]},{"id":"nadab","name":"Nadab","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 976 v. u. Z. (2 Jahre)"}],"year":-976,"meaning":"„Bereitwillig“, „Edel“","summary":"Nadab, der Sohn Jerobeams, war der zweite König des Zehnstämmereichs und setzte die Kälberanbetung seines Vaters fort. Während er die Stadt Gibbethon belagerte, wurde er von Bascha ermordet, der danach das ganze Haus Jerobeams auslöschte.","facts":[{"t":"Er tat, was böse war in Jehovas Augen.","r":{"t":"1. Könige 15:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015025"}},{"t":"Bascha ermordete ihn bei Gibbethon.","r":{"t":"1. Könige 15:27, 28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015027"}},{"t":"Damit erfüllte sich die Prophezeiung über das Haus Jerobeams.","r":{"t":"1. Könige 15:29, 30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015029"}}],"lesson":"","family":{"father":"jerobeam","mother":"","spouses":[],"children":[],"siblings":[]},"related":["bascha"],"events":[],"books":[],"refs":[{"t":"1. Könige 15:25-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/15/#v11015025-v11015031"}],"sources":[{"title":"Nadab – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003159"}]},{"id":"nahum","name":"Nahum","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet aus Elkosch","eras":["geteilt"],"dates":[{"label":"Zeit","value":"Buch vor 632 v. u. Z."}],"year":-640,"meaning":"„Tröster“","summary":"Nahum, ein Elkoschiter, war ein Prophet im 7. Jahrhundert v. u. Z. und schrieb das gleichnamige Bibelbuch wahrscheinlich in Juda. Er kündigte den Untergang Ninives, der Hauptstadt Assyriens, an – eine Prophezeiung, die sich 632 v. u. Z. erfüllte.","facts":[{"t":"Er stammte aus Elkosch.","r":{"t":"Nahum 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nahum/1/#v34001001"}},{"t":"Er sagte Ninives Fall voraus.","r":{"t":"Nahum 3:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nahum/3/#v34003007"}},{"t":"Er nannte Jehova eine Festung am Tag der Bedrängnis.","r":{"t":"Nahum 1:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nahum/1/#v34001007"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["fall-ninives"],"books":["Nahum"],"refs":[{"t":"Nahum 1:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nahum/1/#v34001001-v34001015"},{"t":"Nahum 3:1-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nahum/3/#v34003001-v34003019"}],"sources":[{"title":"Nahum – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003172"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"nathan","name":"Nathan","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet zur Zeit Davids","eras":["koenigreich"],"dates":[],"year":-1070,"meaning":"„(Gott) hat gegeben“","summary":"Nathan war ein Prophet Jehovas während der Herrschaft Davids. Durch ihn kündigte Jehova den Bund für ein Königreich an, das für immer in Davids Linie bleiben sollte. Nach Davids Sünde mit Bathseba hielt er dem König mutig mit einem Gleichnis seine Schuld vor. Später sorgte er mit Bathseba dafür, dass Salomo König wurde. Mit Gad vollendete er das Buch 2. Samuel.","facts":[{"t":"Er übermittelte Jehovas Bund mit David.","r":{"t":"2. Samuel 7:4-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/7/#v10007004-v10007017"}},{"t":"Mit einem Gleichnis führte er David seine Sünde vor Augen.","r":{"t":"2. Samuel 12:1-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/12/#v10012001-v10012007"}},{"t":"Er setzte sich dafür ein, dass Salomo König wurde.","r":{"t":"1. Könige 1:11-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/1/#v11001011-v11001014"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["david","batseba","salomo"],"events":["bund-mit-david","david-und-batseba","salomo-wird-koenig"],"books":["2. Samuel (mit Gad)"],"refs":[{"t":"2. Samuel 7:1-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/7/#v10007001-v10007017"},{"t":"2. Samuel 12:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/12/#v10012001-v10012015"},{"t":"1. Könige 1:22-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/1/#v11001022-v11001027"}],"sources":[{"title":"Nathan – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003184"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"nebukadnezar","name":"Nebukadnezar","alt":["Nebukadrezar","Nebukadnezar II."],"sex":"m","tags":["herrscher"],"role":"König von Babylon","eras":["exil","geteilt"],"dates":[{"label":"Regierung","value":"624–582 v. u. Z. (43 Jahre)"}],"year":-624,"meaning":"„O Nebo, schütze den Erbsohn!“ (akkadisch)","summary":"Nebukadnezar II., Sohn Nabupolassars, herrschte 43 Jahre über das Neubabylonische Reich. Schon als Kronprinz besiegte er 625 v. u. Z. die Ägypter bei Karkemisch. Jehova gebrauchte ihn, um das Gericht an Juda zu vollstrecken: 607 v. u. Z. zerstörte er Jerusalem und den Tempel. Daniel deutete ihm Träume über künftige Weltreiche, und während seiner Regierung durchlebte er „sieben Zeiten“, in denen er wie ein Tier lebte.","facts":[{"t":"Er siegte 625 v. u. Z. bei Karkemisch über Ägypten.","r":{"t":"Jeremia 46:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/46/#v24046002"}},{"t":"617 v. u. Z. führte er Jojachin und viele Judäer nach Babylon.","r":{"t":"2. Könige 24:10-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024010-v12024016"}},{"t":"607 v. u. Z. zerstörte er Jerusalem.","r":{"t":"2. Könige 25:8-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/25/#v12025008-v12025010"}},{"t":"Er träumte von einem riesigen Standbild.","r":{"t":"Daniel 2:31-45","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002031-v27002045"}},{"t":"Sieben Zeiten lang aß er Pflanzen wie ein Stier.","r":{"t":"Daniel 4:31-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/4/#v27004031-v27004033"}}],"lesson":"","family":{"father":"Nabupolassar","mother":"","spouses":[],"children":["Ewil-Merodach"],"siblings":[]},"related":["daniel","zedekia","jojachin"],"events":["wegfuehrung-jojachins","daniel-in-babylon","zerstoerung-jerusalems-607","traum-vom-standbild","feuerofen","nebukadnezars-wahnsinn"],"books":[],"refs":[{"t":"2. Könige 24:1-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024001-v12024016"},{"t":"Daniel 2:1-49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002001-v27002049"},{"t":"Daniel 4:1-37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/4/#v27004001-v27004037"}],"sources":[{"title":"Nebukadnezar – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003200"}]},{"id":"nehemia","name":"Nehemia","alt":[],"sex":"m","tags":["schreiber"],"role":"Statthalter, Wiedererbauer der Mauer","eras":["rueckkehr"],"dates":[{"label":"Zeit","value":"455 v. u. Z. nach Jerusalem; nach 443 v. u. Z. erneut"}],"year":-455,"meaning":"„Jah tröstet“","summary":"Nehemia, der Sohn Hachaljas, war Mundschenk des Perserkönigs Artaxerxes. Als er hörte, dass die Mauer Jerusalems noch immer niedergerissen war, weinte, fastete und betete er. Im 20. Jahr des Artaxerxes (455 v. u. Z.) erhielt er die Erlaubnis, die Stadt wieder aufzubauen. Trotz Widerstand wurde die Mauer in nur 52 Tagen vollendet. Er diente als Statthalter und schrieb das gleichnamige Bibelbuch.","facts":[{"t":"Er betete, bevor er dem König antwortete.","r":{"t":"Nehemia 2:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/2/#v16002004"}},{"t":"Die Mauer wurde in 52 Tagen fertig.","r":{"t":"Nehemia 6:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/6/#v16006015"}},{"t":"Er verzichtete auf das Brot des Statthalters.","r":{"t":"Nehemia 5:14-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/5/#v16005014-v16005018"}},{"t":"Nach dem 32. Jahr des Artaxerxes kam er zurück und schaffte Missstände ab.","r":{"t":"Nehemia 13:6-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/13/#v16013006-v16013031"}}],"lesson":"","family":{"father":"Hachalja","mother":"","spouses":[],"children":[],"siblings":["Hanani"]},"related":["artaxerxes","esra"],"events":["nehemia-baut-die-mauer","abschluss-hebraeische-schriften"],"books":["Nehemia"],"refs":[{"t":"Nehemia 1:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/1/#v16001001-v16001011"},{"t":"Nehemia 2:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/2/#v16002001-v16002020"},{"t":"Nehemia 6:15, 16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/6/#v16006015"}],"sources":[{"title":"Nehemia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003212"}]},{"id":"nikodemus","name":"Nikodemus","alt":[],"sex":"m","tags":["juenger"],"role":"Pharisäer und Mitglied des Sanhedrins","eras":["jesus"],"dates":[],"year":30,"meaning":"„Sieger des Volkes“","summary":"Nikodemus war ein Pharisäer, Lehrer in Israel und Mitglied des Sanhedrins. Beeindruckt von Jesu Zeichen zur Passahzeit 30 u. Z., suchte er ihn bei Nacht auf. Jesus sprach mit ihm darüber, „wiedergeboren“ zu werden, und über Gottes Liebe. Später verteidigte er Jesus vor den Pharisäern, und nach Jesu Tod half er, den Leib für das Begräbnis vorzubereiten.","facts":[{"t":"Er kam bei Nacht zu Jesus.","r":{"t":"Johannes 3:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/3/#v43003001"}},{"t":"Jesus erklärte ihm, man müsse „wiedergeboren“ werden.","r":{"t":"Johannes 3:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/3/#v43003003"}},{"t":"Er sagte: Unser Gesetz richtet niemand, ohne ihn anzuhören.","r":{"t":"Johannes 7:50, 51","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/7/#v43007050"}},{"t":"Er brachte etwa 33 kg Myrrhe und Aloe für Jesu Begräbnis.","r":{"t":"Johannes 19:39, 40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019039"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jesus","joseph-von-arimathaea"],"events":["erste-tempelreinigung","tod-jesu"],"books":[],"refs":[{"t":"Johannes 3:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/3/#v43003001-v43003021"},{"t":"Johannes 7:45-52","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/7/#v43007045-v43007052"},{"t":"Johannes 19:38-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019038-v43019040"}],"sources":[{"title":"Nikodemus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003249"}]},{"id":"nimrod","name":"Nimrod","alt":[],"sex":"m","tags":["herrscher"],"role":"Gründer des ersten Großreichs","eras":["patriarchen"],"dates":[],"year":-2300,"meaning":"","summary":"Nimrod, ein Sohn Kuschs, gründete nach der Sintflut das erste Großreich und war dessen König. Er war als „gewaltiger Jäger“ bekannt – laut jw.org im Widerstand gegen Jehova. Der Anfang seines Königreichs war Babel im Land Schinar.","facts":[{"t":"Sohn Kuschs und somit ein Enkel Hams.","r":{"t":"1. Mose 10:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/10/#v1010008"}},{"t":"Ein „gewaltiger Jäger“ – im Widerstand gegen Jehova.","r":{"t":"1. Mose 10:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/10/#v1010009"}},{"t":"Der Anfang seines Königreichs war Babel.","r":{"t":"1. Mose 10:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/10/#v1010010"}}],"lesson":"","family":{"father":"Kusch","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":[],"books":[],"refs":[{"t":"1. Mose 10:8-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/10/#v1010008-v1010012"},{"t":"1. Chronika 1:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/1/#v13001010"}],"sources":[{"title":"Nimrod – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003259"}]},{"id":"noah","name":"Noah","alt":[],"sex":"m","tags":["patriarch","prophet","vorfahr-jesu"],"role":"Erbauer der Arche","eras":["anfaenge","patriarchen"],"dates":[{"label":"Geboren","value":"2970 v. u. Z."},{"label":"Alter","value":"950 Jahre"}],"year":-2970,"meaning":"„Ruhe“, „Trost“ (wahrscheinlich)","summary":"Noah war der Zehnte in der Linie von Adam über Seth. In einer völlig verdorbenen Welt war er gerecht und „wandelte mit dem wahren Gott“. Auf Gottes Anweisung baute er mit seiner Familie die Arche und warnte als „Prediger der Gerechtigkeit“ vor der kommenden Vernichtung. In der Sintflut 2370 v. u. Z. überlebten nur er und seine Familie – acht Menschen.","facts":[{"t":"Geboren 2970 v. u. Z., 126 Jahre nach Adams Tod.","r":{"t":"1. Mose 5:28, 29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005028"}},{"t":"Er war gerecht und untadelig unter seinen Zeitgenossen.","r":{"t":"1. Mose 6:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006009"}},{"t":"Er tat genau das, was Gott ihm geboten hatte.","r":{"t":"1. Mose 6:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006022"}},{"t":"Als „Prediger der Gerechtigkeit“ warnte er seine Generation.","r":{"t":"2. Petrus 2:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-petrus/2/#v61002005"}},{"t":"Er starb etwa zwei Jahre vor der Geburt Abrahams.","r":{"t":"1. Mose 9:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009029"}}],"lesson":"","family":{"father":"lamech","mother":"","spouses":[],"children":["sem","ham","japhet"],"siblings":[]},"related":["methusalah"],"events":["bau-der-arche","sintflut","regenbogenbund"],"books":[],"refs":[{"t":"1. Mose 6:9-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006009-v1006022"},{"t":"Hebräer 11:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011007"},{"t":"2. Petrus 2:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-petrus/2/#v61002005"}],"sources":[{"title":"Noah – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003266"}]},{"id":"noomi","name":"Noomi","alt":[],"sex":"f","tags":[],"role":"Schwiegermutter Ruths","eras":["richter"],"dates":[],"year":-1360,"meaning":"„Meine Lieblichkeit“","summary":"Noomi lebte in den Tagen der Richter in Bethlehem in Juda. Wegen einer Hungersnot zog sie mit ihrem Mann Elimelech und ihren Söhnen nach Moab. Dort starben ihr Mann und später beide Söhne. Als sie nach Juda zurückkehrte, blieb ihre Schwiegertochter Ruth bei ihr. Durch Ruths Heirat mit Boas bekam Noomi einen Enkel, Obed, den Großvater Davids.","facts":[{"t":"Sie zog wegen einer Hungersnot mit ihrer Familie nach Moab.","r":{"t":"Ruth 1:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/1/#v8001001"}},{"t":"Ihr Mann und ihre beiden Söhne starben.","r":{"t":"Ruth 1:3-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/1/#v8001003-v8001005"}},{"t":"Sie riet Ruth, Boas um Rückkauf zu bitten.","r":{"t":"Ruth 3:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/3/#v8003001-v8003004"}},{"t":"Ruth war ihr „besser als sieben Söhne“.","r":{"t":"Ruth 4:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/4/#v8004015"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Elimelech"],"children":["Machlon","Kiljon"],"siblings":[]},"related":["ruth","boas"],"events":["ruth-und-noomi"],"books":[],"refs":[{"t":"Ruth 1:1-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/1/#v8001001-v8001022"},{"t":"Ruth 4:13-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/4/#v8004013-v8004017"}],"sources":[{"title":"Noomi – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003178"}]},{"id":"obadja","name":"Obadja","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet, Schreiber des Buches Obadja","eras":["geteilt"],"dates":[{"label":"Zeit","value":"Buch um 607 v. u. Z."}],"year":-607,"meaning":"","summary":"Von Obadja ist nichts weiter bekannt als sein Name. Er schrieb das kürzeste prophetische Buch der Hebräischen Schriften, um 607 v. u. Z. Es enthält Jehovas Urteil über Edom, weil die Edomiter – Nachkommen Esaus – sich über Judas Unglück gefreut und sich an der Plünderung beteiligt hatten. Die Prophezeiung erfüllte sich genau.","facts":[{"t":"Die Edomiter freuten sich über das Unglück Judas.","r":{"t":"Obadja 12-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/obadja/1/#v31001012-v31001014"}},{"t":"Er sagte Edoms Untergang voraus.","r":{"t":"Obadja 17-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/obadja/1/#v31001017-v31001018"}},{"t":"Er kündigte die Wiederherstellung des Hauses Jakob an.","r":{"t":"Obadja 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/obadja/1/#v31001017"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":[],"books":["Obadja"],"refs":[{"t":"Obadja 1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/obadja/1/#v31001001-v31001021"}],"sources":[{"title":"Obadja (Buch) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003288"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"omri","name":"Omri","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel, Gründer Samarias","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 951 v. u. Z. (12 Jahre)"}],"year":-951,"meaning":"","summary":"Omri, ein Heeroberster, wurde vom Heer zum König ausgerufen und setzte sich gegen Simri und den Rivalen Tibni durch. Er gründete die dritte Dynastie Israels und baute auf dem Berg, den er kaufte, die neue Hauptstadt Samaria. Er handelte schlimmer als alle Könige vor ihm. Seine Enkelin war Athalja.","facts":[{"t":"Das Heer machte ihn zum König.","r":{"t":"1. Könige 16:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016016"}},{"t":"Er besiegte Tibnis Anhänger.","r":{"t":"1. Könige 16:21, 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016021"}},{"t":"Er baute Samaria.","r":{"t":"1. Könige 16:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016024"}},{"t":"Er tat Schlimmeres als alle vor ihm.","r":{"t":"1. Könige 16:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016025"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":["ahab"],"siblings":[]},"related":["athalja"],"events":[],"books":[],"refs":[{"t":"1. Könige 16:16-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016016-v11016028"}],"sources":[{"title":"Omri – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003324"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"onesimus","name":"Onesimus","alt":[],"sex":"m","tags":["juenger"],"role":"Sklave Philemons, später Christ","eras":["versammlung"],"dates":[],"year":60,"meaning":"„Nützlich“","summary":"Onesimus war ein Sklave Philemons in Kolossä, der seinem Herrn davonlief und nach Rom kam. Dort lernte er Paulus kennen und wurde Christ. Paulus schätzte ihn als treuen Gefährten, schickte ihn aber – mit Onesimus’ Bereitschaft – zu Philemon zurück. Er reiste mit Tychikus und nahm Briefe nach Kolossä mit. Paulus nannte ihn einen „treuen und geliebten Bruder“.","facts":[{"t":"Paulus wurde in der Haft wie ein Vater für ihn.","r":{"t":"Philemon 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philemon/1/#v57001010"}},{"t":"Einst nutzlos, jetzt nützlich.","r":{"t":"Philemon 11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philemon/1/#v57001011"}},{"t":"Paulus schickte ihn mit Tychikus nach Kolossä.","r":{"t":"Kolosser 4:7-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/kolosser/4/#v51004007-v51004009"}},{"t":"Philemon sollte ihn wie einen Bruder aufnehmen.","r":{"t":"Philemon 15-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philemon/1/#v57001015-v57001017"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["philemon","paulus"],"events":["paulus-in-rom"],"books":[],"refs":[{"t":"Philemon 8-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philemon/1/#v57001008-v57001021"},{"t":"Kolosser 4:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/kolosser/4/#v51004009"}],"sources":[{"title":"Onesimus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003328"}]},{"id":"othniel","name":"Othniel","alt":[],"sex":"m","tags":["richter"],"role":"Erster Richter nach Josua","eras":["richter"],"dates":[],"year":-1440,"meaning":"","summary":"Othniel aus dem Stamm Juda ist der erste Richter, den die Bibel nach Josua erwähnt; er war ein Neffe Kalebs. Er eroberte die kanaanitische Stadt Debir und erhielt dafür Kalebs Tochter Achsa zur Frau. Als Israel von einem mesopotamischen König bedrückt wurde, erweckte Jehova ihn als Retter.","facts":[{"t":"Er war der Sohn von Kalebs Bruder Kenas.","r":{"t":"Richter 1:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/1/#v7001013"}},{"t":"Er eroberte Debir und heiratete Achsa.","r":{"t":"Josua 15:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/15/#v6015016"}},{"t":"Jehova erweckte ihn als Retter Israels.","r":{"t":"Richter 3:9-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/3/#v7003009-v7003011"}}],"lesson":"","family":{"father":"Kenas","mother":"","spouses":["Achsa"],"children":[],"siblings":[]},"related":["kaleb"],"events":["zeit-der-richter"],"books":[],"refs":[{"t":"Josua 15:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/15/#v6015016"},{"t":"Richter 3:7-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/3/#v7003007-v7003011"}],"sources":[{"title":"Othniel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003349"}]},{"id":"paulus","name":"Paulus","alt":["Saulus","Saulus von Tarsus","Saul"],"sex":"m","tags":["apostel","schreiber"],"role":"Apostel für die Nationen","eras":["versammlung"],"dates":[{"label":"Wirken","value":"ab seiner Bekehrung um 34 u. Z."},{"label":"Gestorben","value":"wahrscheinlich um 65 u. Z. in Rom"}],"year":34,"meaning":"„Gering“, „Klein“ (aus dem Lateinischen)","summary":"Paulus, auch Saulus genannt, stammte aus Tarsus in Zilizien, war Benjaminit, Pharisäer und von Geburt römischer Bürger; Gamaliel hatte ihn unterrichtet. Zuerst verfolgte er die Christen heftig, doch um 34 u. Z. offenbarte sich ihm Jesus auf dem Weg nach Damaskus. Als „Apostel für die Nationen“ unternahm er drei Missionsreisen, gründete viele Versammlungen und schrieb 14 Briefe der Christlichen Griechischen Schriften. Er starb wahrscheinlich um 65 u. Z. unter Nero als Märtyrer.","facts":[{"t":"Er war bei der Steinigung des Stephanus einverstanden.","r":{"t":"Apostelgeschichte 8:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008001"}},{"t":"Jesus erschien ihm auf dem Weg nach Damaskus.","r":{"t":"Apostelgeschichte 9:3-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009003-v44009006"}},{"t":"Er lernte das Handwerk des Zeltmachers.","r":{"t":"Apostelgeschichte 18:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018003"}},{"t":"Er nannte sich „Apostel für die Nationen“.","r":{"t":"Römer 11:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/11/#v45011013"}},{"t":"„Ich habe den vortrefflichen Kampf gekämpft.“","r":{"t":"2. Timotheus 4:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/4/#v55004007"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["barnabas","silas","timotheus","lukas","gamaliel","stephanus"],"events":["stephanus-gesteinigt","bekehrung-des-saulus","erste-missionsreise","beschneidungsfrage","zweite-missionsreise","paulus-in-athen","dritte-missionsreise","paulus-verhaftet","schiffbruch","paulus-in-rom","tod-des-paulus"],"books":["Römer","1. Korinther","2. Korinther","Galater","Epheser","Philipper","Kolosser","1. Thessalonicher","2. Thessalonicher","1. Timotheus","2. Timotheus","Titus","Philemon","Hebräer"],"refs":[{"t":"Apostelgeschichte 9:1-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009001-v44009022"},{"t":"Apostelgeschichte 22:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/22/#v44022003"},{"t":"Philipper 3:4-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philipper/3/#v50003004-v50003008"},{"t":"2. Korinther 11:23-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-korinther/11/#v47011023-v47011028"}],"sources":[{"title":"Paulus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003406"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"pekach","name":"Pekach","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 778 v. u. Z. (20 Jahre)"}],"year":-778,"meaning":"von einer Wurzel mit der Bedeutung „öffnen“","summary":"Pekach, der Sohn Remaljas, ermordete als Adjutant König Pekachja und regierte etwa 20 Jahre. Er war ein Zeitgenosse der judäischen Könige Usija, Jotham und Ahas und verbündete sich mit Syrien gegen Juda. Schließlich wurde er von Hoschea ermordet.","facts":[{"t":"Er ermordete Pekachja mit Hilfe von 50 Gileaditern.","r":{"t":"2. Könige 15:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015025"}},{"t":"Mit Syrien zog er gegen Jerusalem.","r":{"t":"Jesaja 7:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/7/#v23007001"}},{"t":"Hoschea brachte ihn um.","r":{"t":"2. Könige 15:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015030"}}],"lesson":"","family":{"father":"Remalja","mother":"","spouses":[],"children":[],"siblings":[]},"related":["ahas","hosea-koenig"],"events":[],"books":[],"refs":[{"t":"2. Könige 15:25-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015025-v12015031"},{"t":"Jesaja 7:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/7/#v23007001-v23007009"}],"sources":[{"title":"Pekach – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003415"}]},{"id":"pekachja","name":"Pekachja","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel","eras":["geteilt"],"dates":[{"label":"Regierung","value":"ca. 780–779 v. u. Z. (2 Jahre)"}],"year":-780,"meaning":"„Jah hat geöffnet“","summary":"Pekachja, der Sohn und Nachfolger Menahems, regierte zwei Jahre in Samaria und hielt an der Kälberanbetung fest. Sein Adjutant Pekach verschwor sich gegen ihn, tötete ihn und regierte an seiner Stelle.","facts":[{"t":"Er regierte zwei Jahre.","r":{"t":"2. Könige 15:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015023"}},{"t":"Er hielt an den Sünden Jerobeams fest.","r":{"t":"2. Könige 15:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015024"}},{"t":"Pekach ermordete ihn.","r":{"t":"2. Könige 15:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015025"}}],"lesson":"","family":{"father":"menahem","mother":"","spouses":[],"children":[],"siblings":[]},"related":["pekach"],"events":[],"books":[],"refs":[{"t":"2. Könige 15:22-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015022-v12015026"}],"sources":[{"title":"Pekachja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003416"}]},{"id":"petrus","name":"Petrus","alt":["Simon Petrus","Simon","Simeon","Kephas"],"sex":"m","tags":["apostel","schreiber"],"role":"Apostel Jesu","eras":["jesus","versammlung"],"dates":[],"year":29,"meaning":"„Felsstück“","summary":"Petrus, Sohn des Johannes (Jonas), stammte aus Bethsaida, wohnte später in Kapernaum und war an einem ansehnlichen Fischereiunternehmen beteiligt. Andreas brachte ihn zu Jesus, der ihm den Namen Kephas (Petrus) gab. Er bekannte Jesus als den Christus, verleugnete ihn aber in der Nacht seiner Festnahme dreimal. Zu Pfingsten 33 u. Z. war er der Sprecher der Apostel, und 36 u. Z. predigte er Kornelius – so öffnete er Juden, Samaritern und Nichtjuden den Weg ins Königreich. Er schrieb zwei Briefe.","facts":[{"t":"Er war verheiratet; seine Schwiegermutter lebte in seinem Haus.","r":{"t":"Markus 1:29-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/1/#v41001029-v41001031"}},{"t":"Er bekannte: „Du bist der Christus, der Sohn des lebendigen Gottes.“","r":{"t":"Matthäus 16:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/16/#v40016016"}},{"t":"Er verleugnete Jesus dreimal und weinte bitterlich.","r":{"t":"Matthäus 26:69-75","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026069-v40026075"}},{"t":"Zu Pfingsten war er der Sprecher der Apostel.","r":{"t":"Apostelgeschichte 2:14-41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/2/#v44002014-v44002041"}},{"t":"Er predigte Kornelius, dem ersten unbeschnittenen Gläubigen.","r":{"t":"Apostelgeschichte 10:34-48","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010034-v44010048"}}],"lesson":"","family":{"father":"Johannes (Jonas)","mother":"","spouses":[],"children":[],"siblings":["andreas"]},"related":["johannes-apostel","jakobus-zebedaeus","kornelius"],"events":["erste-juenger","wahl-der-apostel","jesus-geht-auf-dem-wasser","umgestaltung","gethsemane","pfingsten-33","abendmahl-des-herrn","auferweckung-jesu","philippus-und-der-aethiopier","kornelius-getauft","petrus-befreit","beschneidungsfrage"],"books":["1. Petrus","2. Petrus"],"refs":[{"t":"Johannes 1:40-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001040-v43001042"},{"t":"Matthäus 16:13-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/16/#v40016013-v40016019"},{"t":"Lukas 22:31, 32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/22/#v42022031"},{"t":"Apostelgeschichte 2:14-41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/2/#v44002014-v44002041"}],"sources":[{"title":"Petrus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003451"}]},{"id":"philemon","name":"Philemon","alt":[],"sex":"m","tags":["juenger"],"role":"Christ in Kolossä","eras":["versammlung"],"dates":[],"year":60,"meaning":"„Liebevoll“","summary":"Philemon war ein christlicher Sklavenhalter in Kolossä; in seinem Haus versammelte sich die dortige Versammlung. Er ermunterte seine Glaubensbrüder und war ein Vorbild in Glauben und Liebe. Paulus nannte ihn einen geliebten Mitarbeiter. Um 60/61 u. Z. schrieb Paulus ihm aus Rom einen Brief und bat ihn, seinen entlaufenen Sklaven Onesimus, der Christ geworden war, freundlich wieder aufzunehmen.","facts":[{"t":"In seinem Haus versammelte sich eine Versammlung.","r":{"t":"Philemon 1-2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philemon/1/#v57001001-v57001002"}},{"t":"Er erquickte die Herzen der Heiligen.","r":{"t":"Philemon 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philemon/1/#v57001007"}},{"t":"Paulus bat für Onesimus.","r":{"t":"Philemon 10-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philemon/1/#v57001010-v57001012"}},{"t":"Paulus hoffte, bei ihm Gast zu sein.","r":{"t":"Philemon 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philemon/1/#v57001022"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["onesimus","paulus"],"events":[],"books":[],"refs":[{"t":"Philemon 1-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philemon/1/#v57001001-v57001025"}],"sources":[{"title":"Philemon – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003463"}]},{"id":"philippus-apostel","name":"Philippus","alt":["Philippus, der Apostel"],"sex":"m","tags":["apostel"],"role":"Apostel aus Bethsaida","eras":["jesus"],"dates":[],"year":29,"meaning":"„Pferdefreund“","summary":"Philippus stammte wie Petrus und Andreas aus Bethsaida und war einer der ersten Jünger. Als Jesus ihn aufforderte: „Folge mir nach“, tat er es und brachte gleich darauf Nathanael zu Jesus. Ausführlichere Angaben über ihn finden sich nur im Bericht des Johannes.","facts":[{"t":"Jesus sagte zu ihm: „Folge mir nach.“","r":{"t":"Johannes 1:43","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001043"}},{"t":"Er sagte zu Nathanael: „Wir haben den gefunden, von dem Moses schrieb.“","r":{"t":"Johannes 1:45","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001045"}},{"t":"Jesus prüfte ihn vor der Speisung der 5000.","r":{"t":"Johannes 6:5-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/6/#v43006005-v43006007"}},{"t":"Er bat Jesus: „Zeig uns den Vater.“","r":{"t":"Johannes 14:8, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/14/#v43014008"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["bartholomaeus"],"events":["erste-juenger","wahl-der-apostel","speisung-der-5000"],"books":[],"refs":[{"t":"Johannes 1:43-46","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001043-v43001046"},{"t":"Johannes 6:5-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/6/#v43006005-v43006007"},{"t":"Johannes 14:8-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/14/#v43014008-v43014011"}],"sources":[{"title":"Philippus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003466"}]},{"id":"philippus-evangelist","name":"Philippus","alt":["Philippus, der Evangeliumsverkündiger"],"sex":"m","tags":["juenger"],"role":"Evangeliumsverkündiger und Missionar","eras":["versammlung"],"dates":[],"year":33,"meaning":"„Pferdefreund“","summary":"Philippus gehörte wie Stephanus zu den sieben Männern, die in Jerusalem die Verteilung von Nahrung an die Witwen beaufsichtigten. Als die Jünger durch Verfolgung zerstreut wurden, predigte er in Samaria, wo viele getauft wurden. Danach erklärte er einem äthiopischen Eunuchen die Schriften und taufte ihn. Rund 20 Jahre später lebte er als Evangeliumsverkündiger in Cäsarea; er hatte vier Töchter, die prophezeiten.","facts":[{"t":"Er war einer der sieben Männer.","r":{"t":"Apostelgeschichte 6:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/6/#v44006005"}},{"t":"Er verkündigte in Samaria den Christus.","r":{"t":"Apostelgeschichte 8:5-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008005-v44008008"}},{"t":"Er taufte den äthiopischen Eunuchen.","r":{"t":"Apostelgeschichte 8:35-38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008035-v44008038"}},{"t":"Paulus und Lukas wohnten um 56 u. Z. in seinem Haus.","r":{"t":"Apostelgeschichte 21:8, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/21/#v44021008"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":["Vier Töchter"],"siblings":[]},"related":["stephanus","paulus"],"events":["philippus-und-der-aethiopier"],"books":[],"refs":[{"t":"Apostelgeschichte 6:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/6/#v44006001-v44006006"},{"t":"Apostelgeschichte 8:4-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008004-v44008040"},{"t":"Apostelgeschichte 21:8-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/21/#v44021008-v44021010"}],"sources":[{"title":"Philippus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003466"}]},{"id":"phoebe","name":"Phöbe","alt":[],"sex":"f","tags":["juenger"],"role":"Dienerin der Versammlung in Kenchreä","eras":["versammlung"],"dates":[],"year":56,"meaning":"„Rein“, „Leuchtend“, „Strahlend“","summary":"Phöbe war eine Christin des 1. Jahrhunderts und gehörte zur Versammlung in Kenchreä. Paulus nannte sie „eine Dienerin der Versammlung“ und empfahl sie den Christen in Rom: Sie sollten ihr helfen, denn sie hatte vielen beigestanden, auch ihm selbst. Möglicherweise brachte sie den Römerbrief nach Rom oder begleitete den Überbringer.","facts":[{"t":"Paulus empfahl sie der Versammlung in Rom.","r":{"t":"Römer 16:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/16/#v45016001"}},{"t":"Sie hatte sich als Verteidigerin vieler erwiesen.","r":{"t":"Römer 16:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/16/#v45016002"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus"],"events":[],"books":[],"refs":[{"t":"Römer 16:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/16/#v45016001"}],"sources":[{"title":"Phöbe – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003474"}]},{"id":"pinehas","name":"Pinehas","alt":[],"sex":"m","tags":["priester"],"role":"Enkel Aarons, später Hoher Priester","eras":["aegypten","richter"],"dates":[],"year":-1475,"meaning":"","summary":"Pinehas war der Sohn Eleasars und ein Enkel Aarons. Als Israel in den Ebenen Moabs dem Baal von Peor diente und eine Plage 24 000 Menschen das Leben kostete, griff er entschlossen ein. Weil er keine Rivalität gegenüber Jehova duldete, sicherte Gott ihm in einem Bund zu, dass das Priestertum dauerhaft in seiner Linie bleiben werde.","facts":[{"t":"Sein Eingreifen beendete die Plage nach dem Götzendienst bei Peor.","r":{"t":"4. Mose 25:6-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/25/#v4025006-v4025009"}},{"t":"Sein Eifer wurde ihm als Gerechtigkeit angerechnet.","r":{"t":"Psalm 106:30, 31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/psalmen/106/#v19106030"}},{"t":"Gott schloss mit ihm einen Bund für ein dauerhaftes Priestertum.","r":{"t":"4. Mose 25:10-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/25/#v4025010-v4025013"}}],"lesson":"","family":{"father":"Eleasar","mother":"","spouses":[],"children":["Abischua"],"siblings":[]},"related":["aaron"],"events":["bileam-und-balak"],"books":[],"refs":[{"t":"4. Mose 25:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/25/#v4025001-v4025015"},{"t":"Psalm 106:30, 31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/psalmen/106/#v19106030"}],"sources":[{"title":"Pinehas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003472"}]},{"id":"pilatus","name":"Pontius Pilatus","alt":["Pilatus"],"sex":"m","tags":["herrscher"],"role":"Römischer Statthalter von Judäa","eras":["jesus"],"dates":[{"label":"Zeit","value":"Statthalter ab 26 u. Z. (10 Jahre)"}],"year":26,"meaning":"","summary":"Pontius Pilatus wurde 26 u. Z. von Kaiser Tiberius als Statthalter von Judäa eingesetzt und regierte zehn Jahre. Eine 1961 in Cäsarea gefundene Inschrift trägt seinen Namen. Beim Prozess Jesu fand er keine Schuld an ihm und wollte ihn freilassen, gab aber dem Druck der Menge nach und verurteilte ihn zum Tod am Marterpfahl.","facts":[{"t":"Er fragte Jesus: „Was ist Wahrheit?“","r":{"t":"Johannes 18:37, 38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/18/#v43018037"}},{"t":"Er fand keine Schuld an Jesus.","r":{"t":"Lukas 23:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/23/#v42023004"}},{"t":"Er gab Barabbas frei und übergab Jesus zur Hinrichtung.","r":{"t":"Markus 15:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/15/#v41015015"}},{"t":"Er ließ eine Inschrift über Jesus anbringen.","r":{"t":"Johannes 19:19-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019019-v43019022"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jesus","herodes-antipas","kaiphas"],"events":["tod-jesu"],"books":[],"refs":[{"t":"Johannes 18:28–19:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/18/#v43018028-v43019022"},{"t":"Lukas 23:1-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/23/#v42023001-v42023025"}],"sources":[{"title":"Pilatus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003485"}]},{"id":"potiphar","name":"Potiphar","alt":[],"sex":"m","tags":["herrscher"],"role":"Oberster der Leibwache Pharaos","eras":["patriarchen"],"dates":[],"year":-1750,"meaning":"Kurzform von Potiphera (ägyptisch)","summary":"Potiphar war ein wohlhabender ägyptischer Hofbeamter und Oberster der Leibwache Pharaos. Er kaufte Joseph von reisenden Kaufleuten und setzte ihn über sein ganzes Haus, das Jehova um Josephs willen segnete. Als seine Frau Joseph fälschlich beschuldigte, ließ Potiphar ihn ins Gefängnis werfen.","facts":[{"t":"Er kaufte Joseph von midianitischen Kaufleuten.","r":{"t":"1. Mose 37:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037036"}},{"t":"Jehova segnete sein Haus um Josephs willen.","r":{"t":"1. Mose 39:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/39/#v1039005"}},{"t":"Er glaubte den falschen Anschuldigungen seiner Frau.","r":{"t":"1. Mose 39:19, 20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/39/#v1039019"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["joseph"],"events":["joseph-wird-verkauft"],"books":[],"refs":[{"t":"1. Mose 37:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037036"},{"t":"1. Mose 39:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/39/#v1039001-v1039020"}],"sources":[{"title":"Potiphar – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003534"}]},{"id":"priszilla","name":"Priscilla","alt":["Priska"],"sex":"f","tags":["juenger"],"role":"Frau des Aquila","eras":["versammlung"],"dates":[],"year":50,"meaning":"Priska: „Alte (Frau)“; Priscilla: „Kleine alte (Frau)“","summary":"Priscilla – Paulus nennt sie Priska – war die Frau Aquilas und wird immer mit ihm zusammen erwähnt. Wegen des Dekrets von Claudius verließen beide Rom und gingen um 50 u. Z. nach Korinth, wo Paulus mit ihnen als Zeltmacher arbeitete. Sie waren sehr gastfreundlich, unterstützten Einzelne wie Apollos und stellten ihr Haus in Ephesus und in Rom für Zusammenkünfte der Versammlung zur Verfügung.","facts":[{"t":"Sie kam mit Aquila aus Italien nach Korinth.","r":{"t":"Apostelgeschichte 18:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018002"}},{"t":"Sie half Apollos, Gottes Weg genauer zu verstehen.","r":{"t":"Apostelgeschichte 18:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018026"}},{"t":"Paulus nannte sie und Aquila seine Mitarbeiter.","r":{"t":"Römer 16:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/16/#v45016003"}},{"t":"In ihrem Haus traf sich eine Versammlung.","r":{"t":"Römer 16:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/16/#v45016005"}}],"lesson":"","family":{"father":"","mother":"","spouses":["aquila"],"children":[],"siblings":[]},"related":["paulus","apollos"],"events":["zweite-missionsreise","dritte-missionsreise"],"books":[],"refs":[{"t":"Apostelgeschichte 18:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018001-v44018003"},{"t":"Apostelgeschichte 18:18-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018018-v44018026"},{"t":"Römer 16:3-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/16/#v45016003-v45016005"},{"t":"2. Timotheus 4:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/4/#v55004019"}],"sources":[{"title":"Priska – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003556"}]},{"id":"rahab","name":"Rahab","alt":[],"sex":"f","tags":["vorfahr-jesu"],"role":"Frau aus Jericho, Anbeterin Jehovas","eras":["richter"],"dates":[{"label":"Zeit","value":"1473 v. u. Z."}],"year":-1473,"meaning":"„Weit“, „Geräumig“ (vielleicht)","summary":"Rahab war eine Prostituierte in Jericho, die eine Anbeterin Jehovas wurde. Im Frühjahr 1473 v. u. Z. nahm sie zwei israelitische Kundschafter auf und versteckte sie, weil sie glaubte, dass Jehova Israel das Land geben würde. Als Jericho fiel, wurden sie und ihre Familie verschont. Später heiratete sie Salmon und wurde die Mutter von Boas – eine Vorfahrin Jesu.","facts":[{"t":"Sie gewährte zwei Kundschaftern Unterkunft und versteckte sie.","r":{"t":"Josua 2:1-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/2/#v6002001-v6002007"}},{"t":"Sie sagte, Jehova sei Gott oben im Himmel und unten auf der Erde.","r":{"t":"Josua 2:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/2/#v6002011"}},{"t":"Eine karmesinrote Schnur am Fenster kennzeichnete ihr Haus.","r":{"t":"Josua 2:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/2/#v6002018"}},{"t":"Beim Fall Jerichos wurde ihre Familie gerettet.","r":{"t":"Josua 6:22-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/6/#v6006022-v6006025"}},{"t":"Die Bibel nennt sie ein Beispiel für Glauben, der sich durch Werke zeigt.","r":{"t":"Jakobus 2:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jakobus/2/#v59002025"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Salmon"],"children":["boas"],"siblings":[]},"related":["josua"],"events":["jordan-ueberquerung","fall-jerichos"],"books":[],"refs":[{"t":"Josua 2:1-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/2/#v6002001-v6002024"},{"t":"Josua 6:22-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/6/#v6006022-v6006025"},{"t":"Hebräer 11:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011031"},{"t":"Matthäus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001005"}],"sources":[{"title":"Rahab – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003623"},{"title":"Boas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000779"}]},{"id":"rahel","name":"Rahel","alt":[],"sex":"f","tags":[],"role":"Lieblingsfrau Jakobs","eras":["patriarchen"],"dates":[],"year":-1785,"meaning":"„Mutterschaf“","summary":"Rahel, die jüngere Tochter Labans, war Jakobs Cousine und seine Lieblingsfrau; er diente für sie insgesamt 14 Jahre. Lange blieb sie unfruchtbar, bis sie Joseph gebar. Auf dem Weg von Bethel nach Ephrath (Bethlehem) starb sie bei der Geburt ihres zweiten Sohnes Benjamin.","facts":[{"t":"Sie begegnete Jakob 1781 v. u. Z. an einem Brunnen bei Haran.","r":{"t":"1. Mose 29:9-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029009-v1029012"}},{"t":"Jakobs sieben Dienstjahre für sie kamen ihm wie wenige Tage vor.","r":{"t":"1. Mose 29:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029020"}},{"t":"Lange unfruchtbar, gab sie Jakob ihre Magd Bilha.","r":{"t":"1. Mose 30:1-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/30/#v1030001-v1030008"}},{"t":"Sie gebar schließlich Joseph.","r":{"t":"1. Mose 30:22-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/30/#v1030022-v1030024"}},{"t":"Sie starb bei der Geburt Benjamins.","r":{"t":"1. Mose 35:16-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/35/#v1035016-v1035019"}}],"lesson":"","family":{"father":"laban","mother":"","spouses":["jakob"],"children":["joseph","benjamin"],"siblings":["lea"]},"related":[],"events":["jakob-heiratet"],"books":[],"refs":[{"t":"1. Mose 29:9-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029009-v1029030"},{"t":"1. Mose 30:22-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/30/#v1030022-v1030024"},{"t":"1. Mose 35:16-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/35/#v1035016-v1035020"}],"sources":[{"title":"Rahel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003621"}]},{"id":"rebekka","name":"Rebekka","alt":[],"sex":"f","tags":["vorfahr-jesu"],"role":"Frau Isaaks, Mutter von Esau und Jakob","eras":["patriarchen"],"dates":[],"year":-1900,"meaning":"„Kuh“ (vielleicht)","summary":"Rebekka war die Tochter Bethuels, eine Großnichte Abrahams; ihr Bruder war Laban. Als Abrahams Diener 1878 v. u. Z. eine Frau für Isaak suchte, erwies sie sich am Brunnen als gütig, gastfreundlich und fleißig – sie tränkte sogar seine zehn Kamele. Sie willigte ein, mitzugehen, und wurde Isaaks Frau und Mutter der Zwillinge Esau und Jakob.","facts":[{"t":"Tränkte die Kamele von Abrahams Diener – die Antwort auf dessen Gebet.","r":{"t":"1. Mose 24:14-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024014-v1024021"}},{"t":"Sie willigte selbst ein, mit dem Diener zu gehen.","r":{"t":"1. Mose 24:57, 58","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024057"}},{"t":"Isaak liebte sie und fand nach dem Tod seiner Mutter Trost.","r":{"t":"1. Mose 24:67","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024067"}},{"t":"Sie gebar die Zwillinge Esau und Jakob.","r":{"t":"1. Mose 25:24-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025024-v1025026"}}],"lesson":"","family":{"father":"Bethuel","mother":"","spouses":["isaak"],"children":["esau","jakob"],"siblings":["laban"]},"related":[],"events":["isaak-heiratet-rebekka","jakob-erhaelt-den-segen"],"books":[],"refs":[{"t":"1. Mose 24:15-67","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024015-v1024067"},{"t":"1. Mose 25:20-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025020-v1025026"},{"t":"1. Mose 27:5-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/27/#v1027005-v1027017"}],"sources":[{"title":"Rebekka – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003658"}]},{"id":"rehabeam","name":"Rehabeam","alt":[],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"997–980 v. u. Z. (17 Jahre)"}],"year":-997,"meaning":"„Das Volk erweitern“","summary":"Rehabeam, ein Sohn Salomos und der Ammoniterin Naama, wurde 997 v. u. Z. mit 41 Jahren König. Weil er den Rat der älteren Männer verwarf und dem Volk eine noch härtere Last androhte, sagten sich zehn Stämme von ihm los. So wurde er der erste König des Zweistämmereichs Juda und Benjamin.","facts":[{"t":"Er folgte dem Rat der jungen Männer statt dem der älteren.","r":{"t":"1. Könige 12:6-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/12/#v11012006-v11012014"}},{"t":"Zehn Stämme fielen von ihm ab.","r":{"t":"1. Könige 12:16-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/12/#v11012016-v11012020"}},{"t":"993 v. u. Z. plünderte Pharao Schischak den Tempel.","r":{"t":"1. Könige 14:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/14/#v11014025"}}],"lesson":"","family":{"father":"salomo","mother":"Naama","spouses":["Maacha"],"children":["abija"],"siblings":[]},"related":["jerobeam"],"events":["reichsteilung"],"books":[],"refs":[{"t":"1. Könige 12:1-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/12/#v11012001-v11012024"},{"t":"1. Könige 14:21-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/14/#v11014021-v11014031"},{"t":"2. Chronika 10:1-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/10/#v14010001-v14010019"}],"sources":[{"title":"Rehabeam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003680"},{"title":"A6-A Propheten und Könige von Juda und Israel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070206"}]},{"id":"ruben","name":"Ruben","alt":[],"sex":"m","tags":[],"role":"Erstgeborener Jakobs","eras":["patriarchen"],"dates":[],"year":-1773,"meaning":"„Seht, ein Sohn!“","summary":"Ruben war der Erstgeborene der zwölf Söhne Jakobs; seine Mutter war Lea. Er bewahrte Joseph davor, von seinen Brüdern getötet zu werden. Weil er jedoch mit Bilha, der Nebenfrau seines Vaters, Unmoral beging, verlor er die Vorrechte des Erstgeborenen.","facts":[{"t":"Lea nannte ihn Ruben, weil Jehova ihr Elend gesehen hatte.","r":{"t":"1. Mose 29:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029032"}},{"t":"Er hatte Beziehungen mit Bilha und entehrte so seinen Vater.","r":{"t":"1. Mose 35:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/35/#v1035022"}},{"t":"Er überredete seine Brüder, Joseph nicht zu töten.","r":{"t":"1. Mose 37:21, 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037021"}},{"t":"Sein Erstgeburtsrecht ging auf die Söhne Josephs über.","r":{"t":"1. Chronika 5:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/5/#v13005001"}}],"lesson":"","family":{"father":"jakob","mother":"lea","spouses":[],"children":[],"siblings":["simeon","levi","juda","dina","joseph","benjamin"]},"related":[],"events":["joseph-wird-verkauft"],"books":[],"refs":[{"t":"1. Mose 37:18-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037018-v1037030"},{"t":"1. Mose 49:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/49/#v1049003"},{"t":"1. Chronika 5:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/5/#v13005001"}],"sources":[{"title":"Ruben – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003713"}]},{"id":"ruth","name":"Ruth","alt":[],"sex":"f","tags":["vorfahr-jesu"],"role":"Moabiterin, Vorfahrin Davids","eras":["richter"],"dates":[],"year":-1355,"meaning":"","summary":"Ruth war eine Moabiterin, die Machlon heiratete, den Sohn Noomis. Nach dem Tod ihres Mannes hielt sie loyal zu ihrer Schwiegermutter und wollte Jehova mit seinem Volk dienen. In Bethlehem las sie fleißig Ähren auf dem Feld des Boas auf, der sie schließlich als Rückkäufer heiratete. Sie wurde die Urgroßmutter Davids und eine Vorfahrin Jesu.","facts":[{"t":"Sie sagte zu Noomi: „Dein Volk wird mein Volk sein und dein Gott mein Gott.“","r":{"t":"Ruth 1:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/1/#v8001016"}},{"t":"Sie las fleißig Ähren auf dem Feld des Boas auf.","r":{"t":"Ruth 2:2-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/2/#v8002002-v8002007"}},{"t":"Boas lobte ihre loyale Liebe.","r":{"t":"Ruth 3:10, 11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/3/#v8003010"}},{"t":"Sie gebar Obed, den Großvater Davids.","r":{"t":"Ruth 4:13-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/4/#v8004013-v8004017"}}],"lesson":"Ruths loyale Liebe zu Noomi und ihr Wunsch, Jehova zu dienen, gaben ihr die Kraft, Heimat und Familie zu verlassen.","family":{"father":"","mother":"","spouses":["Machlon","boas"],"children":["Obed"],"siblings":[]},"related":["noomi"],"events":["ruth-und-noomi"],"books":[],"refs":[{"t":"Ruth 1:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/1/#v8001016"},{"t":"Ruth 2:1-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/2/#v8002001-v8002023"},{"t":"Ruth 4:9-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/4/#v8004009-v8004017"},{"t":"Matthäus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001005"}],"sources":[{"title":"Ruth – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003776"}]},{"id":"secharja","name":"Sacharja","alt":["Secharja"],"sex":"m","tags":["koenig"],"role":"König von Israel (6 Monate)","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 803/792 v. u. Z. (6 Monate)"}],"year":-803,"meaning":"„Erinnert hat sich Jehova“","summary":"Sacharja, ein Sohn Jerobeams II., war der letzte König aus der Dynastie Jehus. Seine Herrschaft begann in gewissem Sinn nach dem Tod seines Vaters um 803 v. u. Z., lag aber offensichtlich erst um 792 v. u. Z. fest in seinen Händen. Nach sechs Monaten wurde er von Schallum ermordet – so erfüllte sich, dass Jehus Nachkommen bis zur vierten Generation regieren würden.","facts":[{"t":"Er regierte sechs Monate.","r":{"t":"2. Könige 15:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015008"}},{"t":"Schallum ermordete ihn.","r":{"t":"2. Könige 15:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015010"}},{"t":"Jehovas Wort an Jehu erfüllte sich.","r":{"t":"2. Könige 15:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015012"}}],"lesson":"","family":{"father":"jerobeam-ii","mother":"","spouses":[],"children":[],"siblings":[]},"related":["schallum"],"events":[],"books":[],"refs":[{"t":"2. Könige 15:8-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015008-v12015012"}],"sources":[{"title":"Sacharja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004681"},{"title":"A6-B Propheten und Könige von Juda und Israel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070215"}]},{"id":"sacharja","name":"Sacharja","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet nach dem Exil","eras":["rueckkehr"],"dates":[{"label":"Wirken","value":"ab 520 v. u. Z."}],"year":-520,"meaning":"„Erinnert hat sich Jehova“","summary":"Sacharja, der Sohn Berechjas und Enkel Iddos, wurde wahrscheinlich in Babylon geboren. Nur 17 Jahre nach der Rückkehr aus dem Exil begann er als noch junger Mann zu prophezeien. Zusammen mit Haggai ermutigte er Serubbabel, den Hohen Priester Jeschua und das Volk, den Tempel fertigzubauen. Sein Buch enthält zahlreiche Visionen und Prophezeiungen über den Messias.","facts":[{"t":"Er nennt sich „Sohn Berechjas, des Sohnes Iddos“.","r":{"t":"Sacharja 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/1/#v38001001"}},{"t":"Er wird als „junger Mann“ bezeichnet.","r":{"t":"Sacharja 2:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/2/#v38002004"}},{"t":"„Nicht durch eine Streitmacht … sondern durch meinen Geist.“","r":{"t":"Sacharja 4:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/4/#v38004006"}},{"t":"Er sagte voraus, dass der König auf einem Esel kommen würde.","r":{"t":"Sacharja 9:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/9/#v38009009"}}],"lesson":"","family":{"father":"Berechja","mother":"","spouses":[],"children":[],"siblings":[]},"related":["haggai","serubbabel","jeschua"],"events":["tempel-vollendet"],"books":["Sacharja"],"refs":[{"t":"Sacharja 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/1/#v38001001"},{"t":"Sacharja 4:6-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/4/#v38004006-v38004010"},{"t":"Sacharja 9:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/9/#v38009009"},{"t":"Esra 6:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/6/#v15006014"}],"sources":[{"title":"Sacharja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004681"}]},{"id":"zacharias","name":"Sacharja","alt":["Zacharias"],"sex":"m","tags":["priester"],"role":"Priester, Vater von Johannes dem Täufer","eras":["jesus"],"dates":[],"year":-62,"meaning":"„Erinnert hat sich Jehova“","summary":"Sacharja war ein Priester aus der Abteilung Abijas. Er und seine Frau Elisabeth waren gottesfürchtig, aber kinderlos und schon alt. Als er 3 v. u. Z. im Heiligtum Räucherwerk darbrachte, erschien ihm der Engel Gabriel und kündigte einen Sohn an. Weil Sacharja zweifelte, konnte er bis zur Namensgebung nicht mehr sprechen; dann schrieb er: „Johannes ist sein Name“, und prophezeite.","facts":[{"t":"Er gehörte zur Priesterabteilung Abijas.","r":{"t":"Lukas 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001005"}},{"t":"Gabriel erschien ihm am Räucheraltar.","r":{"t":"Lukas 1:11-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001011-v42001017"}},{"t":"Er verstummte, weil er nicht glaubte.","r":{"t":"Lukas 1:18-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001018-v42001020"}},{"t":"Mit heiligem Geist erfüllt, prophezeite er.","r":{"t":"Lukas 1:67-79","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001067-v42001079"}}],"lesson":"","family":{"father":"","mother":"","spouses":["elisabeth"],"children":["johannes-der-taeufer"],"siblings":[]},"related":["gabriel"],"events":["ankuendigung-johannes","geburt-johannes"],"books":[],"refs":[{"t":"Lukas 1:5-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001005-v42001025"},{"t":"Lukas 1:57-80","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001057-v42001080"}],"sources":[{"title":"Sacharja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004681"},{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"}]},{"id":"salomo","name":"Salomo","alt":["Jedidjah"],"sex":"m","tags":["koenig","schreiber","vorfahr-jesu"],"role":"König Israels, Erbauer des Tempels","eras":["koenigreich"],"dates":[{"label":"Regierung","value":"1037–998 v. u. Z."}],"year":-1037,"meaning":"von einer Wurzel mit der Bedeutung „Frieden“","summary":"Salomo, Sohn Davids und Bathsebas, wurde 1037 v. u. Z. König. Statt Reichtum erbat er von Jehova Weisheit und erhielt beides. Er baute in Jerusalem den Tempel, der 1027 v. u. Z. vollendet wurde, und seine Herrschaft war eine Zeit des Friedens. Im Alter jedoch neigten seine vielen ausländischen Frauen sein Herz anderen Göttern zu – sein Herz war nicht mehr ungeteilt mit Jehova.","facts":[{"t":"Jehova gab ihm durch Nathan den Namen Jedidjah („Geliebter Jahs“).","r":{"t":"2. Samuel 12:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/12/#v10012024"}},{"t":"Er bat um ein gehorsames Herz, um das Volk zu richten.","r":{"t":"1. Könige 3:9-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/3/#v11003009-v11003012"}},{"t":"Er baute den Tempel in Jerusalem.","r":{"t":"1. Könige 6:1, 37, 38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/6/#v11006001"}},{"t":"Er hatte 700 Frauen und 300 Nebenfrauen, die sein Herz zu anderen Göttern neigten.","r":{"t":"1. Könige 11:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/11/#v11011003"}},{"t":"Er schrieb das Hohe Lied und Prediger und viele Sprüche."}],"lesson":"","family":{"father":"david","mother":"batseba","spouses":[],"children":["rehabeam"],"siblings":["absalom","Adonia"]},"related":["nathan","koenigin-von-saba"],"events":["salomo-wird-koenig","salomo-bittet-um-weisheit","tempelbau","besuch-der-koenigin-von-saba","reichsteilung"],"books":["Sprüche (größtenteils)","Prediger","Hohes Lied"],"refs":[{"t":"1. Könige 3:5-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/3/#v11003005-v11003014"},{"t":"1. Könige 8:22-61","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/8/#v11008022-v11008061"},{"t":"1. Könige 11:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/11/#v11011001-v11011013"}],"sources":[{"title":"Salomo – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004178"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"samuel","name":"Samuel","alt":[],"sex":"m","tags":["prophet","richter","schreiber"],"role":"Prophet und Richter","eras":["richter","koenigreich"],"dates":[],"year":-1185,"meaning":"„Name Gottes“","summary":"Samuel, der Sohn Elkanas und Hannas, wurde schon als Kind in den Dienst an der Stiftshütte in Silo gestellt. Dort sprach Jehova zu ihm, und er wurde bereits in jungen Jahren ein Prophet. Er richtete Israel von Rama aus. Als das Volk einen König verlangte, salbte er auf Jehovas Anweisung Saul und später David. Der Überlieferung nach schrieb er die Bücher Richter und Ruth sowie einen Teil von 1. Samuel.","facts":[{"t":"Als Kind diente er mit einem leinenen Ephod vor Jehova.","r":{"t":"1. Samuel 2:18, 19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/2/#v9002018"}},{"t":"Jehova rief ihn nachts beim Namen.","r":{"t":"1. Samuel 3:4-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/3/#v9003004-v9003010"}},{"t":"Er richtete Israel in Bethel, Gilgal und Mizpa.","r":{"t":"1. Samuel 7:15-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/7/#v9007015-v9007017"}},{"t":"Er salbte Saul zum König.","r":{"t":"1. Samuel 10:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/10/#v9010001"}},{"t":"Er salbte den jungen David.","r":{"t":"1. Samuel 16:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/16/#v9016013"}}],"lesson":"","family":{"father":"Elkana","mother":"hanna","spouses":[],"children":["Joel","Abija"],"siblings":[]},"related":["eli","saul","david"],"events":["zeit-der-richter","hannas-gebet","bundeslade-erbeutet","israel-will-einen-koenig","saul-wird-koenig","david-wird-gesalbt"],"books":["Richter","Ruth","1. Samuel (teilweise)"],"refs":[{"t":"1. Samuel 3:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/3/#v9003001-v9003021"},{"t":"1. Samuel 8:4-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/8/#v9008004-v9008022"},{"t":"Apostelgeschichte 3:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/3/#v44003024"}],"sources":[{"title":"Samuel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003824"}]},{"id":"sanherib","name":"Sanherib","alt":[],"sex":"m","tags":["herrscher"],"role":"König von Assyrien","eras":["geteilt"],"dates":[{"label":"Zeit","value":"Feldzug gegen Juda 732 v. u. Z."}],"year":-732,"meaning":"„Sin (der Mondgott) hat mir die Brüder ersetzt“ (akkadisch)","summary":"Sanherib, Sohn Sargons II., war König von Assyrien. 732 v. u. Z., im 14. Jahr Hiskias, nahm er die befestigten Städte Judas ein und forderte die Übergabe Jerusalems, wobei er Jehova verhöhnte. Doch Jehovas Engel tötete in einer Nacht 185 000 Mann seines Heeres. Später wurde Sanherib im Tempel seines Gottes Nisroch von zwei seiner Söhne erschlagen.","facts":[{"t":"Er nahm die befestigten Städte Judas ein.","r":{"t":"2. Könige 18:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/18/#v12018013"}},{"t":"Sein Sprecher verhöhnte Jehova.","r":{"t":"2. Könige 18:28-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/18/#v12018028-v12018035"}},{"t":"Der Engel Jehovas schlug 185 000 Assyrer.","r":{"t":"2. Könige 19:35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/19/#v12019035"}},{"t":"Seine Söhne erschlugen ihn im Haus Nisrochs.","r":{"t":"Jesaja 37:37, 38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/37/#v23037037"}}],"lesson":"","family":{"father":"Sargon II.","mother":"","spouses":[],"children":["Adrammelech","Sarezer"],"siblings":[]},"related":["hiskia","jesaja"],"events":["sanherib-bedroht-jerusalem"],"books":[],"refs":[{"t":"2. Könige 18:13–19:37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/18/#v12018013-v12019037"},{"t":"Jesaja 36:1–37:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/36/#v23036001-v23037038"}],"sources":[{"title":"Sanherib – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003897"},{"title":"Hiskia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002011"}]},{"id":"sara","name":"Sara","alt":["Sarai"],"sex":"f","tags":["vorfahr-jesu"],"role":"Frau Abrahams, Mutter Isaaks","eras":["patriarchen"],"dates":[{"label":"Gestorben","value":"1881 v. u. Z."},{"label":"Alter","value":"127 Jahre"}],"year":-2008,"meaning":"„Fürstin“","summary":"Sara, ursprünglich Sarai, war die Halbschwester und Frau Abrahams. Sie begleitete ihn von Ur über Haran nach Kanaan und blieb lange unfruchtbar. Durch ein Wunder bekam sie mit 90 Jahren ihren Sohn Isaak. Sie starb 1881 v. u. Z. mit 127 Jahren und wurde in der Höhle von Machpela begraben.","facts":[{"t":"Sie war zehn Jahre jünger als Abraham und heiratete ihn in Ur.","r":{"t":"1. Mose 17:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/17/#v1017017"}},{"t":"Mit 65 Jahren zog sie mit Abraham von Haran nach Kanaan.","r":{"t":"1. Mose 12:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/12/#v1012004"}},{"t":"Sie gab Abraham ihre Magd Hagar, um durch sie Kinder zu bekommen.","r":{"t":"1. Mose 16:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/16/#v1016001-v1016003"}},{"t":"Sie lachte über die Ankündigung eines Sohnes – im Jahr darauf wurde Isaak geboren.","r":{"t":"1. Mose 18:9-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/18/#v1018009-v1018015"}},{"t":"Sie starb mit 127 Jahren.","r":{"t":"1. Mose 23:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/23/#v1023001"}}],"lesson":"","family":{"father":"","mother":"","spouses":["abraham"],"children":["isaak"],"siblings":[]},"related":["hagar"],"events":["abrahamischer-bund","geburt-isaaks","hagar-und-ismael"],"books":[],"refs":[{"t":"1. Mose 17:15-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/17/#v1017015-v1017019"},{"t":"1. Mose 21:1-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021001-v1021007"},{"t":"Hebräer 11:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011011"}],"sources":[{"title":"Sara – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003837"}]},{"id":"satan","name":"Satan","alt":["Teufel","Schlange"],"sex":"","tags":["engel"],"role":"Widersacher Gottes, der Teufel","eras":["anfaenge","aegypten","jesus"],"dates":[],"year":null,"meaning":"„Widerstandleistender“","summary":"Satan wurde von Gott als vollkommenes, gerechtes Geistgeschöpf erschaffen. Er verließ jedoch die Wahrheit, lehnte sich gegen Gott auf und wurde zu dessen Hauptwidersacher – daher der Name Satan. Durch eine Schlange verleitete er Eva zum Ungehorsam und brachte so Sünde und Tod über die Menschen.","facts":[{"t":"Seinen früheren Namen nennt die Bibel nicht; „Satan“ heißt er wegen seiner Auflehnung gegen Gott."},{"t":"Jesus nannte ihn einen Totschläger, der in der Wahrheit nicht feststand.","r":{"t":"Johannes 8:44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/8/#v43008044"}},{"t":"Er sprach durch eine Schlange zu Eva und verleitete sie, Gottes Gebot zu übertreten.","r":{"t":"1. Mose 3:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003001-v1003006"}},{"t":"Er stellte Hiobs Treue infrage und brachte schweres Unglück über ihn.","r":{"t":"Hiob 1:6-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/1/#v18001006-v18001012"}},{"t":"Nach Jesu Taufe versuchte er ihn in der Wildnis mit drei großen Versuchungen.","r":{"t":"Matthäus 4:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/4/#v40004001-v40004011"}},{"t":"Er wird für 1000 Jahre gefangen gesetzt und schließlich vernichtet.","r":{"t":"Offenbarung 20:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/20/#v66020001-v66020003"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["suendenfall","hiobs-pruefung","versuchung"],"books":[],"refs":[{"t":"1. Mose 3:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003001-v1003015"},{"t":"Hiob 1:6-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/1/#v18001006-v18001012"},{"t":"Johannes 8:44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/8/#v43008044"},{"t":"Offenbarung 12:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/12/#v66012009"}],"sources":[{"title":"Satan – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003845"},{"title":"B1 Das Hauptthema der Bibel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070221"}]},{"id":"saul","name":"Saul","alt":[],"sex":"m","tags":["koenig"],"role":"Erster König Israels","eras":["koenigreich"],"dates":[{"label":"Regierung","value":"ab 1117 v. u. Z. (40 Jahre)"}],"year":-1117,"meaning":"„Erbeten (von Gott)“","summary":"Saul, ein Benjaminiter aus wohlhabender Familie, war der erste König Israels. Er war stattlich, kräftig und anfangs bescheiden. Doch er gehorchte Jehova nicht: Im Krieg gegen die Amalekiter verschonte er König Agag und das beste Vieh und schob die Schuld auf das Volk. Jehova verwarf ihn als König. Zuletzt suchte er sogar ein Geistermedium in En-Dor auf und starb im Kampf gegen die Philister auf dem Berg Gilboa.","facts":[{"t":"Samuel salbte ihn zum König; drei prophetische Zeichen bestätigten das.","r":{"t":"1. Samuel 10:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/10/#v9010001-v9010009"}},{"t":"Er war einen Kopf größer als alle anderen.","r":{"t":"1. Samuel 9:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/9/#v9009002"}},{"t":"Er verschonte Agag und das beste Vieh der Amalekiter.","r":{"t":"1. Samuel 15:7-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/15/#v9015007-v9015009"}},{"t":"„Gehorchen ist besser als ein Schlachtopfer“, sagte Samuel zu ihm.","r":{"t":"1. Samuel 15:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/15/#v9015022"}},{"t":"Er befragte ein Geistermedium in En-Dor.","r":{"t":"1. Samuel 28:7-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/28/#v9028007-v9028019"}},{"t":"Er starb mit drei Söhnen auf dem Berg Gilboa.","r":{"t":"1. Samuel 31:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/31/#v9031001-v9031006"}}],"lesson":"","family":{"father":"Kisch","mother":"","spouses":["Ahinoam"],"children":["jonathan","Isch-Boscheth","michal","Merab"],"siblings":[]},"related":["samuel","david"],"events":["israel-will-einen-koenig","saul-wird-koenig","david-wird-gesalbt","david-und-goliath","david-flieht-vor-saul","sauls-tod"],"books":[],"refs":[{"t":"1. Samuel 9:1–10:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/9/#v9009001-v9010027"},{"t":"1. Samuel 15:1-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/15/#v9015001-v9015035"},{"t":"1. Samuel 31:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/31/#v9031001-v9031013"}],"sources":[{"title":"Saul – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003847"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"schallum","name":"Schallum","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel (1 Monat)","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 791 v. u. Z. (1 Monat)"}],"year":-791,"meaning":"von einer Wurzel mit der Bedeutung „Frieden schließen“","summary":"Schallum, der Sohn des Jabesch, verschwor sich gegen König Sacharja, tötete ihn und regierte dann einen Mondmonat lang in Samaria. Danach wurde er selbst von Menahem ermordet.","facts":[{"t":"Er tötete Sacharja öffentlich.","r":{"t":"2. Könige 15:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015010"}},{"t":"Er regierte einen Monat lang.","r":{"t":"2. Könige 15:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015013"}},{"t":"Menahem tötete ihn in Samaria.","r":{"t":"2. Könige 15:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015014"}}],"lesson":"","family":{"father":"Jabesch","mother":"","spouses":[],"children":[],"siblings":[]},"related":["secharja","menahem"],"events":[],"books":[],"refs":[{"t":"2. Könige 15:10-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015010-v12015015"}],"sources":[{"title":"Schallum – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003933"}]},{"id":"schiphra-und-pua","name":"Schiphra und Pua","alt":["Schiphra","Pua"],"sex":"f","tags":[],"role":"Hebräische Hebammen in Ägypten","eras":["aegypten"],"dates":[],"year":-1595,"meaning":"Schiphra: „Angenehm“, „Schön“","summary":"Schiphra und Pua waren zwei hebräische Hebammen in Ägypten. Pharao befahl ihnen, alle neugeborenen Jungen der Hebräer zu töten. Weil sie Gott fürchteten und die Heiligkeit des menschlichen Lebens respektierten, ließen sie die Jungen am Leben. Jehova segnete sie später mit eigenen Familien.","facts":[{"t":"Pharao befahl ihnen, die Jungen der Hebräer zu töten.","r":{"t":"2. Mose 1:15, 16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/1/#v2001015"}},{"t":"Sie fürchteten den wahren Gott und ließen die Kinder leben.","r":{"t":"2. Mose 1:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/1/#v2001017"}},{"t":"Gott schenkte ihnen eigene Familien.","r":{"t":"2. Mose 1:20, 21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/1/#v2001020"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["unterdrueckung-in-aegypten"],"books":[],"refs":[{"t":"2. Mose 1:15-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/1/#v2001015-v2001021"}],"sources":[{"title":"Schiphra – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004066"},{"title":"Pua – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003574"}]},{"id":"sem","name":"Sem","alt":[],"sex":"m","tags":["vorfahr-jesu"],"role":"Sohn Noahs","eras":["anfaenge","patriarchen"],"dates":[{"label":"Alter","value":"600 Jahre"}],"year":-2468,"meaning":"„Name“, „Ruhm“","summary":"Sem war einer der drei Söhne Noahs und überlebte mit seiner Frau die Sintflut. Von Noahs Söhnen aus breitete sich nach der Flut die ganze Erdbevölkerung aus. Sem starb mit 600 Jahren, einige Jahre nach Saras Tod; Abraham und Sem lebten etwa 150 Jahre gleichzeitig.","facts":[{"t":"Einer der acht Menschen, die die Sintflut in der Arche überlebten.","r":{"t":"1. Mose 7:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/7/#v1007013"}},{"t":"Bedeckte mit Japhet respektvoll die Blöße seines Vaters und wurde gesegnet.","r":{"t":"1. Mose 9:23, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009023"}},{"t":"Wurde 600 Jahre alt.","r":{"t":"1. Mose 11:10, 11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011010"}},{"t":"Er steht im Geschlechtsregister Jesu.","r":{"t":"Lukas 3:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003036"}}],"lesson":"","family":{"father":"noah","mother":"","spouses":[],"children":["Arpachschad"],"siblings":["ham","japhet"]},"related":["abraham"],"events":["bau-der-arche","sintflut"],"books":[],"refs":[{"t":"1. Mose 9:18-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009018-v1009027"},{"t":"1. Mose 11:10, 11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011010"}],"sources":[{"title":"Sem – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003997"},{"title":"Abraham – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000060"}]},{"id":"serubbabel","name":"Serubbabel","alt":["Scheschbazzar"],"sex":"m","tags":["vorfahr-jesu"],"role":"Statthalter nach dem Exil","eras":["rueckkehr"],"dates":[{"label":"Zeit","value":"Rückkehr 537 v. u. Z."}],"year":-537,"meaning":"„Same (Nachkomme) von Babel“ (akkadisch)","summary":"Serubbabel, ein Nachkomme König Davids und Vorfahr Jesu, führte 537 v. u. Z. den jüdischen Überrest aus Babylon zurück und wurde der erste Statthalter. Mit dem Hohen Priester Jeschua begann er 536 v. u. Z. den Bau des Tempels. Als der Bau ins Stocken geriet, ermutigten ihn Haggai und Sacharja, und 515 v. u. Z. wurde der Tempel vollendet.","facts":[{"t":"Er führte die erste Gruppe aus dem Exil zurück.","r":{"t":"Esra 2:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/2/#v15002001"}},{"t":"Mit Jeschua legte er das Fundament des Tempels.","r":{"t":"Esra 3:8-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/3/#v15003008-v15003010"}},{"t":"Haggai und Sacharja ermutigten ihn.","r":{"t":"Haggai 2:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/2/#v37002004"}},{"t":"Er steht im Geschlechtsregister Jesu.","r":{"t":"Matthäus 1:12, 13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001012"}}],"lesson":"","family":{"father":"Schealtiel","mother":"","spouses":[],"children":["Meschullam","Hananja","Schelomith"],"siblings":[]},"related":["jeschua","haggai","sacharja"],"events":["rueckkehr-nach-jerusalem","tempelfundament","tempel-vollendet"],"books":[],"refs":[{"t":"Esra 2:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/2/#v15002001"},{"t":"Esra 3:8-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/3/#v15003008-v15003013"},{"t":"Haggai 2:20-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/2/#v37002020-v37002023"},{"t":"Sacharja 4:6-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/4/#v38004006-v38004010"}],"sources":[{"title":"Serubbabel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004716"}]},{"id":"seth","name":"Seth","alt":[],"sex":"m","tags":["vorfahr-jesu"],"role":"Sohn Adams, Vorfahr Noahs","eras":["anfaenge"],"dates":[{"label":"Lebenszeit","value":"3896–2984 v. u. Z."},{"label":"Alter","value":"912 Jahre"}],"year":-3896,"meaning":"„Gesetzt“, „Bestimmt“","summary":"Seth wurde Adam und Eva geboren, als Adam 130 Jahre alt war. Eva nannte ihn so, weil Gott ihr anstelle des getöteten Abel einen anderen Nachkommen „gesetzt“ hatte. Bedeutsam ist er, weil Noah – und damit die heutige Menschheit – von Seth abstammt, nicht von Kain.","facts":[{"t":"Wurde geboren, als Adam 130 Jahre alt war.","r":{"t":"1. Mose 5:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005003"}},{"t":"Mit 105 Jahren wurde er Vater von Enosch.","r":{"t":"1. Mose 5:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005006"}},{"t":"Starb mit 912 Jahren.","r":{"t":"1. Mose 5:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005008"}},{"t":"Er steht im Geschlechtsregister Jesu.","r":{"t":"Lukas 3:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003038"}}],"lesson":"","family":{"father":"adam","mother":"eva","spouses":[],"children":["Enosch"],"siblings":["kain","abel"]},"related":[],"events":[],"books":[],"refs":[{"t":"1. Mose 4:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004025"},{"t":"1. Mose 5:3-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005003-v1005008"},{"t":"Lukas 3:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003038"}],"sources":[{"title":"Seth – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003911"}]},{"id":"silas","name":"Silas","alt":["Silvanus"],"sex":"m","tags":["prophet","juenger"],"role":"Prophet, Gefährte des Paulus","eras":["versammlung"],"dates":[],"year":49,"meaning":"„Wald“ (Silvanus, aus dem Lateinischen)","summary":"Silas, auch Silvanus genannt, war ein führender Bruder der Versammlung in Jerusalem, ein Prophet und offenbar römischer Bürger. Er überbrachte mit Paulus und Barnabas die Entscheidung über die Beschneidung nach Antiochia. Auf der zweiten Missionsreise begleitete er Paulus; in Philippi wurden beide geschlagen und eingesperrt, sangen aber nachts Lieder. Später schrieb Petrus seinen ersten Brief „durch Silvanus“.","facts":[{"t":"Er brachte den Brief der Apostel nach Antiochia.","r":{"t":"Apostelgeschichte 15:22, 27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015022"}},{"t":"Paulus wählte ihn als Reisegefährten.","r":{"t":"Apostelgeschichte 15:40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015040"}},{"t":"Im Gefängnis von Philippi beteten und sangen sie.","r":{"t":"Apostelgeschichte 16:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016025"}},{"t":"Petrus schrieb „durch Silvanus“.","r":{"t":"1. Petrus 5:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-petrus/5/#v60005012"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus","timotheus","petrus"],"events":["beschneidungsfrage","zweite-missionsreise"],"books":[],"refs":[{"t":"Apostelgeschichte 15:22-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015022-v44015040"},{"t":"Apostelgeschichte 16:19-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016019-v44016040"}],"sources":[{"title":"Silas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004118"}]},{"id":"simeon","name":"Simeon","alt":[],"sex":"m","tags":[],"role":"Zweiter Sohn Jakobs","eras":["patriarchen"],"dates":[],"year":-1772,"meaning":"„Erhörung“","summary":"Simeon war der zweite Sohn Jakobs und Leas. Zusammen mit seinem Bruder Levi rächte er auf grausame Weise die Vergewaltigung ihrer Schwester Dina und brachte damit die Familie in Verruf. In Ägypten hielt Joseph ihn als Geisel fest, bis die Brüder Benjamin mitbrachten.","facts":[{"t":"Lea nannte ihn so, weil Jehova „gehört“ hatte.","r":{"t":"1. Mose 29:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029033"}},{"t":"Mit Levi tötete er die Männer von Sichem.","r":{"t":"1. Mose 34:25-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/34/#v1034025-v1034031"}},{"t":"In Ägypten wurde er als Geisel festgehalten.","r":{"t":"1. Mose 42:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/42/#v1042024"}}],"lesson":"","family":{"father":"jakob","mother":"lea","spouses":[],"children":[],"siblings":["ruben","levi","juda","dina","joseph","benjamin"]},"related":[],"events":["joseph-wird-verkauft","joseph-gibt-sich-zu-erkennen"],"books":[],"refs":[{"t":"1. Mose 34:25-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/34/#v1034025-v1034031"},{"t":"1. Mose 42:14-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/42/#v1042014-v1042024"},{"t":"1. Mose 49:5-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/49/#v1049005-v1049007"}],"sources":[{"title":"Simeon – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004124"}]},{"id":"simeon-in-jerusalem","name":"Simeon","alt":[],"sex":"m","tags":[],"role":"Gerechter Mann in Jerusalem","eras":["jesus"],"dates":[],"year":-2,"meaning":"„Erhörung“","summary":"Simeon war ein gerechter, gottesfürchtiger alter Mann in Jerusalem. Gott hatte ihm offenbart, dass er nicht sterben werde, bevor er den Christus gesehen hätte. Als Joseph und Maria das Kind Jesus in den Tempel brachten, nahm er es in die Arme und pries Jehova. Er sagte voraus, dass Maria wegen ihres Sohnes heftigen Schmerz empfinden würde.","facts":[{"t":"Der heilige Geist war auf ihm.","r":{"t":"Lukas 2:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002025"}},{"t":"Er nahm das Kind in seine Arme und pries Gott.","r":{"t":"Lukas 2:28-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002028-v42002032"}},{"t":"Er sagte: „Dieser ist zum Fall und Wiederaufstehen vieler gesetzt.“","r":{"t":"Lukas 2:34, 35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002034"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["hanna-prophetin"],"events":["darstellung-im-tempel"],"books":[],"refs":[{"t":"Lukas 2:25-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002025-v42002035"}],"sources":[{"title":"Simeon – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004124"}]},{"id":"simon-kananaeer","name":"Simon der Kananäer","alt":["Simon","Simon der Eiferer","Simon der Zelot"],"sex":"m","tags":["apostel"],"role":"Apostel","eras":["jesus"],"dates":[],"year":31,"meaning":"","summary":"Simon wird durch den Beinamen „der Kananäer“ von Simon Petrus unterschieden. Möglicherweise gehörte er zuvor den Zeloten an, einer römerfeindlichen jüdischen Partei; es kann aber auch sein, dass er wegen seines religiösen Eifers „der Eiferer“ genannt wurde.","facts":[{"t":"Er heißt „der Kananäer“.","r":{"t":"Matthäus 10:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/10/#v40010004"}},{"t":"Lukas nennt ihn „der Eiferer“.","r":{"t":"Lukas 6:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006015"}},{"t":"Er war nach der Himmelfahrt bei den Aposteln.","r":{"t":"Apostelgeschichte 1:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001013"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["wahl-der-apostel"],"books":[],"refs":[{"t":"Matthäus 10:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/10/#v40010004"},{"t":"Lukas 6:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006015"},{"t":"Apostelgeschichte 1:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001013"}],"sources":[{"title":"Simon – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004131"}]},{"id":"simri","name":"Simri","alt":[],"sex":"m","tags":["koenig"],"role":"König von Israel (7 Tage)","eras":["geteilt"],"dates":[{"label":"Regierung","value":"um 951 v. u. Z. (7 Tage)"}],"year":-951,"meaning":"","summary":"Simri, Oberster der Hälfte der Wagen, ermordete König Ela und das Haus Baschas und bemächtigte sich des Thrones. Doch er regierte nur sieben Tage: Das Heer rief Omri zum König aus und belagerte Tirza. Als Simri sah, dass die Stadt fiel, verbrannte er sich im Königshaus.","facts":[{"t":"Er tötete Ela in Tirza.","r":{"t":"1. Könige 16:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016009"}},{"t":"Er regierte sieben Tage.","r":{"t":"1. Könige 16:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016015"}},{"t":"Er verbrannte sich im Königshaus.","r":{"t":"1. Könige 16:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016018"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["ela","omri"],"events":[],"books":[],"refs":[{"t":"1. Könige 16:9-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/16/#v11016009-v11016020"}],"sources":[{"title":"Simri – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004737"}]},{"id":"simson","name":"Simson","alt":[],"sex":"m","tags":["richter"],"role":"Richter, Kämpfer gegen die Philister","eras":["richter"],"dates":[{"label":"Wirken","value":"20 Jahre als Richter"}],"year":-1150,"meaning":"von einer Wurzel mit der Bedeutung „Sonne“","summary":"Simson, der Sohn Manoachs aus dem Stamm Dan, war von Geburt an ein Nasiräer und sollte Israel aus der Hand der Philister retten. In der Kraft des Geistes Gottes riss er einen Löwen entzwei und schlug immer wieder die Philister. Durch Delila verriet er das Geheimnis seiner Kraft und geriet in Gefangenschaft. Bei seinem Tod im Haus Dagons riss er die Säulen ein und tötete viele Philister.","facts":[{"t":"Ein Engel kündigte seine Geburt an.","r":{"t":"Richter 13:2-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/13/#v7013002-v7013005"}},{"t":"Er riss mit bloßen Händen einen Löwen entzwei.","r":{"t":"Richter 14:5, 6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/14/#v7014005"}},{"t":"Er richtete Israel 20 Jahre.","r":{"t":"Richter 16:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016031"}},{"t":"Delila verriet ihn an die Philister.","r":{"t":"Richter 16:4-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016004-v7016021"}},{"t":"Er bat Jehova ein letztes Mal um Kraft und riss das Haus Dagons ein.","r":{"t":"Richter 16:28-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016028-v7016030"}}],"lesson":"","family":{"father":"Manoach","mother":"","spouses":[],"children":[],"siblings":[]},"related":["delila"],"events":["zeit-der-richter","simson-und-die-philister"],"books":[],"refs":[{"t":"Richter 13:1–16:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/13/#v7013001-v7016031"},{"t":"Hebräer 11:32-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011032-v58011034"}],"sources":[{"title":"Simson – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003823"}]},{"id":"stephanus","name":"Stephanus","alt":[],"sex":"m","tags":["juenger"],"role":"Erster christlicher Märtyrer","eras":["versammlung"],"dates":[],"year":33,"meaning":"von einem Wurzelwort, das „Krone“, „Kranz“ bedeutet","summary":"Stephanus war einer der sieben Männer, die in Jerusalem für die gerechte tägliche Austeilung von Nahrung an die Witwen eingesetzt wurden. Er war voll Glauben und heiligem Geist und predigte eifrig. Gegner brachten falsche Zeugen vor den Sanhedrin. In seiner Verteidigungsrede zeigte er, wie Gott mit Israel umgegangen war. Daraufhin wurde er gesteinigt – er war der erste christliche Märtyrer.","facts":[{"t":"Er gehörte zu den sieben ausgewählten Männern.","r":{"t":"Apostelgeschichte 6:3-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/6/#v44006003-v44006005"}},{"t":"Er vollbrachte große Zeichen unter dem Volk.","r":{"t":"Apostelgeschichte 6:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/6/#v44006008"}},{"t":"Er sah Jesus zur Rechten Gottes stehen.","r":{"t":"Apostelgeschichte 7:55, 56","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/7/#v44007055"}},{"t":"„Jehova, rechne ihnen diese Sünde nicht zu!“","r":{"t":"Apostelgeschichte 7:60","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/7/#v44007060"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["philippus-evangelist","paulus"],"events":["stephanus-gesteinigt"],"books":[],"refs":[{"t":"Apostelgeschichte 6:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/6/#v44006001-v44006015"},{"t":"Apostelgeschichte 7:1-60","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/7/#v44007001-v44007060"}],"sources":[{"title":"Stephanus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004230"}]},{"id":"tamar","name":"Tamar","alt":[],"sex":"f","tags":["vorfahr-jesu"],"role":"Schwiegertochter Judas","eras":["patriarchen"],"dates":[],"year":-1745,"meaning":"„Palme“","summary":"Tamar war die Schwiegertochter Judas. Nachdem ihre Männer Er und Onan wegen ihrer Bosheit gestorben waren und Juda ihr seinen dritten Sohn vorenthielt, verkleidete sie sich und bekam von Juda selbst Zwillinge. Juda erkannte an: „Sie ist gerechter als ich.“ Ihr Name steht im Geschlechtsregister Jesu.","facts":[{"t":"Sie wurde nacheinander mit Er und Onan verheiratet; beide starben.","r":{"t":"1. Mose 38:6-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/38/#v1038006-v1038010"}},{"t":"Juda zögerte die Ehe mit seinem dritten Sohn hinaus.","r":{"t":"1. Mose 38:11, 14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/38/#v1038011"}},{"t":"Juda erkannte an, dass sie gerechter war als er.","r":{"t":"1. Mose 38:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/38/#v1038026"}},{"t":"Ihr Name steht im Geschlechtsregister Jesu.","r":{"t":"Matthäus 1:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001003"}}],"lesson":"","family":{"father":"","mother":"","spouses":["Er","Onan"],"children":["Perez","Serach"],"siblings":[]},"related":["juda"],"events":[],"books":[],"refs":[{"t":"1. Mose 38:1-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/38/#v1038001-v1038030"},{"t":"Matthäus 1:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001003"}],"sources":[{"title":"Tamar – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004313"}]},{"id":"terach","name":"Terach","alt":[],"sex":"m","tags":["vorfahr-jesu"],"role":"Vater Abrahams","eras":["patriarchen"],"dates":[{"label":"Alter","value":"205 Jahre"}],"year":-2148,"meaning":"„Steinbock“ (vielleicht)","summary":"Terach, der Vater Abrahams, Nahors und Harans, lebte in Ur der Chaldäer. Mit etwa 200 Jahren brach er mit Abraham, Sara und seinem Enkel Lot in Richtung Kanaan auf, starb aber in Haran im Alter von 205 Jahren. Als Abraham geboren wurde, war Terach 130 Jahre alt.","facts":[{"t":"Wohnte mit seiner Familie in Ur der Chaldäer.","r":{"t":"1. Mose 11:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011028"}},{"t":"Er hatte früher anderen Göttern gedient.","r":{"t":"Josua 24:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/24/#v6024002"}},{"t":"Zog mit Abraham, Sara und Lot nach Haran.","r":{"t":"1. Mose 11:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011031"}},{"t":"Starb mit 205 Jahren in Haran.","r":{"t":"1. Mose 11:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011032"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":["abraham","Nahor","Haran"],"siblings":[]},"related":["lot"],"events":["geburt-abrams"],"books":[],"refs":[{"t":"1. Mose 11:26-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011026-v1011032"},{"t":"Josua 24:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/24/#v6024002"},{"t":"Lukas 3:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003034"}],"sources":[{"title":"Terach – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004368"}]},{"id":"thaddaeus","name":"Thaddäus","alt":["Judas, Sohn des Jakobus"],"sex":"m","tags":["apostel"],"role":"Apostel (Judas, Sohn des Jakobus)","eras":["jesus"],"dates":[],"year":31,"meaning":"","summary":"Thaddäus ist einer der zwölf Apostel. In den Apostellisten bei Lukas und in der Apostelgeschichte steht an seiner Stelle „Judas, der Sohn des Jakobus“; Thaddäus ist also offenbar ein anderer Name für diesen Apostel.","facts":[{"t":"Matthäus und Markus nennen ihn Thaddäus.","r":{"t":"Markus 3:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/3/#v41003018"}},{"t":"Lukas nennt ihn „Judas, der Sohn des Jakobus“.","r":{"t":"Lukas 6:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006016"}},{"t":"Anscheinend ist er der „Judas (nicht Iskariot)“, der Jesus beim letzten Abendmahl eine Frage stellte.","r":{"t":"Johannes 14:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/14/#v43014022"}}],"lesson":"","family":{"father":"Jakobus","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["wahl-der-apostel"],"books":[],"refs":[{"t":"Matthäus 10:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/10/#v40010003"},{"t":"Lukas 6:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006016"},{"t":"Johannes 14:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/14/#v43014022"}],"sources":[{"title":"Thaddäus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004374"},{"title":"Judas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002541"}]},{"id":"thomas","name":"Thomas","alt":["Didymus"],"sex":"m","tags":["apostel"],"role":"Apostel, „der Zwilling“","eras":["jesus"],"dates":[],"year":29,"meaning":"„Zwilling“ (aus dem Aramäischen)","summary":"Thomas, auch Didymus („Zwilling“) genannt, war ein Apostel, der seine Empfindungen und Zweifel spontan äußerte. Als Jesus nach Judäa zurückkehren wollte, sagte er mutig: „Lasst auch uns gehen, um mit ihm zu sterben.“ Nach der Auferweckung Jesu zweifelte er zunächst, doch als Jesus ihm erschien, rief er: „Mein Herr und mein Gott!“","facts":[{"t":"„Lasst auch uns gehen, um mit ihm zu sterben.“","r":{"t":"Johannes 11:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011016"}},{"t":"Er äußerte Zweifel, als Jesus von dem Weg zum Vater sprach.","r":{"t":"Johannes 14:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/14/#v43014005"}},{"t":"Er wollte die Nägelmale sehen, bevor er glaubte.","r":{"t":"Johannes 20:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/20/#v43020024"}},{"t":"Er rief: „Mein Herr und mein Gott!“","r":{"t":"Johannes 20:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/20/#v43020028"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":[],"events":["wahl-der-apostel","auferweckung-jesu"],"books":[],"refs":[{"t":"Johannes 11:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011016"},{"t":"Johannes 20:24-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/20/#v43020024-v43020029"}],"sources":[{"title":"Thomas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004385"}]},{"id":"timotheus","name":"Timotheus","alt":[],"sex":"m","tags":["juenger"],"role":"Missionar, Mitarbeiter des Paulus","eras":["versammlung"],"dates":[],"year":49,"meaning":"„Gott Ehrender“","summary":"Timotheus war der Sohn der Jüdin Eunike und eines griechischen Vaters. Seine Mutter und wohl auch seine Großmutter Lois lehrten ihn von klein auf die heiligen Schriften. Als Paulus Ende 49 oder Anfang 50 u. Z. nach Lystra kam, hatte Timotheus bei den Brüdern einen guten Ruf; Paulus nahm ihn mit. Er besuchte und stärkte viele Versammlungen. Paulus nannte ihn sein „geliebtes und treues Kind im Herrn“ und schrieb ihm zwei Briefe.","facts":[{"t":"Er war bei den Brüdern in Lystra und Ikonion in gutem Ruf.","r":{"t":"Apostelgeschichte 16:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016001"}},{"t":"Er kannte die heiligen Schriften von frühester Kindheit an.","r":{"t":"2. Timotheus 3:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/3/#v55003015"}},{"t":"Paulus sandte ihn als sein treues Kind nach Korinth.","r":{"t":"1. Korinther 4:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-korinther/4/#v46004017"}},{"t":"Er hatte oft mit Magenbeschwerden zu kämpfen.","r":{"t":"1. Timotheus 5:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-timotheus/5/#v54005023"}}],"lesson":"","family":{"father":"Grieche (Name nicht genannt)","mother":"eunike","spouses":[],"children":[],"siblings":[]},"related":["paulus","lois","silas"],"events":["zweite-missionsreise","dritte-missionsreise","paulus-in-rom","tod-des-paulus"],"books":[],"refs":[{"t":"Apostelgeschichte 16:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016001-v44016005"},{"t":"Philipper 2:19-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/philipper/2/#v50002019-v50002022"},{"t":"2. Timotheus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/1/#v55001005"}],"sources":[{"title":"Timotheus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004416"}]},{"id":"titus","name":"Titus","alt":[],"sex":"m","tags":["juenger"],"role":"Griechischer Mitarbeiter des Paulus","eras":["versammlung"],"dates":[],"year":49,"meaning":"","summary":"Titus war ein griechischer Christ, der eng mit Paulus zusammenarbeitete. Er begleitete Paulus und Barnabas anscheinend um 49 u. Z. nach Jerusalem, als die Beschneidungsfrage geklärt wurde, und musste sich nicht beschneiden lassen. Um 55 u. Z. half er der Versammlung in Korinth und brachte Paulus einen tröstenden Bericht. Später ließ Paulus ihn auf Kreta zurück, um ältere Männer zu ernennen; Paulus schrieb ihm einen Brief.","facts":[{"t":"Obwohl Grieche, wurde er nicht zur Beschneidung gezwungen.","r":{"t":"Galater 2:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/2/#v48002001-v48002003"}},{"t":"Seine Ankunft tröstete Paulus.","r":{"t":"2. Korinther 7:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-korinther/7/#v47007006"}},{"t":"Er half bei der Sammlung für die Brüder in Judäa.","r":{"t":"2. Korinther 8:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-korinther/8/#v47008006"}},{"t":"Er sollte auf Kreta ältere Männer einsetzen.","r":{"t":"Titus 1:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/titus/1/#v56001004"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["paulus","barnabas"],"events":["beschneidungsfrage"],"books":[],"refs":[{"t":"Galater 2:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/2/#v48002001-v48002003"},{"t":"2. Korinther 8:16-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-korinther/8/#v47008016-v47008023"},{"t":"Titus 1:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/titus/1/#v56001004"}],"sources":[{"title":"Titus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004431"}]},{"id":"uria","name":"Uria","alt":[],"sex":"m","tags":[],"role":"Der Hethiter, Krieger Davids","eras":["koenigreich"],"dates":[],"year":-1061,"meaning":"„Mein Licht ist Jehova“","summary":"Uria, ein Hethiter, gehörte zu Davids Kriegern und war mit Bathseba verheiratet; vermutlich hatte er die Anbetung Jehovas angenommen. Als David ihn aus dem Krieg holte, um seinen Ehebruch zu vertuschen, weigerte sich Uria, nach Hause zu gehen, solange das Heer im Feld war. David ließ ihn daraufhin an der gefährlichsten Stelle der Front sterben.","facts":[{"t":"Er gehörte zu Davids Kriegsleuten.","r":{"t":"2. Samuel 23:39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/23/#v10023039"}},{"t":"Er weigerte sich, heimzugehen, solange das Heer im Feld lag.","r":{"t":"2. Samuel 11:8-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011008-v10011011"}},{"t":"David ließ ihn im Kampf umkommen.","r":{"t":"2. Samuel 11:14-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011014-v10011017"}}],"lesson":"","family":{"father":"","mother":"","spouses":["batseba"],"children":[],"siblings":[]},"related":["david","joab"],"events":["david-und-batseba"],"books":[],"refs":[{"t":"2. Samuel 11:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011001-v10011027"}],"sources":[{"title":"Uria – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004521"}]},{"id":"usija","name":"Usija","alt":["Asarja"],"sex":"m","tags":["koenig","vorfahr-jesu"],"role":"König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"829–778 v. u. Z. (52 Jahre)"}],"year":-829,"meaning":"„Meine Stärke ist Jehova“","summary":"Usija, auch Asarja genannt, regierte 52 Jahre über Juda. Jesaja, Hosea, Amos und vielleicht Joel waren seine Zeitgenossen. Als er stark wurde, wurde er hochmütig: Er drang in den Tempel ein, um Räucherwerk darzubringen, was nur Priestern erlaubt war. Dabei wurde er mit Aussatz geschlagen und blieb bis zu seinem Tod aussätzig.","facts":[{"t":"Solange er Jehova suchte, ließ Gott ihn Gelingen haben.","r":{"t":"2. Chronika 26:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/26/#v14026004"}},{"t":"Er wollte im Tempel Räucherwerk darbringen.","r":{"t":"2. Chronika 26:16-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/26/#v14026016-v14026018"}},{"t":"Er wurde mit Aussatz geschlagen.","r":{"t":"2. Chronika 26:19-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/26/#v14026019-v14026021"}},{"t":"In seiner Regierungszeit gab es ein großes Erdbeben.","r":{"t":"Sacharja 14:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/14/#v38014005"}}],"lesson":"","family":{"father":"amazja","mother":"Jecholja","spouses":["Jeruscha"],"children":["jotham"],"siblings":[]},"related":["jesaja"],"events":["jesaja-wird-berufen"],"books":[],"refs":[{"t":"2. Chronika 26:1-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/26/#v14026001-v14026023"},{"t":"2. Könige 15:1-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/15/#v12015001-v12015007"}],"sources":[{"title":"Usija – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004535"}]},{"id":"zachaeus","name":"Zachäus","alt":[],"sex":"m","tags":["juenger"],"role":"Obersteuereinnehmer in Jericho","eras":["jesus"],"dates":[{"label":"Zeit","value":"Begegnung mit Jesus im Frühling 33 u. Z."}],"year":33,"meaning":"vielleicht von einer Wurzel, die „rein“ bedeutet","summary":"Zachäus war Obersteuereinnehmer in Jericho und reich geworden. Als Jesus im Frühling 33 u. Z. durch Jericho kam, stieg der kleine Mann auf einen Baum, um ihn zu sehen. Jesus kehrte bei ihm ein, obwohl die Leute murrten. Zachäus änderte seine Gesinnung: Er versprach, die Hälfte seines Besitzes den Armen zu geben und alles Erpresste vierfach zurückzuzahlen.","facts":[{"t":"Er stieg auf einen Maulbeerfeigenbaum, um Jesus zu sehen.","r":{"t":"Lukas 19:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/19/#v42019003"}},{"t":"Jesus sagte: „Heute muss ich in deinem Haus bleiben.“","r":{"t":"Lukas 19:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/19/#v42019005"}},{"t":"Er wollte Erpresstes vierfach erstatten.","r":{"t":"Lukas 19:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/19/#v42019008"}},{"t":"„Heute ist diesem Haus Rettung zuteilgeworden.“","r":{"t":"Lukas 19:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/19/#v42019009"}}],"lesson":"","family":{"father":"","mother":"","spouses":[],"children":[],"siblings":[]},"related":["jesus"],"events":[],"books":[],"refs":[{"t":"Lukas 19:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/19/#v42019001-v42019010"}],"sources":[{"title":"Zachäus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004650"}]},{"id":"zedekia","name":"Zedekia","alt":["Mattanja"],"sex":"m","tags":["koenig"],"role":"Letzter König von Juda","eras":["geteilt"],"dates":[{"label":"Regierung","value":"617–607 v. u. Z. (11 Jahre)"}],"year":-617,"meaning":"„Gerechtigkeit ist Jehova“","summary":"Zedekia, ursprünglich Mattanja, ein Sohn Josias, wurde von Nebukadnezar als abhängiger König eingesetzt und war der letzte König in der Linie Davids, der in Jerusalem regierte. Er tat fortgesetzt, was böse war, und hörte nicht auf Jeremia. Als er sich gegen Babylon auflehnte, wurde Jerusalem belagert und 607 v. u. Z. zerstört; Zedekia wurde geblendet und nach Babylon gebracht.","facts":[{"t":"Nebukadnezar änderte seinen Namen in Zedekia.","r":{"t":"2. Könige 24:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024017"}},{"t":"Er lieferte Jeremia den Fürsten aus.","r":{"t":"Jeremia 38:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/38/#v24038004"}},{"t":"Er lehnte sich gegen den König von Babylon auf.","r":{"t":"2. Könige 24:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024020"}},{"t":"Seine Söhne wurden vor seinen Augen getötet, dann wurde er geblendet.","r":{"t":"2. Könige 25:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/25/#v12025006"}}],"lesson":"","family":{"father":"josia","mother":"Hamutal","spouses":[],"children":[],"siblings":["joahas-juda","jojakim"]},"related":["jeremia","nebukadnezar","ebed-melech"],"events":["wegfuehrung-jojachins","zerstoerung-jerusalems-607"],"books":[],"refs":[{"t":"2. Könige 24:17–25:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024017-v12025007"},{"t":"Jeremia 38:14-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/38/#v24038014-v24038028"},{"t":"Hesekiel 21:25-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/21/#v26021025-v26021027"}],"sources":[{"title":"Zedekia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004685"},{"title":"A6-B Propheten und Könige von Juda und Israel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070215"}]},{"id":"zephanja","name":"Zephanja","alt":[],"sex":"m","tags":["prophet","schreiber"],"role":"Prophet zu Beginn der Herrschaft Josias","eras":["geteilt"],"dates":[{"label":"Zeit","value":"Buch vor 648 v. u. Z."}],"year":-650,"meaning":"„Verborgen (aufbewahrt) hat Jehova“","summary":"Zephanja war ein Prophet Jehovas in Juda zu Beginn der Herrschaft Josias und schrieb das gleichnamige Buch vor 648 v. u. Z. Er war anscheinend ein Ururenkel König Hiskias. Seine Verurteilung des Götzendienstes trug offenbar dazu bei, dass Josia das Land reinigte.","facts":[{"t":"Er war anscheinend ein Ururenkel Hiskias.","r":{"t":"Zephanja 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/zephanja/1/#v36001001"}},{"t":"Er verurteilte den Götzendienst in Juda.","r":{"t":"Zephanja 1:4-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/zephanja/1/#v36001004-v36001006"}},{"t":"„Sucht Jehova … vielleicht werdet ihr verborgen werden.“","r":{"t":"Zephanja 2:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/zephanja/2/#v36002003"}}],"lesson":"","family":{"father":"Kuschi","mother":"","spouses":[],"children":[],"siblings":[]},"related":["josia"],"events":["fall-ninives"],"books":["Zephanja"],"refs":[{"t":"Zephanja 1:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/zephanja/1/#v36001001-v36001006"},{"t":"Zephanja 2:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/zephanja/2/#v36002003"},{"t":"Zephanja 3:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/zephanja/3/#v36003009"}],"sources":[{"title":"Zephanja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004696"},{"title":"Josia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002525"}]},{"id":"zippora","name":"Zippora","alt":[],"sex":"f","tags":[],"role":"Frau von Moses","eras":["aegypten"],"dates":[],"year":-1560,"meaning":"„Vogel“ (vielleicht „Kleiner Vogel“)","summary":"Zippora, eine Tochter Jethros, lernte Moses an einem Brunnen in Midian kennen, als er ihr und ihren Schwestern gegen Hirten half und ihre Herde tränkte. Sie wurde seine Frau und gebar ihm zwei Söhne, Gerschom und Elieser. Auf dem Weg nach Ägypten beschnitt sie in einer gefährlichen Situation ihren Sohn.","facts":[{"t":"Moses half ihr und ihren Schwestern am Brunnen.","r":{"t":"2. Mose 2:16-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002016-v2002021"}},{"t":"Sie gebar Gerschom und Elieser.","r":{"t":"2. Mose 18:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/18/#v2018003"}},{"t":"Sie beschnitt ihren Sohn, als Gefahr drohte.","r":{"t":"2. Mose 4:24-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/4/#v2004024-v2004026"}}],"lesson":"","family":{"father":"jethro","mother":"","spouses":["moses"],"children":["Gerschom","Elieser"],"siblings":[]},"related":[],"events":["moses-flieht-nach-midian"],"books":[],"refs":[{"t":"2. Mose 2:16-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002016-v2002022"},{"t":"2. Mose 4:24-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/4/#v2004024-v2004026"},{"t":"2. Mose 18:2-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/18/#v2018002-v2018006"}],"sources":[{"title":"Zippora – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004748"}]}],"events":[{"id":"schoepfung","title":"Die Schöpfung","era":"anfaenge","year":-4100,"date":"„Im Anfang“ – Zeitpunkt unbekannt","place":"","summary":"„Im Anfang erschuf Gott die Himmel und die Erde.“ Danach bereitete Jehova die Erde in sechs Schöpfungstagen für das Leben vor. Diese „Tage“ waren keine 24-Stunden-Tage, sondern längere Zeitabschnitte; wie lang sie jeweils waren, sagt die Bibel nicht. Am sechsten Tag erschuf Gott den Menschen.","facts":[{"t":"Jehova ist der Schöpfer der Himmel und der Erde.","r":{"t":"1. Mose 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001001"}},{"t":"Jeder Schöpfungstag endete mit den Worten „Und es wurde Abend, und es wurde Morgen“.","r":{"t":"1. Mose 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001005"}},{"t":"Jeder Schöpfungstag dauerte länger als 24 Stunden."},{"t":"Am siebten Tag ruhte Gott von seinem Werk.","r":{"t":"1. Mose 2:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/2/#v1002001-v1002003"}}],"significance":"","persons":["jehova"],"refs":[{"t":"1. Mose 1:1–2:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001001-v1002003"}],"sources":[{"title":"Schöpfung – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001061"}]},{"id":"erschaffung-des-menschen","title":"Jehova erschafft Adam und Eva","era":"anfaenge","year":-4026,"date":"4026 v. u. Z.","place":"Eden","summary":"Als Krönung seiner irdischen Schöpfung bildete Jehova den ersten Menschen, Adam, aus dem Staub des Erdbodens und machte ihn zu einer lebenden Seele – wahrscheinlich im Herbst 4026 v. u. Z. Weil es nicht gut war, dass der Mensch allein blieb, bildete Gott aus einer Rippe Adams die Frau, Eva. Beide lebten im Garten Eden, einem Paradies.","facts":[{"t":"Der Mensch wurde „im Bilde Gottes“ erschaffen.","r":{"t":"1. Mose 1:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001027"}},{"t":"Jehova bildete Adam aus Staub; so wurde er eine lebende Seele.","r":{"t":"1. Mose 2:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/2/#v1002007"}},{"t":"Gott gab dem Paar den Auftrag, die Erde zu füllen.","r":{"t":"1. Mose 1:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001028"}},{"t":"Im Garten Eden wuchsen Bäume, die gut zur Speise waren.","r":{"t":"1. Mose 2:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/2/#v1002009"}}],"significance":"Die Bäume in Eden hätten Adam für immer am Leben erhalten können.","persons":["jehova","adam","eva"],"refs":[{"t":"1. Mose 1:26-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/1/#v1001026-v1001028"},{"t":"1. Mose 2:7-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/2/#v1002007-v1002025"}],"sources":[{"title":"Adam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000089"},{"title":"Eva – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001450"}]},{"id":"suendenfall","title":"Rebellion in Eden","era":"anfaenge","year":-4025,"date":"Kurz nach der Erschaffung des Menschen","place":"Eden","summary":"Satan sprach durch eine Schlange zu Eva und stellte Gottes Gebot infrage. Eva ließ sich täuschen, aß von dem Baum der Erkenntnis von Gut und Böse und veranlasste Adam, ebenfalls davon zu essen. Dadurch kamen Sünde und Tod über alle Menschen. Zugleich sagte Jehova einen „Nachkommen“ voraus, der die Schlange schließlich zermalmen würde.","facts":[{"t":"Die Schlange war das Sprachrohr eines unsichtbaren Geistgeschöpfes.","r":{"t":"1. Mose 3:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003001-v1003005"}},{"t":"Eva wurde getäuscht; Adam hörte auf die Stimme seiner Frau.","r":{"t":"1. Timotheus 2:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-timotheus/2/#v54002014"}},{"t":"Gott verkündete das Urteil: Mühsal, Schmerzen und die Rückkehr zum Staub.","r":{"t":"1. Mose 3:16-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003016-v1003019"}},{"t":"Erste Prophezeiung: Der „Nachkomme“ der Frau würde der Schlange den Kopf zermalmen.","r":{"t":"1. Mose 3:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003015"}},{"t":"Durch einen Menschen kam die Sünde in die Welt und durch die Sünde der Tod.","r":{"t":"Römer 5:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/5/#v45005012"}}],"significance":"Mit der Ankündigung des „Nachkommen“ beginnt das Hauptthema der Bibel.","persons":["adam","eva","satan","jehova"],"refs":[{"t":"1. Mose 3:1-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003001-v1003024"}],"sources":[{"title":"Eva – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001450"},{"title":"B1 Das Hauptthema der Bibel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070221"}]},{"id":"kain-und-abel","title":"Kain tötet Abel","era":"anfaenge","year":-4000,"date":"Zeitpunkt unbekannt","place":"","summary":"Kain und Abel, die Söhne Adams und Evas, brachten Jehova Opfer dar – Kain von seinem Ernteertrag, Abel von den Erstlingen seiner Herde. Gott nahm Abels Opfer wohlwollend an, das Kains jedoch nicht. Statt sich zu ändern, erschlug Kain seinen Bruder. Daraufhin wurde er vom Erdboden verbannt.","facts":[{"t":"Abels Opfer war wegen seines Glaubens „wertvoller“.","r":{"t":"Hebräer 11:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011004"}},{"t":"Gott warnte Kain vor der Sünde, die auf ihn lauerte.","r":{"t":"1. Mose 4:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004006"}},{"t":"Kain erschlug Abel auf dem Feld.","r":{"t":"1. Mose 4:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004008"}},{"t":"Kain wurde verbannt; der Boden sollte ihm kaum noch Ertrag bringen.","r":{"t":"1. Mose 4:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004011"}}],"significance":"","persons":["kain","abel","jehova"],"refs":[{"t":"1. Mose 4:1-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/4/#v1004001-v1004016"},{"t":"1. Johannes 3:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-johannes/3/#v62003011"}],"sources":[{"title":"Kain – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000857"},{"title":"Abel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000018"}]},{"id":"henoch-wandelt-mit-gott","title":"Henoch wandelt mit Gott","era":"anfaenge","year":-3100,"date":"Vor der Sintflut","place":"","summary":"Henoch, der Siebte in der Linie von Adam her, wandelte beständig mit dem wahren Gott, während die meisten Menschen gottlos lebten. Als Prophet kündigte er Gottes Gericht über die Gottlosen an und wurde deshalb wahrscheinlich verfolgt. Gott ließ nicht zu, dass ihn seine Feinde töteten, sondern „nahm ihn hinweg“.","facts":[{"t":"Er prophezeite, dass Gott mit seinen heiligen Myriaden Gericht halten werde.","r":{"t":"Judas 14-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001014-v65001015"}},{"t":"Gott verkürzte sein Leben auf 365 Jahre.","r":{"t":"1. Mose 5:23, 24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005023"}},{"t":"Er gehört zu den Vorbildern des Glaubens.","r":{"t":"Hebräer 11:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011005"}}],"significance":"","persons":["henoch"],"refs":[{"t":"1. Mose 5:21-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005021-v1005024"},{"t":"Hebräer 11:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011005"},{"t":"Judas 14-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001014-v65001015"}],"sources":[{"title":"Henoch – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001371"}]},{"id":"tod-adams","title":"Adam stirbt","era":"anfaenge","year":-3096,"date":"3096 v. u. Z.","place":"","summary":"Adam starb im Alter von 930 Jahren. Wie Gott angekündigt hatte, kehrte er zum Staub zurück, aus dem er genommen war. Er erlebte noch Lamech, den Vater Noahs, als Zeitgenossen. Durch seinen Ungehorsam hatte er Sünde und Tod an alle seine Nachkommen weitergegeben.","facts":[{"t":"Adam wurde 930 Jahre alt.","r":{"t":"1. Mose 5:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005005"}},{"t":"Gottes Urteil lautete: Zum Staub wirst du zurückkehren.","r":{"t":"1. Mose 3:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/3/#v1003019"}},{"t":"Durch ihn kam der Tod auf alle Menschen.","r":{"t":"Römer 5:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/R%C3%B6mer/5/#v45005012"}}],"significance":"","persons":["adam"],"refs":[{"t":"1. Mose 5:3-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/5/#v1005003-v1005005"}],"sources":[{"title":"Adam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000089"}]},{"id":"nephilim","title":"Ungehorsame Engel und die Nephilim","era":"anfaenge","year":-2500,"date":"Vor der Sintflut","place":"","summary":"In den Tagen Noahs verließen Engel ihre ursprüngliche Stellung und ihre rechte Wohnstätte, heirateten Frauen und zeugten Nachkommen, die Nephilim. Diese „Männer von Ruhm“ schürten die Gewalttat auf der ganzen Erde. Die Menschen waren so verdorben, dass jede Neigung ihres Herzens nur schlecht war.","facts":[{"t":"„Nephilim“ bedeutet „Fäller“ oder „die zu Fall Bringenden“.","r":{"t":"1. Mose 6:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006004"}},{"t":"Die ungehorsamen Engel verließen ihre rechte Wohnstätte.","r":{"t":"Judas 6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001006"}},{"t":"Die Erde war verderbt und voll Gewalttat.","r":{"t":"1. Mose 6:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006011"}}],"significance":"","persons":[],"refs":[{"t":"1. Mose 6:1-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006001-v1006007"},{"t":"Judas 6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001006"}],"sources":[{"title":"Nephilim – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003223"},{"title":"Noah – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003266"}]},{"id":"bau-der-arche","title":"Noah baut die Arche","era":"anfaenge","year":-2420,"date":"Etwa 40–50 Jahre vor der Sintflut","place":"","summary":"Gott kündigte an, die gewalttätige Welt durch eine Flut zu vernichten, schloss einen Bund mit Noah und beauftragte ihn, eine Arche zu bauen. Unterstützt von seiner Familie machte sich Noah an das gewaltige Werk und warnte zugleich als „Prediger der Gerechtigkeit“ seine Zeitgenossen. Er tat genau das, was Gott ihm geboten hatte.","facts":[{"t":"Gott setzte der damaligen Welt eine Frist von 120 Jahren.","r":{"t":"1. Mose 6:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006003"}},{"t":"Als Noahs Söhne erwachsen und verheiratet waren, erhielt er den Auftrag zum Bau.","r":{"t":"1. Mose 6:13-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006013-v1006018"}},{"t":"Noah tat alles, was Gott geboten hatte.","r":{"t":"1. Mose 6:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006022"}},{"t":"Durch seinen Glauben verurteilte er die damalige Welt.","r":{"t":"Hebräer 11:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011007"}}],"significance":"","persons":["noah","sem","ham","japhet"],"refs":[{"t":"1. Mose 6:9-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/6/#v1006009-v1006022"},{"t":"Hebräer 11:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011007"},{"t":"2. Petrus 2:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-petrus/2/#v61002005"}],"sources":[{"title":"Noah – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003266"},{"title":"Arche – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000367"}]},{"id":"sintflut","title":"Die Sintflut","era":"anfaenge","year":-2370,"date":"2370 v. u. Z.","place":"Weltweit; die Arche landete auf den Bergen von Ararat","summary":"Weil die Erde voll Gewalttat war, vernichtete Jehova die damalige Welt durch eine gewaltige Flut – die größte Überschwemmung der Geschichte. Nur der gerechte Noah und seine Familie, insgesamt acht Menschen, überlebten mit den Tieren in der Arche. Die Flut dauerte über ein Jahr; etwa fünf Monate nach Beginn des Regens setzte die Arche auf den Bergen von Ararat auf.","facts":[{"t":"Es war keine örtliche Überschwemmung, sondern eine weltweite Katastrophe.","r":{"t":"Lukas 17:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/17/#v42017027"}},{"t":"Nur acht Menschen überlebten.","r":{"t":"1. Petrus 3:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-petrus/3/#v60003020"}},{"t":"Die Arche ruhte auf den Bergen von Ararat.","r":{"t":"1. Mose 8:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/8/#v1008004"}},{"t":"Das Sinken des Wassers dauerte am längsten; insgesamt dauerte die Flut über ein Jahr.","r":{"t":"1. Mose 8:13, 14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/8/#v1008013"}}],"significance":"","persons":["noah","sem","ham","japhet"],"refs":[{"t":"1. Mose 7:1–8:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/7/#v1007001-v1008019"},{"t":"Matthäus 24:37-39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/24/#v40024037-v40024039"},{"t":"2. Petrus 3:5-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-petrus/3/#v61003005-v61003007"}],"sources":[{"title":"Sintflut – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001150"}]},{"id":"regenbogenbund","title":"Gottes Bund mit Noah","era":"anfaenge","year":-2369,"date":"Nach der Sintflut","place":"","summary":"Nachdem Noah und seine Familie die Arche verlassen hatten, opferte Noah Jehova. Gott gab neue Verordnungen und schloss einen Bund mit ihnen, mit ihren Nachkommen und mit allen Lebewesen: Nie mehr sollte eine Sintflut alles Leben vernichten. Das Zeichen dieses Bundes ist der Regenbogen.","facts":[{"t":"Noah baute einen Altar und brachte Jehova Opfer dar.","r":{"t":"1. Mose 8:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/8/#v1008020"}},{"t":"Gott erlaubte, Tierfleisch zu essen – Blut aber sollte nicht gegessen werden.","r":{"t":"1. Mose 9:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009003"}},{"t":"Der Regenbogen ist das Zeichen der Bundesverheißung.","r":{"t":"1. Mose 9:11-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/9/#v1009011-v1009016"}}],"significance":"","persons":["noah","jehova"],"refs":[{"t":"1. Mose 8:18–9:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/8/#v1008018-v1009017"}],"sources":[{"title":"Regenbogen – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003626"},{"title":"Noah – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003266"}]},{"id":"turmbau-zu-babel","title":"Der Turmbau zu Babel","era":"patriarchen","year":-2260,"date":"In den Tagen Pelegs (2269–2030 v. u. Z.)","place":"Babel im Land Schinar","summary":"Nach der Sintflut begannen Menschen in Babel eine Stadt und einen Turm zu bauen, dessen Spitze bis in die Himmel reichen sollte, um sich „einen berühmten Namen“ zu machen – statt, wie Gott geboten hatte, die Erde zu füllen. Der Turm war einer von Menschen erdachten Religion geweiht. Jehova verwirrte ihre Sprache und zerstreute sie über die ganze Erde.","facts":[{"t":"Die Erbauer wollten sich einen berühmten Namen machen.","r":{"t":"1. Mose 11:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011004"}},{"t":"Jehova verwirrte ihre Sprache.","r":{"t":"1. Mose 11:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011007"}},{"t":"„In den Tagen Pelegs“ wurde die Erdbevölkerung geteilt.","r":{"t":"1. Mose 10:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/10/#v1010025"}}],"significance":"","persons":[],"refs":[{"t":"1. Mose 11:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011001-v1011009"}],"sources":[{"title":"Babel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000529"},{"title":"Noah – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003266"}]},{"id":"geburt-abrams","title":"Abram wird geboren","era":"patriarchen","year":-2018,"date":"2018 v. u. Z.","place":"Ur in Chaldäa","summary":"Abram, der spätere Abraham, wurde 352 Jahre nach der Sintflut geboren; sein Vater Terach war damals 130 Jahre alt. Er wuchs in Ur auf, einer blühenden Stadt im Land Schinar, die dem Kult des Mondgottes Sin ergeben war. Abram dagegen glaubte wie Sem und Noah an Jehova.","facts":[{"t":"Er war der Zehnte in der Linie von Noah über Sem.","r":{"t":"1. Mose 11:10-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011010-v1011026"}},{"t":"Terach war 130 Jahre alt, als Abram geboren wurde.","r":{"t":"1. Mose 11:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011032"}},{"t":"Ur lag etwa 240 km südöstlich von Babel."}],"significance":"","persons":["abraham","terach"],"refs":[{"t":"1. Mose 11:26-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/11/#v1011026-v1011028"}],"sources":[{"title":"Abraham – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000060"}]},{"id":"abrahamischer-bund","title":"Der Bund mit Abraham tritt in Kraft","era":"patriarchen","year":-1943,"date":"1943 v. u. Z.","place":"Euphrat; Land Kanaan","summary":"Nach dem Tod Terachs zog Abraham mit 75 Jahren aus Haran fort und überquerte den Euphrat – offenbar am 14. Tag des Monats, der später Nisan hieß. Damit trat der Bund in Kraft, den Jehova mit ihm geschlossen hatte. Mit diesem Zeitpunkt begannen die 430 Jahre, die bis zum Auszug Israels aus Ägypten 1513 v. u. Z. reichten.","facts":[{"t":"Abraham war damals 75 Jahre alt.","r":{"t":"1. Mose 12:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/12/#v1012004"}},{"t":"Gott versprach, ihn zu einer großen Nation zu machen.","r":{"t":"1. Mose 12:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/12/#v1012001-v1012003"}},{"t":"Der angekündigte „Nachkomme“ sollte von Abraham abstammen.","r":{"t":"1. Mose 22:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/22/#v1022018"}},{"t":"Von hier an zählen die 430 Jahre bis zum Gesetzesbund.","r":{"t":"Galater 3:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/3/#v48003017"}}],"significance":"Jehova machte deutlich, dass der verheißene „Nachkomme“ aus Abrahams Familie kommen würde.","persons":["abraham","sara","lot"],"refs":[{"t":"1. Mose 12:1-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/12/#v1012001-v1012007"},{"t":"Galater 3:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/3/#v48003016"}],"sources":[{"title":"Abraham – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000060"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"B1 Das Hauptthema der Bibel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070221"}]},{"id":"melchisedek-segnet-abram","title":"Melchisedek segnet Abram","era":"patriarchen","year":-1934,"date":"vor 1933 v. u. Z.","place":"Tiefebene Schawe („Tiefebene des Königs“)","summary":"Kedorlaomer und verbündete Könige hatten Lot verschleppt. Abram verfolgte sie mit seinen Männern, besiegte sie und befreite seinen Neffen. Auf dem Rückweg kam ihm Melchisedek, König von Salem und Priester Gottes, des Höchsten, entgegen, brachte Brot und Wein heraus und segnete ihn. Abram gab ihm den Zehnten.","facts":[{"t":"Abram befreite seinen Neffen Lot.","r":{"t":"1. Mose 14:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/14/#v1014014-v1014016"}},{"t":"Melchisedek segnete Abram im Namen Gottes, des Höchsten.","r":{"t":"1. Mose 14:19, 20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/14/#v1014019"}},{"t":"Abram gab ihm ein Zehntel von allem.","r":{"t":"1. Mose 14:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/14/#v1014020"}},{"t":"Paulus erklärt im Hebräerbrief die Bedeutung dieser Begegnung.","r":{"t":"Hebräer 7:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/7/#v58007001-v58007010"}}],"significance":"","persons":["abraham","melchisedek","lot"],"refs":[{"t":"1. Mose 14:1-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/14/#v1014001-v1014024"},{"t":"Hebräer 7:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/7/#v58007001-v58007010"}],"sources":[{"title":"Melchisedek – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002970"}]},{"id":"sodom-und-gomorra","title":"Untergang von Sodom und Gomorra","era":"patriarchen","year":-1919,"date":"um 1919 v. u. Z.","place":"Bezirk des Jordan","summary":"Die Sünde Sodoms und Gomorras war sehr schwer. Gott sandte Engel und versicherte Abraham, die Stadt um zehn Gerechter willen zu verschonen – so viele gab es dort nicht. Die Engel führten Lot, seine Frau und seine Töchter hinaus; dann vernichtete Jehova die Städte durch Feuer. Lots Frau schaute sich um und wurde zu einer Salzsäule.","facts":[{"t":"Abraham setzte sich bei Jehova für die Gerechten in Sodom ein.","r":{"t":"1. Mose 18:20-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/18/#v1018020-v1018033"}},{"t":"Lot floh mit seinen Töchtern nach Zoar.","r":{"t":"1. Mose 19:22, 23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/19/#v1019022"}},{"t":"Jehova vernichtete die Städte durch Feuer.","r":{"t":"1. Mose 19:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/19/#v1019024"}},{"t":"Sodom und Gomorra dienen als warnendes Beispiel.","r":{"t":"Judas 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001007"}}],"significance":"","persons":["lot","lots-frau","abraham"],"refs":[{"t":"1. Mose 18:16–19:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/18/#v1018016-v1019029"},{"t":"2. Petrus 2:6-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-petrus/2/#v61002006-v61002008"},{"t":"Judas 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/judas/1/#v65001007"}],"sources":[{"title":"Sodom – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004176"},{"title":"Lot – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002776"}]},{"id":"geburt-isaaks","title":"Isaak wird geboren","era":"patriarchen","year":-1918,"date":"1918 v. u. Z.","place":"","summary":"Abraham war 100 und Sara 90 Jahre alt, als sich Gottes Verheißung erfüllte und Sara einen Sohn gebar. Er wurde Isaak („Lachen“) genannt, denn beide hatten gelacht, als sie von der Verheißung hörten, und Sara sagte: „Gott hat mir ein Lachen bereitet.“ Am achten Tag wurde Isaak beschnitten.","facts":[{"t":"Gott hatte die Geburt ein Jahr zuvor angekündigt.","r":{"t":"1. Mose 18:10-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/18/#v1018010-v1018014"}},{"t":"Für Jehova ist nichts zu außergewöhnlich.","r":{"t":"1. Mose 18:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/18/#v1018014"}},{"t":"Isaak sollte der Erbe des Bundes sein.","r":{"t":"1. Mose 17:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/17/#v1017019"}},{"t":"Er wurde am achten Tag beschnitten.","r":{"t":"1. Mose 21:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021004"}}],"significance":"","persons":["isaak","abraham","sara"],"refs":[{"t":"1. Mose 21:1-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021001-v1021007"}],"sources":[{"title":"Isaak – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002203"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"hagar-und-ismael","title":"Hagar und Ismael werden weggeschickt","era":"patriarchen","year":-1913,"date":"1913 v. u. Z.","place":"","summary":"Am Tag, an dem Isaak entwöhnt wurde, verspottete Ismael seinen fünf Jahre alten Halbbruder. Sara bestand darauf, dass der Sohn der Sklavin nicht mit Isaak erben sollte, und Gott billigte, dass Abraham Hagar und Ismael wegschickte. Mit diesem Jahr begannen die 400 Jahre der Bedrückung der Nachkommen Abrahams, die 1513 v. u. Z. endeten.","facts":[{"t":"Ismael „spottlachte“ über Isaak.","r":{"t":"1. Mose 21:8, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021008"}},{"t":"Gott sagte Abraham, er solle auf Sara hören.","r":{"t":"1. Mose 21:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021012"}},{"t":"In der Wildnis rettete Gott Hagar und Ismael.","r":{"t":"1. Mose 21:17-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021017-v1021019"}},{"t":"Paulus beschreibt Ismaels Verhalten als Verfolgung.","r":{"t":"Galater 4:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/4/#v48004029"}}],"significance":"Die vorhergesagten 400 Jahre der Bedrückung (1913–1513 v. u. Z.) begannen hier.","persons":["hagar","ismael","isaak","sara","abraham"],"refs":[{"t":"1. Mose 21:8-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/21/#v1021008-v1021021"},{"t":"Apostelgeschichte 7:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/7/#v44007006"},{"t":"Galater 4:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/4/#v48004029"}],"sources":[{"title":"Ismael – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002215"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"opferung-isaaks","title":"Abraham ist bereit, Isaak zu opfern","era":"patriarchen","year":-1893,"date":"um 1893 v. u. Z.","place":"Berg Moria","summary":"Die größte Prüfung für Abrahams Glauben: Jehova forderte ihn auf, seinen Sohn Isaak auf einem Berg im Land Moria als Brandopfer darzubringen. Abraham gehorchte, denn er rechnete damit, dass Gott Isaak sogar von den Toten auferwecken könnte. Im letzten Augenblick hielt Jehova ihn zurück und sorgte für einen Widder. Danach bekräftigte er seinen Bund mit Abraham durch einen Eid.","facts":[{"t":"Isaak war damals etwa 25 Jahre alt."},{"t":"Abraham zog von Beerscheba zum Berg Moria.","r":{"t":"1. Mose 22:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/22/#v1022002-v1022004"}},{"t":"Er vertraute darauf, dass Gott Isaak auferwecken könnte.","r":{"t":"Hebräer 11:17-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011017-v58011019"}},{"t":"Gott bekräftigte den Bund durch einen Eid.","r":{"t":"1. Mose 22:15-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/22/#v1022015-v1022018"}}],"significance":"","persons":["abraham","isaak"],"refs":[{"t":"1. Mose 22:1-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/22/#v1022001-v1022018"},{"t":"Hebräer 11:17-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011017-v58011019"},{"t":"Jakobus 2:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jakobus/2/#v59002021"}],"sources":[{"title":"Abraham – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000060"},{"title":"Isaak – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002203"}]},{"id":"isaak-heiratet-rebekka","title":"Isaak heiratet Rebekka","era":"patriarchen","year":-1878,"date":"1878 v. u. Z.","place":"Mesopotamien; Negeb","summary":"Abraham sandte seinen Hausverwalter nach Mesopotamien, um unter seinen Verwandten eine Frau für Isaak zu finden. Am Brunnen erwies sich Rebekka als gütig und fleißig – sie tränkte sogar die zehn Kamele des Dieners, genau wie dieser es im Gebet erbeten hatte. Ihre Familie stimmte zu, und Rebekka ging mit, um Isaaks Frau zu werden.","facts":[{"t":"Isaak war damals 40 Jahre alt.","r":{"t":"1. Mose 25:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025020"}},{"t":"Der Diener bat Jehova im Gebet um Leitung.","r":{"t":"1. Mose 24:12-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024012-v1024014"}},{"t":"Rebekka willigte selbst ein, mitzugehen.","r":{"t":"1. Mose 24:58","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024058"}},{"t":"Isaak liebte Rebekka und fand nach dem Tod seiner Mutter Trost.","r":{"t":"1. Mose 24:67","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024067"}}],"significance":"","persons":["isaak","rebekka","abraham","laban"],"refs":[{"t":"1. Mose 24:1-67","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/24/#v1024001-v1024067"}],"sources":[{"title":"Rebekka – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003658"}]},{"id":"tod-abrahams","title":"Abraham stirbt","era":"patriarchen","year":-1843,"date":"1843 v. u. Z.","place":"Höhle von Machpela","summary":"Abraham starb im hohen Alter von 175 Jahren. Seine Söhne Isaak und Ismael begruben ihn in der Höhle von Machpela, wo bereits Sara begraben lag. Zuvor hatte er Isaak alles übergeben, was er besaß, und die Söhne seiner Nebenfrauen mit Geschenken fortgeschickt.","facts":[{"t":"Abraham wurde 175 Jahre alt.","r":{"t":"1. Mose 25:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025007"}},{"t":"Isaak erbte alles, was Abraham besaß.","r":{"t":"1. Mose 25:5, 6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025005"}},{"t":"Er wurde in der Höhle von Machpela begraben.","r":{"t":"1. Mose 25:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025009"}}],"significance":"","persons":["abraham","isaak","ismael"],"refs":[{"t":"1. Mose 25:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025001-v1025011"}],"sources":[{"title":"Abraham – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000060"}]},{"id":"esau-verkauft-erstgeburtsrecht","title":"Esau verkauft sein Erstgeburtsrecht","era":"patriarchen","year":-1835,"date":"Nach 1843 v. u. Z.","place":"","summary":"Als Esau erschöpft und hungrig vom Feld kam, bat er Jakob um etwas von dessen rotem Gericht. Jakob verlangte dafür das Erstgeburtsrecht, und Esau verkaufte es ihm mit einem Schwur für ein Linsengericht und etwas Brot. Damit zeigte er, dass er die heiligen Verheißungen, die Gott Abraham gegeben hatte, gering schätzte.","facts":[{"t":"Das Erstgeburtsrecht war mit den Verheißungen an Abraham verbunden."},{"t":"Esau verkaufte es durch einen Schwur.","r":{"t":"1. Mose 25:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025033"}},{"t":"So verachtete er das Erstgeburtsrecht.","r":{"t":"1. Mose 25:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025034"}},{"t":"Die Bibel warnt davor, heilige Dinge so gering zu schätzen wie Esau.","r":{"t":"Hebräer 12:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/12/#v58012016"}}],"significance":"","persons":["esau","jakob","isaak"],"refs":[{"t":"1. Mose 25:27-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025027-v1025034"},{"t":"Hebräer 12:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/12/#v58012016"}],"sources":[{"title":"Esau – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001417"},{"title":"Jakob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002279"}]},{"id":"jakob-erhaelt-den-segen","title":"Jakob erhält den Segen","era":"patriarchen","year":-1782,"date":"um 1781 v. u. Z.","place":"","summary":"Der alte Isaak wollte seinen älteren Sohn Esau segnen. Auf Rebekkas Rat gab sich Jakob als Esau aus und erhielt den Segen des Erstgeborenen. Als Esau zurückkam, war der Segen bereits gegeben – und Isaak bestätigte ihn. Weil Esau ihn töten wollte, floh Jakob nach Haran.","facts":[{"t":"Jehova hatte vorhergesagt, dass der Ältere dem Jüngeren dienen werde.","r":{"t":"1. Mose 25:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/25/#v1025023"}},{"t":"Rebekka half Jakob, den Segen zu erhalten.","r":{"t":"1. Mose 27:5-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/27/#v1027005-v1027017"}},{"t":"Isaak bestätigte den Segen für Jakob.","r":{"t":"1. Mose 27:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/27/#v1027033"}},{"t":"Esau hasste Jakob und wollte ihn töten.","r":{"t":"1. Mose 27:41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/27/#v1027041"}}],"significance":"","persons":["isaak","rebekka","jakob","esau"],"refs":[{"t":"1. Mose 27:1-45","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/27/#v1027001-v1027045"}],"sources":[{"title":"Esau – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001417"},{"title":"Rahel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003621"}]},{"id":"jakobs-traum","title":"Jakobs Traum in Bethel","era":"patriarchen","year":-1781,"date":"1781 v. u. Z.","place":"Bethel","summary":"Auf der Flucht nach Haran übernachtete Jakob unter freiem Himmel, einen Stein als Kopfstütze. Im Traum sah er eine Leiter (oder Treppe), die bis an den Himmel reichte und auf der Engel auf- und niederstiegen. Jehova bestätigte ihm die Verheißungen, die er Abraham gegeben hatte. Jakob nannte den Ort Bethel („Haus Gottes“).","facts":[{"t":"Jakob sah Engel auf einer Leiter auf- und niedersteigen.","r":{"t":"1. Mose 28:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/28/#v1028012"}},{"t":"Jehova bestätigte ihm den abrahamischen Bund.","r":{"t":"1. Mose 28:13-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/28/#v1028013-v1028015"}},{"t":"Jakob stellte eine Säule auf und nannte den Ort Bethel.","r":{"t":"1. Mose 28:18, 19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/28/#v1028018"}}],"significance":"","persons":["jakob"],"refs":[{"t":"1. Mose 28:10-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/28/#v1028010-v1028022"}],"sources":[{"title":"Jakob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002279"},{"title":"Bethel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000682"}]},{"id":"jakob-heiratet","title":"Jakob heiratet Lea und Rahel","era":"patriarchen","year":-1774,"date":"um 1774 v. u. Z.","place":"Haran (Paddan-Aram)","summary":"Jakob diente seinem Onkel Laban sieben Jahre, um Rahel heiraten zu dürfen. In der Hochzeitsnacht gab Laban ihm jedoch Lea. Jakob vollendete die Hochzeitswoche mit Lea, erhielt danach auch Rahel und arbeitete dafür weitere sieben Jahre.","facts":[{"t":"Die sieben Jahre kamen Jakob wie wenige Tage vor.","r":{"t":"1. Mose 29:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029020"}},{"t":"Laban berief sich auf einen örtlichen Brauch.","r":{"t":"1. Mose 29:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029026"}},{"t":"Jakob liebte Rahel mehr als Lea.","r":{"t":"1. Mose 29:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029030"}}],"significance":"","persons":["jakob","lea","rahel","laban"],"refs":[{"t":"1. Mose 29:15-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/29/#v1029015-v1029030"}],"sources":[{"title":"Rahel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003621"},{"title":"Lea – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002702"}]},{"id":"jakob-ringt-mit-engel","title":"Jakob ringt mit einem Engel","era":"patriarchen","year":-1761,"date":"um 1761 v. u. Z.","place":"Am Jabbok","summary":"Nach 20 Jahren bei Laban kehrte Jakob mit seiner Familie nach Kanaan zurück. In der Nacht, bevor er seinem Bruder Esau begegnete, rang er am Jabbok mit einem Engel. Wegen seiner Beharrlichkeit erhielt er einen neuen Namen: Israel. Am nächsten Tag empfing ihn Esau freundlich.","facts":[{"t":"Jakob hatte 20 Jahre bei Laban gedient.","r":{"t":"1. Mose 31:41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/31/#v1031041"}},{"t":"Er ließ den Engel nicht los, bevor dieser ihn segnete.","r":{"t":"1. Mose 32:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/32/#v1032026"}},{"t":"„Israel“ bedeutet „Streiter mit Gott“ oder „Gott streitet“.","r":{"t":"1. Mose 32:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/32/#v1032028"}},{"t":"Esau lief ihm entgegen und umarmte ihn.","r":{"t":"1. Mose 33:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/33/#v1033004"}}],"significance":"","persons":["jakob","esau"],"refs":[{"t":"1. Mose 32:22-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/32/#v1032022-v1032032"},{"t":"1. Mose 33:1-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/33/#v1033001-v1033017"},{"t":"Hosea 12:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hosea/12/#v28012003"}],"sources":[{"title":"Jakob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002279"}]},{"id":"joseph-wird-verkauft","title":"Joseph wird nach Ägypten verkauft","era":"patriarchen","year":-1750,"date":"um 1750 v. u. Z.","place":"Dothan; Ägypten","summary":"Josephs Halbbrüder hassten ihn, weil ihr Vater ihn bevorzugte und weil er Träume von einer künftigen Vorrangstellung erzählte. Als Jakob ihn zu ihnen schickte, wollten sie ihn töten. Auf Rubens Rat warfen sie ihn in eine leere Zisterne, und auf Judas Vorschlag verkauften sie ihn für 20 Silberstücke an Kaufleute. In Ägypten kaufte ihn Potiphar.","facts":[{"t":"Joseph war 17 Jahre alt.","r":{"t":"1. Mose 37:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037002"}},{"t":"Ruben verhinderte, dass sie ihn töteten.","r":{"t":"1. Mose 37:21, 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037021"}},{"t":"Sie verkauften ihn für 20 Silberstücke.","r":{"t":"1. Mose 37:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037028"}},{"t":"Jakob glaubte, ein wildes Tier habe Joseph getötet.","r":{"t":"1. Mose 37:31-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037031-v1037035"}}],"significance":"","persons":["joseph","ruben","juda","jakob","potiphar","simeon","levi"],"refs":[{"t":"1. Mose 37:12-36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/37/#v1037012-v1037036"}],"sources":[{"title":"Joseph – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002515"},{"title":"Juda – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002538"}]},{"id":"joseph-wird-verwalter","title":"Joseph wird Verwalter Ägyptens","era":"patriarchen","year":-1737,"date":"1737 v. u. Z.","place":"Ägypten","summary":"Nach Jahren als Sklave und Gefangener wurde Joseph vor Pharao gerufen, um dessen Träume zu deuten. Mit Gottes Hilfe kündigte er sieben Jahre des Überflusses und sieben Jahre der Hungersnot an und riet, Vorräte anzulegen. Pharao setzte den 30-Jährigen über ganz Ägypten.","facts":[{"t":"Im Gefängnis deutete er die Träume des Mundschenks und des Bäckers.","r":{"t":"1. Mose 40:1-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/40/#v1040001-v1040023"}},{"t":"Er sagte, nicht er, sondern Gott werde die Deutung geben.","r":{"t":"1. Mose 41:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/41/#v1041016"}},{"t":"Er war 30 Jahre alt, als er vor Pharao stand.","r":{"t":"1. Mose 41:46","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/41/#v1041046"}},{"t":"In den sieben guten Jahren sammelte er Getreide.","r":{"t":"1. Mose 41:47-49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/41/#v1041047-v1041049"}}],"significance":"","persons":["joseph"],"refs":[{"t":"1. Mose 41:1-57","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/41/#v1041001-v1041057"}],"sources":[{"title":"Joseph – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002515"},{"title":"Isaak – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002203"}]},{"id":"joseph-gibt-sich-zu-erkennen","title":"Joseph gibt sich seinen Brüdern zu erkennen","era":"patriarchen","year":-1729,"date":"Im 2. Jahr der Hungersnot","place":"Ägypten","summary":"Wegen der Hungersnot kamen Josephs Brüder nach Ägypten, um Getreide zu kaufen, und verneigten sich vor ihm, ohne ihn zu erkennen. Joseph prüfte, ob sie sich geändert hatten. Als Juda sich anbot, an Benjamins Stelle Sklave zu werden, gab sich Joseph unter Tränen zu erkennen und vergab ihnen.","facts":[{"t":"Die Brüder erkannten Joseph nicht.","r":{"t":"1. Mose 42:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/42/#v1042008"}},{"t":"Joseph behielt Simeon als Geisel zurück.","r":{"t":"1. Mose 42:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/42/#v1042024"}},{"t":"Juda bot sich an Benjamins Stelle an.","r":{"t":"1. Mose 44:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/44/#v1044033"}},{"t":"Joseph erkannte, dass Gott ihn vorausgesandt hatte, um Leben zu erhalten.","r":{"t":"1. Mose 45:5-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/45/#v1045005-v1045008"}}],"significance":"","persons":["joseph","juda","benjamin","simeon"],"refs":[{"t":"1. Mose 42:1–45:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/42/#v1042001-v1045015"}],"sources":[{"title":"Juda – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002538"},{"title":"Simeon – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004124"}]},{"id":"jakob-zieht-nach-aegypten","title":"Jakob zieht nach Ägypten","era":"patriarchen","year":-1728,"date":"1728 v. u. Z.","place":"Gosen in Ägypten","summary":"Auf Josephs Einladung zog Jakob mit seiner ganzen Familie nach Ägypten. Gott sicherte ihm zu, dort eine große Nation aus ihm zu machen. Bald nach der Ankunft wurde der 130-jährige Jakob zu Pharao gebracht und segnete ihn; die Familie ließ sich im Land Gosen nieder.","facts":[{"t":"Gott ermutigte Jakob, nach Ägypten zu ziehen.","r":{"t":"1. Mose 46:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/46/#v1046002-v1046004"}},{"t":"Jakob war damals 130 Jahre alt.","r":{"t":"1. Mose 47:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/47/#v1047009"}},{"t":"Er segnete Pharao.","r":{"t":"1. Mose 47:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/47/#v1047007"}},{"t":"Israel wohnte danach 215 Jahre in Ägypten (1728–1513 v. u. Z.)."}],"significance":"Damit begann die Zeit Israels in Ägypten, die bis zum Auszug 1513 v. u. Z. dauerte.","persons":["jakob","joseph"],"refs":[{"t":"1. Mose 46:1–47:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/46/#v1046001-v1047012"}],"sources":[{"title":"Jakob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002279"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"tod-jakobs","title":"Jakob segnet seine Söhne und stirbt","era":"aegypten","year":-1711,"date":"1711 v. u. Z.","place":"Ägypten; begraben in Machpela","summary":"Nach 17 Jahren in Ägypten starb Jakob mit 147 Jahren. Vor seinem Tod segnete er Josephs Söhne Ephraim und Manasse und sprach prophetische Worte über jeden seiner zwölf Söhne. Über Juda sagte er voraus, dass das Zepter nicht von ihm weichen werde. Seine Söhne begruben ihn in der Höhle von Machpela.","facts":[{"t":"Jakob segnete Ephraim und Manasse.","r":{"t":"1. Mose 48:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/48/#v1048001-v1048020"}},{"t":"Er sprach über jeden seiner Söhne prophetische Worte.","r":{"t":"1. Mose 49:1-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/49/#v1049001-v1049028"}},{"t":"Das Zepter sollte nicht von Juda weichen.","r":{"t":"1. Mose 49:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/49/#v1049010"}},{"t":"Er wurde in der Höhle von Machpela begraben.","r":{"t":"1. Mose 50:12, 13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/50/#v1050012"}}],"significance":"","persons":["jakob","joseph","juda"],"refs":[{"t":"1. Mose 47:28–50:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/47/#v1047028-v1050014"}],"sources":[{"title":"Jakob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002279"},{"title":"Juda – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002538"}]},{"id":"tod-josephs","title":"Joseph stirbt","era":"aegypten","year":-1657,"date":"1657 v. u. Z.","place":"Ägypten","summary":"Joseph starb mit 110 Jahren und überlebte seinen Vater um etwa 54 Jahre; er erlebte sogar noch einige seiner Urenkel. Im Glauben an Gottes Verheißung ließ er seine Brüder schwören, seine Gebeine mitzunehmen, wenn Gott Israel aus Ägypten herausführen würde.","facts":[{"t":"Joseph wurde 110 Jahre alt.","r":{"t":"1. Mose 50:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/50/#v1050022"}},{"t":"Er sah noch Urenkel.","r":{"t":"1. Mose 50:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/50/#v1050023"}},{"t":"Er gab Anweisung wegen seiner Gebeine.","r":{"t":"1. Mose 50:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/50/#v1050024"}},{"t":"Die Bibel nennt das ein Zeichen seines Glaubens.","r":{"t":"Hebräer 11:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011022"}}],"significance":"","persons":["joseph"],"refs":[{"t":"1. Mose 50:22-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-mose/50/#v1050022-v1050026"},{"t":"2. Mose 13:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/13/#v2013019"},{"t":"Hebräer 11:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011022"}],"sources":[{"title":"Joseph – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002515"},{"title":"Hiob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002475"}]},{"id":"unterdrueckung-in-aegypten","title":"Israel wird in Ägypten unterdrückt","era":"aegypten","year":-1650,"date":"Nach dem Tod Josephs (1657 v. u. Z.)","place":"Ägypten","summary":"Nach dem Tod Josephs vermehrten sich die Israeliten in Ägypten stark. Ein neuer König, der Joseph nicht kannte, zwang sie zu harter Sklavenarbeit. Als sie sich trotzdem weiter vermehrten, befahl Pharao den Hebammen, alle neugeborenen hebräischen Jungen zu töten – doch Schiphra und Pua fürchteten Gott und ließen die Kinder leben.","facts":[{"t":"Die Israeliten wurden sehr zahlreich.","r":{"t":"2. Mose 1:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/1/#v2001007"}},{"t":"Ein neuer König bedrückte sie mit Zwangsarbeit.","r":{"t":"2. Mose 1:8-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/1/#v2001008-v2001014"}},{"t":"Die Hebammen ließen die Jungen am Leben.","r":{"t":"2. Mose 1:15-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/1/#v2001015-v2001021"}},{"t":"Pharao befahl, die neugeborenen Jungen in den Nil zu werfen.","r":{"t":"2. Mose 1:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/1/#v2001022"}}],"significance":"","persons":["schiphra-und-pua"],"refs":[{"t":"2. Mose 1:1-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/1/#v2001001-v2001022"}],"sources":[{"title":"Exodus (2. Mose) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001459"},{"title":"Schiphra – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004066"}]},{"id":"hiobs-pruefung","title":"Hiobs Prüfung","era":"aegypten","year":-1613,"date":"wahrscheinlich um 1613 v. u. Z.","place":"Land Uz","summary":"Satan behauptete vor Jehova, Hiob diene Gott nur, weil er gesegnet sei. Jehova vertraute Hiobs Lauterkeit und ließ eine Prüfung zu: Hiob verlor seinen Besitz und seine Kinder, dann wurde er schwer krank. Doch Hiob blieb treu. Danach stellte Jehova ihn wieder her und gab ihm das Doppelte von dem, was er vorher besessen hatte.","facts":[{"t":"Satan stellte Hiobs Beweggründe infrage.","r":{"t":"Hiob 1:9-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/1/#v18001009-v18001011"}},{"t":"Hiob sagte: „Jehova hat gegeben, und Jehova hat genommen.“","r":{"t":"Hiob 1:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/1/#v18001021"}},{"t":"Er hielt an seiner Lauterkeit fest.","r":{"t":"Hiob 27:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/27/#v18027005"}},{"t":"Jehova gab ihm das Doppelte zurück.","r":{"t":"Hiob 42:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/42/#v18042010"}}],"significance":"Hiobs Treue widerlegte Satans Behauptung, Hiob diene Gott nur aus Eigennutz.","persons":["hiob","satan","jehova"],"refs":[{"t":"Hiob 1:1–2:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/1/#v18001001-v18002013"},{"t":"Hiob 42:10-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hiob/42/#v18042010-v18042017"},{"t":"Jakobus 5:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jakobus/5/#v59005011"}],"sources":[{"title":"Hiob – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002475"}]},{"id":"geburt-moses","title":"Moses wird geboren","era":"aegypten","year":-1593,"date":"1593 v. u. Z.","place":"Ägypten","summary":"Trotz Pharaos Befehl, alle hebräischen Jungen zu töten, verbarg Jochebed ihren Sohn drei Monate lang. Dann legte sie ihn in einem Papyruskästchen ins Schilf am Nil, wo ihn Pharaos Tochter fand. Durch das kluge Vorgehen seiner Schwester durfte seine eigene Mutter ihn stillen; später adoptierte ihn Pharaos Tochter und nannte ihn Moses.","facts":[{"t":"Seine Mutter verbarg ihn drei Monate lang.","r":{"t":"2. Mose 2:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002002"}},{"t":"Seine Schwester beobachtete, was mit ihm geschah.","r":{"t":"2. Mose 2:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002004"}},{"t":"Pharaos Tochter nahm ihn als Sohn an.","r":{"t":"2. Mose 2:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002010"}},{"t":"Seine Eltern handelten im Glauben.","r":{"t":"Hebräer 11:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011023"}}],"significance":"","persons":["moses","jochebed","mirjam"],"refs":[{"t":"2. Mose 2:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002001-v2002010"},{"t":"Hebräer 11:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011023"}],"sources":[{"title":"Moses – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003118"},{"title":"Jochebed – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002478"}]},{"id":"moses-flieht-nach-midian","title":"Moses flieht nach Midian","era":"aegypten","year":-1553,"date":"1553 v. u. Z.","place":"Midian","summary":"Mit 40 Jahren sah Moses, wie ein Ägypter einen Hebräer schlug. Er verteidigte seinen Bruder, tötete den Ägypter und begrub ihn im Sand – er hatte sich entschieden, lieber mit Gottes Volk zu leiden, als Ansehen am Hof Pharaos zu genießen. Als die Sache bekannt wurde, floh er nach Midian. Dort heiratete er Zippora und hütete 40 Jahre die Herden Jethros.","facts":[{"t":"Moses weigerte sich, der Sohn der Tochter Pharaos genannt zu werden.","r":{"t":"Hebräer 11:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011024"}},{"t":"Er tötete einen Ägypter, der einen Hebräer schlug.","r":{"t":"2. Mose 2:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002011"}},{"t":"Er floh vor Pharao nach Midian.","r":{"t":"2. Mose 2:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002015"}},{"t":"In Midian heiratete er Zippora.","r":{"t":"2. Mose 2:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002021"}}],"significance":"","persons":["moses","jethro","zippora"],"refs":[{"t":"2. Mose 2:11-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/2/#v2002011-v2002022"},{"t":"Apostelgeschichte 7:23-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/7/#v44007023-v44007029"}],"sources":[{"title":"Moses – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003118"}]},{"id":"brennender-dornbusch","title":"Der brennende Dornbusch","era":"aegypten","year":-1514,"date":"1514 v. u. Z.","place":"Berg Horeb","summary":"Als Moses am Horeb die Herde Jethros hütete, sah er einen Dornbusch, der brannte, aber nicht verbrannte. Jehovas Engel sprach aus der Flamme, und Jehova beauftragte den 80-Jährigen, sein Volk aus Ägypten zu befreien. Moses brachte viele Einwände vor; schließlich bestimmte Jehova Aaron zu seinem Sprecher.","facts":[{"t":"Der Dornbusch brannte, verbrannte aber nicht.","r":{"t":"2. Mose 3:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/3/#v2003002"}},{"t":"Gott stellte sich als der Gott Abrahams, Isaaks und Jakobs vor.","r":{"t":"2. Mose 3:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/3/#v2003006"}},{"t":"Gott sprach über die Bedeutung seines Namens.","r":{"t":"2. Mose 3:13-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/3/#v2003013-v2003015"}},{"t":"Aaron sollte für Moses sprechen.","r":{"t":"2. Mose 4:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/4/#v2004014-v2004016"}}],"significance":"","persons":["moses","aaron","jehova"],"refs":[{"t":"2. Mose 3:1–4:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/3/#v2003001-v2004017"}],"sources":[{"title":"Moses – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003118"}]},{"id":"zehn-plagen","title":"Die zehn Plagen","era":"aegypten","year":-1513,"date":"1513 v. u. Z.","place":"Ägypten","summary":"Pharao weigerte sich, Israel ziehen zu lassen. Daraufhin brachte Jehova durch Moses und Aaron zehn Plagen über Ägypten. Nach den ersten drei Plagen waren nur noch die Ägypter betroffen. Durch die zehnte Plage starben alle männlichen Erstgeborenen der Ägypter und ihrer Tiere, während Israel das Passah feierte.","facts":[{"t":"Aaron gab mit dem Stab das Zeichen für die erste Plage.","r":{"t":"2. Mose 7:19, 20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/7/#v2007019"}},{"t":"Das Land Gosen, wo Israel wohnte, wurde verschont.","r":{"t":"2. Mose 8:22, 23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/8/#v2008022"}},{"t":"Die zehnte Plage traf alle Erstgeborenen Ägyptens.","r":{"t":"2. Mose 12:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/12/#v2012029"}},{"t":"Jehova vollstreckte Gericht an allen Göttern Ägyptens.","r":{"t":"2. Mose 12:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/12/#v2012012"}}],"significance":"","persons":["moses","aaron","jehova"],"refs":[{"t":"2. Mose 7:14–12:36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/7/#v2007014-v2012036"}],"sources":[{"title":"Exodus (2. Mose) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001459"},{"title":"Aaron – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000005"}]},{"id":"erstes-passah","title":"Das erste Passah","era":"aegypten","year":-1513,"date":"14. Abib (Nisan) 1513 v. u. Z.","place":"Ägypten","summary":"In der Nacht der zehnten Plage feierte Israel das erste Passah: Jede Familie schlachtete ein Lamm und strich etwas von seinem Blut an die Türpfosten. Wo das Blut zu sehen war, ging Jehova vorüber. Das Passah sollte jedes Jahr gefeiert werden; anschließend folgte das siebentägige Fest der ungesäuerten Brote.","facts":[{"t":"Es wurde um die Zeit des Vollmonds am 14. Abib gefeiert.","r":{"t":"2. Mose 12:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/12/#v2012006"}},{"t":"Das Blut an den Türpfosten schützte die Erstgeborenen.","r":{"t":"2. Mose 12:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/12/#v2012013"}},{"t":"Es sollte jedes Jahr gefeiert werden.","r":{"t":"2. Mose 12:24-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/12/#v2012024-v2012027"}},{"t":"Christus ist das Passahopfer.","r":{"t":"1. Korinther 5:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-korinther/5/#v46005007"}}],"significance":"","persons":["moses","aaron"],"refs":[{"t":"2. Mose 12:1-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/12/#v2012001-v2012028"}],"sources":[{"title":"Passah – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003397"}]},{"id":"auszug-aus-aegypten","title":"Auszug aus Ägypten","era":"aegypten","year":-1513,"date":"1513 v. u. Z.","place":"Von Ramses nach Sukkoth","summary":"Nach der zehnten Plage drängten die Ägypter die Israeliten, das Land zu verlassen. So zog Israel nach Ablauf der 430 Jahre „Wohnzeit“ – gerechnet ab 1943 v. u. Z. – aus Ägypten aus, zusammen mit einer großen gemischten Volksmenge. Die Gebeine Josephs nahmen sie mit, und Jehova führte sie mit einer Wolken- und einer Feuersäule.","facts":[{"t":"Der Auszug geschah genau am Ende der 430 Jahre.","r":{"t":"2. Mose 12:40, 41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/12/#v2012040"}},{"t":"Eine große gemischte Volksmenge zog mit.","r":{"t":"2. Mose 12:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/12/#v2012038"}},{"t":"Moses nahm die Gebeine Josephs mit.","r":{"t":"2. Mose 13:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/13/#v2013019"}},{"t":"Eine Wolkensäule und eine Feuersäule führten sie.","r":{"t":"2. Mose 13:21, 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/13/#v2013021"}}],"significance":"1513 v. u. Z. ist ein Schlüsseldatum: Israel wurde frei von der Herrschaft Ägyptens.","persons":["moses","aaron"],"refs":[{"t":"2. Mose 12:29-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/12/#v2012029-v2012042"},{"t":"2. Mose 13:17-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/13/#v2013017-v2013022"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Exodus (2. Mose) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001459"}]},{"id":"durchzug-rotes-meer","title":"Durchzug durch das Rote Meer","era":"aegypten","year":-1513,"date":"1513 v. u. Z.","place":"Rotes Meer","summary":"Pharao bereute, Israel ziehen gelassen zu haben, und jagte mit seinen Streitwagen hinterher. Am Roten Meer schienen die Israeliten gefangen. Doch Jehova teilte durch ein Wunder das Meer, sodass sie auf trockenem Land hindurchzogen. Als die Ägypter folgten, kehrte das Wasser zurück, und Pharaos Streitmacht kam um. Israel sang ein Siegeslied, und Mirjam leitete die Frauen beim Tanz.","facts":[{"t":"Jehova teilte das Meer durch einen starken Ostwind.","r":{"t":"2. Mose 14:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/14/#v2014021"}},{"t":"Israel zog auf trockenem Land hindurch.","r":{"t":"2. Mose 14:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/14/#v2014022"}},{"t":"Die Streitmacht Pharaos kam im Meer um.","r":{"t":"2. Mose 14:27, 28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/14/#v2014027"}},{"t":"Mirjam, die Prophetin, leitete den Gesang der Frauen.","r":{"t":"2. Mose 15:20, 21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/15/#v2015020"}}],"significance":"","persons":["moses","mirjam","aaron"],"refs":[{"t":"2. Mose 14:1–15:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/14/#v2014001-v2015021"},{"t":"Hebräer 11:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011029"}],"sources":[{"title":"Rotes Meer – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003669"},{"title":"Mirjam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003074"}]},{"id":"manna","title":"Manna in der Wildnis","era":"aegypten","year":-1513,"date":"1513 v. u. Z.","place":"Wildnis Sin","summary":"In der Wildnis murrte das Volk über den Mangel an Nahrung. Jehova versorgte es mit Wachteln und mit Manna, das morgens erschien, wenn der Tau verdunstet war. In Verbindung mit dem Manna wurde der Sabbat eingesetzt. Israel aß Manna, bis es 1473 v. u. Z. nach Kanaan kam.","facts":[{"t":"Manna wurde zuerst in der Wildnis Sin gegeben.","r":{"t":"2. Mose 16:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/16/#v2016001-v2016004"}},{"t":"Am sechsten Tag sammelten sie die doppelte Menge – für den Sabbat.","r":{"t":"2. Mose 16:22-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/16/#v2016022-v2016026"}},{"t":"Das Manna hörte auf, als Israel vom Ertrag des Landes aß.","r":{"t":"Josua 5:10-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/5/#v6005010-v6005012"}}],"significance":"","persons":["moses"],"refs":[{"t":"2. Mose 16:1-36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/16/#v2016001-v2016036"}],"sources":[{"title":"Manna – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002888"},{"title":"Exodus (2. Mose) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001459"}]},{"id":"gesetzesbund","title":"Der Gesetzesbund am Sinai","era":"aegypten","year":-1513,"date":"1513 v. u. Z.","place":"Berg Sinai","summary":"Im dritten Monat nach dem Auszug lagerte Israel am Berg Sinai. Jehova lud die Nation ein, sein besonderes Eigentum zu werden, und gab ihr die Zehn Gebote und weitere Gesetze. Der Gesetzesbund wurde über dem Blut von Opfertieren geschlossen; Moses war der Mittler. Das Volk versprach: „Alles, was Jehova geredet hat, wollen wir tun.“","facts":[{"t":"Israel lagerte im dritten Monat am Sinai.","r":{"t":"2. Mose 19:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/19/#v2019001"}},{"t":"Jehova gab die Zehn Gebote.","r":{"t":"2. Mose 20:1-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/20/#v2020001-v2020017"}},{"t":"Der Bund wurde mit dem Blut von Opfertieren geschlossen.","r":{"t":"2. Mose 24:5-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/24/#v2024005-v2024008"}},{"t":"Das Gesetz war wie ein Erzieher, der zu Christus führte.","r":{"t":"Galater 3:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/3/#v48003024"}}],"significance":"","persons":["moses","aaron","jehova"],"refs":[{"t":"2. Mose 19:1–24:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/19/#v2019001-v2024018"},{"t":"Galater 3:19-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/3/#v48003019-v48003024"}],"sources":[{"title":"Exodus (2. Mose) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001459"},{"title":"Zehn Gebote – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004361"},{"title":"Bund – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001054"}]},{"id":"goldenes-kalb","title":"Das goldene Kalb","era":"aegypten","year":-1513,"date":"1513 v. u. Z.","place":"Am Fuß des Sinai","summary":"Während Moses 40 Tage auf dem Berg Sinai war, drängte das Volk Aaron, ihm einen Gott zu machen. Aaron fertigte ein goldenes Kalb, und das Volk betete es an. Als Moses mit Josua herabkam, zerbrach er die Steintafeln, die Gott ihm gegeben hatte. Die Leviten erwiesen sich als loyal; etwa 3000 Götzenanbeter wurden getötet.","facts":[{"t":"Moses war 40 Tage und Nächte auf dem Berg.","r":{"t":"2. Mose 24:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/24/#v2024018"}},{"t":"Aaron machte auf Drängen des Volkes ein goldenes Kalb.","r":{"t":"2. Mose 32:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/32/#v2032001-v2032004"}},{"t":"Moses zerbrach die Steintafeln.","r":{"t":"2. Mose 32:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/32/#v2032019"}},{"t":"Die Leviten stellten sich auf Jehovas Seite.","r":{"t":"2. Mose 32:26-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/32/#v2032026-v2032028"}}],"significance":"","persons":["moses","aaron","josua"],"refs":[{"t":"2. Mose 32:1-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/32/#v2032001-v2032035"}],"sources":[{"title":"Exodus (2. Mose) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001459"},{"title":"Josua – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002523"}]},{"id":"stiftshuette","title":"Die Stiftshütte wird errichtet","era":"aegypten","year":-1512,"date":"1. Nisan 1512 v. u. Z.","place":"Am Berg Sinai","summary":"Nach den genauen Anweisungen Jehovas bauten die Israeliten die Stiftshütte, ein tragbares Heiligtum, mit Material, das das Volk freiwillig spendete. Am ersten Tag des ersten Monats 1512 v. u. Z. wurde sie aufgerichtet, und Jehova bekundete seine Anerkennung: Die Wolke bedeckte das Zelt der Zusammenkunft, und seine Herrlichkeit erfüllte es.","facts":[{"t":"Die Materialien kamen aus freiwilligen Spenden.","r":{"t":"2. Mose 36:3-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/36/#v2036003-v2036007"}},{"t":"Alles wurde genau nach Jehovas Anweisungen gemacht.","r":{"t":"2. Mose 39:42, 43","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/39/#v2039042"}},{"t":"Die Wolke bedeckte das Zelt der Zusammenkunft.","r":{"t":"2. Mose 40:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/40/#v2040034"}},{"t":"Die Stiftshütte war ein Schatten himmlischer Dinge.","r":{"t":"Hebräer 8:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/8/#v58008005"}}],"significance":"","persons":["moses","aaron"],"refs":[{"t":"2. Mose 35:4–40:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-mose/35/#v2035004-v2040038"},{"t":"Hebräer 9:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/9/#v58009001-v58009012"}],"sources":[{"title":"Stiftshütte – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004295"}]},{"id":"zwoelf-kundschafter","title":"Die zwölf Kundschafter","era":"aegypten","year":-1512,"date":"1512 v. u. Z.","place":"Kadesch; Land Kanaan","summary":"Moses sandte zwölf Männer aus, um das Land Kanaan 40 Tage lang auszukundschaften. Zehn von ihnen entmutigten das Volk mit der Behauptung, die Bewohner seien zu stark. Nur Josua und Kaleb vertrauten auf Jehova und gaben einen guten Bericht. Wegen des Unglaubens musste Israel 40 Jahre in der Wildnis bleiben, bis jene Generation gestorben war.","facts":[{"t":"Die Kundschafter erkundeten das Land 40 Tage lang.","r":{"t":"4. Mose 13:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/13/#v4013025"}},{"t":"Zehn von ihnen brachten einen schlechten Bericht.","r":{"t":"4. Mose 13:31-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/13/#v4013031-v4013033"}},{"t":"Josua und Kaleb ermutigten das Volk.","r":{"t":"4. Mose 14:6-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/14/#v4014006-v4014009"}},{"t":"Für jeden Tag ein Jahr: 40 Jahre Wanderung.","r":{"t":"4. Mose 14:33, 34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/14/#v4014033"}}],"significance":"","persons":["josua","kaleb","moses"],"refs":[{"t":"4. Mose 13:1–14:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/13/#v4013001-v4014038"}],"sources":[{"title":"Josua – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002523"},{"title":"Kaleb – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000863"}]},{"id":"korahs-aufstand","title":"Korahs Aufstand","era":"aegypten","year":-1500,"date":"Während der Wanderung durch die Wildnis","place":"Wildnis","summary":"Der Levit Korah lehnte sich mit Dathan, Abiram, On und 250 angesehenen Vorstehern gegen Moses und Aaron auf. Jehova entschied den Streit: Die Erde tat sich auf und verschlang die Aufrührer mit ihren Hausgemeinschaften, und Feuer verzehrte die 250 Männer, die Räucherwerk darbrachten. Später bestätigte Jehova Aarons Priestertum durch dessen Stab, der Blüten trieb.","facts":[{"t":"Die Aufrührer behaupteten, die ganze Gemeinde sei heilig.","r":{"t":"4. Mose 16:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/16/#v4016003"}},{"t":"Die Erde verschlang die Aufrührer und ihre Familien.","r":{"t":"4. Mose 16:31-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/16/#v4016031-v4016033"}},{"t":"Feuer von Jehova verzehrte die 250 Männer.","r":{"t":"4. Mose 16:35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/16/#v4016035"}},{"t":"Aarons Stab trieb Blüten und Mandeln.","r":{"t":"4. Mose 17:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/17/#v4017008"}}],"significance":"","persons":["korah","moses","aaron"],"refs":[{"t":"4. Mose 16:1–17:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/16/#v4016001-v4017013"}],"sources":[{"title":"Korah – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002648"}]},{"id":"kupferschlange","title":"Die Kupferschlange","era":"aegypten","year":-1474,"date":"Gegen Ende der Wanderung durch die Wildnis","place":"Nahe der Grenze Edoms","summary":"In der Nähe der Grenze Edoms zeigte das Volk erneut einen rebellischen Geist und beklagte sich über Gott und Moses. Da kamen giftige Schlangen, und viele starben. Als das Volk bereute, machte Moses auf Gottes Anweisung eine Schlange aus Kupfer und richtete sie an einer Stange auf; wer gebissen war und auf sie schaute, blieb am Leben.","facts":[{"t":"Das Volk beklagte sich über das Manna.","r":{"t":"4. Mose 21:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/21/#v4021005"}},{"t":"Giftige Schlangen kamen über das Volk.","r":{"t":"4. Mose 21:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/21/#v4021006"}},{"t":"Wer auf die Kupferschlange schaute, blieb am Leben.","r":{"t":"4. Mose 21:8, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/21/#v4021008"}},{"t":"Jesus verglich sein Erhöhtwerden mit der Kupferschlange.","r":{"t":"Johannes 3:14, 15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/3/#v43003014"}}],"significance":"","persons":["moses"],"refs":[{"t":"4. Mose 21:4-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/21/#v4021004-v4021009"},{"t":"Johannes 3:14, 15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/3/#v43003014"}],"sources":[{"title":"Kupferschlange – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001031"}]},{"id":"bileam-und-balak","title":"Bileam und Balak","era":"aegypten","year":-1473,"date":"um 1473 v. u. Z.","place":"Ebenen Moabs","summary":"Der Moabiterkönig Balak fürchtete Israel und bot Bileam reichen Lohn, damit er das Volk verfluche. Unterwegs stellte sich Jehovas Engel Bileam in den Weg, und seine Eselin sprach durch ein Wunder. Statt Israel zu verfluchen, musste Bileam es segnen. Später verleitete man Israel jedoch zum Götzendienst des Baal von Peor; Pinehas beendete die darauf folgende Plage.","facts":[{"t":"Balak bot Bileam einen „Wahrsagerlohn“.","r":{"t":"4. Mose 22:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/22/#v4022007"}},{"t":"Bileams Eselin sprach.","r":{"t":"4. Mose 22:28-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/22/#v4022028-v4022030"}},{"t":"Bileam musste Israel segnen.","r":{"t":"4. Mose 24:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/24/#v4024010"}},{"t":"Bei Peor fiel Israel in Götzendienst; Pinehas griff ein.","r":{"t":"4. Mose 25:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/25/#v4025001-v4025009"}}],"significance":"","persons":["bileam","pinehas"],"refs":[{"t":"4. Mose 22:1–24:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/22/#v4022001-v4024025"},{"t":"4. Mose 25:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/25/#v4025001-v4025009"},{"t":"4. Mose 31:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/4-mose/31/#v4031016"}],"sources":[{"title":"Bileam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000543"},{"title":"Pinehas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003472"}]},{"id":"tod-moses","title":"Moses stirbt","era":"aegypten","year":-1473,"date":"1473 v. u. Z.","place":"Berg Nebo (Moab)","summary":"Im Frühjahr 1473 v. u. Z. gab Moses bekannt, dass Josua nach Jehovas Anordnung sein Nachfolger werden sollte. Nachdem er das Volk ermahnt, ein Lied vorgetragen und Israel gesegnet hatte, stieg er auf den Nebo, um das Land der Verheißung zu sehen. Dort starb er mit 120 Jahren, noch im Vollbesitz seiner Kräfte.","facts":[{"t":"Josua wurde als Nachfolger eingesetzt.","r":{"t":"5. Mose 31:7, 8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/5-mose/31/#v5031007"}},{"t":"Moses sah das Land vom Nebo aus.","r":{"t":"5. Mose 34:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/5-mose/34/#v5034001-v5034004"}},{"t":"Er starb mit 120 Jahren; seine Kraft war nicht geschwunden.","r":{"t":"5. Mose 34:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/5-mose/34/#v5034007"}},{"t":"Niemand kennt sein Grab.","r":{"t":"5. Mose 34:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/5-mose/34/#v5034006"}}],"significance":"","persons":["moses","josua"],"refs":[{"t":"5. Mose 34:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/5-mose/34/#v5034001-v5034012"}],"sources":[{"title":"Moses – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003118"}]},{"id":"jordan-ueberquerung","title":"Israel überquert den Jordan","era":"richter","year":-1473,"date":"1473 v. u. Z.","place":"Jordan bei Jericho; Gilgal","summary":"Nach 40 Jahren in der Wildnis zog Israel unter Josua in das Land der Verheißung. Jehova staute durch ein Wunder den Jordan, sodass das Volk auf trockenem Boden hinüberziehen konnte. Zur Erinnerung stellte Josua zwölf Steine im Flussbett und zwölf bei Gilgal auf, Israels erstem Lagerplatz westlich des Jordan. Dort feierte das Volk das Passah.","facts":[{"t":"Josua sandte zwei Kundschafter nach Jericho.","r":{"t":"Josua 2:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/2/#v6002001"}},{"t":"Das Wasser des Jordan staute sich.","r":{"t":"Josua 3:15-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/3/#v6003015-v6003017"}},{"t":"Zwölf Gedenksteine wurden aufgestellt.","r":{"t":"Josua 4:1-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/4/#v6004001-v6004009"}},{"t":"In Gilgal feierte Israel das Passah.","r":{"t":"Josua 5:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/5/#v6005010"}}],"significance":"Mit der Jordanüberquerung begann die Landnahme in Kanaan.","persons":["josua","rahab"],"refs":[{"t":"Josua 3:1–4:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/3/#v6003001-v6004024"}],"sources":[{"title":"Josua – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002523"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"fall-jerichos","title":"Der Fall Jerichos","era":"richter","year":-1473,"date":"1473 v. u. Z.","place":"Jericho","summary":"Jericho war die erste Stadt, die Israel im Land der Verheißung einnahm. Nach Gottes Anweisung zogen die Krieger sechs Tage lang täglich einmal um die Stadt, mit Priestern, die Hörner bliesen, und mit der Bundeslade. Am siebten Tag zogen sie siebenmal herum; beim letzten Hornsignal erhob das Volk ein Kriegsgeschrei, und die Mauern stürzten ein. Rahab und ihre Familie wurden verschont.","facts":[{"t":"Ein Engelfürst gab Josua Anweisungen.","r":{"t":"Josua 5:13-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/5/#v6005013-v6005015"}},{"t":"Sechs Tage lang einmal, am siebten Tag siebenmal um die Stadt.","r":{"t":"Josua 6:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/6/#v6006003"}},{"t":"Die Mauern stürzten ein.","r":{"t":"Josua 6:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/6/#v6006020"}},{"t":"Rahab und ihre Familie wurden gerettet.","r":{"t":"Josua 6:22-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/6/#v6006022-v6006025"}},{"t":"Achan nahm verbotene Beute und brachte Unglück über Israel.","r":{"t":"Josua 7:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/7/#v6007001"}}],"significance":"","persons":["josua","rahab","achan"],"refs":[{"t":"Josua 6:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/6/#v6006001-v6006027"},{"t":"Hebräer 11:30, 31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011030"}],"sources":[{"title":"Jericho – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002426"},{"title":"Josua – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002523"}]},{"id":"sonne-steht-still","title":"Die Sonne steht still","era":"richter","year":-1472,"date":"Während der Eroberung Kanaans","place":"Gibeon; Tal Ajalon","summary":"Die Bewohner von Gibeon hatten sich durch eine List einen Bund mit Israel erschlichen, den Israel trotzdem hielt. Als fünf Amoriterkönige Gibeon angriffen, kam Josua der Stadt zu Hilfe. Jehova ließ große Hagelsteine auf die Feinde fallen, und auf Josuas Bitte hin standen Sonne und Mond still, bis Israel den Sieg errungen hatte.","facts":[{"t":"Die Gibeoniter erschlichen sich durch eine List einen Bund.","r":{"t":"Josua 9:3-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/9/#v6009003-v6009015"}},{"t":"Israel hielt den Bund trotzdem.","r":{"t":"Josua 9:19-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/9/#v6009019-v6009021"}},{"t":"Jehova ließ Hagelsteine auf die Feinde fallen.","r":{"t":"Josua 10:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/10/#v6010011"}},{"t":"Sonne und Mond standen still.","r":{"t":"Josua 10:12-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/10/#v6010012-v6010014"}}],"significance":"","persons":["josua"],"refs":[{"t":"Josua 9:3-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/9/#v6009003-v6009027"},{"t":"Josua 10:1-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/10/#v6010001-v6010014"}],"sources":[{"title":"Gibeon – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001682"},{"title":"Sonne – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004260"}]},{"id":"landverteilung","title":"Das Land wird verteilt","era":"richter","year":-1467,"date":"um 1467 v. u. Z.","place":"Gilgal; Silo","summary":"Nachdem Israel große Teile des Landes eingenommen hatte, wurde es durch Lose unter die Stämme verteilt – zuerst von Gilgal aus, später von Silo, wo die Stiftshütte aufgestellt worden war. Kaleb erhielt mit 85 Jahren das Gebiet um Hebron. Josua selbst bekam die Stadt Timnath-Serach im Bergland Ephraim.","facts":[{"t":"Die Verteilung geschah durch Lose.","r":{"t":"Josua 14:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/14/#v6014001"}},{"t":"Kaleb erbat sich Hebron.","r":{"t":"Josua 14:6-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/14/#v6014006-v6014014"}},{"t":"In Silo wurde die Stiftshütte aufgestellt.","r":{"t":"Josua 18:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/18/#v6018001"}},{"t":"Josua erhielt Timnath-Serach.","r":{"t":"Josua 19:49, 50","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/19/#v6019049"}}],"significance":"","persons":["josua","kaleb"],"refs":[{"t":"Josua 13:1–21:45","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/13/#v6013001-v6021045"}],"sources":[{"title":"Josua – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002523"},{"title":"Kaleb – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000863"}]},{"id":"tod-josuas","title":"Josua stirbt","era":"richter","year":-1450,"date":"Nach der Landverteilung","place":"Timnath-Serach","summary":"Vor seinem Tod versammelte Josua das Volk und ermahnte es, Jehova von ganzem Herzen zu dienen – er selbst und seine Hausgemeinschaft würden Jehova dienen. Das Volk erneuerte seinen Bund mit Gott. Josua starb mit 110 Jahren. Solange er und die älteren Männer seiner Generation lebten, diente Israel Jehova.","facts":[{"t":"Josua stellte das Volk vor die Wahl, wem es dienen wollte.","r":{"t":"Josua 24:14, 15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/24/#v6024014"}},{"t":"Das Volk versprach, Jehova zu gehorchen.","r":{"t":"Josua 24:16-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/24/#v6024016-v6024024"}},{"t":"Josua starb mit 110 Jahren.","r":{"t":"Josua 24:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/24/#v6024029"}},{"t":"Israel diente Jehova alle Tage Josuas.","r":{"t":"Josua 24:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/24/#v6024031"}}],"significance":"","persons":["josua"],"refs":[{"t":"Josua 23:1–24:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/josua/23/#v6023001-v6024031"}],"sources":[{"title":"Josua – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002523"}]},{"id":"zeit-der-richter","title":"Die Zeit der Richter","era":"richter","year":-1440,"date":"Nach Josuas Tod bis 1117 v. u. Z.","place":"Israel","summary":"Nach dem Tod Josuas und seiner Generation wandte sich Israel immer wieder anderen Göttern zu. Dann ließ Jehova zu, dass Feinde das Volk bedrückten. Wenn die Israeliten zu ihm um Hilfe riefen, erweckte er Richter, die sie befreiten – so begann der Kreislauf von Neuem. Zwischen Josua und Samuel werden zwölf Richter mit Namen genannt.","facts":[{"t":"Israel diente den Baalen und vergaß Jehova.","r":{"t":"Richter 2:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/2/#v7002011-v7002013"}},{"t":"Jehova erweckte Richter, die das Volk retteten.","r":{"t":"Richter 2:16-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/2/#v7002016-v7002018"}},{"t":"Jeder tat, was in seinen eigenen Augen recht war.","r":{"t":"Richter 21:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/21/#v7021025"}},{"t":"Zu den Richtern gehören Othniel, Ehud, Barak, Gideon, Jephtha und Simson.","r":{"t":"Hebräer 11:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Hebr%C3%A4er/11/#v58011032"}}],"significance":"","persons":["othniel","ehud","debora","gideon","jephtha","simson","samuel"],"refs":[{"t":"Richter 2:6-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/2/#v7002006-v7002023"}],"sources":[{"title":"Richter – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002545"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"ruth-und-noomi","title":"Ruth hält zu Noomi","era":"richter","year":-1355,"date":"In den Tagen der Richter","place":"Moab; Bethlehem","summary":"Nachdem Noomis Mann und ihre beiden Söhne in Moab gestorben waren, kehrte sie nach Bethlehem zurück. Ihre Schwiegertochter Orpa ging zu ihrem Volk zurück, doch die Moabiterin Ruth blieb bei ihr – aus Liebe zu Noomi und weil sie Jehova dienen wollte. In Bethlehem las Ruth Ähren auf dem Feld des Boas, der sie schließlich als Rückkäufer heiratete. Ihr Sohn Obed wurde der Großvater Davids.","facts":[{"t":"Ruth sagte: „Dein Gott wird mein Gott sein.“","r":{"t":"Ruth 1:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/1/#v8001016"}},{"t":"Sie kamen zu Beginn der Gerstenernte nach Bethlehem.","r":{"t":"Ruth 1:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/1/#v8001022"}},{"t":"Boas heiratete Ruth als Rückkäufer.","r":{"t":"Ruth 4:9-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/4/#v8004009-v8004013"}},{"t":"Obed wurde der Großvater Davids.","r":{"t":"Ruth 4:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/4/#v8004017"}}],"significance":"Durch Ruth und Boas führt die Abstammungslinie zu David und schließlich zu Jesus.","persons":["ruth","noomi","boas"],"refs":[{"t":"Ruth 1:1–4:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/ruth/1/#v8001001-v8004022"},{"t":"Matthäus 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001005"}],"sources":[{"title":"Ruth – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003776"},{"title":"Boas – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000779"}]},{"id":"debora-und-barak","title":"Debora und Barak besiegen Sisera","era":"richter","year":-1300,"date":"Zeitpunkt unbekannt","place":"Berg Tabor; Wildbach Kischon","summary":"Zwanzig Jahre lang bedrückte der Kanaaniterkönig Jabin Israel. Durch die Prophetin Debora beauftragte Jehova Barak, mit 10 000 Mann gegen Jabins Heerführer Sisera zu ziehen. Jehova gab Israel den Sieg über das gut bewaffnete Heer. Sisera floh zu Fuß und wurde von Jael getötet. Debora und Barak besangen den Sieg in einem Lied, das Jehova alle Ehre gibt.","facts":[{"t":"Barak zog mit 10 000 Mann zum Berg Tabor.","r":{"t":"Richter 4:6, 14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004006"}},{"t":"Jehova brachte Sisera und sein Heer in Verwirrung.","r":{"t":"Richter 4:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004015"}},{"t":"Jael tötete Sisera in ihrem Zelt.","r":{"t":"Richter 4:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004021"}},{"t":"Das Lied Deboras und Baraks preist Jehova.","r":{"t":"Richter 5:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/5/#v7005001-v7005003"}}],"significance":"","persons":["debora","barak","jael"],"refs":[{"t":"Richter 4:1–5:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/4/#v7004001-v7005031"}],"sources":[{"title":"Debora – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001138"},{"title":"Barak – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000559"}]},{"id":"gideons-300","title":"Gideons 300 Mann","era":"richter","year":-1250,"date":"Zeitpunkt unbekannt","place":"Ebene Jesreel","summary":"Sieben Jahre lang fielen die Midianiter wie Heuschrecken in Israel ein. Jehova berief Gideon zum Befreier, verringerte aber sein Heer: Nur 300 Mann, die das Wasser mit der Hand zum Mund schöpften, durften bleiben. In der Nacht umstellten sie das Lager Midians von drei Seiten, bliesen die Hörner, zerschlugen ihre Krüge, hielten die Fackeln hoch – und das feindliche Heer floh in Panik.","facts":[{"t":"Gideon bat um Zeichen mit einem Wollvlies.","r":{"t":"Richter 6:36-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/6/#v7006036-v7006040"}},{"t":"Von 32 000 Mann blieben 300.","r":{"t":"Richter 7:2-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/7/#v7007002-v7007007"}},{"t":"Sie riefen: „Jehovas Schwert und Gideons!“","r":{"t":"Richter 7:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/7/#v7007020"}},{"t":"Die Midianiter wandten sich gegeneinander.","r":{"t":"Richter 7:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/7/#v7007022"}}],"significance":"","persons":["gideon"],"refs":[{"t":"Richter 6:1–7:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/6/#v7006001-v7007025"}],"sources":[{"title":"Gideon – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001685"}]},{"id":"hannas-gebet","title":"Hanna betet um einen Sohn","era":"richter","year":-1186,"date":"Zeitpunkt unbekannt","place":"Silo","summary":"Die kinderlose Hanna betete in Silo lautlos zu Jehova und gelobte, einen Sohn seinem Dienst zu weihen. Der Hohe Priester Eli hielt sie zuerst für betrunken, segnete sie dann aber. Hanna bekam Samuel und brachte ihn nach seiner Entwöhnung zur Stiftshütte, wo er unter Elis Aufsicht Jehova diente.","facts":[{"t":"Peninna verhöhnte Hanna wegen ihrer Kinderlosigkeit.","r":{"t":"1. Samuel 1:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001006"}},{"t":"Hanna gelobte, ihren Sohn Jehova zu geben.","r":{"t":"1. Samuel 1:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001011"}},{"t":"Eli wünschte ihr, dass Gott ihre Bitte erfülle.","r":{"t":"1. Samuel 1:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001017"}},{"t":"Sie gab Samuel Jehova für sein ganzes Leben.","r":{"t":"1. Samuel 1:27, 28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001027"}}],"significance":"","persons":["hanna","eli","samuel"],"refs":[{"t":"1. Samuel 1:1–2:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/1/#v9001001-v9002011"}],"sources":[{"title":"Hanna – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001861"},{"title":"Samuel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003824"}]},{"id":"jephthas-geluebde","title":"Jephthas Gelübde","era":"richter","year":-1173,"date":"um 1173 v. u. Z.","place":"Gilead; Mizpa","summary":"Vor der Schlacht gegen die Ammoniter gelobte Jephtha: Wer ihm nach dem Sieg zuerst aus seinem Haus entgegenkommt, soll Jehova gehören. Als seine einzige Tochter ihm entgegenkam, hielt er sein Gelübde. Nach jw.org war das kein Menschenopfer – das hätte Jehova verabscheut –, sondern sie diente fortan unverheiratet am Heiligtum.","facts":[{"t":"Jehovas Geist kam auf Jephtha.","r":{"t":"Richter 11:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011029"}},{"t":"Jehova gab die Ammoniter in seine Hand.","r":{"t":"Richter 11:32, 33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011032"}},{"t":"Seine Tochter kam ihm als Erste entgegen.","r":{"t":"Richter 11:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011034"}},{"t":"Menschenopfer waren für Jehova etwas Abscheuliches.","r":{"t":"5. Mose 18:10-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/5-mose/18/#v5018010-v5018012"}}],"significance":"","persons":["jephtha","jephthas-tochter"],"refs":[{"t":"Richter 11:29-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/11/#v7011029-v7011040"}],"sources":[{"title":"Jephtha – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002413"}]},{"id":"simson-und-die-philister","title":"Simson und die Philister","era":"richter","year":-1150,"date":"Zeitpunkt unbekannt","place":"Gebiet der Philister; Gaza","summary":"In der Kraft des Geistes Gottes kämpfte Simson 20 Jahre lang gegen die Philister. Doch durch Delila verriet er das Geheimnis seiner Kraft; die Philister nahmen ihn gefangen, blendeten ihn und ließen ihn in Gaza Mühlsteine drehen. Beim Opferfest für ihren Gott Dagon betete Simson ein letztes Mal um Kraft, riss die tragenden Säulen ein und tötete bei seinem Tod mehr Philister als zu Lebzeiten.","facts":[{"t":"Er tötete in Aschkelon 30 Philister.","r":{"t":"Richter 14:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/14/#v7014019"}},{"t":"Delila verriet ihn.","r":{"t":"Richter 16:18-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016018-v7016021"}},{"t":"Er betete: „Gedenke bitte meiner.“","r":{"t":"Richter 16:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016028"}},{"t":"Er starb mit den Philistern im Haus Dagons.","r":{"t":"Richter 16:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/16/#v7016030"}}],"significance":"","persons":["simson","delila"],"refs":[{"t":"Richter 14:1–16:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/richter/14/#v7014001-v7016031"}],"sources":[{"title":"Simson – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003823"},{"title":"Delila – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001149"}]},{"id":"bundeslade-erbeutet","title":"Die Philister erbeuten die Bundeslade","era":"richter","year":-1140,"date":"Zeitpunkt unbekannt","place":"Eben-Eser; Aschdod","summary":"Im Krieg gegen die Philister holten die Israeliten die Bundeslade aus Silo, als wäre sie ein Glücksbringer. Dennoch fielen 30 000 Israeliten, die Lade wurde erbeutet, und Elis Söhne Hophni und Pinehas kamen um. Als der 98-jährige Eli die Nachricht hörte, fiel er rücklings vom Sitz und starb. Die Philister mussten die Lade jedoch bald zurückgeben, weil Jehova sie mit Plagen schlug.","facts":[{"t":"Die Israeliten holten die Lade ins Kriegslager.","r":{"t":"1. Samuel 4:3-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/4/#v9004003-v9004005"}},{"t":"30 000 Israeliten fielen; die Lade wurde erbeutet.","r":{"t":"1. Samuel 4:10, 11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/4/#v9004010"}},{"t":"Eli starb, als er die Nachricht hörte.","r":{"t":"1. Samuel 4:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/4/#v9004018"}},{"t":"Das Götzenbild Dagon fiel vor der Lade nieder.","r":{"t":"1. Samuel 5:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/5/#v9005001-v9005004"}}],"significance":"","persons":["eli","samuel"],"refs":[{"t":"1. Samuel 4:1–6:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/4/#v9004001-v9006021"}],"sources":[{"title":"Eli – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001290"},{"title":"Bundeslade – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000369"}]},{"id":"israel-will-einen-koenig","title":"Israel verlangt einen König","era":"richter","year":-1117,"date":"1117 v. u. Z.","place":"Rama","summary":"Weil Samuels Söhne das Recht beugten und ein Krieg mit den Ammonitern drohte, verlangten die älteren Männer Israels einen menschlichen König „wie alle Nationen“. Damit zeigten sie Mangel an Glauben an Jehovas Königtum. Jehova ließ Samuel dem Wunsch nachkommen, das Volk aber vor den Folgen warnen. Danach salbte Samuel den Benjaminiter Saul.","facts":[{"t":"Samuels Söhne nahmen Bestechung an.","r":{"t":"1. Samuel 8:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/8/#v9008001-v9008003"}},{"t":"Das Volk wollte einen König wie alle Nationen.","r":{"t":"1. Samuel 8:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/8/#v9008005"}},{"t":"Jehova sagte: „Mich haben sie verworfen.“","r":{"t":"1. Samuel 8:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/8/#v9008007"}},{"t":"Samuel warnte vor den Lasten eines Königtums.","r":{"t":"1. Samuel 8:10-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/8/#v9008010-v9008018"}}],"significance":"Damit endete die Richterzeit; 1117 v. u. Z. begann die Zeit der Könige.","persons":["samuel","saul"],"refs":[{"t":"1. Samuel 8:1-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/8/#v9008001-v9008022"}],"sources":[{"title":"Samuel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003824"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"saul-wird-koenig","title":"Saul wird König","era":"koenigreich","year":-1117,"date":"1117 v. u. Z.","place":"Rama; Mizpa","summary":"Als Saul die verlorenen Eselinnen seines Vaters suchte, führte Jehova ihn zu Samuel. Samuel salbte ihn heimlich zum König und gab ihm drei Zeichen, die sich noch am selben Tag erfüllten. Später wurde Saul in Mizpa durch das Los als König bestätigt – er hatte sich zunächst beim Gepäck versteckt. Nach einem Sieg über die Ammoniter wurde sein Königtum in Gilgal erneuert.","facts":[{"t":"Saul zeigte anfangs ein bescheidenes Wesen.","r":{"t":"1. Samuel 9:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/9/#v9009021"}},{"t":"Samuel salbte ihn mit Öl.","r":{"t":"1. Samuel 10:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/10/#v9010001"}},{"t":"In Mizpa fiel das Los auf ihn.","r":{"t":"1. Samuel 10:20-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/10/#v9010020-v9010024"}},{"t":"Er regierte 40 Jahre.","r":{"t":"Apostelgeschichte 13:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/13/#v44013021"}}],"significance":"Mit Saul begann die Zeit der Könige über alle zwölf Stämme Israels.","persons":["saul","samuel"],"refs":[{"t":"1. Samuel 9:1–11:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/9/#v9009001-v9011015"}],"sources":[{"title":"Saul – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003847"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"david-wird-gesalbt","title":"Samuel salbt David","era":"koenigreich","year":-1092,"date":"Zeitpunkt unbekannt","place":"Bethlehem","summary":"Nachdem Jehova Saul als König verworfen hatte, sandte er Samuel nach Bethlehem in das Haus Isais. Keiner der älteren Söhne war der Erwählte, denn „Jehova sieht, wie das Herz ist“. Schließlich wurde David geholt, der jüngste, der die Schafe hütete. Samuel salbte ihn, und Jehovas Geist kam von diesem Tag an über David.","facts":[{"t":"Samuel sollte einen der Söhne Isais salben.","r":{"t":"1. Samuel 16:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/16/#v9016001"}},{"t":"Jehova sieht nicht das Äußere, sondern das Herz.","r":{"t":"1. Samuel 16:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/16/#v9016007"}},{"t":"David, der Jüngste, wurde gesalbt.","r":{"t":"1. Samuel 16:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/16/#v9016011-v9016013"}},{"t":"Der Geist Jehovas wich von Saul.","r":{"t":"1. Samuel 16:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/16/#v9016014"}}],"significance":"","persons":["samuel","david","saul"],"refs":[{"t":"1. Samuel 16:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/16/#v9016001-v9016013"}],"sources":[{"title":"David – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001130"}]},{"id":"david-und-goliath","title":"David besiegt Goliath","era":"koenigreich","year":-1091,"date":"Kurz nach Davids Salbung","place":"Tal Ela (zwischen Socho und Aseka)","summary":"Die Heere Israels und der Philister standen sich gegenüber, als der Riese Goliath Israel verhöhnte und einen Zweikampf forderte. Der junge David, der Lebensmittel zu seinen Brüdern brachte, trat ihm entgegen – nicht in Sauls Rüstung, sondern mit Stab und Schleuder und „im Namen Jehovas“. Mit dem ersten Stein traf er Goliath an der Stirn und tötete ihn; die Philister flohen.","facts":[{"t":"Goliath forderte Israel 40 Tage lang heraus.","r":{"t":"1. Samuel 17:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017016"}},{"t":"David hatte schon einen Löwen und einen Bären besiegt.","r":{"t":"1. Samuel 17:34-37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017034-v9017037"}},{"t":"„Ich komme zu dir mit dem Namen Jehovas der Heerscharen.“","r":{"t":"1. Samuel 17:45","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017045"}},{"t":"Der Stein drang in Goliaths Stirn ein.","r":{"t":"1. Samuel 17:49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017049"}}],"significance":"","persons":["david","goliath","saul"],"refs":[{"t":"1. Samuel 17:1-58","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/17/#v9017001-v9017058"}],"sources":[{"title":"Goliath – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001739"}]},{"id":"david-flieht-vor-saul","title":"David auf der Flucht vor Saul","era":"koenigreich","year":-1088,"date":"Zeitpunkt unbekannt","place":"Wildnis von Juda; Ziklag","summary":"Davids Erfolge machten Saul eifersüchtig; mehrmals versuchte er, David zu töten. Mit Hilfe Michals und Jonathans entkam David und lebte jahrelang als Flüchtling in der Wildnis. Zweimal hätte er Saul töten können, verschonte ihn aber, weil er „den Gesalbten Jehovas“ nicht antasten wollte. In dieser Zeit bewahrte ihn Abigail vor Blutschuld.","facts":[{"t":"Saul warf einen Speer nach David.","r":{"t":"1. Samuel 18:10, 11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/18/#v9018010"}},{"t":"Jonathan schloss einen Bund mit David.","r":{"t":"1. Samuel 20:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/20/#v9020016"}},{"t":"David verschonte Saul in einer Höhle.","r":{"t":"1. Samuel 24:3-7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/24/#v9024003-v9024007"}},{"t":"Abigail hielt ihn davon ab, Rache zu üben.","r":{"t":"1. Samuel 25:32-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/25/#v9025032-v9025034"}}],"significance":"","persons":["david","saul","jonathan","michal","abigail"],"refs":[{"t":"1. Samuel 18:6–27:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/18/#v9018006-v9027012"}],"sources":[{"title":"David – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001130"}]},{"id":"sauls-tod","title":"Saul und Jonathan sterben","era":"koenigreich","year":-1078,"date":"um 1078 v. u. Z.","place":"Berg Gilboa","summary":"Im Krieg gegen die Philister erreichte die Schlacht auf dem Berg Gilboa ihren Höhepunkt. Saul und drei seiner Söhne, darunter Jonathan, kamen ums Leben. David trauerte um sie und dichtete ein Klagelied, in dem er die Freundschaft Jonathans würdigte.","facts":[{"t":"Zuvor hatte Saul ein Geistermedium in En-Dor befragt.","r":{"t":"1. Samuel 28:7-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/28/#v9028007-v9028019"}},{"t":"Saul und drei seiner Söhne fielen am Gilboa.","r":{"t":"1. Samuel 31:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/31/#v9031001-v9031006"}},{"t":"David beklagte Saul und Jonathan in einem Lied.","r":{"t":"2. Samuel 1:17-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/1/#v10001017-v10001027"}}],"significance":"","persons":["saul","jonathan","david"],"refs":[{"t":"1. Samuel 31:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-samuel/31/#v9031001-v9031013"},{"t":"2. Samuel 1:17-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/1/#v10001017-v10001027"}],"sources":[{"title":"Jonathan – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002506"},{"title":"David – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001130"}]},{"id":"david-koenig-in-hebron","title":"David wird König in Hebron","era":"koenigreich","year":-1077,"date":"1077 v. u. Z.","place":"Hebron","summary":"Nach Sauls Tod zog David nach Hebron. Dort salbten ihn die älteren Männer Judas im Alter von 30 Jahren zum König über ihren Stamm. Über die übrigen Stämme regierte zunächst Sauls Sohn Isch-Boscheth; nach dessen Tod kamen alle Stämme zu David.","facts":[{"t":"Die Männer Judas salbten David in Hebron.","r":{"t":"2. Samuel 2:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/2/#v10002001-v10002004"}},{"t":"Isch-Boscheth wurde König über die anderen Stämme.","r":{"t":"2. Samuel 2:8-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/2/#v10002008-v10002010"}},{"t":"David regierte siebeneinhalb Jahre in Hebron.","r":{"t":"2. Samuel 5:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/5/#v10005005"}}],"significance":"","persons":["david","joab"],"refs":[{"t":"2. Samuel 2:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/2/#v10002001-v10002011"},{"t":"2. Samuel 5:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/5/#v10005001-v10005005"}],"sources":[{"title":"David – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001130"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"david-erobert-jerusalem","title":"David erobert Jerusalem","era":"koenigreich","year":-1070,"date":"1070 v. u. Z.","place":"Jerusalem (Zion)","summary":"1070 v. u. Z. wurde David König über ganz Israel. Er eroberte die Festung Zion von den Jebusitern und machte Jerusalem zu seiner Hauptstadt – zur „Stadt Davids“. Von dort aus regierte er weitere 33 Jahre.","facts":[{"t":"Alle Stämme Israels salbten David in Hebron zum König.","r":{"t":"2. Samuel 5:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/5/#v10005001-v10005003"}},{"t":"Er nahm die Festung Zion ein.","r":{"t":"2. Samuel 5:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/5/#v10005006"}},{"t":"Er regierte 33 Jahre in Jerusalem.","r":{"t":"2. Samuel 5:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/5/#v10005005"}}],"significance":"Jerusalem wurde zum Mittelpunkt der Anbetung Jehovas und des Königreichs Israel.","persons":["david","joab"],"refs":[{"t":"2. Samuel 5:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/5/#v10005001-v10005010"},{"t":"1. Chronika 11:4-9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/11/#v13011004-v13011009"}],"sources":[{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"bundeslade-nach-jerusalem","title":"Die Bundeslade kommt nach Jerusalem","era":"koenigreich","year":-1069,"date":"Nach 1070 v. u. Z.","place":"Jerusalem","summary":"David wollte die Bundeslade nach Jerusalem holen. Beim ersten Versuch wurde sie auf einem Wagen gefahren, statt – wie Gott angeordnet hatte – von Leviten getragen, und Ussa starb, als er die Lade berührte. Beim zweiten Mal trugen die Leviten sie, und David tanzte voller Freude vor Jehova, während Michal ihn verachtete.","facts":[{"t":"Ussa starb, weil er die Lade anfasste.","r":{"t":"2. Samuel 6:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/6/#v10006006"}},{"t":"Beim zweiten Versuch trugen Leviten die Lade.","r":{"t":"1. Chronika 15:2, 15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/15/#v13015002"}},{"t":"David tanzte mit aller Kraft vor Jehova.","r":{"t":"2. Samuel 6:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/6/#v10006014"}},{"t":"Michal verachtete ihn in ihrem Herzen.","r":{"t":"2. Samuel 6:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/6/#v10006016"}}],"significance":"","persons":["david","michal"],"refs":[{"t":"2. Samuel 6:1-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/6/#v10006001-v10006023"},{"t":"1. Chronika 15:1-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/15/#v13015001-v13015029"}],"sources":[{"title":"Bundeslade – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000369"},{"title":"Michal – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003036"}]},{"id":"bund-mit-david","title":"Jehovas Bund mit David","era":"koenigreich","year":-1068,"date":"Nach 1070 v. u. Z.","place":"Jerusalem","summary":"David wollte Jehova einen Tempel bauen. Doch durch den Propheten Nathan ließ Jehova ihm sagen, nicht David, sondern einer seiner Nachkommen werde das Haus Jehovas bauen. Stattdessen werde Jehova David ein „Haus“ bauen: Er schloss mit ihm einen Bund für ein Königreich, das für immer in Davids Linie bleiben sollte.","facts":[{"t":"Nathan ermutigte David zuerst, dann übermittelte er Jehovas Antwort.","r":{"t":"2. Samuel 7:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/7/#v10007001-v10007005"}},{"t":"Ein Nachkomme Davids sollte den Tempel bauen.","r":{"t":"2. Samuel 7:12, 13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/7/#v10007012"}},{"t":"Davids Thron sollte auf unabsehbare Zeit bestehen.","r":{"t":"2. Samuel 7:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/7/#v10007016"}},{"t":"Der verheißene „Nachkomme“ sollte aus Davids Familie stammen.","r":{"t":"Lukas 1:32, 33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001032"}}],"significance":"Jehova versprach David, dass der verheißene „Nachkomme“ aus seiner Familie kommen würde – erfüllt in Jesus.","persons":["david","nathan","jehova"],"refs":[{"t":"2. Samuel 7:1-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/7/#v10007001-v10007029"},{"t":"1. Chronika 17:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-chronika/17/#v13017001-v13017015"}],"sources":[{"title":"Nathan – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003184"},{"title":"B1 Das Hauptthema der Bibel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070221"}]},{"id":"david-und-batseba","title":"David sündigt mit Bathseba","era":"koenigreich","year":-1060,"date":"Zeitpunkt unbekannt","place":"Jerusalem","summary":"Während sein Heer gegen die Ammoniter kämpfte, sah David vom Dach seines Palastes Bathseba, die Frau Urias. Er beging Ehebruch mit ihr, und als sie schwanger wurde, ließ er Uria an der Front sterben. Der Prophet Nathan hielt ihm mit einem Gleichnis seine Sünde vor. David bereute aufrichtig – Psalm 51 bringt seine Reue zum Ausdruck –, musste aber die Folgen tragen.","facts":[{"t":"David ließ Bathseba in den Palast holen.","r":{"t":"2. Samuel 11:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011002-v10011004"}},{"t":"Er ließ Uria an der gefährlichsten Stelle kämpfen.","r":{"t":"2. Samuel 11:14-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011014-v10011017"}},{"t":"Nathan sagte: „Du selbst bist der Mann!“","r":{"t":"2. Samuel 12:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/12/#v10012007"}},{"t":"David bekannte: „Ich habe gegen Jehova gesündigt.“","r":{"t":"2. Samuel 12:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/12/#v10012013"}}],"significance":"","persons":["david","batseba","uria","nathan","joab"],"refs":[{"t":"2. Samuel 11:1–12:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/11/#v10011001-v10012025"},{"t":"Psalm 51:1-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/psalmen/51/#v19051001-v19051019"}],"sources":[{"title":"Bathseba – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000581"},{"title":"Uria – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004521"}]},{"id":"absaloms-aufstand","title":"Absaloms Aufstand","era":"koenigreich","year":-1045,"date":"Zeitpunkt unbekannt","place":"Hebron; Jerusalem; Wald Ephraim","summary":"Davids Sohn Absalom gewann durch Schmeichelei die Herzen vieler Israeliten und ließ sich in Hebron zum König ausrufen. David musste aus Jerusalem fliehen. In der entscheidenden Schlacht im Wald Ephraim wurde Absaloms Heer geschlagen; Absalom verfing sich mit dem Kopf in einem großen Baum und wurde von Joab getötet. David trauerte bitterlich um seinen Sohn.","facts":[{"t":"Absalom stahl die Herzen der Männer Israels.","r":{"t":"2. Samuel 15:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/15/#v10015006"}},{"t":"David floh aus Jerusalem.","r":{"t":"2. Samuel 15:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/15/#v10015014"}},{"t":"Joab tötete Absalom gegen Davids Wunsch.","r":{"t":"2. Samuel 18:5, 14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/18/#v10018005"}},{"t":"David rief: „Mein Sohn Absalom!“","r":{"t":"2. Samuel 18:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/18/#v10018033"}}],"significance":"","persons":["absalom","david","joab"],"refs":[{"t":"2. Samuel 15:1–18:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-samuel/15/#v10015001-v10018033"}],"sources":[{"title":"Absalom – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000063"},{"title":"Joab – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002469"}]},{"id":"salomo-wird-koenig","title":"Salomo wird König","era":"koenigreich","year":-1037,"date":"1037 v. u. Z.","place":"Jerusalem (Gihon)","summary":"Als David alt war, versuchte sein Sohn Adonia, den Thron an sich zu reißen. Doch Nathan und Bathseba erinnerten David an seinen Eid, dass Salomo ihm folgen sollte. David ließ Salomo daraufhin zum König salben. Bevor David starb, ermahnte er Salomo, auf Jehovas Wegen zu wandeln.","facts":[{"t":"Adonia ließ sich zum König ausrufen.","r":{"t":"1. Könige 1:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/1/#v11001005"}},{"t":"Nathan und Bathseba sprachen bei David vor.","r":{"t":"1. Könige 1:11-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/1/#v11001011-v11001031"}},{"t":"Salomo wurde am Gihon gesalbt.","r":{"t":"1. Könige 1:38, 39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/1/#v11001038"}},{"t":"David ermahnte Salomo, Jehovas Gebote zu halten.","r":{"t":"1. Könige 2:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/2/#v11002001-v11002004"}}],"significance":"","persons":["salomo","david","nathan","batseba"],"refs":[{"t":"1. Könige 1:1–2:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/1/#v11001001-v11002012"}],"sources":[{"title":"Salomo – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004178"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"salomo-bittet-um-weisheit","title":"Salomo bittet um Weisheit","era":"koenigreich","year":-1036,"date":"Zu Beginn seiner Herrschaft","place":"Gibeon","summary":"In Gibeon erschien Jehova Salomo in einem Traum und forderte ihn auf, um etwas zu bitten. Salomo bat nicht um Reichtum oder ein langes Leben, sondern um ein gehorsames Herz, um das Volk zu richten und Gut und Böse zu unterscheiden. Jehova gab ihm außergewöhnliche Weisheit – und dazu Reichtum und Ehre.","facts":[{"t":"Salomo nannte sich einen „kleinen Jungen“.","r":{"t":"1. Könige 3:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/3/#v11003007"}},{"t":"Er bat um ein gehorsames Herz.","r":{"t":"1. Könige 3:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/3/#v11003009"}},{"t":"Jehova gab ihm Weisheit, Reichtum und Ehre.","r":{"t":"1. Könige 3:12, 13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/3/#v11003012"}},{"t":"Seine Weisheit zeigte sich im Streit zweier Frauen um ein Kind.","r":{"t":"1. Könige 3:16-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/3/#v11003016-v11003028"}}],"significance":"","persons":["salomo","jehova"],"refs":[{"t":"1. Könige 3:4-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/3/#v11003004-v11003028"}],"sources":[{"title":"Salomo – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004178"}]},{"id":"tempelbau","title":"Der Tempel wird gebaut","era":"koenigreich","year":-1034,"date":"1034–1027 v. u. Z.","place":"Jerusalem (Berg Moria)","summary":"Im zweiten Monat des vierten Regierungsjahres Salomos – im Frühjahr 1034 v. u. Z. – begann der Bau des Tempels, 479 volle Jahre nach dem Auszug aus Ägypten. Nach rund sieben Jahren wurde er 1027 v. u. Z. vollendet. Bei der Einweihung betete Salomo, und Jehovas Herrlichkeit erfüllte das Haus.","facts":[{"t":"Der Bau begann im 480. Jahr nach dem Auszug.","r":{"t":"1. Könige 6:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/6/#v11006001"}},{"t":"Der Tempel wurde nach sieben Jahren vollendet.","r":{"t":"1. Könige 6:37, 38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/6/#v11006037"}},{"t":"Salomo sprach bei der Einweihung ein Gebet.","r":{"t":"1. Könige 8:22-53","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/8/#v11008022-v11008053"}},{"t":"Die Herrlichkeit Jehovas erfüllte das Haus.","r":{"t":"2. Chronika 7:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/7/#v14007001-v14007003"}}],"significance":"Das Datum 1034 v. u. Z. ist ein wichtiger Anhaltspunkt der biblischen Zeitrechnung.","persons":["salomo"],"refs":[{"t":"1. Könige 6:1-38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/6/#v11006001-v11006038"},{"t":"1. Könige 8:1-66","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/8/#v11008001-v11008066"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Tempel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004359"},{"title":"B8 Der Tempel Salomos – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070228"}]},{"id":"besuch-der-koenigin-von-saba","title":"Die Königin von Scheba besucht Salomo","era":"koenigreich","year":-1020,"date":"Nach der Vollendung von Salomos Bauten","place":"Jerusalem","summary":"Einige Zeit nachdem Salomo viele Bauwerke vollendet hatte, kam die Königin von Scheba nach Jerusalem. Sie hatte vom Ruf Salomos „in Verbindung mit dem Namen Jehovas“ gehört und prüfte ihn mit schwierigen Fragen. Überwältigt von seiner Weisheit und dem Wohlstand seines Reiches pries sie Jehova und beschenkte den König reich.","facts":[{"t":"Sie kam mit einem eindrucksvollen Tross.","r":{"t":"1. Könige 10:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/10/#v11010001"}},{"t":"Salomo beantwortete alle ihre Fragen.","r":{"t":"1. Könige 10:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/10/#v11010003"}},{"t":"Sie sagte, nicht die Hälfte sei ihr berichtet worden.","r":{"t":"1. Könige 10:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/10/#v11010007"}},{"t":"Jesus erwähnte ihren Besuch.","r":{"t":"Lukas 11:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/11/#v42011031"}}],"significance":"","persons":["koenigin-von-saba","salomo"],"refs":[{"t":"1. Könige 10:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/10/#v11010001-v11010013"},{"t":"2. Chronika 9:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/9/#v14009001-v14009012"}],"sources":[{"title":"Scheba – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003970"}]},{"id":"reichsteilung","title":"Das Königreich wird geteilt","era":"geteilt","year":-997,"date":"997 v. u. Z.","place":"Sichem","summary":"Nach Salomos Tod bat das Volk Rehabeam, die schwere Last zu erleichtern. Doch Rehabeam folgte dem Rat der jungen Männer und drohte mit noch härterer Behandlung. Daraufhin sagten sich zehn Stämme vom Haus Davids los und machten Jerobeam zum König. So entstanden das Zehnstämmereich Israel und das Zweistämmereich Juda und Benjamin – wie Jehova es wegen Salomos Untreue angekündigt hatte.","facts":[{"t":"Der Prophet Ahija hatte Jerobeam zehn Stämme angekündigt.","r":{"t":"1. Könige 11:29-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/11/#v11011029-v11011031"}},{"t":"Rehabeam verwarf den Rat der älteren Männer.","r":{"t":"1. Könige 12:8-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/12/#v11012008-v11012014"}},{"t":"Die zehn Stämme machten Jerobeam zum König.","r":{"t":"1. Könige 12:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/12/#v11012020"}},{"t":"Jerobeam führte den Kälberdienst ein.","r":{"t":"1. Könige 12:28-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/12/#v11012028-v11012030"}}],"significance":"Von 997 v. u. Z. bis zum Fall Jerusalems 607 v. u. Z. vergingen 390 Jahre.","persons":["rehabeam","jerobeam","salomo"],"refs":[{"t":"1. Könige 11:26–12:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/11/#v11011026-v11012033"},{"t":"2. Chronika 10:1-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/10/#v14010001-v14010019"}],"sources":[{"title":"Rehabeam – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003680"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"elia-und-die-duerre","title":"Elia kündigt eine Dürre an","era":"geteilt","year":-936,"date":"Zur Zeit Ahabs","place":"Samaria; Wildbachtal Krith; Zarephath","summary":"Weil Ahab den Baalskult förderte, kündigte Elia an, dass es weder Tau noch Regen geben werde, außer auf sein Wort. Die Dürre dauerte dreieinhalb Jahre. Jehova versorgte Elia zuerst durch Raben am Wildbach Krith, dann durch eine Witwe in Zarephath, deren Mehl und Öl nicht ausgingen. Als ihr Sohn starb, erweckte Elia ihn zum Leben.","facts":[{"t":"Elia kündigte die Dürre an.","r":{"t":"1. Könige 17:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/17/#v11017001"}},{"t":"Die Dürre dauerte drei Jahre und sechs Monate.","r":{"t":"Jakobus 5:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jakobus/5/#v59005017"}},{"t":"Mehl und Öl der Witwe gingen nicht aus.","r":{"t":"1. Könige 17:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/17/#v11017014-v11017016"}},{"t":"Elia erweckte ihren Sohn.","r":{"t":"1. Könige 17:21-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/17/#v11017021-v11017024"}}],"significance":"","persons":["elia","ahab"],"refs":[{"t":"1. Könige 17:1-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/17/#v11017001-v11017024"},{"t":"Lukas 4:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/4/#v42004025"}],"sources":[{"title":"Elia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001307"},{"title":"Ahab – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000138"}]},{"id":"elia-auf-dem-karmel","title":"Elia auf dem Berg Karmel","era":"geteilt","year":-933,"date":"Zur Zeit Ahabs","place":"Berg Karmel","summary":"Auf dem Karmel forderte Elia 450 Baalspropheten heraus: Der Gott, der mit Feuer antwortet, ist der wahre Gott. Die Baalspropheten riefen stundenlang vergeblich. Elia baute den Altar Jehovas wieder auf, übergoss Opfer und Holz mit Wasser und betete. Jehova sandte Feuer, das alles verzehrte. Das Volk rief: „Jehova ist der wahre Gott!“ Danach kam der Regen.","facts":[{"t":"Elia fragte: „Wie lange werdet ihr auf zwei Meinungen hinken?“","r":{"t":"1. Könige 18:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/18/#v11018021"}},{"t":"Baal antwortete nicht.","r":{"t":"1. Könige 18:26-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/18/#v11018026-v11018029"}},{"t":"Jehova sandte Feuer vom Himmel.","r":{"t":"1. Könige 18:36-38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/18/#v11018036-v11018038"}},{"t":"Danach endete die Dürre.","r":{"t":"1. Könige 18:41-45","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/18/#v11018041-v11018045"}}],"significance":"","persons":["elia","ahab"],"refs":[{"t":"1. Könige 18:17-46","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/18/#v11018017-v11018046"}],"sources":[{"title":"Elia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001307"}]},{"id":"elia-am-horeb","title":"Elia am Horeb","era":"geteilt","year":-932,"date":"Zur Zeit Ahabs","place":"Berg Horeb","summary":"Nach dem Sieg auf dem Karmel schwor Isebel, Elia zu töten. Elia floh in die Wildnis und wünschte sich den Tod. Ein Engel stärkte ihn, und er wanderte bis zum Horeb. Dort sprach Jehova zu ihm mit einer „ruhigen, leisen Stimme“, sagte ihm, dass es noch 7000 Treue in Israel gab, und beauftragte ihn, Elisa als Nachfolger zu berufen sowie Hasael und Jehu zu salben.","facts":[{"t":"Isebel drohte Elia mit dem Tod.","r":{"t":"1. Könige 19:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/19/#v11019001"}},{"t":"Ein Engel versorgte ihn mit Nahrung.","r":{"t":"1. Könige 19:5-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/19/#v11019005-v11019008"}},{"t":"Jehova sprach mit einer ruhigen, leisen Stimme.","r":{"t":"1. Könige 19:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/19/#v11019011-v11019013"}},{"t":"7000 hatten ihr Knie nicht vor Baal gebeugt.","r":{"t":"1. Könige 19:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/19/#v11019018"}}],"significance":"","persons":["elia","isebel","elisa","jehu"],"refs":[{"t":"1. Könige 19:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-K%C3%B6nige/19/#v11019001-v11019021"}],"sources":[{"title":"Elia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001307"},{"title":"Jehu – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002401"}]},{"id":"elia-wird-weggenommen","title":"Elia wird im Sturmwind weggenommen","era":"geteilt","year":-917,"date":"Nach dem Tod Ahasjas von Israel","place":"Östlich des Jordan","summary":"Elisa begleitete Elia bis zuletzt und bat um „zwei Anteile“ von seinem Geist. Dann sah er einen feurigen Kriegswagen und Elia in einem Windsturm aufsteigen. Laut jw.org starb Elia dabei nicht und kam auch nicht in den geistigen Himmel, sondern wurde mit einem neuen Auftrag an einen anderen Ort gebracht – Jahre später schrieb er noch einen Brief an König Joram von Juda. Elisa nahm Elias Amtsgewand auf und wurde sein Nachfolger.","facts":[{"t":"Elisa erbat zwei Anteile von Elias Geist.","r":{"t":"2. Könige 2:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/2/#v12002009"}},{"t":"Ein feuriger Kriegswagen trennte die beiden.","r":{"t":"2. Könige 2:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/2/#v12002011"}},{"t":"Elisa nahm Elias Amtsgewand auf.","r":{"t":"2. Könige 2:13, 14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/2/#v12002013"}},{"t":"Niemand ist in den Himmel hinaufgestiegen außer dem Menschensohn.","r":{"t":"Johannes 3:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/3/#v43003013"}}],"significance":"","persons":["elia","elisa"],"refs":[{"t":"2. Könige 2:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/2/#v12002001-v12002015"},{"t":"2. Chronika 21:12-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/21/#v14021012-v14021015"}],"sources":[{"title":"Elia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001307"}]},{"id":"naaman-wird-geheilt","title":"Naaman wird geheilt","era":"geteilt","year":-910,"date":"Zur Zeit Jorams von Israel","place":"Samaria; Jordan","summary":"Der aussätzige syrische Heerführer Naaman kam auf Rat eines israelitischen Mädchens zu Elisa. Der Prophet ließ ihm ausrichten, er solle sich siebenmal im Jordan waschen. Erst war Naaman empört, doch seine Diener überredeten ihn. Als er gehorchte, wurde er völlig gesund und erklärte, er werde nur noch Jehova anbeten. Elisas Diener Gehasi dagegen erschlich sich Geschenke und wurde aussätzig.","facts":[{"t":"Das verschleppte Mädchen sprach vom Propheten in Samaria.","r":{"t":"2. Könige 5:2, 3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005002"}},{"t":"Naaman wurde zornig über die einfache Anweisung.","r":{"t":"2. Könige 5:11, 12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005011"}},{"t":"Nach dem siebten Mal wurde er rein.","r":{"t":"2. Könige 5:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005014"}},{"t":"Gehasi wurde wegen seiner Habgier aussätzig.","r":{"t":"2. Könige 5:20-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005020-v12005027"}}],"significance":"","persons":["naaman","elisa","joram-israel"],"refs":[{"t":"2. Könige 5:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/5/#v12005001-v12005027"},{"t":"Lukas 4:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/4/#v42004027"}],"sources":[{"title":"Naaman – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003149"}]},{"id":"athalja-und-joas","title":"Athalja reißt die Macht an sich","era":"geteilt","year":-905,"date":"um 905–898 v. u. Z.","place":"Jerusalem","summary":"Nach dem Tod ihres Sohnes Ahasja ließ Athalja, die Tochter Ahabs und Isebels, die königliche Nachkommenschaft Judas umbringen und machte sich zur Königin. Doch Jehoscheba rettete den kleinen Joas und verbarg ihn sechs Jahre im Tempel. Im siebten Jahr ließ der Hohe Priester Jehojada Joas zum König krönen; Athalja wurde getötet, und das Volk zerstörte das Haus Baals.","facts":[{"t":"Athalja vernichtete die königliche Nachkommenschaft.","r":{"t":"2. Könige 11:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011001"}},{"t":"Joas wurde sechs Jahre versteckt.","r":{"t":"2. Könige 11:2, 3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011002"}},{"t":"Jehojada ließ Joas krönen.","r":{"t":"2. Könige 11:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011012"}},{"t":"Das Haus Baals wurde niedergerissen.","r":{"t":"2. Könige 11:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011018"}}],"significance":"Durch die Rettung des Joas blieb die königliche Linie Davids erhalten.","persons":["athalja","joas-juda","jojada"],"refs":[{"t":"2. Könige 11:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/11/#v12011001-v12011021"},{"t":"2. Chronika 22:10–23:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/22/#v14022010-v14023021"}],"sources":[{"title":"Jehojada – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002376"},{"title":"Athalja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000457"}]},{"id":"jehu-vollstreckt-gericht","title":"Jehu vollstreckt das Urteil an Ahabs Haus","era":"geteilt","year":-905,"date":"um 905 v. u. Z.","place":"Ramoth-Gilead; Jesreel; Samaria","summary":"Ein Prophetensohn salbte im Auftrag Elisas den Heeroberst Jehu zum König über Israel. Jehu handelte sofort: Er fuhr nach Jesreel, tötete König Joram von Israel und König Ahasja von Juda und ließ Isebel aus dem Fenster stürzen. Danach rottete er die Nachkommen Ahabs und die Baalsanbeter aus – doch die goldenen Kälber Jerobeams ließ er bestehen.","facts":[{"t":"Jehu wurde in Ramoth-Gilead gesalbt.","r":{"t":"2. Könige 9:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009001-v12009006"}},{"t":"Er fuhr „wie ein Wahnsinniger“.","r":{"t":"2. Könige 9:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009020"}},{"t":"Isebel wurde aus dem Fenster geworfen.","r":{"t":"2. Könige 9:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009033"}},{"t":"Er tilgte Baal aus Israel.","r":{"t":"2. Könige 10:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/10/#v12010028"}}],"significance":"","persons":["jehu","joram-israel","ahasja-juda","isebel","elisa"],"refs":[{"t":"2. Könige 9:1–10:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/9/#v12009001-v12010031"}],"sources":[{"title":"Jehu – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002401"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"jona-in-ninive","title":"Jona predigt in Ninive","era":"geteilt","year":-844,"date":"um 844 v. u. Z.","place":"Joppe; Ninive","summary":"Jona sollte der großen assyrischen Stadt Ninive Jehovas Urteil verkünden, floh aber per Schiff. Ein Sturm brach los, die Seeleute warfen ihn ins Meer, und ein großer Fisch verschlang ihn. Nach drei Tagen spie ihn der Fisch aus. Beim zweiten Auftrag ging Jona nach Ninive; die Einwohner glaubten Gott und bereuten, und Jehova verschonte die Stadt.","facts":[{"t":"Jona floh in Richtung Tarschisch.","r":{"t":"Jona 1:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jona/1/#v32001003"}},{"t":"Er war drei Tage im Fisch.","r":{"t":"Jona 1:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jona/1/#v32001017"}},{"t":"„Noch vierzig Tage, und Ninive wird umgekehrt.“","r":{"t":"Jona 3:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jona/3/#v32003004"}},{"t":"Jesus nannte das „Zeichen Jonas“.","r":{"t":"Matthäus 12:39-41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/12/#v40012039-v40012041"}}],"significance":"","persons":["jona"],"refs":[{"t":"Jona 1:1–4:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jona/1/#v32001001-v32004011"}],"sources":[{"title":"Jona – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002503"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"jesaja-wird-berufen","title":"Jesaja wird Prophet","era":"geteilt","year":-778,"date":"um 778 v. u. Z.","place":"Jerusalem","summary":"In dem Jahr, in dem König Usija starb, sah Jesaja in einer Vision Jehova auf einem hohen Thron, umgeben von Seraphen. Als Jehova fragte, wen er senden solle, antwortete Jesaja: „Hier bin ich! Sende mich.“ Er erfuhr, dass das Volk nicht hören würde, bis das Land verwüstet sei – doch ein „heiliger Same“ würde übrig bleiben.","facts":[{"t":"Er sah Jehova auf einem erhabenen Thron.","r":{"t":"Jesaja 6:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/6/#v23006001-v23006004"}},{"t":"Er bot sich bereitwillig an.","r":{"t":"Jesaja 6:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/6/#v23006008"}},{"t":"Ein Überrest – wie ein Baumstumpf – sollte bleiben.","r":{"t":"Jesaja 6:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/6/#v23006011-v23006013"}}],"significance":"","persons":["jesaja","usija"],"refs":[{"t":"Jesaja 6:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/6/#v23006001-v23006013"}],"sources":[{"title":"Jesaja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002204"}]},{"id":"fall-samarias","title":"Samaria fällt","era":"geteilt","year":-740,"date":"740 v. u. Z.","place":"Samaria","summary":"Weil König Hoschea sich gegen Assyrien auflehnte und Hilfe bei Ägypten suchte, belagerte das assyrische Heer Samaria drei Jahre lang. 740 v. u. Z. fiel die Stadt; das Zehnstämmereich Israel hörte auf zu bestehen, und seine Bewohner wurden ins Exil geführt. Die Bibel nennt als Grund, dass Israel Jehova verlassen und anderen Göttern gedient hatte. Assyrien siedelte Menschen aus anderen Ländern in Samaria an.","facts":[{"t":"Die Belagerung begann 742 v. u. Z.","r":{"t":"2. Könige 17:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/17/#v12017005"}},{"t":"Im 9. Jahr Hoscheas wurde Samaria eingenommen.","r":{"t":"2. Könige 17:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/17/#v12017006"}},{"t":"Israel hatte Jehovas Warnungen nicht beachtet.","r":{"t":"2. Könige 17:13-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/17/#v12017013-v12017018"}},{"t":"Fremde wurden in den Städten Samarias angesiedelt.","r":{"t":"2. Könige 17:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/17/#v12017024"}}],"significance":"Das Ende des Nordreichs Israel – im 6. Jahr Hiskias von Juda.","persons":["hosea-koenig"],"refs":[{"t":"2. Könige 17:1-41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/17/#v12017001-v12017041"},{"t":"2. Könige 18:9-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/18/#v12018009-v12018012"}],"sources":[{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"},{"title":"Hoschea – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002090"}]},{"id":"sanherib-bedroht-jerusalem","title":"Sanherib bedroht Jerusalem","era":"geteilt","year":-732,"date":"732 v. u. Z.","place":"Juda; Jerusalem","summary":"Im 14. Jahr Hiskias nahm der Assyrerkönig Sanherib die befestigten Städte Judas ein und forderte die Übergabe Jerusalems. Sein Sprecher verhöhnte Jehova vor den Mauern der Stadt. Hiskia breitete den Brief Sanheribs vor Jehova aus und betete; Jesaja überbrachte Jehovas Antwort. In einer Nacht tötete der Engel Jehovas 185 000 Assyrer, und Sanherib kehrte nach Ninive zurück.","facts":[{"t":"Hiskia betete im Tempel um Rettung.","r":{"t":"2. Könige 19:14-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/19/#v12019014-v12019019"}},{"t":"Jesaja kündigte an, dass Sanherib die Stadt nicht betreten werde.","r":{"t":"2. Könige 19:32-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/19/#v12019032-v12019034"}},{"t":"Der Engel Jehovas schlug 185 000 Mann.","r":{"t":"2. Könige 19:35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/19/#v12019035"}}],"significance":"","persons":["hiskia","sanherib","jesaja"],"refs":[{"t":"2. Könige 18:13–19:37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/18/#v12018013-v12019037"},{"t":"Jesaja 36:1–37:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/36/#v23036001-v23037038"}],"sources":[{"title":"Hiskia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002011"},{"title":"Sanherib – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003897"}]},{"id":"jeremia-wird-berufen","title":"Jeremia wird Prophet","era":"geteilt","year":-647,"date":"647 v. u. Z.","place":"Juda","summary":"Im 13. Regierungsjahr Josias berief Jehova den jungen Jeremia zum Propheten: Schon bevor Jeremia geboren war, hatte Gott ihn dafür bestimmt. Jeremia wandte ein, er sei noch zu jung und könne nicht reden. Doch Jehova legte seine Worte in Jeremias Mund und versprach, mit ihm zu sein.","facts":[{"t":"Jehova sagte: „Bevor ich dich im Mutterleib bildete, kannte ich dich.“","r":{"t":"Jeremia 1:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/1/#v24001004"}},{"t":"Jeremia sagte: „Ich bin nur ein Knabe.“","r":{"t":"Jeremia 1:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/1/#v24001006"}},{"t":"Jehova legte seine Worte in seinen Mund.","r":{"t":"Jeremia 1:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/1/#v24001009"}}],"significance":"","persons":["jeremia","josia"],"refs":[{"t":"Jeremia 1:1-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/1/#v24001001-v24001019"}],"sources":[{"title":"Jeremia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002421"}]},{"id":"josias-reform","title":"Josia findet das Buch des Gesetzes","era":"geteilt","year":-642,"date":"642 v. u. Z.","place":"Jerusalem","summary":"Bei der Ausbesserung des Tempels fand der Hohe Priester Hilkija „das durch die Hand Mose übermittelte Buch des Gesetzes Jehovas“. Als man es König Josia vorlas, zerriss er seine Kleider. Er ließ Jehova durch die Prophetin Hulda befragen, las dem Volk den Bund vor, beseitigte den Götzendienst weiter und feierte im 18. Jahr seiner Regierung ein Passah wie keines zuvor.","facts":[{"t":"Hilkija fand das Buch im Haus Jehovas.","r":{"t":"2. Könige 22:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/22/#v12022008"}},{"t":"Josia zerriss beim Zuhören seine Kleider.","r":{"t":"2. Könige 22:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/22/#v12022011"}},{"t":"Das Volk trat in den Bund ein.","r":{"t":"2. Könige 23:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/23/#v12023001-v12023003"}},{"t":"Ein solches Passah war seit den Tagen der Richter nicht gefeiert worden.","r":{"t":"2. Könige 23:21-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/23/#v12023021-v12023023"}}],"significance":"","persons":["josia","hulda"],"refs":[{"t":"2. Könige 22:3–23:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/22/#v12022003-v12023025"},{"t":"2. Chronika 34:8–35:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/34/#v14034008-v14035019"}],"sources":[{"title":"Josia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002525"},{"title":"Hulda – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002101"}]},{"id":"fall-ninives","title":"Ninive wird zerstört","era":"geteilt","year":-632,"date":"632 v. u. Z.","place":"Ninive (Assyrien)","summary":"Ninive, die Hauptstadt des Assyrischen Reiches, wurde von den Streitkräften Nabupolassars von Babylon und Kyaxares’, des Meders, belagert und eingenommen. Die Stadt wurde offensichtlich durch Feuer zerstört. Damit erfüllten sich die Prophezeiungen Nahums und Zephanjas über Ninive.","facts":[{"t":"Nahum hatte die Verwüstung Ninives vorhergesagt.","r":{"t":"Nahum 3:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nahum/3/#v34003007"}},{"t":"Auch Zephanja kündigte Ninives Untergang an.","r":{"t":"Zephanja 2:13-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/zephanja/2/#v36002013-v36002015"}},{"t":"Assyrische Reliefs zeigen Spuren von Feuer und Rauch."}],"significance":"","persons":["nahum","zephanja"],"refs":[{"t":"Nahum 3:1-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nahum/3/#v34003001-v34003019"},{"t":"Zephanja 2:13-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/zephanja/2/#v36002013-v36002015"}],"sources":[{"title":"Ninive – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003261"}]},{"id":"wegfuehrung-jojachins","title":"Jojachin wird nach Babylon weggeführt","era":"geteilt","year":-617,"date":"617 v. u. Z.","place":"Jerusalem; Babylon","summary":"Nachdem sich Jojakim gegen Babylon aufgelehnt hatte, belagerte Nebukadnezar Jerusalem. König Jojachin ergab sich nach nur drei Monaten und zehn Tagen. Nebukadnezar führte ihn mit seiner Familie, den Fürsten, den Kriegern und den Handwerkern nach Babylon – unter ihnen auch Hesekiel. Er nahm Tempelschätze mit und setzte Zedekia als König ein.","facts":[{"t":"Jojachin ergab sich dem König von Babylon.","r":{"t":"2. Könige 24:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024012"}},{"t":"Tausende wurden weggeführt.","r":{"t":"2. Könige 24:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024014-v12024016"}},{"t":"Nebukadnezar setzte Mattanja (Zedekia) ein.","r":{"t":"2. Könige 24:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024017"}}],"significance":"","persons":["jojachin","nebukadnezar","zedekia","hesekiel"],"refs":[{"t":"2. Könige 24:8-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024008-v12024017"}],"sources":[{"title":"Jojachin – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002375"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"zerstoerung-jerusalems-607","title":"Babylon zerstört Jerusalem","era":"geteilt","year":-607,"date":"607 v. u. Z.","place":"Jerusalem","summary":"Weil sich Zedekia gegen Babylon auflehnte, belagerte Nebukadnezar ab 609 v. u. Z. Jerusalem. Am 9. Tag des 4. Monats 607 v. u. Z. wurden die Mauern durchbrochen, am 10. Tag des 5. Monats Stadt und Tempel niedergebrannt. Nachdem die letzten Juden um die Mitte des 7. Monats das Land verlassen hatten, lag Juda verödet da – der Beginn der vorhergesagten 70 Jahre.","facts":[{"t":"Die Belagerung begann 609 v. u. Z.","r":{"t":"2. Könige 25:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/25/#v12025001"}},{"t":"Der Tempel und die Stadt wurden verbrannt.","r":{"t":"Jeremia 52:12, 13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/52/#v24052012"}},{"t":"Zedekia wurde geblendet und nach Babylon gebracht.","r":{"t":"2. Könige 25:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/25/#v12025007"}},{"t":"Das Land sollte 70 Jahre verwüstet liegen.","r":{"t":"2. Chronika 36:20, 21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/36/#v14036020"}}],"significance":"Mit 607 v. u. Z. begannen die 70 Jahre der Verwüstung, die 537 v. u. Z. endeten.","persons":["zedekia","nebukadnezar","jeremia","ebed-melech"],"refs":[{"t":"2. Könige 25:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/25/#v12025001-v12025021"},{"t":"Jeremia 39:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/39/#v24039001-v24039010"},{"t":"Jeremia 52:1-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/52/#v24052001-v24052030"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Chronologie – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000970"}]},{"id":"daniel-in-babylon","title":"Daniel und seine Freunde in Babylon","era":"exil","year":-617,"date":"617 v. u. Z.","place":"Babylon","summary":"Anfang 617 v. u. Z. führte Nebukadnezar König Jojachin und die Vornehmsten Judas nach Babylon – unter ihnen den jungen Daniel und seine Gefährten Hananja, Mischael und Asarja. Sie sollten für den Staatsdienst ausgebildet werden und erhielten babylonische Namen. Weil sie sich nicht mit den Speisen des Königs verunreinigen wollten, baten sie um Gemüse und Wasser. Nach drei Jahren waren sie zehnmal besser als alle Weisen des Reiches.","facts":[{"t":"Sie erhielten babylonische Namen.","r":{"t":"Daniel 1:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001006"}},{"t":"Daniel beschloss, sich nicht zu verunreinigen.","r":{"t":"Daniel 1:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001008"}},{"t":"Nach zehn Tagen sahen sie besser aus als die anderen.","r":{"t":"Daniel 1:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001015"}},{"t":"Jehova gab ihnen Erkenntnis und Einsicht.","r":{"t":"Daniel 1:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001017"}}],"significance":"","persons":["daniel","hananja","mischael","asarja","nebukadnezar"],"refs":[{"t":"Daniel 1:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/1/#v27001001-v27001021"},{"t":"2. Könige 24:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-K%C3%B6nige/24/#v12024015"}],"sources":[{"title":"Daniel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001117"}]},{"id":"hesekiel-wird-prophet","title":"Hesekiel wird Prophet","era":"exil","year":-613,"date":"613 v. u. Z.","place":"Am Strom Kebar (Babylonien)","summary":"Im fünften Jahr des Exils König Jojachins sah Hesekiel am Strom Kebar eine überwältigende Vision von Jehovas Herrlichkeit und seinem himmlischen Wagen. Er war damals offenbar 30 Jahre alt. Jehova machte ihn zum Wächter für das Haus Israel und sandte ihn zu den Weggeführten – zur selben Zeit, als Jeremia in Jerusalem prophezeite.","facts":[{"t":"Die Vision kam im 30. Jahr, im 4. Monat.","r":{"t":"Hesekiel 1:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/1/#v26001001-v26001003"}},{"t":"Er sah lebende Geschöpfe und Räder.","r":{"t":"Hesekiel 1:4-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/1/#v26001004-v26001021"}},{"t":"Er sollte ein Wächter sein.","r":{"t":"Hesekiel 3:17-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/3/#v26003017-v26003021"}}],"significance":"","persons":["hesekiel","jojachin"],"refs":[{"t":"Hesekiel 1:1–3:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/hesekiel/1/#v26001001-v26003027"}],"sources":[{"title":"Hesekiel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001469"}]},{"id":"traum-vom-standbild","title":"Nebukadnezars Traum vom Standbild","era":"exil","year":-605,"date":"Im „2. Jahr“ Nebukadnezars (wahrscheinlich ab 607 v. u. Z. gerechnet)","place":"Babylon","summary":"Nebukadnezar hatte einen beunruhigenden Traum, den keiner seiner Weisen nennen oder deuten konnte. Gott offenbarte Daniel den Traum: ein riesiges Standbild aus Gold, Silber, Kupfer, Eisen und Ton, das von einem Stein zermalmt wird. Daniel erklärte, dass die Metalle aufeinanderfolgende Weltmächte darstellen und der Stein Gottes Königreich ist, das alle diese Reiche beenden und für immer bestehen wird.","facts":[{"t":"Keiner der Weisen konnte den Traum kundtun.","r":{"t":"Daniel 2:10, 11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002010"}},{"t":"Daniel bat seine Gefährten um Gebet.","r":{"t":"Daniel 2:17, 18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002017"}},{"t":"Das goldene Haupt stellte Nebukadnezar dar.","r":{"t":"Daniel 2:37, 38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002037"}},{"t":"Gottes Königreich wird für immer bestehen.","r":{"t":"Daniel 2:44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002044"}}],"significance":"Die Prophezeiung zeigt die Abfolge der Weltmächte bis zu Gottes Königreich.","persons":["nebukadnezar","daniel"],"refs":[{"t":"Daniel 2:1-49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/2/#v27002001-v27002049"}],"sources":[{"title":"Daniel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001117"},{"title":"B9 Weltmächte der Prophezeiung Daniels – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070229"}]},{"id":"feuerofen","title":"Die drei Hebräer im Feuerofen","era":"exil","year":-600,"date":"Zeitpunkt unbekannt","place":"Ebene Dura (Babylon)","summary":"Nebukadnezar ließ in der Ebene Dura ein riesiges goldenes Standbild aufstellen und befahl allen, sich davor niederzuwerfen. Hananja, Mischael und Asarja (Schadrach, Meschach und Abednego) weigerten sich. Der König ließ sie in den übermäßig geheizten Feuerofen werfen – doch er sah vier Männer frei im Feuer umhergehen. Die drei kamen unversehrt heraus; nicht einmal ihr Haar war versengt.","facts":[{"t":"Sie sagten, sie würden dem Bild nicht dienen.","r":{"t":"Daniel 3:16-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003016-v27003018"}},{"t":"Der Ofen wurde siebenmal stärker geheizt.","r":{"t":"Daniel 3:19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003019"}},{"t":"Der König sah vier Männer im Feuer.","r":{"t":"Daniel 3:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003024"}},{"t":"Das Feuer hatte keine Macht über sie.","r":{"t":"Daniel 3:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003027"}}],"significance":"","persons":["hananja","mischael","asarja","nebukadnezar"],"refs":[{"t":"Daniel 3:1-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/3/#v27003001-v27003030"}],"sources":[{"title":"Asarja – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000486"}]},{"id":"nebukadnezars-wahnsinn","title":"Nebukadnezars Wahnsinn","era":"exil","year":-590,"date":"Während seiner Regierung (624–582 v. u. Z.)","place":"Babylon","summary":"Nebukadnezar träumte von einem gewaltigen Baum, der gefällt wurde. Daniel deutete den Traum: Der König sollte „sieben Zeiten“ lang wie ein Tier leben, bis er erkenne, dass der Höchste über das Königreich der Menschen herrscht. Als Nebukadnezar sich seiner Größe rühmte, erfüllte sich das; er aß Pflanzen wie ein Stier. Danach erhielt er seinen Verstand zurück und pries den König der Himmel.","facts":[{"t":"Der Baum sollte gefällt werden, der Wurzelstock aber bleiben.","r":{"t":"Daniel 4:14, 15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/4/#v27004014"}},{"t":"„Sieben Zeiten“ sollten über ihm vergehen.","r":{"t":"Daniel 4:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/4/#v27004016"}},{"t":"Er aß Pflanzen wie Stiere.","r":{"t":"Daniel 4:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/4/#v27004033"}},{"t":"Danach pries er den König der Himmel.","r":{"t":"Daniel 4:34-37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/4/#v27004034-v27004037"}}],"significance":"","persons":["nebukadnezar","daniel"],"refs":[{"t":"Daniel 4:1-37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/4/#v27004001-v27004037"}],"sources":[{"title":"Nebukadnezar – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003200"}]},{"id":"fall-babylons","title":"Die Schrift an der Wand – Babylon fällt","era":"exil","year":-539,"date":"Oktober 539 v. u. Z.","place":"Babylon","summary":"Während Belsazar mit 1000 Großen feierte und aus den Gefäßen des Tempels Jehovas trank, schrieb eine Hand an die Wand. Daniel deutete die Worte: Gott hatte die Tage des Königreichs gezählt und es den Medern und Persern gegeben. In derselben Nacht eroberten die Truppen des Cyrus Babylon, und Belsazar wurde getötet. Darius der Meder empfing das Königreich.","facts":[{"t":"Belsazar ließ aus den Tempelgefäßen trinken.","r":{"t":"Daniel 5:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005002-v27005004"}},{"t":"„MENE, MENE, TEKEL und PARSIN.“","r":{"t":"Daniel 5:25-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005025-v27005028"}},{"t":"Belsazar wurde in derselben Nacht getötet.","r":{"t":"Daniel 5:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005030"}},{"t":"Jesaja hatte Cyrus als Eroberer angekündigt.","r":{"t":"Jesaja 45:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/45/#v23045001"}}],"significance":"539 v. u. Z. ist ein Schlüsseldatum der biblischen Zeitrechnung.","persons":["belsazar","daniel","cyrus","darius-der-meder"],"refs":[{"t":"Daniel 5:1-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/5/#v27005001-v27005031"},{"t":"Jesaja 45:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jesaja/45/#v23045001-v23045003"}],"sources":[{"title":"Belsazar – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000628"},{"title":"Cyrus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001102"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"loewengrube","title":"Daniel in der Löwengrube","era":"exil","year":-538,"date":"Unter Darius dem Meder (nach 539 v. u. Z.)","place":"Babylon","summary":"Darius setzte Daniel als einen von drei hohen Beamten ein. Neidische Würdenträger brachten den König dazu, ein unabänderliches Gesetz zu erlassen: 30 Tage lang durfte man nur den König bitten. Daniel betete weiterhin dreimal täglich zu Jehova und wurde in die Löwengrube geworfen. Jehovas Engel verschloss den Löwen das Maul; Darius ließ Daniel herausholen und die Verschwörer bestrafen.","facts":[{"t":"Daniel betete wie gewohnt dreimal am Tag.","r":{"t":"Daniel 6:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006010"}},{"t":"Der König konnte das Gesetz nicht ändern.","r":{"t":"Daniel 6:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006015"}},{"t":"Gott sandte seinen Engel.","r":{"t":"Daniel 6:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006022"}},{"t":"Darius befahl, den Gott Daniels zu fürchten.","r":{"t":"Daniel 6:26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006026"}}],"significance":"","persons":["daniel","darius-der-meder"],"refs":[{"t":"Daniel 6:1-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/6/#v27006001-v27006028"}],"sources":[{"title":"Daniel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001117"}]},{"id":"erlass-des-cyrus","title":"Der Erlass des Cyrus","era":"exil","year":-538,"date":"538/537 v. u. Z. (1. Jahr des Cyrus)","place":"Babylon","summary":"In seinem ersten Jahr, vor dem Frühjahr 537 v. u. Z., erließ Cyrus eine Verordnung: Die Juden durften nach Jerusalem zurückkehren und das Haus Jehovas wieder aufbauen. Er gab ihnen die Gefäße des Tempels zurück, die Nebukadnezar mitgenommen hatte. So erfüllte sich Jeremias Prophezeiung über 70 Jahre.","facts":[{"t":"Cyrus sagte, Jehova habe ihm aufgetragen, ihm ein Haus zu bauen.","r":{"t":"Esra 1:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/1/#v15001002"}},{"t":"Jeder Jude durfte hinaufziehen.","r":{"t":"Esra 1:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/1/#v15001003"}},{"t":"Die Tempelgeräte wurden zurückgegeben.","r":{"t":"Esra 1:7-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/1/#v15001007-v15001011"}},{"t":"Jeremia hatte 70 Jahre angekündigt.","r":{"t":"Jeremia 29:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/jeremia/29/#v24029010"}}],"significance":"","persons":["cyrus","daniel"],"refs":[{"t":"Esra 1:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/1/#v15001001-v15001011"},{"t":"2. Chronika 36:22, 23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-chronika/36/#v14036022"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Cyrus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001102"}]},{"id":"rueckkehr-nach-jerusalem","title":"Die Juden kehren nach Jerusalem zurück","era":"rueckkehr","year":-537,"date":"Herbst 537 v. u. Z.","place":"Jerusalem","summary":"Unter Serubbabel und dem Hohen Priester Jeschua kehrte ein Überrest aus Babylon zurück. Bis zum siebten Monat (Tischri) waren die Israeliten wieder in ihren Städten; sie bauten den Altar wieder auf und brachten Opfer dar. Im Herbst 537 v. u. Z. war damit die Anbetung Jehovas in Jerusalem wiederhergestellt – genau 70 Jahre nach der Verwüstung des Landes.","facts":[{"t":"Serubbabel und Jeschua führten die Gruppe an.","r":{"t":"Esra 2:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/2/#v15002001"}},{"t":"Im siebten Monat versammelte sich das Volk in Jerusalem.","r":{"t":"Esra 3:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/3/#v15003001"}},{"t":"Sie bauten den Altar und opferten.","r":{"t":"Esra 3:2-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/3/#v15003002-v15003006"}}],"significance":"Mit dem Herbst 537 v. u. Z. endeten die 70 Jahre der Verwüstung.","persons":["serubbabel","jeschua"],"refs":[{"t":"Esra 2:1–3:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/2/#v15002001-v15003007"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Serubbabel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004716"}]},{"id":"tempelfundament","title":"Das Fundament des Tempels wird gelegt","era":"rueckkehr","year":-536,"date":"536 v. u. Z.","place":"Jerusalem","summary":"Im zweiten Monat des zweiten Jahres nach der Rückkehr (536 v. u. Z.) begannen Serubbabel, Jeschua und die Leviten mit dem eigentlichen Bau des Tempels. Als das Fundament gelegt war, jubelten viele, während ältere Männer, die den früheren Tempel gekannt hatten, laut weinten. Bald darauf behinderten Gegner das Werk, und der Bau kam zum Stillstand.","facts":[{"t":"Der Bau begann im zweiten Monat des zweiten Jahres.","r":{"t":"Esra 3:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/3/#v15003008"}},{"t":"Freudengeschrei und Weinen waren zu hören.","r":{"t":"Esra 3:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/3/#v15003011-v15003013"}},{"t":"Gegner entmutigten das Volk.","r":{"t":"Esra 4:4, 5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/4/#v15004004"}}],"significance":"","persons":["serubbabel","jeschua"],"refs":[{"t":"Esra 3:8-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/3/#v15003008-v15003013"},{"t":"Esra 4:1-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/4/#v15004001-v15004024"}],"sources":[{"title":"Serubbabel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004716"}]},{"id":"tempel-vollendet","title":"Der Tempel wird vollendet","era":"rueckkehr","year":-515,"date":"515 v. u. Z.","place":"Jerusalem","summary":"Im zweiten Jahr des Perserkönigs Darius Hystaspis (520 v. u. Z.) spornten die Propheten Haggai und Sacharja Serubbabel, Jeschua und das Volk an, den liegengebliebenen Tempelbau wieder aufzunehmen. Darius bestätigte den früheren Erlass des Cyrus. 515 v. u. Z. wurde der Tempel vollendet und mit großer Freude eingeweiht.","facts":[{"t":"Haggai sprach seine Botschaften 520 v. u. Z.","r":{"t":"Haggai 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/1/#v37001001"}},{"t":"Die Propheten unterstützten die Bauleute.","r":{"t":"Esra 5:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/5/#v15005001"}},{"t":"Der Tempel wurde im 6. Jahr des Darius vollendet.","r":{"t":"Esra 6:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/6/#v15006015"}},{"t":"Das Volk feierte die Einweihung mit Freuden.","r":{"t":"Esra 6:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/6/#v15006016"}}],"significance":"","persons":["serubbabel","jeschua","haggai","sacharja"],"refs":[{"t":"Esra 5:1–6:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/5/#v15005001-v15006022"},{"t":"Haggai 1:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/haggai/1/#v37001001-v37001015"}],"sources":[{"title":"Serubbabel – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004716"},{"title":"Haggai – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001812"}]},{"id":"esther-wird-koenigin","title":"Esther wird Königin","era":"rueckkehr","year":-489,"date":"Im 7. Regierungsjahr des Ahasverus (5. Jh. v. u. Z.)","place":"Susa (Persien)","summary":"Nachdem König Ahasverus Königin Waschti wegen ihres Ungehorsams verstoßen hatte, ließ er im ganzen Reich schöne junge Frauen zusammenbringen. Auch die Jüdin Esther wurde in den Palast gebracht; auf Mordechais Rat verschwieg sie ihre Herkunft. Im 7. Jahr seiner Regierung wählte der König sie zur Königin.","facts":[{"t":"Waschti weigerte sich, vor dem König zu erscheinen.","r":{"t":"Esther 1:10-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/1/#v17001010-v17001012"}},{"t":"Esther verschwieg, dass sie Jüdin war.","r":{"t":"Esther 2:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002010"}},{"t":"Der König liebte Esther mehr als alle anderen.","r":{"t":"Esther 2:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/2/#v17002017"}}],"significance":"","persons":["esther","mordechai","ahasverus"],"refs":[{"t":"Esther 1:1–2:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/1/#v17001001-v17002023"}],"sources":[{"title":"Ahasverus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000142"},{"title":"Esther – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001430"}]},{"id":"esther-rettet-ihr-volk","title":"Esther rettet ihr Volk","era":"rueckkehr","year":-484,"date":"Im 12. Regierungsjahr des Ahasverus","place":"Susa (Persien)","summary":"Im 12. Jahr des Ahasverus erwirkte der erste Minister Haman einen Erlass zur Ausrottung aller Juden in den 127 Gerichtsbezirken. Mordechai bat Esther einzuschreiten. Unter Lebensgefahr ging sie ungerufen zum König, lud ihn und Haman zu Festmählern ein und deckte dort Hamans Plan auf. Haman wurde gehängt, und die Juden durften sich verteidigen. Zur Erinnerung wird das Purimfest gefeiert.","facts":[{"t":"Haman warf das Los (Pur) für den Tag der Vernichtung.","r":{"t":"Esther 3:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/3/#v17003007"}},{"t":"Esther ging ungerufen zum König.","r":{"t":"Esther 5:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/5/#v17005001"}},{"t":"Haman wurde an seinem eigenen Pfahl gehängt.","r":{"t":"Esther 7:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/7/#v17007009"}},{"t":"Das Purimfest wurde eingeführt.","r":{"t":"Esther 9:20-28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/9/#v17009020-v17009028"}}],"significance":"","persons":["esther","mordechai","haman","ahasverus"],"refs":[{"t":"Esther 3:1–9:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esther/3/#v17003001-v17009032"}],"sources":[{"title":"Esther – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001430"},{"title":"Purim – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003588"}]},{"id":"esra-kommt-nach-jerusalem","title":"Esra kommt nach Jerusalem","era":"rueckkehr","year":-468,"date":"468 v. u. Z.","place":"Babylon; Jerusalem","summary":"Im 7. Jahr des Artaxerxes erhielt der Priester und Abschreiber Esra die Erlaubnis, mit einer Gruppe von Juden nach Jerusalem zu ziehen, und reiche Gaben für den Tempel. Weil er dem König gesagt hatte, dass Gott seine Diener beschützt, verzichtete er auf eine militärische Eskorte und bat stattdessen fastend um Jehovas Schutz. In Jerusalem lehrte er das Gesetz und ging gegen Ehen mit Frauen aus den Nationen vor.","facts":[{"t":"Esra war ein kundiger Abschreiber des Gesetzes.","r":{"t":"Esra 7:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/7/#v15007006"}},{"t":"Er fastete und betete um eine sichere Reise.","r":{"t":"Esra 8:21-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/8/#v15008021-v15008023"}},{"t":"Die Reise dauerte rund vier Monate.","r":{"t":"Esra 7:8, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/7/#v15007008"}}],"significance":"","persons":["esra","artaxerxes"],"refs":[{"t":"Esra 7:1–10:44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/esra/7/#v15007001-v15010044"}],"sources":[{"title":"Esra – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001475"}]},{"id":"nehemia-baut-die-mauer","title":"Nehemia baut die Mauer Jerusalems","era":"rueckkehr","year":-455,"date":"455 v. u. Z.","place":"Jerusalem","summary":"Im 20. Jahr des Artaxerxes erhielt Nehemia die Erlaubnis, die Mauer Jerusalems wieder aufzubauen. Trotz Spott, Drohungen und Intrigen von Sanballat, Tobija und anderen arbeiteten die Juden – mit Waffen griffbereit – und vollendeten die Mauer in nur 52 Tagen. Mit diesem „Wort, Jerusalem wiederherzustellen“, begannen die 69 Jahrwochen, die zum Messias führten.","facts":[{"t":"Nehemia inspizierte nachts die Mauer.","r":{"t":"Nehemia 2:11-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/2/#v16002011-v16002016"}},{"t":"Die Bauleute arbeiteten mit einer Hand und hielten mit der anderen eine Waffe.","r":{"t":"Nehemia 4:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/4/#v16004017"}},{"t":"Die Mauer wurde am 25. Elul vollendet – nach 52 Tagen.","r":{"t":"Nehemia 6:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/6/#v16006015"}},{"t":"Daniel hatte das „Ausgehen des Wortes“ vorhergesagt.","r":{"t":"Daniel 9:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/9/#v27009025"}}],"significance":"Ab 455 v. u. Z. zählten die 69 Jahrwochen (483 Jahre) bis zum Auftreten des Messias im Jahr 29 u. Z.","persons":["nehemia","artaxerxes"],"refs":[{"t":"Nehemia 2:1–6:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/2/#v16002001-v16006016"},{"t":"Daniel 9:24-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/9/#v27009024-v27009027"}],"sources":[{"title":"Nehemia – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003212"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"abschluss-hebraeische-schriften","title":"Maleachi – Abschluss der Hebräischen Schriften","era":"rueckkehr","year":-443,"date":"nach 443 v. u. Z.","place":"Juda","summary":"Nachdem Nehemia einige Zeit nach dem 32. Jahr des Artaxerxes (um 443 v. u. Z.) zurückgekehrt war, fand er schlimme Zustände vor: Vernachlässigung des Tempels, Missachtung des Gesetzes und Ehen mit Ausländerinnen. Genau diese Zustände prangert das Buch Maleachi an. Es wurde wie das Buch Nehemia nach 443 v. u. Z. geschrieben und schließt die Hebräischen Schriften ab.","facts":[{"t":"Nehemia kam nach dem 32. Jahr des Artaxerxes zurück.","r":{"t":"Nehemia 13:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/13/#v16013006"}},{"t":"Maleachi tadelte die Priester.","r":{"t":"Maleachi 1:6-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/1/#v39001006-v39001008"}},{"t":"Jehova verhieß Segen für Treue.","r":{"t":"Maleachi 3:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/3/#v39003010"}},{"t":"Ein Gedenkbuch wird für die geschrieben, die Jehova fürchten.","r":{"t":"Maleachi 3:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/3/#v39003016"}}],"significance":"Mit dem Buch Maleachi enden die Hebräischen Schriften.","persons":["maleachi","nehemia"],"refs":[{"t":"Maleachi 1:1–4:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/maleachi/1/#v39001001-v39004006"},{"t":"Nehemia 13:6-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/nehemia/13/#v16013006-v16013031"}],"sources":[{"title":"Maleachi (Buch) – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002861"}]},{"id":"ankuendigung-johannes","title":"Gabriel kündigt Johannes an","era":"jesus","year":-3,"date":"3 v. u. Z.","place":"Jerusalem, Tempel","summary":"Als der Priester Sacharja im Heiligtum Räucherwerk darbrachte, erschien ihm der Engel Gabriel. Er kündigte an, dass Sacharjas betagte Frau Elisabeth einen Sohn gebären werde, der Johannes heißen und Jehova ein vorbereitetes Volk bereit machen sollte. Weil Sacharja zweifelte, verstummte er bis zur Geburt.","facts":[{"t":"Sacharja diente in der Abteilung Abijas.","r":{"t":"Lukas 1:5, 8, 9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001005"}},{"t":"Johannes sollte wie Elia vor Jehova hergehen.","r":{"t":"Lukas 1:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001017"}},{"t":"Sacharja konnte nicht mehr sprechen.","r":{"t":"Lukas 1:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001020"}}],"significance":"","persons":["zacharias","elisabeth","gabriel","johannes-der-taeufer"],"refs":[{"t":"Lukas 1:5-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001005-v42001025"}],"sources":[{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"}]},{"id":"ankuendigung-jesu","title":"Gabriel besucht Maria","era":"jesus","year":-2,"date":"um 2 v. u. Z.","place":"Nazareth; Judäa","summary":"Gott sandte den Engel Gabriel nach Nazareth zu Maria, einer Jungfrau, die mit Joseph verlobt war. Er kündigte an, dass sie durch heiligen Geist schwanger werden und einen Sohn gebären werde, der Jesus heißen und als König auf dem Thron Davids für immer regieren werde. Maria nahm den Auftrag demütig an und besuchte danach ihre Verwandte Elisabeth.","facts":[{"t":"Jesus sollte „Sohn des Höchsten“ genannt werden.","r":{"t":"Lukas 1:32, 33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001032"}},{"t":"Heiliger Geist würde über Maria kommen.","r":{"t":"Lukas 1:35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001035"}},{"t":"„Für Gott ist nichts unmöglich.“","r":{"t":"Lukas 1:37","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001037"}},{"t":"Maria pries Jehova bei Elisabeth.","r":{"t":"Lukas 1:46-55","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001046-v42001055"}}],"significance":"","persons":["maria","gabriel","elisabeth","jesus"],"refs":[{"t":"Lukas 1:26-56","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001026-v42001056"}],"sources":[{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"},{"title":"Maria – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002918"}]},{"id":"geburt-johannes","title":"Johannes wird geboren","era":"jesus","year":-2,"date":"2 v. u. Z.","place":"Judäisches Hügelland","summary":"Elisabeth gebar einen Sohn. Als Verwandte ihn nach seinem Vater benennen wollten, bestand sie auf dem Namen Johannes, und Sacharja schrieb auf ein Täfelchen: „Johannes ist sein Name.“ Sofort konnte er wieder sprechen, und er prophezeite über den kommenden Retter. Johannes wuchs heran und blieb in der Wüste, bis er öffentlich auftrat.","facts":[{"t":"Die Verwandten wollten ihn Sacharja nennen.","r":{"t":"Lukas 1:59","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001059"}},{"t":"Sacharja schrieb: „Johannes ist sein Name.“","r":{"t":"Lukas 1:63, 64","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001063"}},{"t":"Er blieb in der Wüste bis zu seinem Auftreten.","r":{"t":"Lukas 1:80","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001080"}}],"significance":"","persons":["johannes-der-taeufer","zacharias","elisabeth"],"refs":[{"t":"Lukas 1:57-80","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/1/#v42001057-v42001080"}],"sources":[{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"},{"title":"Johannes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002489"}]},{"id":"geburt-jesu","title":"Jesus wird geboren","era":"jesus","year":-2,"date":"2 v. u. Z., um den 1. Oktober","place":"Bethlehem","summary":"Wegen einer Volkszählung reisten Joseph und Maria nach Bethlehem, der Stadt Davids. Dort wurde Jesus geboren und in eine Krippe gelegt – „das Wort“ wurde Mensch. In der Nähe verkündete ein Engel Hirten die gute Botschaft, eine Menge Engel pries Gott, und die Hirten besuchten das Neugeborene.","facts":[{"t":"Joseph und Maria zogen zur Eintragung nach Bethlehem.","r":{"t":"Lukas 2:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002001-v42002005"}},{"t":"Maria legte das Kind in eine Krippe.","r":{"t":"Lukas 2:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002007"}},{"t":"Engel erschienen Hirten auf dem Feld.","r":{"t":"Lukas 2:8-14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002008-v42002014"}},{"t":"„Das Wort wurde Fleisch.“","r":{"t":"Johannes 1:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001014"}}],"significance":"Michas Prophezeiung, dass der Herrscher aus Bethlehem kommen werde, erfüllte sich.","persons":["jesus","maria","joseph-marias-mann"],"refs":[{"t":"Lukas 2:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002001-v42002020"},{"t":"Matthäus 1:18-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/1/#v40001018-v40001025"},{"t":"Micha 5:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/micha/5/#v33005002"}],"sources":[{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"}]},{"id":"darstellung-im-tempel","title":"Jesus wird im Tempel dargestellt","era":"jesus","year":-1,"date":"2 v. u. Z. (nach dem 40. Tag)","place":"Bethlehem; Jerusalem","summary":"Am achten Tag wurde Jesus beschnitten. Nach dem 40. Tag brachten Joseph und Maria ihn in den Tempel, um ihn Jehova zu übergeben, und brachten das Opfer der Armen dar. Dort nahm der greise Simeon das Kind in die Arme und pries Gott, und die betagte Prophetin Anna sprach über das Kind zu allen, die auf Befreiung warteten.","facts":[{"t":"Jesus wurde am achten Tag beschnitten.","r":{"t":"Lukas 2:21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002021"}},{"t":"Die Eltern opferten zwei Turteltauben oder junge Tauben.","r":{"t":"Lukas 2:24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002024"}},{"t":"Simeon pries Gott.","r":{"t":"Lukas 2:28-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002028-v42002032"}},{"t":"Anna sprach über das Kind.","r":{"t":"Lukas 2:38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002038"}}],"significance":"","persons":["jesus","maria","joseph-marias-mann","simeon-in-jerusalem","hanna-prophetin"],"refs":[{"t":"Lukas 2:21-38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002021-v42002038"}],"sources":[{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"}]},{"id":"astrologen-und-flucht","title":"Die Astrologen und die Flucht nach Ägypten","era":"jesus","year":0,"date":"1 v. u. Z. oder 1 u. Z.","place":"Jerusalem; Bethlehem; Ägypten; Nazareth","summary":"Astrologen aus dem Osten kamen nach Jerusalem und fragten nach dem neugeborenen „König der Juden“. Herodes erschrak und wollte das Kind töten lassen. Gewarnt durch einen Engel, floh Joseph mit Maria und Jesus nach Ägypten. Herodes ließ in Bethlehem alle Jungen bis zu zwei Jahren umbringen. Nach seinem Tod kehrte die Familie zurück und wohnte in Nazareth.","facts":[{"t":"Die Astrologen fragten nach dem König der Juden.","r":{"t":"Matthäus 2:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002001"}},{"t":"Ein Engel warnte Joseph im Traum.","r":{"t":"Matthäus 2:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002013"}},{"t":"Herodes ließ die kleinen Jungen töten.","r":{"t":"Matthäus 2:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002016"}},{"t":"Die Familie ließ sich in Nazareth nieder.","r":{"t":"Matthäus 2:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002023"}}],"significance":"","persons":["jesus","maria","joseph-marias-mann","herodes-der-grosse"],"refs":[{"t":"Matthäus 2:1-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/2/#v40002001-v40002023"}],"sources":[{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"},{"title":"Herodes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002000"}]},{"id":"zwoelfjaehriger-jesus","title":"Der 12-jährige Jesus im Tempel","era":"jesus","year":12,"date":"12 u. Z., Passah","place":"Jerusalem","summary":"Zum Passah reiste die Familie nach Jerusalem. Auf dem Heimweg merkten Joseph und Maria, dass der 12-jährige Jesus fehlte. Nach drei Tagen fanden sie ihn im Tempel, wo er den Lehrern zuhörte und Fragen stellte; alle staunten über sein Verständnis. Jesus fragte: „Wusstet ihr nicht, dass ich im Haus meines Vaters sein muss?“ Danach kehrte er nach Nazareth zurück, ordnete sich seinen Eltern unter und wurde Zimmermann.","facts":[{"t":"Die Eltern fanden ihn nach drei Tagen.","r":{"t":"Lukas 2:46","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002046"}},{"t":"Alle staunten über seine Antworten.","r":{"t":"Lukas 2:47","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002047"}},{"t":"Er ordnete sich seinen Eltern weiter unter.","r":{"t":"Lukas 2:51","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002051"}},{"t":"Er wurde Zimmermann.","r":{"t":"Markus 6:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/6/#v41006003"}}],"significance":"","persons":["jesus","maria","joseph-marias-mann"],"refs":[{"t":"Lukas 2:41-52","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/2/#v42002041-v42002052"}],"sources":[{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"}]},{"id":"johannes-tauft","title":"Johannes beginnt zu taufen","era":"jesus","year":29,"date":"Frühjahr 29 u. Z.","place":"Wildnis; Jordan","summary":"Im 15. Jahr der Regierung des Tiberius erging Gottes Wort an Johannes in der Wildnis. Er predigte, die Menschen sollten bereuen, denn das Königreich des Himmels habe sich genaht, und taufte im Jordan alle, die ihre Sünden bekannten. Er bereitete den Weg für den Messias vor, von dem er sagte, er werde mit heiligem Geist taufen.","facts":[{"t":"Sein Dienst begann im 15. Jahr des Tiberius.","r":{"t":"Lukas 3:1-3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003001-v42003003"}},{"t":"„Bereut, denn das Königreich der Himmel hat sich genaht.“","r":{"t":"Matthäus 3:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/3/#v40003001"}},{"t":"Er erfüllte Jesajas Prophezeiung von der Stimme in der Wildnis.","r":{"t":"Matthäus 3:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/3/#v40003003"}}],"significance":"","persons":["johannes-der-taeufer"],"refs":[{"t":"Matthäus 3:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/3/#v40003001-v40003012"},{"t":"Lukas 3:1-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003001-v42003018"}],"sources":[{"title":"A7-A Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070207"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"taufe-jesu","title":"Jesus wird getauft","era":"jesus","year":29,"date":"Herbst 29 u. Z.","place":"Jordan (bei Bethanien auf der anderen Jordanseite)","summary":"Mit etwa 30 Jahren kam Jesus zu Johannes an den Jordan, um sich taufen zu lassen. Als er aus dem Wasser stieg, kam heiliger Geist auf ihn herab, und Jehova sagte vom Himmel: „Dies ist mein Sohn, der Geliebte, an dem ich Gefallen gefunden habe.“ Damit wurde Jesus der Messias, der Gesalbte – genau 483 Jahre nach 455 v. u. Z., wie in Daniel 9 vorhergesagt.","facts":[{"t":"Jesus war etwa 30 Jahre alt.","r":{"t":"Lukas 3:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003023"}},{"t":"Der Geist kam wie eine Taube auf ihn herab.","r":{"t":"Matthäus 3:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/3/#v40003016"}},{"t":"Jehova bezeichnete ihn als seinen Sohn.","r":{"t":"Matthäus 3:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/3/#v40003017"}},{"t":"Die 69 Jahrwochen endeten 29 u. Z.","r":{"t":"Daniel 9:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/daniel/9/#v27009025"}}],"significance":"29 u. Z. trat der „Messias, der Führer“, auf.","persons":["jesus","johannes-der-taeufer"],"refs":[{"t":"Matthäus 3:13-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/3/#v40003013-v40003017"},{"t":"Lukas 3:21, 22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/3/#v42003021"}],"sources":[{"title":"A7-B Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070208"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"versuchung","title":"Jesus wird in der Wildnis versucht","era":"jesus","year":29,"date":"29 u. Z.","place":"Wildnis von Judäa","summary":"Nach seiner Taufe hielt sich Jesus etwa 40 Tage in der Wildnis auf. Dort trat der Teufel mit drei großen Versuchungen an ihn heran: Steine in Brot zu verwandeln, sich vom Tempel zu stürzen und für einen Akt der Anbetung alle Königreiche der Welt zu bekommen. Jesus wies jede Versuchung mit einem Zitat aus Gottes Wort zurück.","facts":[{"t":"Er fastete 40 Tage und Nächte.","r":{"t":"Matthäus 4:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/4/#v40004002"}},{"t":"„Nicht von Brot allein soll der Mensch leben.“","r":{"t":"Matthäus 4:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/4/#v40004004"}},{"t":"„Jehova, deinen Gott, sollst du anbeten.“","r":{"t":"Matthäus 4:10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/4/#v40004010"}}],"significance":"","persons":["jesus","satan"],"refs":[{"t":"Matthäus 4:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/4/#v40004001-v40004011"},{"t":"Lukas 4:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/4/#v42004001-v42004013"}],"sources":[{"title":"A7-B Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070208"},{"title":"Satan – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003845"}]},{"id":"erste-juenger","title":"Die ersten Jünger","era":"jesus","year":29,"date":"29 u. Z.","place":"Bethanien auf der anderen Jordanseite","summary":"Johannes der Täufer wies seine Jünger auf Jesus hin: „Siehe, das Lamm Gottes!“ Daraufhin schlossen sich Andreas und ein weiterer Jünger – wahrscheinlich Johannes, der Sohn des Zebedäus – Jesus an. Andreas holte seinen Bruder Simon, dem Jesus den Namen Kephas (Petrus) gab; auch Philippus und Nathanael wurden Jünger.","facts":[{"t":"Johannes nannte Jesus das Lamm Gottes.","r":{"t":"Johannes 1:29, 36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001029"}},{"t":"Andreas sagte: „Wir haben den Messias gefunden.“","r":{"t":"Johannes 1:41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001041"}},{"t":"Simon erhielt den Namen Kephas.","r":{"t":"Johannes 1:42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001042"}},{"t":"Nathanael erkannte Jesus als Sohn Gottes.","r":{"t":"Johannes 1:49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001049"}}],"significance":"","persons":["jesus","johannes-der-taeufer","andreas","petrus","johannes-apostel","philippus-apostel","bartholomaeus"],"refs":[{"t":"Johannes 1:35-51","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/1/#v43001035-v43001051"}],"sources":[{"title":"A7-B Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070208"},{"title":"Johannes – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002489"}]},{"id":"hochzeit-in-kana","title":"Die Hochzeit in Kana","era":"jesus","year":29,"date":"29 u. Z.","place":"Kana in Galiläa","summary":"Bei einer Hochzeit in Kana ging der Wein aus. Auf Bitten seiner Mutter ließ Jesus sechs große Steinkrüge mit Wasser füllen und verwandelte das Wasser in Wein. Es war sein erstes Wunder. Dadurch offenbarte er seine Herrlichkeit, und seine Jünger glaubten an ihn.","facts":[{"t":"Maria sagte: „Sie haben keinen Wein.“","r":{"t":"Johannes 2:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/2/#v43002003"}},{"t":"Die Krüge wurden bis zum Rand gefüllt.","r":{"t":"Johannes 2:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/2/#v43002007"}},{"t":"Es war der Anfang seiner Zeichen.","r":{"t":"Johannes 2:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/2/#v43002011"}}],"significance":"","persons":["jesus","maria"],"refs":[{"t":"Johannes 2:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/2/#v43002001-v43002012"}],"sources":[{"title":"A7-B Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070208"},{"title":"Kana – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000873"}]},{"id":"erste-tempelreinigung","title":"Jesus reinigt den Tempel","era":"jesus","year":30,"date":"Passah 30 u. Z.","place":"Jerusalem","summary":"Zum Passah 30 u. Z. kam Jesus nach Jerusalem und fand im Tempel Händler mit Rindern, Schafen und Tauben sowie Geldwechsler. Er machte eine Peitsche aus Stricken und trieb sie hinaus: „Hört auf, das Haus meines Vaters zu einem Haus des Handels zu machen!“ In dieser Zeit sprach er auch nachts mit Nikodemus.","facts":[{"t":"Er stieß die Tische der Geldwechsler um.","r":{"t":"Johannes 2:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/2/#v43002015"}},{"t":"Die Jünger dachten an den Eifer für Gottes Haus.","r":{"t":"Johannes 2:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/2/#v43002017"}},{"t":"Er sprach mit Nikodemus über die neue Geburt.","r":{"t":"Johannes 3:1-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/3/#v43003001-v43003008"}}],"significance":"","persons":["jesus","nikodemus"],"refs":[{"t":"Johannes 2:13-25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/2/#v43002013-v43002025"},{"t":"Johannes 3:1-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/3/#v43003001-v43003021"}],"sources":[{"title":"A7-B Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070208"}]},{"id":"samariterin","title":"Jesus und die Samariterin","era":"jesus","year":30,"date":"30 u. Z.","place":"Sychar in Samaria","summary":"Auf dem Weg nach Galiläa rastete Jesus an einem Brunnen bei Sychar und bat eine samaritische Frau um Wasser. Er sprach mit ihr über „lebendiges Wasser“ und erklärte, dass wahre Anbeter Gott mit Geist und Wahrheit anbeten. Ihr gegenüber gab er sich deutlich als Messias zu erkennen. Viele Samariter glaubten daraufhin an ihn.","facts":[{"t":"Jesus bat die Frau um Wasser.","r":{"t":"Johannes 4:7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/4/#v43004007"}},{"t":"Gott muss mit Geist und Wahrheit angebetet werden.","r":{"t":"Johannes 4:23, 24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/4/#v43004023"}},{"t":"„Ich bin es, der mit dir redet“ – der Messias.","r":{"t":"Johannes 4:25, 26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/4/#v43004025"}},{"t":"Viele Samariter glaubten an ihn.","r":{"t":"Johannes 4:39-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/4/#v43004039-v43004042"}}],"significance":"","persons":["jesus"],"refs":[{"t":"Johannes 4:4-43","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/4/#v43004004-v43004043"}],"sources":[{"title":"A7-B Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070208"}]},{"id":"wahl-der-apostel","title":"Jesus wählt 12 Apostel","era":"jesus","year":31,"date":"31 u. Z.","place":"Berg bei Kapernaum","summary":"Nachdem Jesus die ganze Nacht im Gebet zu Gott verbracht hatte, rief er seine Jünger und wählte aus ihnen zwölf aus, die er Apostel nannte: Simon Petrus und Andreas, Jakobus und Johannes, Philippus, Bartholomäus, Matthäus, Thomas, Jakobus, den Sohn des Alphäus, Thaddäus, Simon den Kananäer und Judas Iskariot. Sie sollten bei ihm sein und predigen.","facts":[{"t":"Jesus betete die ganze Nacht.","r":{"t":"Lukas 6:12, 13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006012"}},{"t":"Er nannte die Zwölf Apostel.","r":{"t":"Markus 3:14","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/3/#v41003014"}},{"t":"Die Namen der Apostel werden aufgezählt.","r":{"t":"Lukas 6:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006014-v42006016"}}],"significance":"","persons":["jesus","petrus","andreas","jakobus-zebedaeus","johannes-apostel","philippus-apostel","bartholomaeus","matthaeus","thomas","jakobus-alphaeus","thaddaeus","simon-kananaeer","judas-iskariot"],"refs":[{"t":"Markus 3:13-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/3/#v41003013-v41003019"},{"t":"Lukas 6:12-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006012-v42006016"}],"sources":[{"title":"A7-C Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070209"}]},{"id":"bergpredigt","title":"Die Bergpredigt","era":"jesus","year":31,"date":"31 u. Z.","place":"Berg bei Kapernaum","summary":"Auf einem Berg bei Kapernaum hielt Jesus seine bekannteste Rede. Er sprach darüber, wer wirklich glücklich ist, über Liebe auch zu Feinden, aufrichtiges Gebet – mit dem Mustergebet – und darüber, zuerst das Königreich zu suchen. Die Menge staunte, denn er lehrte wie jemand, der Autorität hat.","facts":[{"t":"Glücklich sind die, die sich ihrer geistigen Bedürfnisse bewusst sind.","r":{"t":"Matthäus 5:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/5/#v40005003"}},{"t":"Er lehrte das Mustergebet.","r":{"t":"Matthäus 6:9-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/6/#v40006009-v40006013"}},{"t":"„Sucht zuerst das Königreich.“","r":{"t":"Matthäus 6:33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/6/#v40006033"}},{"t":"Die Goldene Regel: Behandelt andere so, wie ihr behandelt werden wollt.","r":{"t":"Matthäus 7:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/7/#v40007012"}}],"significance":"","persons":["jesus"],"refs":[{"t":"Matthäus 5:1–7:29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/5/#v40005001-v40007029"},{"t":"Lukas 6:17-49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/6/#v42006017-v42006049"}],"sources":[{"title":"A7-C Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070209"}]},{"id":"tod-johannes-des-taeufers","title":"Johannes der Täufer wird hingerichtet","era":"jesus","year":32,"date":"31 oder 32 u. Z.","place":"Tiberias (Herrschaftsgebiet des Herodes Antipas)","summary":"Johannes hatte Herodes Antipas vorgehalten, dass es nicht erlaubt sei, Herodias, die Frau seines Bruders, zu haben, und war deshalb ins Gefängnis gekommen. An seinem Geburtstag versprach Herodes der Tochter der Herodias nach ihrem Tanz jeden Wunsch. Auf Anstiften ihrer Mutter verlangte sie den Kopf des Johannes, und Herodes ließ ihn enthaupten.","facts":[{"t":"Johannes hatte Herodes zurechtgewiesen.","r":{"t":"Markus 6:18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/6/#v41006018"}},{"t":"Die Tochter der Herodias verlangte seinen Kopf.","r":{"t":"Markus 6:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/6/#v41006024"}},{"t":"Seine Jünger begruben ihn und berichteten Jesus davon.","r":{"t":"Matthäus 14:12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/14/#v40014012"}}],"significance":"","persons":["johannes-der-taeufer","herodes-antipas"],"refs":[{"t":"Matthäus 14:1-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/14/#v40014001-v40014012"},{"t":"Markus 6:14-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/6/#v41006014-v41006029"}],"sources":[{"title":"A7-D Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070210"}]},{"id":"speisung-der-5000","title":"Die Speisung der 5000","era":"jesus","year":32,"date":"32 u. Z., vor dem Passah","place":"Nordostufer des Sees von Galiläa","summary":"Als die Apostel von ihrer Predigtreise zurückkamen, folgte eine große Menge Jesus an einen abgelegenen Ort. Mit nur fünf Broten und zwei Fischen speiste er etwa 5000 Männer, dazu Frauen und Kinder; danach sammelte man zwölf Körbe voller Reste. Die Menge wollte ihn daraufhin zum König machen.","facts":[{"t":"Es waren nur fünf Brote und zwei Fische da.","r":{"t":"Johannes 6:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/6/#v43006009"}},{"t":"Etwa 5000 Männer aßen sich satt.","r":{"t":"Johannes 6:10, 11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/6/#v43006010"}},{"t":"Zwölf Körbe mit Resten blieben übrig.","r":{"t":"Johannes 6:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/6/#v43006013"}},{"t":"Man wollte ihn zum König machen; er zog sich zurück.","r":{"t":"Johannes 6:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/6/#v43006015"}}],"significance":"","persons":["jesus","philippus-apostel","andreas"],"refs":[{"t":"Johannes 6:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/6/#v43006001-v43006015"},{"t":"Matthäus 14:13-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/14/#v40014013-v40014021"}],"sources":[{"title":"A7-D Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070210"}]},{"id":"jesus-geht-auf-dem-wasser","title":"Jesus geht auf dem Wasser","era":"jesus","year":32,"date":"32 u. Z., vor dem Passah","place":"See von Galiläa","summary":"In der Nacht nach der Speisung der 5000 kämpften die Jünger in ihrem Boot gegen den Wind. Da kam Jesus auf dem Wasser zu ihnen. Petrus ging ihm auf dem Wasser entgegen, bekam aber Angst und begann zu sinken, bis Jesus ihn fasste. Als sie ins Boot stiegen, legte sich der Wind, und die Jünger sagten: „Du bist wirklich Gottes Sohn.“","facts":[{"t":"Jesus ging in der vierten Nachtwache auf dem See.","r":{"t":"Matthäus 14:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/14/#v40014025"}},{"t":"Petrus ging auf dem Wasser, begann aber zu sinken.","r":{"t":"Matthäus 14:29, 30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/14/#v40014029"}},{"t":"„Du Kleingläubiger, warum hast du gezweifelt?“","r":{"t":"Matthäus 14:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/14/#v40014031"}}],"significance":"","persons":["jesus","petrus"],"refs":[{"t":"Matthäus 14:22-33","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/14/#v40014022-v40014033"},{"t":"Johannes 6:16-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/6/#v43006016-v43006021"}],"sources":[{"title":"A7-D Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070210"}]},{"id":"umgestaltung","title":"Die Umgestaltung Jesu","era":"jesus","year":32,"date":"32 u. Z., nach dem Passah","place":"Wahrscheinlich Berg Hermon","summary":"Jesus nahm Petrus, Jakobus und Johannes mit auf einen hohen Berg. Dort wurde er vor ihren Augen umgestaltet: Sein Gesicht leuchtete wie die Sonne, und Moses und Elia erschienen und sprachen mit ihm. Aus einer Wolke sagte Jehovas Stimme: „Dies ist mein Sohn … hört auf ihn.“ Die Vision gab einen Vorgeschmack auf Jesu Herrlichkeit in seinem Königreich.","facts":[{"t":"Sein Gesicht leuchtete wie die Sonne.","r":{"t":"Matthäus 17:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/17/#v40017002"}},{"t":"Moses und Elia erschienen in der Vision.","r":{"t":"Matthäus 17:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/17/#v40017003"}},{"t":"Jehova sagte: „Hört auf ihn.“","r":{"t":"Matthäus 17:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/17/#v40017005"}},{"t":"Petrus schrieb später darüber.","r":{"t":"2. Petrus 1:16-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-petrus/1/#v61001016-v61001018"}}],"significance":"","persons":["jesus","petrus","jakobus-zebedaeus","johannes-apostel"],"refs":[{"t":"Matthäus 17:1-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/17/#v40017001-v40017013"},{"t":"Lukas 9:28-36","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/9/#v42009028-v42009036"}],"sources":[{"title":"A7-E Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070211"},{"title":"Umgestaltung – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004466"}]},{"id":"auferweckung-des-lazarus","title":"Lazarus wird auferweckt","era":"jesus","year":33,"date":"Nach dem Fest der Einweihung 32 u. Z.","place":"Bethanien","summary":"Lazarus, der Bruder von Martha und Maria, war gestorben und lag schon vier Tage im Grab, als Jesus nach Bethanien kam. Jesus weinte, ließ den Stein wegnehmen, betete laut und rief: „Lazarus, komm heraus!“ Der Tote kam heraus. Viele glaubten an Jesus – doch die führenden Juden beschlossen, ihn zu töten.","facts":[{"t":"Lazarus lag seit vier Tagen im Grab.","r":{"t":"Johannes 11:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011017"}},{"t":"„Ich bin die Auferstehung und das Leben.“","r":{"t":"Johannes 11:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011025"}},{"t":"Jesus brach in Tränen aus.","r":{"t":"Johannes 11:35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011035"}},{"t":"Danach planten die Führer, Jesus zu töten.","r":{"t":"Johannes 11:53","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011053"}}],"significance":"","persons":["jesus","lazarus","martha","maria-bethanien","kaiphas"],"refs":[{"t":"Johannes 11:1-54","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/11/#v43011001-v43011054"}],"sources":[{"title":"A7-F Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070212"}]},{"id":"einzug-in-jerusalem","title":"Jesus zieht in Jerusalem ein","era":"jesus","year":33,"date":"9. Nisan 33 u. Z.","place":"Bethanien – Bethphage – Jerusalem","summary":"Sechs Tage vor dem Passah kam Jesus nach Bethanien. Am 9. Nisan ritt er auf einem Esel nach Jerusalem, wie Sacharja vorhergesagt hatte. Eine große Menge breitete ihre Gewänder und Zweige auf dem Weg aus und rief: „Rette doch den Sohn Davids! Gesegnet ist der, der im Namen Jehovas kommt!“","facts":[{"t":"Er ritt auf einem jungen Esel.","r":{"t":"Matthäus 21:6, 7","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/21/#v40021006"}},{"t":"So erfüllte sich Sacharja 9:9.","r":{"t":"Sacharja 9:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/sacharja/9/#v38009009"}},{"t":"Die Menge rief „Hosanna dem Sohn Davids“.","r":{"t":"Matthäus 21:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/21/#v40021009"}},{"t":"Am nächsten Tag reinigte er erneut den Tempel.","r":{"t":"Markus 11:15-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/markus/11/#v41011015-v41011017"}}],"significance":"","persons":["jesus"],"refs":[{"t":"Matthäus 21:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/21/#v40021001-v40021011"},{"t":"Johannes 12:12-19","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/12/#v43012012-v43012019"}],"sources":[{"title":"A7-G Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070213"}]},{"id":"abendmahl-des-herrn","title":"Das Abendmahl des Herrn","era":"jesus","year":33,"date":"14. Nisan 33 u. Z. (abends)","place":"Jerusalem","summary":"Am Abend des 14. Nisan feierte Jesus mit seinen Aposteln das letzte Passah und wusch ihnen die Füße. Nachdem er Judas weggeschickt hatte, führte er das Abendmahl des Herrn ein: Das ungesäuerte Brot stellte seinen Leib dar, der Wein sein „Blut des Bundes“. Er gebot: „Tut dies immer wieder zur Erinnerung an mich.“","facts":[{"t":"Jesus wusch den Aposteln die Füße.","r":{"t":"Johannes 13:1-15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/13/#v43013001-v43013015"}},{"t":"Er entlarvte Judas als Verräter.","r":{"t":"Johannes 13:21-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/13/#v43013021-v43013030"}},{"t":"„Tut dies immer wieder zur Erinnerung an mich.“","r":{"t":"Lukas 22:19, 20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/22/#v42022019"}},{"t":"Paulus beschreibt das Abendmahl des Herrn.","r":{"t":"1. Korinther 11:23-26","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-korinther/11/#v46011023-v46011026"}}],"significance":"Wie das Passah soll das Abendmahl des Herrn einmal im Jahr gefeiert werden – zur Erinnerung an Jesu Tod.","persons":["jesus","petrus","johannes-apostel","judas-iskariot"],"refs":[{"t":"Lukas 22:7-30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/22/#v42022007-v42022030"},{"t":"Matthäus 26:17-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026017-v40026029"}],"sources":[{"title":"A7-H Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070214"},{"title":"Abendmahl des Herrn – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002773"}]},{"id":"gethsemane","title":"Gethsemane und Verhaftung","era":"jesus","year":33,"date":"14. Nisan 33 u. Z. (nachts)","place":"Garten Gethsemane; Jerusalem","summary":"Nach dem Abendmahl ging Jesus mit den Aposteln in den Garten Gethsemane und betete in tiefer Qual. Judas kam mit einer bewaffneten Schar und verriet ihn mit einem Kuss. Jesus wurde festgenommen, zuerst von Annas verhört und dann vor Kaiphas und dem Sanhedrin angeklagt, während Petrus ihn dreimal verleugnete.","facts":[{"t":"Jesus betete: „Nicht wie ich will, sondern wie du willst.“","r":{"t":"Matthäus 26:39","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026039"}},{"t":"Judas verriet ihn mit einem Kuss.","r":{"t":"Matthäus 26:48, 49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026048"}},{"t":"Annas verhörte ihn zuerst.","r":{"t":"Johannes 18:13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/18/#v43018013"}},{"t":"Petrus verleugnete ihn dreimal.","r":{"t":"Matthäus 26:69-75","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026069-v40026075"}}],"significance":"","persons":["jesus","judas-iskariot","petrus","hannas","kaiphas"],"refs":[{"t":"Matthäus 26:36-75","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/26/#v40026036-v40026075"},{"t":"Johannes 18:1-27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/18/#v43018001-v43018027"}],"sources":[{"title":"A7-H Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070214"},{"title":"Gethsemane – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200001671"}]},{"id":"tod-jesu","title":"Jesus stirbt","era":"jesus","year":33,"date":"14. Nisan 33 u. Z. (Freitag gegen 15 Uhr)","place":"Golgotha","summary":"Am Morgen brachte man Jesus zu Pilatus, dann zu Herodes und wieder zu Pilatus. Obwohl Pilatus ihn freilassen wollte, forderte die Menge Barabbas, und Jesus wurde zum Tod am Marterpfahl verurteilt. Auf Golgotha starb er am Freitag gegen 15 Uhr. Joseph von Arimathia legte seinen Leichnam in ein neues Grab. Sein Tod öffnete den Weg zu Sündenvergebung und ewigem Leben.","facts":[{"t":"Pilatus fand keine Schuld an ihm.","r":{"t":"Lukas 23:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/23/#v42023004"}},{"t":"Er wurde an einen Marterpfahl gehängt.","r":{"t":"Johannes 19:16-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019016-v43019018"}},{"t":"Seine letzten Worte: „Es ist vollbracht!“","r":{"t":"Johannes 19:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019030"}},{"t":"Er gab sein Leben als Lösegeld für viele.","r":{"t":"Matthäus 20:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/20/#v40020028"}}],"significance":"Jesus starb als Passahopfer genau am 14. Nisan 33 u. Z.","persons":["jesus","pilatus","herodes-antipas","maria","maria-magdalene","johannes-apostel","joseph-von-arimathaea","kaiphas","nikodemus"],"refs":[{"t":"Johannes 19:1-42","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/19/#v43019001-v43019042"},{"t":"Matthäus 27:11-61","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/27/#v40027011-v40027061"},{"t":"Lukas 23:1-56","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/23/#v42023001-v42023056"}],"sources":[{"title":"A7-H Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070214"},{"title":"Marterpfahl – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004456"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"auferweckung-jesu","title":"Jesus wird auferweckt","era":"jesus","year":33,"date":"16. Nisan 33 u. Z.","place":"Jerusalem und Umgebung; Emmaus","summary":"Am dritten Tag, dem 16. Nisan, fanden Frauen das Grab leer. Engel verkündeten, dass Jesus auferweckt worden war. Noch am selben Tag erschien Jesus seinen Jüngern fünfmal, unter anderem Maria Magdalene und zwei Jüngern auf dem Weg nach Emmaus. In den folgenden 40 Tagen zeigte er sich ihnen immer wieder und gab ihnen den Auftrag, Menschen zu Jüngern zu machen.","facts":[{"t":"Das Grab war leer.","r":{"t":"Lukas 24:1-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/24/#v42024001-v42024006"}},{"t":"Er erschien Maria Magdalene.","r":{"t":"Johannes 20:14-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/20/#v43020014-v43020016"}},{"t":"Er erschien über 500 Brüdern auf einmal.","r":{"t":"1. Korinther 15:6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-korinther/15/#v46015006"}},{"t":"„Macht Jünger aus Menschen aller Nationen.“","r":{"t":"Matthäus 28:19, 20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/28/#v40028019"}}],"significance":"Jehova erweckte Jesus zum Leben; mit dem Wert seines vollkommenen Lebens erschien er im Himmel vor Gott.","persons":["jesus","maria-magdalene","petrus","thomas"],"refs":[{"t":"Matthäus 28:1-20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/28/#v40028001-v40028020"},{"t":"Lukas 24:1-49","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/24/#v42024001-v42024049"},{"t":"Johannes 20:1-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/20/#v43020001-v43020029"}],"sources":[{"title":"A7-H Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070214"},{"title":"B1 Das Hauptthema der Bibel – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070221"}]},{"id":"himmelfahrt","title":"Jesus fährt in den Himmel auf","era":"jesus","year":33,"date":"25. Ijjar 33 u. Z.","place":"Ölberg, bei Bethanien","summary":"Am 40. Tag nach seiner Auferweckung führte Jesus seine Jünger zum Ölberg bei Bethanien. Er versprach ihnen heiligen Geist und sagte, sie würden seine Zeugen sein „bis zum entferntesten Teil der Erde“. Dann wurde er emporgehoben, und eine Wolke entzog ihn ihren Blicken. Zwei Engel sagten, er werde in gleicher Weise kommen.","facts":[{"t":"Es war der 40. Tag nach der Auferweckung.","r":{"t":"Apostelgeschichte 1:3","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001003"}},{"t":"„Ihr werdet Zeugen von mir sein.“","r":{"t":"Apostelgeschichte 1:8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001008"}},{"t":"Eine Wolke nahm ihn auf.","r":{"t":"Apostelgeschichte 1:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001009"}}],"significance":"","persons":["jesus"],"refs":[{"t":"Apostelgeschichte 1:3-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001003-v44001011"},{"t":"Lukas 24:50-53","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/24/#v42024050-v42024053"}],"sources":[{"title":"A7-H Jesu Leben auf der Erde – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070214"}]},{"id":"pfingsten-33","title":"Pfingsten 33 u. Z.","era":"versammlung","year":33,"date":"Pfingsten 33 u. Z.","place":"Jerusalem, Obersaal","summary":"Am Pfingsttag goss Jesus heiligen Geist auf etwa 120 Jünger aus, die in einem Obersaal in Jerusalem versammelt waren. Sie redeten durch ein Wunder in verschiedenen Sprachen, sodass Juden und Proselyten aus dem ganzen Römischen Reich die gute Botschaft in ihrer Sprache hörten. Petrus hielt eine Rede, und etwa 3000 ließen sich taufen. So entstand die Christenversammlung.","facts":[{"t":"Etwa 120 Jünger waren versammelt.","r":{"t":"Apostelgeschichte 1:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/1/#v44001015"}},{"t":"Sie redeten in fremden Sprachen.","r":{"t":"Apostelgeschichte 2:4-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/2/#v44002004-v44002011"}},{"t":"Petrus zitierte die Prophezeiung Joels.","r":{"t":"Apostelgeschichte 2:16-21","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/2/#v44002016-v44002021"}},{"t":"Etwa 3000 wurden getauft.","r":{"t":"Apostelgeschichte 2:41","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/2/#v44002041"}}],"significance":"Mit Pfingsten 33 u. Z. begann die Christenversammlung.","persons":["petrus","matthias","johannes-apostel","maria","joel","jakobus-halbbruder-jesu"],"refs":[{"t":"Apostelgeschichte 2:1-47","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/2/#v44002001-v44002047"}],"sources":[{"title":"Pfingsten – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003431"},{"title":"B13 Die Ausbreitung des Christentums – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070234"}]},{"id":"stephanus-gesteinigt","title":"Stephanus wird gesteinigt","era":"versammlung","year":34,"date":"Vor der Bekehrung des Saulus","place":"Jerusalem","summary":"Stephanus, einer der sieben Männer, die für die Verteilung von Lebensmitteln eingesetzt worden waren, predigte mutig. Gegner beschuldigten ihn mit falschen Zeugen der Lästerung vor dem Sanhedrin. In seiner Verteidigung schilderte er Gottes Handeln mit Israel und warf den Führern vor, den Gerechten getötet zu haben. Daraufhin wurde er gesteinigt – Saulus war damit einverstanden.","facts":[{"t":"Falsche Zeugen traten gegen ihn auf.","r":{"t":"Apostelgeschichte 6:11-13","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/6/#v44006011-v44006013"}},{"t":"Er sah Jesus zur Rechten Gottes.","r":{"t":"Apostelgeschichte 7:55, 56","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/7/#v44007055"}},{"t":"Er betete: „Jehova, rechne ihnen diese Sünde nicht zu!“","r":{"t":"Apostelgeschichte 7:60","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/7/#v44007060"}},{"t":"Danach begann eine große Verfolgung.","r":{"t":"Apostelgeschichte 8:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008001"}}],"significance":"","persons":["stephanus","paulus"],"refs":[{"t":"Apostelgeschichte 6:8–8:2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/6/#v44006008-v44008002"}],"sources":[{"title":"Stephanus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200004230"}]},{"id":"philippus-und-der-aethiopier","title":"Philippus und der äthiopische Eunuch","era":"versammlung","year":34,"date":"Nach dem Tod des Stephanus","place":"Samaria; Straße nach Gasa","summary":"Als die Jünger nach dem Tod des Stephanus zerstreut wurden, predigte Philippus, der Evangeliumsverkündiger, in Samaria; viele ließen sich taufen. Dann führte ihn ein Engel an die Straße nach Gasa. Dort las ein äthiopischer Eunuch, ein Hofbeamter der Königin von Äthiopien, aus Jesaja. Philippus erklärte ihm die Prophezeiung über Jesus, und der Eunuch ließ sich sogleich taufen.","facts":[{"t":"Philippus verkündete in Samaria den Christus.","r":{"t":"Apostelgeschichte 8:5-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008005-v44008008"}},{"t":"Petrus und Johannes kamen nach Samaria.","r":{"t":"Apostelgeschichte 8:14-17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008014-v44008017"}},{"t":"Der Eunuch las Jesaja 53.","r":{"t":"Apostelgeschichte 8:32-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008032-v44008035"}},{"t":"„Was hindert mich, getauft zu werden?“","r":{"t":"Apostelgeschichte 8:36-38","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008036-v44008038"}}],"significance":"","persons":["philippus-evangelist","petrus","johannes-apostel"],"refs":[{"t":"Apostelgeschichte 8:4-40","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/8/#v44008004-v44008040"}],"sources":[{"title":"Philippus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003466"}]},{"id":"bekehrung-des-saulus","title":"Saulus wird Christ","era":"versammlung","year":34,"date":"um 34 u. Z.","place":"Weg nach Damaskus","summary":"Saulus von Tarsus verfolgte die Jünger erbittert und war mit einer Vollmacht auf dem Weg nach Damaskus, um Christen festzunehmen. In der Nähe der Stadt offenbarte sich ihm Jesus in einem hellen Licht und beauftragte ihn, sein Zeuge zu sein. Saulus erblindete und wurde nach Damaskus geführt. Drei Tage später heilte ihn der Jünger Ananias, und Saulus ließ sich taufen.","facts":[{"t":"Er wollte Jünger gefesselt nach Jerusalem bringen.","r":{"t":"Apostelgeschichte 9:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009001"}},{"t":"„Saul, Saul, warum verfolgst du mich?“","r":{"t":"Apostelgeschichte 9:4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009004"}},{"t":"Ananias legte ihm die Hände auf.","r":{"t":"Apostelgeschichte 9:17, 18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009017"}},{"t":"Er wurde ein „auserwähltes Gefäß“ für die Nationen.","r":{"t":"Apostelgeschichte 9:15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009015"}}],"significance":"","persons":["paulus","ananias-damaskus"],"refs":[{"t":"Apostelgeschichte 9:1-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/9/#v44009001-v44009022"},{"t":"Apostelgeschichte 26:12-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/26/#v44026012-v44026018"}],"sources":[{"title":"Paulus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003406"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"kornelius-getauft","title":"Kornelius wird getauft","era":"versammlung","year":36,"date":"36 u. Z.","place":"Joppe; Cäsarea","summary":"Petrus sah in Joppe eine Vision, in der Gott ihm zeigte, dass er nichts unrein nennen soll, was Gott gereinigt hat. Danach reiste er nach Cäsarea zu dem römischen Offizier Kornelius und predigte ihm und seinen Angehörigen. Noch während Petrus sprach, kam heiliger Geist auf sie – die ersten unbeschnittenen Nichtjuden wurden Christen.","facts":[{"t":"Ein Engel erschien Kornelius.","r":{"t":"Apostelgeschichte 10:3-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010003-v44010006"}},{"t":"Petrus sah eine Vision von unreinen Tieren.","r":{"t":"Apostelgeschichte 10:9-16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010009-v44010016"}},{"t":"„Gott ist nicht parteiisch.“","r":{"t":"Apostelgeschichte 10:34, 35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010034"}},{"t":"Der heilige Geist kam auf die Zuhörer.","r":{"t":"Apostelgeschichte 10:44-48","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010044-v44010048"}}],"significance":"Mit 36 u. Z. endete die 70. Jahrwoche; ab jetzt wurde die gute Botschaft auch Nichtjuden gepredigt.","persons":["kornelius","petrus"],"refs":[{"t":"Apostelgeschichte 10:1-48","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/10/#v44010001-v44010048"},{"t":"Apostelgeschichte 11:1-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/11/#v44011001-v44011018"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Petrus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003451"}]},{"id":"petrus-befreit","title":"Jakobus wird hingerichtet, Petrus befreit","era":"versammlung","year":44,"date":"44 u. Z.","place":"Jerusalem; Cäsarea","summary":"König Herodes Agrippa I. ließ den Apostel Jakobus mit dem Schwert hinrichten. Weil das den Juden gefiel, nahm er zur Passahzeit auch Petrus fest. Die Versammlung betete inständig für ihn. In der Nacht vor dem Prozess befreite ein Engel Petrus auf wunderbare Weise aus dem Gefängnis. Kurz darauf starb Herodes in Cäsarea, von Gott geschlagen.","facts":[{"t":"Jakobus wurde mit dem Schwert getötet.","r":{"t":"Apostelgeschichte 12:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012001"}},{"t":"Die Versammlung betete für Petrus.","r":{"t":"Apostelgeschichte 12:5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012005"}},{"t":"Ein Engel führte ihn hinaus.","r":{"t":"Apostelgeschichte 12:7-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012007-v44012010"}},{"t":"Herodes starb kurz darauf.","r":{"t":"Apostelgeschichte 12:21-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012021-v44012023"}}],"significance":"","persons":["jakobus-zebedaeus","petrus","herodes-agrippa-i"],"refs":[{"t":"Apostelgeschichte 12:1-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/12/#v44012001-v44012024"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Jakobus – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002313"}]},{"id":"erste-missionsreise","title":"Die erste Missionsreise des Paulus","era":"versammlung","year":47,"date":"um 47–48 u. Z.","place":"Zypern; Kleinasien","summary":"Von Antiochia in Syrien aus wurden Paulus und Barnabas durch den heiligen Geist ausgesandt. Sie predigten auf Zypern und in vielen Städten Kleinasiens wie Antiochia in Pisidien, Ikonion, Lystra und Derbe. Sie stießen auf Widerstand – in Lystra wurde Paulus gesteinigt –, doch viele wurden Jünger. Danach kehrten sie nach Antiochia zurück.","facts":[{"t":"Der heilige Geist sonderte sie aus.","r":{"t":"Apostelgeschichte 13:2-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/13/#v44013002-v44013004"}},{"t":"In Antiochia wandten sie sich den Nationen zu.","r":{"t":"Apostelgeschichte 13:46-48","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/13/#v44013046-v44013048"}},{"t":"Paulus wurde in Lystra gesteinigt.","r":{"t":"Apostelgeschichte 14:19, 20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/14/#v44014019"}},{"t":"Sie ernannten ältere Männer in den Versammlungen.","r":{"t":"Apostelgeschichte 14:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/14/#v44014023"}}],"significance":"","persons":["paulus","barnabas","markus"],"refs":[{"t":"Apostelgeschichte 13:1–14:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/13/#v44013001-v44014028"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"B13 Die Ausbreitung des Christentums – Studienbibel","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1001070234"}]},{"id":"beschneidungsfrage","title":"Die Beschneidungsfrage wird geklärt","era":"versammlung","year":49,"date":"49 u. Z.","place":"Jerusalem","summary":"Manche lehrten, Christen aus den Nationen müssten beschnitten werden und das Gesetz Moses halten. Paulus und Barnabas reisten deshalb nach Jerusalem zu den Aposteln und älteren Männern. Nach Berichten von Petrus, Paulus und Barnabas und einer Schlussfolgerung des Jakobus entschied man durch heiligen Geist: Nichtjüdische Christen müssen sich nicht beschneiden lassen, sollen sich aber von Götzenopfern, Blut, Ersticktem und Hurerei enthalten.","facts":[{"t":"Die Frage wurde den Aposteln und älteren Männern vorgelegt.","r":{"t":"Apostelgeschichte 15:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015001"}},{"t":"Jakobus zitierte die Propheten.","r":{"t":"Apostelgeschichte 15:13-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015013-v44015018"}},{"t":"„Der heilige Geist und wir selbst haben es für gut befunden …“","r":{"t":"Apostelgeschichte 15:28, 29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015028"}},{"t":"Der Brief brachte den Versammlungen Freude.","r":{"t":"Apostelgeschichte 15:30, 31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015030"}}],"significance":"","persons":["paulus","barnabas","petrus","jakobus-halbbruder-jesu","silas","titus"],"refs":[{"t":"Apostelgeschichte 15:1-35","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015001-v44015035"},{"t":"Galater 2:1-10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/galater/2/#v48002001-v48002010"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Beschneidung – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000977"}]},{"id":"zweite-missionsreise","title":"Die zweite Missionsreise","era":"versammlung","year":49,"date":"um 49–52 u. Z.","place":"Kleinasien; Mazedonien; Griechenland","summary":"Spät im Sommer 49 u. Z. brach Paulus mit Silas von Antiochia auf; unterwegs schloss sich Timotheus an. Im Frühjahr 50 folgte Paulus dem Ruf des Mazedoniers und setzte nach Europa über. In Philippi, Thessalonich, Beröa und Athen predigte er und gründete Versammlungen. Im Herbst 50 kam er nach Korinth und blieb dort 18 Monate, bis zum Frühjahr 52 u. Z.","facts":[{"t":"Er sah in einer Vision einen Mann aus Mazedonien.","r":{"t":"Apostelgeschichte 16:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016009"}},{"t":"In Philippi wurde Lydia getauft.","r":{"t":"Apostelgeschichte 16:14, 15","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016014"}},{"t":"Paulus und Silas sangen im Gefängnis.","r":{"t":"Apostelgeschichte 16:25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/16/#v44016025"}},{"t":"In Korinth blieb er anderthalb Jahre.","r":{"t":"Apostelgeschichte 18:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018011"}}],"significance":"","persons":["paulus","silas","timotheus","lukas","lydia","aquila","priszilla"],"refs":[{"t":"Apostelgeschichte 15:36–18:22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/15/#v44015036-v44018022"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"paulus-in-athen","title":"Paulus auf dem Areopag","era":"versammlung","year":50,"date":"um 50 u. Z.","place":"Athen","summary":"In Athen war Paulus erregt über die vielen Götzen. Er sprach in der Synagoge und auf dem Marktplatz, und Philosophen brachten ihn zum Areopag. Dort knüpfte er an einen Altar „Einem unbekannten Gott“ an und erklärte, dass der Schöpfer nicht in von Händen gemachten Tempeln wohnt und alle Menschen zur Reue aufruft. Einige wurden gläubig, darunter Dionysius und eine Frau namens Damaris.","facts":[{"t":"Die Stadt war voller Götzen.","r":{"t":"Apostelgeschichte 17:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/17/#v44017016"}},{"t":"Er erwähnte den Altar „Einem unbekannten Gott“.","r":{"t":"Apostelgeschichte 17:23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/17/#v44017023"}},{"t":"„In ihm haben wir Leben und bewegen uns und existieren.“","r":{"t":"Apostelgeschichte 17:28","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/17/#v44017028"}},{"t":"Einige schlossen sich ihm an.","r":{"t":"Apostelgeschichte 17:34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/17/#v44017034"}}],"significance":"","persons":["paulus"],"refs":[{"t":"Apostelgeschichte 17:16-34","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/17/#v44017016-v44017034"}],"sources":[{"title":"Areopag – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200000355"},{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"dritte-missionsreise","title":"Die dritte Missionsreise","era":"versammlung","year":52,"date":"um 52–56 u. Z.","place":"Kleinasien (Ephesus); Mazedonien; Griechenland","summary":"Paulus reiste wieder nach Kleinasien und erreichte Ephesus im Winter 52/53. Dort lehrte er drei Monate in der Synagoge und dann zwei Jahre im Hörsaal des Tyrannus, sodass alle in der Provinz Asia das Wort hörten. Nach Pfingsten 55 zog er über Mazedonien nach Korinth, kehrte um und kam zu Pfingsten 56 u. Z. nach Jerusalem.","facts":[{"t":"Er lehrte zwei Jahre im Hörsaal des Tyrannus.","r":{"t":"Apostelgeschichte 19:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/19/#v44019009"}},{"t":"Der Silberschmied Demetrius zettelte einen Aufruhr an.","r":{"t":"Apostelgeschichte 19:23-29","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/19/#v44019023-v44019029"}},{"t":"Er lehrte „öffentlich und von Haus zu Haus“.","r":{"t":"Apostelgeschichte 20:20","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/20/#v44020020"}},{"t":"In Troas fiel Eutychus aus dem Fenster und wurde auferweckt.","r":{"t":"Apostelgeschichte 20:9-12","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/20/#v44020009-v44020012"}}],"significance":"","persons":["paulus","timotheus","aquila","priszilla","apollos"],"refs":[{"t":"Apostelgeschichte 18:23–21:17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/18/#v44018023-v44021017"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"paulus-verhaftet","title":"Paulus wird in Jerusalem verhaftet","era":"versammlung","year":56,"date":"56 u. Z.","place":"Jerusalem; Cäsarea","summary":"Kurz nach seiner Ankunft in Jerusalem wurde Paulus im Tempel von einer aufgebrachten Menge angegriffen und von römischen Soldaten festgenommen. Weil Juden planten, ihn zu töten, brachte man ihn nach Cäsarea. Dort blieb er zwei Jahre in Haft, bis Festus Statthalter Felix ablöste. Vor Festus berief sich Paulus auf Cäsar und legte später auch vor König Agrippa Zeugnis ab.","facts":[{"t":"Die Menge wollte ihn töten.","r":{"t":"Apostelgeschichte 21:30-32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/21/#v44021030-v44021032"}},{"t":"Der Herr sagte: „Du musst auch in Rom Zeugnis ablegen.“","r":{"t":"Apostelgeschichte 23:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/23/#v44023011"}},{"t":"Er war zwei Jahre in Cäsarea in Haft.","r":{"t":"Apostelgeschichte 24:27","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/24/#v44024027"}},{"t":"„Ich berufe mich auf Cäsar!“","r":{"t":"Apostelgeschichte 25:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/25/#v44025011"}}],"significance":"","persons":["paulus","felix","festus","herodes-agrippa-ii"],"refs":[{"t":"Apostelgeschichte 21:27–26:32","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/21/#v44021027-v44026032"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"schiffbruch","title":"Reise nach Rom und Schiffbruch","era":"versammlung","year":58,"date":"um 58–59 u. Z.","place":"Mittelmeer; Malta","summary":"Vermutlich 58 u. Z. wurde Paulus als Gefangener nach Rom gebracht. Trotz seiner Warnung segelte das Schiff weiter und geriet in einen gewaltigen Sturm. Ein Engel versicherte Paulus, dass niemand umkommen würde. Das Schiff zerschellte vor Malta, doch alle 276 Personen erreichten das Land. Nach dem Winter auf Malta kam Paulus um 59 u. Z. in Rom an.","facts":[{"t":"Paulus warnte vor der Weiterfahrt.","r":{"t":"Apostelgeschichte 27:9, 10","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/27/#v44027009"}},{"t":"Ein Engel ermutigte ihn.","r":{"t":"Apostelgeschichte 27:23, 24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/27/#v44027023"}},{"t":"Alle 276 kamen sicher an Land.","r":{"t":"Apostelgeschichte 27:37, 44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/27/#v44027037"}},{"t":"Eine Giftschlange schadete ihm auf Malta nicht.","r":{"t":"Apostelgeschichte 28:3-6","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/28/#v44028003-v44028006"}}],"significance":"","persons":["paulus","lukas"],"refs":[{"t":"Apostelgeschichte 27:1–28:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/27/#v44027001-v44028016"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Malta – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002875"}]},{"id":"paulus-in-rom","title":"Paulus als Gefangener in Rom","era":"versammlung","year":59,"date":"um 59–61 u. Z.","place":"Rom","summary":"In Rom durfte Paulus unter Bewachung in einem gemieteten Haus wohnen. Zwei Jahre lang empfing er alle, die zu ihm kamen, predigte das Königreich Gottes und lehrte über Jesus „mit größtem Freimut, ungehindert“. In dieser Zeit schrieb er mehrere Briefe. Damit endet der Bericht der Apostelgeschichte.","facts":[{"t":"Er wohnte zwei Jahre in einem gemieteten Haus.","r":{"t":"Apostelgeschichte 28:30","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/28/#v44028030"}},{"t":"Er predigte ungehindert das Königreich Gottes.","r":{"t":"Apostelgeschichte 28:31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/28/#v44028031"}},{"t":"Er sprach mit den führenden Juden Roms.","r":{"t":"Apostelgeschichte 28:17-23","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/28/#v44028017-v44028023"}}],"significance":"","persons":["paulus","lukas","timotheus","epaphroditus","onesimus"],"refs":[{"t":"Apostelgeschichte 28:16-31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/apostelgeschichte/28/#v44028016-v44028031"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"tod-des-paulus","title":"Paulus stirbt als Märtyrer","era":"versammlung","year":65,"date":"um 65 u. Z.","place":"Rom","summary":"Nach dem Ende der Apostelgeschichte wurde Paulus anscheinend freigelassen und setzte seine Missionstätigkeit fort, unter anderem auf Kreta und in Mazedonien. Nach dem großen Brand Roms im Juli 64 u. Z. begann Nero, Christen zu verfolgen. Paulus wurde erneut verhaftet, saß in Ketten und starb wahrscheinlich kurz danach, um 65 u. Z., als Märtyrer.","facts":[{"t":"In seinem letzten Brief schrieb er: „Ich habe den vortrefflichen Kampf gekämpft.“","r":{"t":"2. Timotheus 4:6-8","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/4/#v55004006-v55004008"}},{"t":"Er war in Ketten.","r":{"t":"2. Timotheus 1:16","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/1/#v55001016"}},{"t":"Lukas war bei ihm.","r":{"t":"2. Timotheus 4:11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/4/#v55004011"}}],"significance":"","persons":["paulus","lukas","timotheus"],"refs":[{"t":"2. Timotheus 4:6-18","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/4/#v55004006-v55004018"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]},{"id":"zerstoerung-jerusalems-70","title":"Rom zerstört Jerusalem","era":"versammlung","year":70,"date":"70 u. Z.","place":"Jerusalem","summary":"Im Jahr 70 u. Z. kehrten die römischen Truppen unter dem Feldherrn Titus zurück und belagerten Jerusalem, das mit Besuchern des Passahfestes überfüllt war. Die Römer schütteten Belagerungswälle auf und schlossen die Stadt mit einem Pfahlwall ein. Die Hungersnot wurde furchtbar; Titus’ Friedensangebote wurden abgelehnt. Schließlich wurden Stadt und Tempel zerstört – wie Jesus vorhergesagt hatte.","facts":[{"t":"Jesus hatte die Zerstörung der Stadt angekündigt.","r":{"t":"Lukas 19:43, 44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/19/#v42019043"}},{"t":"Er hatte seinen Jüngern gesagt, wann sie fliehen sollten.","r":{"t":"Lukas 21:20-22","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/21/#v42021020-v42021022"}},{"t":"Vom Tempel sollte kein Stein auf dem anderen bleiben.","r":{"t":"Matthäus 24:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/24/#v40024001"}}],"significance":"","persons":[],"refs":[{"t":"Lukas 19:41-44","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/19/#v42019041-v42019044"},{"t":"Lukas 21:20-24","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/lukas/21/#v42021020-v42021024"},{"t":"Matthäus 24:1, 2","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/Matth%C3%A4us/24/#v40024001"}],"sources":[{"title":"Jerusalem – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200002436"}]},{"id":"offenbarung-auf-patmos","title":"Johannes erhält die Offenbarung","era":"versammlung","year":96,"date":"um 96 u. Z.","place":"Insel Patmos","summary":"Gegen Ende der von Kaiser Domitian eingeleiteten Verfolgung war der betagte Apostel Johannes auf die Insel Patmos verbannt. Dort empfing er durch Jesus Christus eine Reihe von Visionen und schrieb sie nieder – das Buch Offenbarung. Es enthält Botschaften an sieben Versammlungen und zeigt, wie Gottes Königreich alle Feinde besiegt und eine neue Erde schafft.","facts":[{"t":"Johannes war „um des Wortes Gottes willen“ auf Patmos.","r":{"t":"Offenbarung 1:9","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/1/#v66001009"}},{"t":"Die Offenbarung kommt von Gott durch Jesus Christus.","r":{"t":"Offenbarung 1:1","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/1/#v66001001"}},{"t":"Gott wird jede Träne abwischen, und der Tod wird nicht mehr sein.","r":{"t":"Offenbarung 21:3, 4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/21/#v66021003"}}],"significance":"","persons":["johannes-apostel"],"refs":[{"t":"Offenbarung 1:1-11","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/1/#v66001001-v66001011"},{"t":"Offenbarung 21:1-5","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/offenbarung/21/#v66021001-v66021005"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"},{"title":"Patmos – Einsichten über die Heilige Schrift","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1200003403"}]},{"id":"abschluss-der-bibel","title":"Die Bibel wird vollendet","era":"versammlung","year":98,"date":"um 98 u. Z.","place":"Ephesus (oder Umgebung)","summary":"Nach seiner Freilassung schrieb der Apostel Johannes von Ephesus oder dessen Umgebung aus sein Evangelium und drei Briefe. Damit war die Bibel vollständig: 66 Bücher, geschrieben über rund 1600 Jahre. Um das Jahr 100 u. Z. starb Johannes als letzter der Apostel.","facts":[{"t":"Das Johannesevangelium entstand um 98 u. Z.","r":{"t":"Johannes 20:30, 31","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/20/#v43020030"}},{"t":"Johannes schrieb auch drei Briefe.","r":{"t":"1. Johannes 1:1-4","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/1-johannes/1/#v62001001-v62001004"}},{"t":"Er starb um 100 u. Z. als letzter Apostel."}],"significance":"","persons":["johannes-apostel"],"refs":[{"t":"Johannes 21:24, 25","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/johannes/21/#v43021024"},{"t":"2. Timotheus 3:16, 17","u":"https://www.jw.org/de/bibliothek/bibel/studienbibel/buecher/2-timotheus/3/#v55003016"}],"sources":[{"title":"Studie 3 – Ereignisse in den Strom der Zeit einordnen","url":"https://wol.jw.org/de/wol/d/r10/lp-x/1101990130"}]}]};
